window.__D("text/zohar-hebrew-translation/c034",{"p":[[9522012488,"<p>כְּשֶׁרָאָה יְחֶזְקֵאל אֶת הַשְּׁכִינָה מִתּוֹךְ הַקְּלִפּוֹת, רָאָה עִמָּהּ עֶשֶׂר סְפִירוֹת בְּלִי פֵרוּד כְּלָל, וְאֵלֶּה הֵם מֹחַ, מִבִּפְנִים, אֶת כֻּלָּם רָאָה מִתּוֹךְ נְהַר כְּבָר שֶׁלְּמַטָּה, הִיא (תהלים סח) רֶכֶב אֱלֹהַיִם רִבּתַיִם. כָּל רִבּוֹא עֲשָׂרָה אֲלָפִים, רִבּוֹתַיִם עֶשְׂרִים אֶלֶף. תּוֹצִיא שְׁנַיִם שֶׁאֵינָם, נִשְׁאֲרוּ שְׁמוֹנָה עָשָׂר, בְּחֶשְׁבּוֹן שְׁמוֹנָה עָשָׂר עוֹלָמוֹת, שֶׁכּוֹלְלִים עֶשֶׂר סְפִירוֹת שֶׁהִתְלַבֵּשׁ טֵ\"ט מִמְּטַטְרוֹן. טֵ\"ט מִטֹּטָפֹת, וְנֶאֱמַר בּוֹ (דברים ו) וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךְ. מִי הָעֵינַיִם? אֵלּוּ לְמַעְלָה, שֶׁנֶּאֱמַר בָּהֶן (יחזקאל א) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אֱלֹהִים. אֵילוּ מַרְאוֹת? אֵלּוּ עֲשָׂרָה מַרְאוֹת שֶׁל מְטַטְרוֹן שֶׁנִּרְאָה כְּמוֹ נֵר בַּעֲשָׁשִׁית, תִּשְׁעָה בְגָלוּי וְאֶחָד בְּנִסְתָּר.</p>\n<p>מַרְאֶה אֶחָד, שֶׁהוּא מַרְאֶה רִאשׁוֹן מֵאֵלּוּ הָעֲשָׂרָה, זֶהוּ שֶׁנֶּאֱמַר בּוֹ, וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. וְאַף עַל גַּב שֶׁנִּפְרָד לְמַעְלָה, צָרִיךְ לְחַדֵּשׁ עָלָיו חִדּוּשִׁים.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַמַּחֲנוֹת שֶׁלְּמַעְלָה: מִי שֶׁמִּתְפַּלֵּל, בֵּין שֶׁיִּהְיֶה גִבּוֹר, בֵּין שֶׁיִּהְיֶה חָכָם, בֵּין שֶׁיִּהְיֶה עָשִׁיר; בִּזְכֻיּוֹת גִּבּוֹר, חָכָם בַּתּוֹרָה, וְעָשִׁיר בְּמִצְווֹת - לֹא תִכָּנֵס תְּפִלָּתוֹ בְּהֵיכָל זֶה עַד שֶׁיֵּרָאוּ בוֹ סִימָנִים אֵלּוּ, שֶׁנָּתַן עַצְמוֹ בּוֹ תִּקּוּנִים שֶׁלִּי. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, אִם הָרַב דּוֹמֶה לְמַלְאַךְ ה' צְבָאוֹת, תּוֹרָה יְבַקְשׁוּ מִפִּיהוּ. לְמִי שֶׁיִּהְיֶה רָשׁוּם בַּסִּימָנִים הַלָּלוּ בִּלְבוּשׁוֹ, תְּקַבְּלוּ תְפִלָּתוֹ. סִימָן אֶחָד שֶׁיִּהְיֶה רָשׁוּם בִּתְפִלָּתוֹ, בִּתְכֵלֶת בְּכַנְפֵי מִצְוָה צִיצִית, שֶׁהוּא דּוֹמֶה לָרָקִיעַ, שֶׁהוּא מְטַטְרוֹן. דְּמוּתוֹ תְּכֵלֶת שֶׁבַּצִּיצִית.</p>\n<p>וּמִשּׁוּם זֶה שִׁעוּר הַצִּיצִית פֵּרְשׁוּהוּ רַבּוֹתֵינוּ, טַלִּית שֶׁהַקָּטָן מִתְכַּסֶּה בָּהּ רֹאשׁוֹ וְרֻבּוֹ. וְזֶהוּ שֶׁנֶּאֱמַר בּוֹ (ישעיה יא) וְנַעַר קָטֹן נֹהֵג בָּם. וְזֶהוּ נוֹהֵג בְּאַרְבַּע חַיּוֹת, שֶׁהֵם אַרְבַּע, וְהוּא כּוֹלֵל (מלכים א י) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, שֶׁהֵם ו'. וּמִשּׁוּם שֶׁהוּא כָּלוּל עֶשֶׂר, מִתְלַבְּשִׁים בּוֹ עֶשֶׂר סְפִירוֹת, י'. וּבוֹ נִרְאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁכִינָתוֹ, שֶׁהִיא כְּלוּלָה מֵעֶשֶׂר סְפִירוֹת - לַנְּבִיאִים. וּמִצַּד הַשְּׁכִינָה, שֶׁהִיא עֲשִׂירִית, תְּכֵלֶת שֶׁבַּצִּיצִית, הִיא תְּכֵלֶת שֶׁל כָּל הַגְּוָנִים.</p>\n<p>שֶׁהִיא תַּכְלִית שֶׁל עֶשֶׂר סְפִירוֹת, וּבוֹ (שמות לט) וַתֵּכֶל כָּל עֲבֹדַת (משכן) אֹהֶל מוֹעֵד, וְהִיא לְשׁוֹן כַּלָּה. זֶהוּ שֶׁכָּתוּב (במדבר ז) וַיְהִי בְּיוֹם כַּלֹּת מֹשֶׁה לְהָקִים אֶת הַמִּשְׁכָּן. וּפֵרְשׁוּהָ רַבָּנָן, כַּלַּת כָּתוּב, וְהִיא תְּכֵלֶת הַנֵּר, שֶׁאוֹכֶלֶת חֲלָבִים וְעוֹלוֹת.</p>\n<p>וְעָלָיו אָמַר יְחֶזְקֵאל, דְּמוּת כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. סְגֻלַּת הָאֶבֶן הַזּוֹ, שֶׁמִּי שֶׁיּוֹרֵשׁ אוֹתָהּ לֹא שׁוֹלֶטֶת בּוֹ אֵשׁ הַגֵּיהִנֹּם. אֵין אֵשׁ שֶׁמְּקַלְקֶלֶת אוֹתָהּ וְלֹא כָּל מִינֵי מַתָּכוֹת, כָּל שֶׁכֵּן שֶׁהַמַּיִם לֹא מַזִּיקִים אוֹתָהּ. מִי שֶׁיּוֹרֵשׁ אוֹתָהּ, מִתְקַיֵּם בּוֹ (ישעיה מג) כִּי תַעֲבֹר בַּמַּיִם אִתְּךְ אָנִי וְגוֹ'. וְכָל עֶלְיוֹנִים וְתַחְתּוֹנִים שֶׁל צַד הָאַחֵר פּוֹחֲדִים מִמֶּנּוּ. תְּכֵלֶת הַיָּם, בִּשְׁבִילָהּ נֶאֱמַר כִּי תַעֲבֹר בַּמַּיִם אִתְּךְ אָנִי. שֶׁבִּסְגֻלָּה זוֹ (שמותטו) סוּס וְרֹכְבוֹ רָמָה בַיָּם, זֶה מְמֻנֶּה שֶׁל מִצְרַיִם.</p>\n<p>מִגָּוֶן זֶה פּוֹחֲדִים עֶלְיוֹנִים וְתַחְתּוֹנִים. מַחֲנוֹת הַיָּם פּוֹחֲדִים מִמֶּנּוּ. וּמַחֲנוֹת הָרָקִיעַ, שֶׁהוּא תְּכֵלֶת, מִמֶּנּוּ פּוֹחֲדִים. מַחֲנוֹת הַתְּכֵלֶת (ומחנות הרקיעים ומחנות) שֶׁאִשֵּׁי הַגֵּיהִנֹּם פּוֹחֲדִים מִמֶּנָּה.</p>\n<p>וּתְכֵלֶת זוֹ הִיא דִּין, דִּינָא - אֲדֹנָ\"י. דִּינָא דְמַלְכוּתָא דִּינָא, וּשְׁנֵי גְוָנִים רְשׁוּמִים בַּטַּלִּית, אֶחָד לָבָן וְאֶחָד תְּכֵלֶת. וְעַל שְׁנֵי גְוָנִים אֵלּוּ נֶאֱמַר, (שמות כד) וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר. לִבְנַת - לֹבֶן הַסַּפִּיר, שֶׁהוּא כָּלוּל בִּשְׁנֵי גְוָנִים, רַחֲמִים וְדִין, לָבָן וְשָׁחֹר. שְׁחֹר הַתְּכֵלֶת. וְעַל שְׁנֵי גְוָנִים רָמְזוּ רַבּוֹתֵינוּ, מֵאֵימָתַי קוֹרְאִים אֶת שְׁמַע בְּשַׁחֲרִית? מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. לִהְיוֹת בַּת הַמֶּלֶךְ, קְרִיאַת שְׁמַע, יִחוּד הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּלוּל מִשְּׁנֵי גְוָנִים אֵלּוּ, שֶׁהֵם יְהֹוָ\"ה אֲדֹנָ\"י, רַחֲמִים וְדִין. כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא כּוֹלֵל שְׁנֵי גְוָנִים - יְהֹוָ\"ה אֲדנָ\"י, לִהְיוֹת רַחֲמִים וְדִין, כִּסֵּא דִין וְכִסֵּא רַחֲמִים. (מטטרון).</p>\n<p>כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. מַה זֶּה דְּמוּת כִּסֵּא? אֶלָּא כְּנֶגֶד הַכִּסֵּא, שֶׁיֵּשׁ לוֹ שִׁבְעִים וּשְׁנַיִם גְּשָׁרִים. שֶׁיִּהְיֶה אָדָם רָשׁוּם בְּשִׁבְעִים וּשְׁנַיִם קְשָׁרִים, וְחֻלְיוֹת הַצִּיצִית, כְּנֶגֶד שִׁבְעִים וּשְׁנַיִם גְּשָׁרִים שֶׁל הַכִּסֵּא, שֶׁהֵם שְׁמוֹנָה עָשָׂר קְשָׁרִים, וְחֻלְיוֹת לְכָל צַד. שֶׁהַכִּסֵּא שֶׁהוּא ה', לְכָל צַד בְּאַרְבַּע חַיּוֹת הַכִּסֵּא, שֶׁהֵם ד'.</p>\n<p>וְשֵׁשׁ מַעֲלוֹת הַכִּסֵּא, שֶׁהֵם ו', וְזֶה מְטַטְרוֹן, הוּא כּוֹלֵל אַרְבַּע חַיּוֹת. זֶהוּ שֶׁכָּתוּב (ישעיה יא) וְנַעַר קָטֹן נֹהֵג בָּם, וְהֵם: מִיכָאֵל, גַּבְרִיאֵל, נוּרִיאֵל, רְפָאֵל. מְטַטְרוֹן, (מלכים א י) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, שֶׁעוֹלִים שֵׁשׁ מֵאוֹת, צִיצִית בִּשְׁתֵּי יוֹדִי\"ן. וְאִם חָסֵר יוֹ\"ד, הֲרֵי חִירִק בִּמְקוֹמָהּ, כָּךְ עוֹלֶה. בְּכָל צַד בְּאַרְבַּע כְּנָפוֹת, צִיצִית וּשְׁלֹשׁ עֶשְׂרֵה חֻלְיוֹת הַצִּיצִית - הֵם תרי\"ג.</p>\n<p>וְעוֹד שֵׁשׁ מַעֲלוֹת לַכִּסֵּא - בְּסוֹד זֶה וָא\"ו, עוֹלֶה לְחֶשְׁבּוֹן י\"ג, שֶׁנִּרְמָז בְּשָׁלֹשׁ תֵּבוֹת (שמות יד) וַיִּסַּע, וַיָּבא, וַיֵּט. שֶׁהֵם וָהוּ אֲנִי וָהוּ. חֲמִשָּׁה קְשָׁרִים, ה' לְכָל צַד. א' טַלִּית אַחַת לְכֻלָּם. וּבָאוֹת ה' נִשְׁלָם ח\"י, שֶׁהֵם טֵ\"ט, לִהְיוֹת חַיָּה לְכָל צַד, כּוֹלֵל אַרְבַּע חַיּוֹת. וּלְכָל חַיָּה אַרְבַּע פָּנִים וְאַרְבַּע כְּנָפַיִם, הֵם ל\"ב פָּנִים וּכְנָפַיִם, וְהֵם תְּלוּיִים מֵחַיָּה שֶׁהוּא אָדָם.</p>\n<p>וְהֵם ל\"ב, כְּחֶשְׁבּוֹן יוֹ\"ד הֵ\"א הֵ\"א. שְׁלֵמוּת שֶׁלָּהֶם וָא\"ו. שְׁלֹשׁ עֶשְׂרֵה חֻלְיוֹת בְּכָל אַרְבַּע הַכְּנָפַיִם. וְהַוָּא\"ו מִתְיַחֵד עִם כָּל אַרְבַּע חַיּוֹת, וּמַשְׁלִים לְמַעְלָה, מַשְׁלִים לְמַטָּה. עַמּוּד הָאֶמְצָעִי הוּא מְטַטְרוֹן, לְהַשְׁלִים לְמַעְלָה, כְּמוֹ הַתִּפְאֶרֶת. שְׁמוֹ כְּשֵׁם רַבּוֹ. בְּצַלְמוֹ כִדְמוּתוֹ נִבְרָא. שֶׁהוּא כּוֹלֵל כָּל הַדְּרָגוֹת, מִלְמַעְלָה לְמַטָּה, וּמִלְּמַטָּה לְמַעְלָה, וְאָחוּז הוּא בָּאֶמְצַע. זֶהוּ שֶׁכָּתוּב (שמות כו) וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה.</p>\n<p>וְהוּא כּוֹלֵל אַרְבַּע פָּנִים וְאַרְבַּע כְּנָפַיִם לְכָל חַיָּה וְחַיָּה שֶׁלְּמַעְלָה, שֶׁהֵם יְאֲהַדוֹנָהִי. אָז יָשִׁיר מֹשֶׁה. בְּכָל חַיָּה אַרְבַּע פָּנִים וְאַרְבַּע כְּנָפַיִם כְּמוֹ זֶה. א\"ז בָּאַרְיֵה. א\"ז בַּשּׁוֹר. א\"ז בַּנֶּשֶׁר. א\"ז בָּאָדָם. שֶׁהֵם ל\"ב פָּנִים וּכְנָפַיִם, בְּחֶשְׁבּוֹן א\"ז אַרְבַּע פְּעָמִים.</p>\n<p>וְהֵם אַרְבַּע פָּנִים: יְהֹוָ\"ה. אַרְבַּע כְּנָפַיִם: אֲדנָי. כְּנֶגֶד אַרְבָּעָה בִּגְדֵי זָהָב וְאַרְבָּעָה בִּגְדֵי לָבָן שֶׁלּוֹבֵשׁ הַכֹּהֵן לְכַפֵּר עַל יִשְׂרָאֵל, כְּנֶגֶד (תהלים נא) אֲדנָי שְׂפָתַי תִּפְתָּח. וּתְפִלָּה, שֶׁל תְּפִלָּה יְהֹוָ\"ה, בַּחֲתִימָה י\"ח בִּרְכוֹת הַתְּפִלָּה. וּשְׁמוֹנֶה עֶשְׂרֵה פְעָמִים יְהֹוָ\"ה, יֵשׁ בָּהֶם ע\"ב אוֹתִיּוֹת, בְּחֶשְׁבּוֹן (בראשית ב) וַיְכֻלּוּ, שֶׁכְּלוּלִים בְּצַדִּיק חַ\"י הָעוֹלָמִים.</p>\n<p>וּבְאַרְבַּע חַיּוֹת, יְהֹוָ\"ה אֲדנָי. שְׁמוֹנָה לְכָל צַד - הֵם ל\"ב אוֹתִיּוֹת, וְי\"ג אוֹתִיּוֹת שֶׁנִּמְצְאוּ מִן וָה\"וּ אֲנִי וָה\"וּ. הֲרֵי שְׁלֹשָׁה עָשָׂר שֶׁכְּלוּלִים לְמַעְלָה וּלְמַטָּה, בָּהֶם הִשְׁתַּלֵּם אָדָם, שֶׁהוּא מ\"ה, עַמּוּד הָאֶמְצָעִי.</p>"],[9522012489,"<p>לְמַעְלָה בְּעֵץ הַחַיִּים אֵין קְלִפּוֹת, (אסתרד) כִּי אֵין לָבא אֶל שַׁעַר הַמֶּלֶךְ בִּלְבוּשׁ שָׂק. לְמַטָּה יֵשׁ קְלִפּוֹת בִּמְטַטְרוֹן, שֶׁהוּא בִּדְמוּת הָעַמּוּד הָאֶמְצָעִי. שֶׁבִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִחוּץ לְמַלְכוּתוֹ, מִתְכַּסֶּה בְכַנְפֵי וּפְנֵי הָעֶבֶד שֶׁלּוֹ, זֶהוּ שֶׁכָּתוּב (שמואל ב כב) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף.</p>\n<p>וְאוֹתָן קְלִפּוֹת שֶׁסּוֹבְבוֹת לְאַרְבַּע חַיּוֹת מְטַטְרוֹן הֵן: תֹּהוּ - (מלכים א יט) וְהִנֵּה רוּחַ גְּדוֹלָה וְחָזָק מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים לֹא בָרוּחַ ה'. בֹּה\"וּ - וְאַחַר הָרוּחַ רַעַשׁ לֹא בָרַעַשׁ ה'. הֲרֵי שְׁתֵּי קְלִפּוֹת, יָרֹק וְלָבָן. שֶׁקְּלִפּוֹת הָאֱגוֹז - אֶחָד תֹּהוּ, קַו יָרֹק. שֵׁנִי בּהוּ, אֲבָנִים מְפֻלָּמוֹת, קְלִפָּה חֲזָקָה כְּאֶבֶן מְפֻלֶּמֶת. כְּנֶגֶד שְׁתֵּי קְלִפּוֹת אֵלּוּ, מוֹץ וְתֶבֶן שֶׁל חִטָּה.</p>\n<p>קְלִפָּה שְׁלִישִׁית, דַּקִּיקָה - כְּנֶגֶד סֻבִּין שֶׁל חִטָּה, שֶׁכָּאן הוּא נִדְבָּק בַּחִטָּה וְלֹא יָכוֹל לְהִפָּרֵד מִשָּׁם עַד שֶׁטּוֹחֲנִים אוֹתוֹ בָּרֵחַיִם, שֶׁהֵן כְּנֶגֶד טוֹחֲנוֹת הַפֶּה שֶׁל הָאִישׁ, שֶׁצָּרִיךְ לִטְחֹן בָּהֶן דִּבְרֵי תוֹרָה עַד שֶׁיִּהְיוּ כְּמוֹ קֶמַח סֹלֶת נְקִיָּה. וּבְנָפָה, שֶׁהִיא הַשָּׂפָה, מִתְבָּרֶרֶת הַפְּסֹלֶת, שֶׁהוּא סֻבִּין (של התורה), עַד שֶׁתִּמָּצֵא הֲלָכָה סֹלֶת נְקִיָּה. בְּאוֹתוֹ זְמַן נוֹטֵל אוֹתָהּ הַלֵּב וְהַמֹּחַ, וְכָל אֵיבְרֵי הַגּוּף שֶׁהַנְּשָׁמָה מִתְפַּשֶּׁטֶת בָּהֶם, וְהַנְּשָׁמָה מִתְפַּרְנֶסֶת מִמֶּנָּה כְּמוֹ שֶׁהַגּוּף מִתְפַּרְנֵס מִדִּבְרֵי הָעוֹלָם. שֶׁזֶּה לְעֻמַּת זֶה עָשָׂה אֱלֹהִים - לֶחֶם הַגּוּף, וְלֶחֶם הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי.</p>\n<p>וּקְלִפָּה זוֹ הִיא כְּמוֹ קְלִפָּה שֶׁנִּדְבֶּקֶת לְמֹחַ הָאֱגוֹז, וּכְשֶׁהָאֱגוֹז רַךְ, נִפְרֶדֶת אוֹתָהּ קְלִפָּה מִמֹּחַ הָאֱגוֹז בְּלִי קֹשִׁי. וּכְשֶׁהָאֱגוֹז יָבֵשׁ, קָשֶׁה לָאָדָם לְהַעֲבִירָהּ מִשָּׁם, כִּי עֲדַיִן הַקֻּשְׁיָא בִּמְקוֹמָהּ עוֹמֶדֶת. וְלָכֵן צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם לַחֲזֹר בִּתְשׁוּבָה בְּבַחֲרוּתוֹ, לִפְנֵי שֶׁיַּזְקִין בּוֹ יֵצֶר הָרָע. זֶהוּ שֶׁכָּתוּב (ויקרא יט) מִפְּנֵי שֵׂיבָה תָּקוּם, קֹדֶם שֵׂיבָה שֶׁלְּךְ. וּקְלִפָּה זוֹ הִיא אֵשׁ, וְנֶאֱמַר בָּהּ, וְאַחַר הָרַעַשׁ אֵשׁ לֹא בָאֵשׁ ה'. רְבִיעִית - תְּהוֹם, חֲלַל הָאֱגוֹז, קוֹל דְּמָמָה דַּקָּה, שָׁם בָּא הַמֶּלֶךְ, (יחזקאל א) וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ.</p>\n<p>וְאוֹתָן קְלִפּוֹת רְשׁוּמוֹת בְּאַרְבָּעָה אֵיבָרִים שֶׁל הַגּוּף. בָּרֵאָה, שָׁם לֵחָה, שֶׁמִּמֶּנָּה יוֹצְאוֹת סִרְחוֹת הָרֵאָה, (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמֹכוּ. וְשָׁם רוּחַ חָזָק מְפָרֵק, שֶׁדּוֹפֵק בְּכַנְפֵי הָרֵאָה שֶׁל הָאָדָם, וְזֶהוּ רוּחַ שֶׁמַּסְעִיר אֶת גּוּף הָאָדָם, מַה שֶּׁכּוֹפֵף לוֹ אֵלִיָּהוּ תַּחְתָּיו וְעוֹלֶה בּוֹ לְמַעְלָה. זֶהוּ שֶׁכָּתוּב (מלכים ב ב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמַיְמָה (השמים). וְזֶהוּ דּוֹפֵק עַל הָרֵאָה, שֶׁשּׁוֹתָה כָּל מַשְׁקִים, וּבָהֶם (בראשית א) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, זוֹהִי קְלִפָּה לְרוּחַ הַקֹּדֶשׁ. לִשְׂמֹאל, רוּחַ סְעָרָה, עֲלֵיהֶם נֶאֱמַר (קהלת י) לֵב חָכָם לִימִינוֹ וְלֵב כְּסִיל לִשְׂמֹאלוֹ.</p>"],[9522012490,"<p>דָּוִד הֶעֱבִיר מִלִּבּוֹ וְהָרַג אוֹתוֹ, זֶהוּ שֶׁכָּתוּב (תהלים קט) וְלִבִּי חָלָל בְּקִרְבִּי, וְלָכֵן זָכָה לְנִשּׁוּב רוּחַ צְפוֹנִית בְּכִנּוֹרוֹ, וְנֶאֱמַר בּוֹ (יחזקאל לז) כֹּה אָמַר ה' מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, וְהָיָה מְנַגֵּן בּוֹ בַּכִּנּוֹר בְּאַרְבָּעָה מִינֵי נִגּוּנִים: בְּשִׁיר פָּשׁוּט, שֶׁהוּא י'. וּבְשִׁיר כָּפוּל, שֶׁהוּא י\"ד. וּבְשִׁיר מְשֻׁלָּשׁ, שֶׁהוּא יה\"ו. וּבְשִׁיר מְרֻבָּע, שֶׁהוּא יְהֹוָ\"ה. הֲרֵי הֵן עֶשֶׂר אוֹתִיּוֹת שֶׁעָשָׂה דָוִד כְּנֶגְדָּן עֲשָׂרָה מִינֵי תִלִּים, וְעוֹלִים לְע\"ב פָּנִים, כְּחֶשְׁבּוֹן עֶשֶׂר אוֹתִיּוֹת אֵלּוּ.</p>\n<p>וּמָתַי עָלוּ בְע\"ב מִינֵי נִגּוּן? כְּשֶׁעָבַר שִׁלְטוֹן עָון מַשְׁחִית אַף וְחֵמָה, שֶׁבָּהֶם דּוֹפֶקֶת רוּחַ סְעָרָה בְּאַרְבָּעָה צְדָדִים שֶׁעוֹלִים לַעֲשָׂרָה כְתָרִים לְע\"ב אֻמּוֹת. זֶהוּ שֶׁכָּתוּב (משלי יא) וּבַאֲבֹד רְשָׁעִים רִנָּה.</p>\n<p>שֶׁמִּיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל רְפָאֵ\"ל שׁוֹלְטִים עַל אַרְבַּעַת הַצְּדָדִים (היסודות) הַטּוֹבִים שֶׁל הָאָדָם, שֶׁהֵם מַיִם וְאֵשׁ וְרוּחַ וְעָפָר, וּלְכָל אֶחָד יֵשׁ לוֹ אַרְבַּע פָּנִים: עָון מַשְׁחִית אַף וְחֵמָה, תְּלוּיִים (שולטים) עַל מָרָה לְבָנָה, שֶׁרֵאָה עוֹשָׂה סִרְכָה. וּבַמָּרָה הָאָדם שֶׁל הַכָּבֵד שֶׁהִתְאַדֵּם בְּמַאְדִּים. וּבְמָרָה יְרֻקָּה שֶׁאֲחוּזָה בַּכָּבֵד, שֶׁהוּא חֶרֶב מַלְאַךְ הַמָּוֶת, שֶׁנֶּאֱמַר בָּהּ (שם ה) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה חַדָּה כְּחֶרֶב פִּיּוֹת. וּבְמָרָה שְׁחֹרָה, לִילִית, שַׁבְּתַי, שִׁלְטוֹן בַּטְּחוֹל, שֶׁהוּא עַצְבוּת, שְׁאוֹל תַּחְתִּית, עֲנִיּוּת וְחֹשֶׁךְ, בְּכִיָּה וְהֶסְפֵּד וּרְעָבוֹן.</p>\n<p>מִיָּד כְּשֶׁעוֹבְרוֹת קְלִפּוֹת אֵלּוּ מֵהָאָדָם, שׁוֹלֵט עָלָיו עֵץ הַחַיִּים בְּע\"ב פָּנִים, שֶׁהֵם י' י\"ה יה\"ו יְהֹוָ\"ה, שֶׁנִּמְצְאוּ עֲשָׂרָה תְלוּיִים מֵאַרְבַּע רוּחוֹת, שֶׁהֵם יְהֹוָה, שֶׁנֶּאֱמר בָּהֶם, כֹּה אָמַר ה' מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ. זֶהוּ רוּחוֹ שֶׁל מָשִׁיחַ, שֶׁנֶּאֱמַר בּוֹ (ישעיה יא) וְנָחָה עָלָיו רוּחַ ה', כְּשֶׁהוּא מְנַשֵּׁב בְּאֹזֶן יָמִין שֶׁל הַלֵּב, שֶׁשָּׁם חָכְמָה מִצַּד הַחֶסֶד, שֶׁבּוֹ הָרוֹצֶה לְהַחְכִּים יַדְרִים בְּחָכְמָה. וְחֶסֶ\"ד נוֹשֵׁב בְּבִינָה. שֶׁבְּחָכְמָה י', בְּבִינָה ה', בְּתִפְאֶרֶת ו', בְּמַלְכוּת ה'. יְהֹוָה דּוֹפֵק בְּכָל הָאַרְבָּעָה, שֶׁעוֹלִים לַעֲשָׂרָה, וּלְע\"ב מַחֲשֶׁבֶת הַלֵּב.</p>\n<p>זְהִ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. יָמִין הוּא מַיִם, וְהוּא יָד הַגְּדוֹלָה. מִשְּׂמֹאל אֵשׁ, וְהִיא יָד הַחֲזָקָה. בָּעַמּוּד הָאֶמְצָעִי יָ\"ד רָמָה, שֶׁהִיא רוּחַ הַקֹּדֶשׁ. וְהַכֹּל בֶּן י\"ד.</p>\n<p>כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים. אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ (יחזקאל א). בּוֹ מִתְנַהֲגִים מַיִם וְאֵשׁ. שֶׁאוֹחֵז בִּשְׁנֵיהֶם, וְדוֹפֵק בְּעוֹרְקֵי הַמֹּחַ, שֶׁהוּא מַיִם. וּבְעוֹרְקֵי הַלֵּב, שֶׁהוּא אֵשׁ. וְרוּחַ בְּכַנְפֵי רֵאָה.</p>\n<p>בְּכָל אֵיבָר וְאֵיבָר שֶׁל הַגּוּף נִמְצָאִים גַּלְגַּלֵּי יָם הַתּוֹרָה וְגַלְגַּלֵּי הָרָקִיעַ, שֶׁהֵם אֵשׁ. כֻּלָּם עוֹלִים וְיוֹרְדִים בּוֹ, וְהוּא מְקוֹמוֹ בֵּין רָקִיעַ וְיָם. כְּלִי שֶׁלּוֹ אֶרֶץ, שֶׁהִיא שְׁכִינָה.</p>\n<p>וּכְמוֹ עוֹפוֹת, פּוֹתְחִים כַּנְפֵיהֶם לְקַבֵּל רוּחַ לִפְרֹחַ בּוֹ - כָּךְ כָּל הָאֵיבָרִים אֵיבְרֵי הַגּוּף פְּתוּחִים בְּכַמָּה מְקוֹרוֹת, בְּכַמָּה פְרָקִים, בְּכַמָּה עוֹרְקִים, בְּכַמָּה חַדְרֵי הַלֵּב, חַדְרֵי הַמֹּחַ, לְקַבֵּל אוֹתוֹ. שֶׁאִם לֹא יִנְֹשב בְּבָתֵּי הַלֵּב, הָיָה אֵשׁ הַלֵּב שׂוֹרֵף כָּל הַגּוּף. וְכַמָּה סֻלָּמוֹת וַחֲדָרִים שֶׁל עוֹרְקֵי קְנֵה הַלֵּב וּקְנֵה הָרֵאָה, כֻּלָּם מִתְתַּקְּנִים אֵלָיו.</p>"],[9522012491,"<p>כְּשֶׁעוֹלֶה הַדִּבּוּר עַל כַּנְפֵי הָרֵאָה, נַעֲשֶׂה קוֹל. בְּאוֹתוֹ זְמַן, (קהלת י) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל. (תהלים כט) קוֹל ה' עַל הַמָּיִם - מִצַּד הַמַּיִם, שֶׁהוּא מֹחַ, שֶׁשָּׁם עוֹלֶה בְּכַנְפֵי רֵאָה. קוֹל ה' חֹצֵב לַהֲבוֹת אֵשׁ - מִצַּד הַלֵּב, כְּשֶׁיּוֹצֵא מֵהַפֶּה, נִקְרָא דִבּוּר.</p>\n<p>וּכְנֶגֶד שְׁתֵּי כַנְפֵי רֵאָה שֶׁפּוֹתְחוֹת כְּנָפַיִם לְקַבְּלוֹ, זֶהוּ שֶׁכָּתוּב (יחזקאל א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה - כָּךְ שְׂפָתַיִם לוֹקְחוֹת הַדִּבּוּר וּמַפְרִיחוֹת אוֹתוֹ לְמַעְלָה.</p>\n<p>וּכְמוֹ שֶׁאוֹתָן חָמֵשׁ כַּנְפֵי (ענפי) רֵאָה, כֻּלָּן פְּתוּחוֹת בְּלֹא סִרְכָה לְקַבֵּל קוֹל זֶה - כָּךְ גַּם צְרִיכִים לִהְיוֹת חֲמִשָּׁה תִּקּוּנֵי הַפֶּה, כֻּלָּם פְּתוּחִים בְּלִי סִרְכָה בַּחֲמִשָּׁה תִקּוּנִים, שֶׁהֵם: אחה\"ע בַּגָּרוֹן. בומ\"ף בַּשְּׂפָתַיִם. גיכ\"ק בַּחֵךְ. דטלנ\"ת בַּלָּשׁוֹן. זסשר\"ץ בַּשִּׁנַּיִם.</p>\n<p>וְדִבּוּר שֶׁיִּהְיֶה בָהֶם בְּלִי סִרְכָה וְעִכּוּב כְּלָל, זֶהוּ שֶׁכָּתוּב (בראשית כד) וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יֹצֵאת, זוֹ תְּפִלָּה, שֶׁהוּא דִּבּוּר, וּבִגְלָלָהּ נֶאֱמַר, אִם שְׁגוּרָה תְפִלָּתִי בְּפִי, יוֹדֵעַ אֲנִי שֶׁמְּקֻבָּל. וְאִם יֵשׁ סִרְכָה וְיוֹצֵא בְעִכּוּב, יוֹדֵעַ אֲנִי שֶׁמְּטֹרָף, בִּגְלַל (כגון) סִרְכָה בָּרֵאָה שֶׁהִיא טְרֵפָה.</p>\n<p>וְקוֹל זֶה שְׁמַע יִשְׂרָאֵל, שֶׁבּוֹ (יחזקאל א) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם. וְזֶה יְהֹוָ\"ה שֶׁהוּא קוֹל, כְּשֶׁיּוֹצֵא לְקַבֵּל שְׁכִינָה בִּתְפִלָּה בַּחֲשַׁאי, שֶׁהוּא דִּבּוּר, שֶׁבּוֹ אֲדֹנָ\"י שְׂפָתַי תִּפְתָּח, כָּל הָאֵיבָרִים פּוֹתְחִים כֻּלָּם אֶת כַּנְפֵיהֶם בְּרמ\"ח תֵּבוֹת, שֶׁהֵם בְּאַרְבַּע פָּרָשִׁיּוֹת קְרִיאַת שְׁמַע, שֶׁבָּהֶן יוֹרֵד הַקּוֹל.</p>\n<p>וּכְשֶׁיּוֹרֵד, כַּמָּה צִפֳּרִים מְצַפְצְפוֹת לוֹ בְּכַמָּה מִינֵי נִגּוּן, כֻּלָּם עַל אֵיבְרֵי הַגּוּף, שֶׁהֵם עַנְפֵי הָאִילָן. וּבְכָל כַּנְפֵי כָּל אֵיבָר, שֶׁשָּׁם דִּיּוּר הַצִּפּוֹר, שֶׁהִיא אֲדנָ\"י, בְּכָל עָנָף וְעָנָף נִמְצְאָה פְתוּחָה לְבַעְלָהּ. אֲדֹנָ\"י שְׂפָתַי תִּפְתָּח, הוּא פָּתַח אֵלָיו בִּתְפִלַּת הָעֲמִידָה - אֵין אֵיבָר מִמָּאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבְרֵי הַשְּׁכִינָה שֶׁלֹּא פָתוּחַ לְקַבְּלוֹ, וְלָכֵן נִקְרֵאת שִׂיחַת מַלְאֲכֵי הַשָּׁרֵת. הוּא צִפְצוּף עוֹפוֹת, שֶׁהֵם נְשָׁמוֹת שֶׁשּׁוֹרוֹת בָּאֵיבָרִים. הִיא שִׂיחַת דְּקָלִים, שֶׁהֵם עַנְפֵי הָאִילָן.</p>\n<p>וּבְאוֹתוֹ הַזְּמַן שֶׁיּוֹרֵד יְהֹוָ\"ה אֶל אֲדֹנָ\"י בְּכָל אֵיבָר, נֶאֱמַר בָּהֶם, בְּעָמְדָם תְּרַפֶּינָה כַּנְפֵיהֶם. וְזֶה סוֹד הַחַשְׁמַ\"ל, חַיּוֹת אֵשׁ, עִתִּים חָשׁוֹת, וְעִתִּים מְמַלְּלוֹת. וְאָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, בְּמַתְנִיתָא לָמַדְנוּ, כְּשֶׁהַדִּבּוּר יוֹצֵא מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא - הֵן חָשׁוֹת. וּכְשֶׁאֵין הַדִּבּוּר יוֹצֵא מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא - הֵן מְמַלְּלוֹת. בְּאוֹתוֹ זְמַן שֶׁמִּתְיַחֲדִים קוֹל וְדִבּוּר כְּאֶחָד, שֶׁהֵם יְאֲהדוָנָהי - חָשׁוֹת. אֲבָל בִּזְמַן שֶׁפְּנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת, יְהֹוָ\"ה מֵאֲדנָ\"י בְּפֵרוּד - הוּא נִמְצָא בְּאַרְבַּע פְּנֵי הַחַיּוֹת, כֻּלָּם פְּתוּחִים, לְעֻמָּתָן מְמַלְּלוֹת לִשְׁאֹל מָזוֹן מִשּׁוּם שֶׁמָּזוֹן לַכֹּל בּוֹ. אֲדֹנָ\"י נִמְצָא בְּכַנְפֵי הַחַיּוֹת, כֻּלָּם פְּתוּחִים לַחַיּוֹת.</p>\n<p>שׁוֹאֲגִים בְּקוֹל, שֶׁהוּא יְהֹוָ\"ה, כֻּלָּם בְּיָמִין. אוֹפַנִּים מְצַפְצְפִים בְּדִבּוּר, שֶׁהוּא אֲדנָ\"י, בִּשְׂמֹאל. בִּשְׂרָפִים מִתְחַבְּרִים קוֹל וְדִבּוּר בָּאֶמְצַע. יְאֲהדוָנָהי. בָּהֶם (בראשית א) וְעוֹף יְעוֹפֵף. זֶהוּ שֶׁכָּתוּב (ישעיה ו) וַיָּעָף אֵלַי אֶחָד מִן הַשְּׂרָפִים. וְנֶאֱמַר בָּהֶם, (קהלת י) וְעוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגֵּיד דָּבָר. וּשְׂרָפִים - שֵׁשׁ כְּנָפַיִם לְאֶחָד (ישעיה ו), מִצַּד הָאוֹת ו', שֶׁהוּא הָעַמּוּד הָאֶמְצָעִי, כּוֹלֵל יָמִין וּשְׂמֹאל. וְהוּא כּוֹלֵל שֵׁשׁ תֵּבוֹת - בִּשְׁתַּיִם יְכַסֶּה פָנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וּבִשְׁתַּיִם יְעוֹפֵף סִימָן.</p>\n<p>תִּקּוּן שֵׁנִי - וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. רֹשֶׁם שֶׁל סֵפֶר תּוֹרָה, וְהוּא (שם מד) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת.</p>"],[9522012492,"<p>וּפֵרְשׁוּהָ רַבָּנָן, כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע עַרְבִית וְשַׁחֲרִית כְּאִלּוּ מְקַיֵּם (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. שֶׁטַּלִּית לְבָנָה הִיא לְיָמִין, מִצַּד חֶסֶד, וְנֶאֱמַר אֵל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים וּמִתְנַהֵג בַּחֲסִידוּת. (ישעיה טז) וְהוּכַן בַּחֶסֶד כִּסֵּא. חֶסֶד עוֹלֶה ע\"ב חֻלְיוֹת וְקִשְׁרֵי הַטַּלִּית.</p>\n<p>וְיִשִׁ טַלִּית מִצַּד מְטַטְרוֹ\"ן, שֶׁהוּא טֵ\"ט, כּוֹלֵל ח\"י, בֵּין קְשָׁרִים וְחֻלְיוֹת לְכָל צַד. חֲמִשָּׁה קְשָׁרִים כְּנֶגֶד חֲמִשָּׁה חֻמְשֵׁי תוֹרָה. וּשְׁלֹשׁ עֶשְׂרֵה חֻלְיוֹת כְּנֶגֶד שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים שֶׁל הַתּוֹרָה, שֶׁנֶּאֱמַר בָּהֶן, בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הַתּוֹרָה נִדְרֶשֶׁת.</p>\n<p>וּבִגְלָלָהּ נֶאֱמַר, כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. בְּצוּרַת הַתִּפְאֶרֶת, שֶׁהוּא תִּפְאֶרֶת אָדָם עָלָיו מִלְמָעְלָה. וְנִקְרָא בִשְׁמוֹ, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו. וּלְמַעְלָה כְּמַרְאֵה אָדָם - זוֹ שְׁכִינָה, שֶׁהִיא כְּמַרְאֶה שֶׁל הָעַמּוּד הָאֶמְצָעִי בְּאַרְבָּעָה פָּנִים וּבְעֶשֶׂר סְפִירוֹת, שֶׁהֵם אָדָם. וְאַרְבָּעָה פָּנִים שֶׁל אָדָם - אַרְבַּע אוֹתִיּוֹת. וְהֵם י\"ד אוֹתִיּוֹת, וּבָהֶן (הושע יב) וּבְיַד הַנְּבִיאִים אֲדַמֶּה.</p>\n<p>וְעוֹד נִקְרָא חַ\"י מִצַּד שֶׁל צַדִּיק, וּבוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ נִקְרָא אָז אָדָם, שֶׁהוּא הָעַמּוּד הָאֶמְצָעִי, טַ\"ל, וְהַשְּׁכִינָה ה'. וּבְה' הוּא אָדָם, מִשּׁוּם שֶׁטַּ\"ל כָּךְ עוֹלֶה בְּחֶשְׁבּוֹן - יוֹ\"ד הֵ\"א וָא\"ו. וְזֶהוּ מוֹרִיד הַטַּ\"ל, לְגַבֵּי אוֹת הֵ\"א. קֶשֶׁר הַטַּלִּית - חַ\"י הָעוֹלָמִים, שֶׁקּוֹשֵׁר הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל הַצְּדָדִים בְּאַרְבַּע כַּנְפוֹת הַטַּלִּית.</p>\n<p>תְּפִלִּין מִשְּׂמֹאלוֹ, זֶהוּ שֶׁכָּתוּב (ישעיה סב) נִשְׁבַּע ה' בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ. בִּימִינוֹ - זוֹ תּוֹרָה. וּבִזְרוֹעַ עֻזּוֹ - אֵלּוּ תְּפִלִּין. יְהֹוָ\"ה בְּאַרְבַּע פָּרָשִׁיּוֹת. אֲדנָ\"י - הֵיכָל לְאַרְבַּע אוֹתִיּוֹת בְּאַרְבָּעָה בָּתֵּי הַתְּפִלִּין. קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד זֶה צַדִּיק חַ\"י הָעוֹלָמִים, שֶׁהוּא קֶשֶׁר שֶׁל שְׁנֵיהֶם, בִּזְרוֹעַ שְׂמֹאל. קֶשֶׁר שֶׁל רֹאשׁ זֶה הָעַמּוּד הָאֶמְצָעִי שֶׁאָחוּז בּוֹ יְהֹוָ\"ה אֶהְיֶ\"ה לְמַעְלָה, שֶׁהֵם (כת\"ר) חָכְמָ\"ה וּבִינָ\"ה.</p>\n<p>קְרִיאַת שְׁמַע שֶׁהִיא הַיִּחוּד בָּאֶמְצַע, וְהִיא אֲחוּזָה בֵּין צִיצִית וּתְפִלִּין, שֶׁכָּל הַפָּרָשִׁיּוֹת שֶׁל צִיצִית וּתְפִלִּין הֵן כְּלוּלוֹת בַּיִּחוּד שֶׁל קְרִיאַת שְׁמַע. וּמִצַּד שֶׁל עַמּוּד הָאֶמְצָעִי, שֶׁהוּא טַלִּית וּתְפִלִּין, שֶׁנֶּאֱמַר בָּהֶן (שמות יג) וְהָיָה לְאוֹת עַל יָדְכָה וּלְטוֹטָפֹת בֵּין עֵינֶיךְ. (במדבר טו) וְעָשׂוּ לָהֶם צִיצִת.</p>\n<p>ש' שֶׁל תְּפִלִּין, הֲלָכָה לְמֹשֶׁה מִסִּינַי. (דברים כח) וְרָאוּ כָל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ וְיָרְאוּ מִמֶּךָּ. וּבֵאֲרוּהוּ - מַהוּ שֵׁם ה'? אֵלּוּ תְּפִלִּין שֶׁבָּרֹאשׁ. ש' שֶׁל תְּפִלִּין. שְׁתֵּי שִׁינִין - שֵׁשׁ מֵאוֹת. שֵׁשׁ מַדְרֵגוֹת וְשִׁבְעָה עֲנָפִים שֶׁל שְׁתֵּי שִׁינִים - הֲרֵי שְׁלֹשָׁה עָשָׂר, וְהַכֹּל תרי\"ג. וְאֵין מִצְוָה שֶׁאֵינָהּ שְׁקוּלָה לְכָל הַתּוֹרָה.</p>\n<p>כְּגוֹן זֶה, כָּל מִצְוָה הִיא יְהֹוָ\"ה. י\"ה עִם שְׁמִ\"י - שס\"ה. ו\"ה עִם זִכְרִי - רמ\"ח. וּמִשּׁוּם זֶה כָּל מִצְוָה הִיא שְׁקוּלָה לְתרי\"ג. וַהֲרֵי פֵּרְשׁוּהוּ, שְׁמַע יִשְׂרָאֵל - כָּלוּל תרי\"ג מִצַּד שֶׁל צִיצִית. וְתרי\"ג מִצַּד שֶׁל תְּפִלִּין הוּא בְּכָל מָקוֹם.</p>\n<p>וְהָיוּ לְטוֹטָפֹת. טֹטָפֹת - ט\"ט, חַ\"י עוֹלָמִים, צַדִּיק, כְּנֶגְדּוֹ שֶׁל מְטַטְרוֹן. פַּ\"ת, תִּפְאֶרֶת. מְטַטְרוֹן סוּס שֶׁל תִּפְאֶרֶת, שֶׁבּוֹ כָּל הַסְּפִירוֹת מִתְלַבְּשׁוֹת. וְכָךְ הוּא כְּגוּף לַנְּשָׁמָה. וְכַאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא מִסְתַּלֵּק מִמֶּנּוּ, נִשְׁאָר אִלֵּם, אֵין לוֹ קוֹל וְלֹא דִבּוּר. נִמְצָא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְהַשְּׁכִינָה הֵם קוֹל וְדִבּוּר שֶׁל כָּל מַלְאָךְ וּמַלְאָךְ, וּבְכָל קוֹל וְדִבּוּר שֶׁל תּוֹרָה, וּבְכָל קוֹל שֶׁל תְּפִלָּה וּבְכָל מִצְוָה וּמִצְוָה. בְּכָל מָקוֹם שְׁלִיטָתוֹ בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים, הוּא חַיִּים שֵׁל הַכֹּל וְהוּא סוֹבֵל הַכֹּל.</p>\n<p>וְאֵיןֹ אֲדנָי בְּלֹא יְהֹוָה, כְּמוֹ שֶׁאֵין דִּבּוּר בְּלֹא קוֹל. וְאֵין קוֹל בְּלֹא דִבּוּר. וְזֶהוּ אֱמֶת בְּעוֹלַם הָאֲצִילוּת. אֲבָל בְּעוֹלַם הַפֵּרוּד יֵשׁ קוֹל בְּלֹא דִבּוּר. קֶשֶׁר שֶׁל תְּפִלִּין שַׁדַּי, אָחוּז בּוֹ הָעֶלְיוֹן וְהַתַּחְתּוֹן. וְזֶה צַדִּיק חַי הָעוֹלָמִים, אָחוּז (בו) בֵּין קוֹל וְדִבּוּר.</p>\n<p>בְּתוֹךָ כָּךְ הָרוֹעֶה הַנֶּאֱמָן נִזְדַּמֵּן אֵצֶל הַזָּקֵן וְאָמַר, זָקֵן זָקֵן, תְּפִלִּין וְצִיצִית וּפָרָשַׁת מְזוּזָה הֵן שָׁלֹשׁ מִצְווֹת כְּלוּלוֹת בַּקְּרִיאַת שְׁמַע, וּקְרִיאַת שְׁמַע הִיא מִצְוָה רְבִיעִית. וְצִיצִית מֻזְכֶּרֶת שָׁלֹשׁ פְּעָמִים. וּבַתְּפִלִּין נִזְכֶּרֶת בָּהֶן שְׁתֵּי פְעָמִים אוֹת. וּבַצִּיצִית, הָאוֹת ז' שֶׁל תִּזְכְּרוּ שֶׁצָּרִיךְ לְהַתִּיז בָּהּ. וּבַמְּזוּזָה, שַׁדַּ\"י מִבַּחוּץ, יְהֹוָה מִבִּפְנִים.</p>\n<p>וּפָרָשִׁיּוֹת סְתוּמוֹת וּפְתוּחוֹת מַדּוּעַ? וְשִׁעוּר אָרְכָּהּ שֶׁל צִיצִית וְרָחְבָּהּ, שֶׁתִּקְּנוּ אֹרֶךְ כָּל הַצִּיצִית שְׁתֵּים עֶשְׂרֵה אֶצְבָּעוֹת בְּגוּדָל. מִצְוַת תְּכֵלֶת שְׁלִישׁ גְּדִיל, וּשְׁנֵי שְׁלִישֵׁי עָנָף, וּבֵין קֶשֶׁר לְקֶשֶׁר כִּמְלֹא גוּדָל. וְכָל חֻלְיָה וְחֻלְיָה תִּהְיֶה מְשֻׁלֶּשֶׁת. וְכָךְ תְּפִלִּין מַדּוּעַ בַּמֹּחַ? וּכְנֶגֶד הַלֵּב, וְשִׁעוּר הָרְצוּעוֹת, מַדּוּעַ הֵן עַד הַלֵּב לִשְׂמֹאל וְעַד הַטַּבּוּר לְיָמִין? וּרְצוּעָה שֶׁל יָד עַד שֶׁיִּכְרֹךְ, וִישַׁלֵּשׁ שָׁלֹשׁ פְּעָמִים בָּאֶצְבַּע הָאֲרֻכָּה?</p>\n<p>אֶלָּא וַדַּאי בֶּגֶד חָשׁוּב אֵין הוּא, אֶלָּא שָׁלֹשׁ עַל שָׁלֹשׁ לְכָל צַד. וְהֵם שְׁנֵים עָשָׂר, כְּנֶגֶד אַרְבָּעָה בִּגְדֵי לָבָן וְאַרְבָּעָה בִּגְדֵי זָהָב וְאַרְבָּעָה בִּגְדֵי כֹּהֵן הֶדְיוֹט. וּמִצַּד שֶׁל בִּרְכַּת כֹּהֵן הֶדְיוֹט הוּא רוֹמֵז: אַל תְּהִי בִּרְכַּת הֶדְיוֹט קַלָּה בְּעֵינֶיךְ. שְׁלִישׁ גְּדִיל וּשְׁנֵי שְׁלִישֵׁי עָנָף, שֶׁהוּא תְּכֵלֶת.</p>\n<p>וְכָל חֻלְיָה מְשֻׁלֶּשֶׁת, כָּל מְשֻׁלָּשׁ מִצַּד הַקְּדֻשָּׁה. זֶהוּ שֶׁכָּתוּב קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. וְיִשְׂרָאֵל שְׁלִישִׁיָּה, מִשּׁוּם (שמות יד) שֶׁוְשָׁלִשִׁם עַל כֻּלּוֹ. שֶׁצִּיצִית מִצַּד הָעַמּוּד הָאֶמְצָעִי, שֶׁהוּא שְׁלִישִׁי לָאָבוֹת, וְכָל דָּבָר מְשֻׁלָּשׁ, וה\"ו יל\"י, כָּל תֵּבָה מְשֻׁלֶּשֶׁת מִצִּדּוֹ. חֻלְיָה כְּלוּלָה מִשָּׁלֹשׁ כְּרִיכוֹת מְשֻׁלָּשׁוֹת, זוֹ הַשְּׁכִינָה. קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. וְהִיא מְשֻׁלֶּשֶׁת בָּעַמּוּד הָאֶמְצָעִי, כָּלוּל מִשְּׁלֹשָׁה עַנְפֵי הָאָבוֹת, שֶׁהֵם אוֹת ש' מִשַּׁבָּת, שְׁכִינָה בַּת יְחִידָה. (מלאה מן) חֻלְיָה, תְּכֵלֶת שֶׁבַּצִּיצִית.</p>\n<p>אַשְׁרֵי הַגּוּף שֶׁכָּךְ הוּא רָשׁוּם בַּשְּׁכִינָה וְהַקָּדוֹשׁ בָּרוּךְ הוּא עַל כַּנְפֵי הַמִּצְוָה. רָשׁוּם בָּרְצוּעָה שֶׁהִיא תְּפִלָּה שֶׁל יָד בְּשָׁלֹשׁ כְּרִיכוֹת בָּאֶצְבַּע הָאֲרֻכָּה, שֶׁהִיא כְּדֻגְמַת הַחֻלְיָה, כְּרוּכָה בְּשָׁלֹשׁ כְּרִיכוֹת בָּאֶצְבַּע. רָשׁוּם בְּקֶשֶׁר שֶׁל תְּפִלִּין, כָּלוּל בִּשְׁנֵי קְשָׁרִים, עוֹלִים חֲמִשָּׁה עָשָׂר מְשֻׁלָּשִׁים, שְׁנַיִם בְּקֶשֶׁר אֶחָד.</p>\n<p>שְׁלֹש עֶשְׂרֵה חֻלְיוֹת יֵשׁ בָּהֶן תֵּשַׁע וּשְׁלֹשִׁים כְּרִיכוֹת כְּחֶשְׁבּוֹן טַ\"ל, וּשְׁלֹשׁ עֶשְׂרֵה חֻלְיוֹת כְּחֶשְׁבּוֹן אֶחָד - עוֹלִים בֵּ\"ן. וְזֶהוּ בֶּן יָ\"הּ, הָעַמּוּד הָאֶמְצָעִי.</p>\n<p>כָּל קֶשֶׁר בַּצּוּרָה שֶׁל כַּף יָמִין, כָּל חֻלְיָה בַּצּוּרָה שֶׁל אֶצְבַּע, שֶׁיֵּשׁ בָּהּ שְׁלֹשָׁה פְרָקִים כְּנֶגֶד שָׁלֹשׁ כְּרִיכוֹת. וְכָךְ בְּכָל אֶצְבַּע שְׁלֹשָׁה פְרָקִים, חוּץ מִגּוּדָל, שֶׁהוּא שִׁעוּר בֵּין קֶשֶׁר לַקֶּשֶׁר שֶׁל הַצִּיצִית כִּמְלֹא גוּדָל. הִיא מִדַּת הַחֹטֶם, וּמִדָּה שֶׁל עֵין יָמִין וּשְׂמֹאל, וְהִיא מִדָּה בֵּין עַיִן לְעַיִן, וּמִדָּה שֶׁל אֹזֶן יָמִין וּשְׂמֹאל, וּמִדָּה שֶׁל כָּל שָׂפָה וְשָׂפָה, וּמִדַּת הַלָּשׁוֹן. (שמות כו) מִדָּה אַחַת לְכָל הַיְרִיעֹת.</p>\n<p>הָאַמָּה הִיא שִׁעוּר הַגּוּף, לְאַרְבָּעָה צְדָדִים וּמַעְלָה וּמַטָּה, שֶׁהֵם שֵׁשׁ אַמּוֹת. וּבְכָל אַמָּה וְאַמָּה שְׁלֹשָׁה פְּרָקִים. ח\"י פְּרָקִים בְּשֵׁשׁ אַמּוֹת. וְהֵם סוֹד שֶׁל ח\"י נִעְנוּעִים שֶׁל הַלּוּלָב לְשִׁשָּׁה צְדָדִים, שְׁלֹשָׁה נִעְנוּעִים לְכָל צַד, וַעֲלֵיהֶם נֶאֱמַר (שיר השירים ז) זֹּאת קוֹמָתֵךְ דָּמְתָה לְתָמָר. וְזֶה שִׁעוּר קוֹמָה, מִקְוֵה יִשְׂרָאֵל בַּשְּׁכִינָה, הוּא ח\"י אַרְבַּע פְּעָמִים, שֶׁאֵלּוּ הָאַרְבַּע עוֹלִים לְשִׁבְעִים וּשְׁתַּיִם.</p>\n<p>וְסוֹד שֶׁל הַחַיּוֹת, הַקּוֹמָה שֶׁלָּהֶן - (יחזקאל א) וְגַבֵּיהֶן וְגֹבַהּ לָהֶם וְיִרְאָה לָהֶם וְגַבֹּתָם וְגוֹ'. וְגַבֵּיהֶן - אַרְבַּע חַיּוֹת שֶׁל הַמֶּרְכָּבָה הַתַּחְתּוֹנָה. וְגֹבַהּ לָהֶם - אַרְבַּע חַיּוֹת שֶׁל הַמֶּרְכָּבָה הָאֶמְצָעִית. וְגַבּתָם - אַרְבַּע חַיּוֹת שֶׁל הַמֶּרְכָּבָה הַשְּׁלִישִׁית. וְכֻלָּן שְׁתֵּים עֶשְׂרֵה. וְהֵן מְלֵאוֹת עֵינַיִם. כְּדֻגְמָא זוֹ (ראה ציור למעלה) סָבִיב לְאַרְבַּעְתָּן - יְהֹוָה יְהֹוָה יְהֹוָה.</p>"],[9522012493,"<p>וּבַעָלֵי הַקּוֹמָה רְשׁוּמִים בָּהֶם בַּתְּפִלָּה בְּאֵיזֶה מָקוֹם. אֶלָּא כָּל הַכּוֹרֵעַ - כּוֹרֵעַ בְּבָרוּךְ, וְכָל הַזּוֹקֵף - זוֹקֵף בַּשֵּׁם. זְקִיפוֹת אַרְבַּע וּכְרִיכוֹת אַרְבַּע. הֲרֵי כָּאן רוֹמֵז בְּאֵלּוּ הַזְּקִיפוֹת וְהַכְּרִיעוֹת, מוֹלִיךְ וּמֵבִיא לְמִי שֶׁאַרְבַּע רוּחוֹת הָעוֹלָם שֶׁלּוֹ, מַעֲלֶה וּמוֹרִיד לְמִי שֶׁהַשָּׁמַיִם וְהָאָרֶץ שֶׁלּוֹ. וְאֵלּוּ הֵם שִׁשָּׁה צְדָדִים - שָׁמַיִם וָאָרֶץ וְאַרְבַּע רוּחוֹת. כְּנֶגֶד שָׁלֹשׁ בְּרָכוֹת רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת. בְּעֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו - אַרְבַּע, כְּרִיעָה וּזְקִיפָה לִשְׂמֹאל, וּכְרִיעָה וּזְקִיפָה לְיָמִין. וְזֶה הוּא נוֹתֵן שָׁלוֹם לִשְׂמֹאלוֹ וִימִינוֹ. לִשְׂמֹאל רַבּוֹ, וְלִימִין רַבּוֹ.</p>\n<p>הֲרֵי הֵן שְׁתֵּים עֶשְׂרֵה בֵּין (כריכות) (כריעות) וּכְרִיעוֹת וּזְקִיפוֹת, וּבָהֶן ע\"ב עֵינַיִם. שֵׁשׁ כְּרִיעוֹת בָּהֶן שְׁמוֹנָה עָשָׂר נִעְנוּעִים, שָׁלֹשׁ בְּכָל פַּעַם, רֹאשׁ וְגוּף וְזָנָב, שֶׁצָּרִיךְ לִכְרֹעַ בִּשְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת שֶׁעוֹלוֹת שִׁבְעִים וּשְׁתַּיִם. בְּאֵלּוּ הַשִּׁבְעִים וּשְׁתַּיִם עֵינַיִם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מְאִירִים שִׁבְעִים וּשְׁתַּיִם כַּנְפֵי הַשְּׁכִינָה, וְעוֹמֶדֶת עֲלֵיהֶם, וְנִקְרֵאת עֲמִידָה. שֶׁבַּתְּחִלָּה הָיְתָה נְפִילָה, וְצָרִיךְ לְזָקְפָהּ בְּשֵׁם יְהֹוָה, בְּחַ\"י עוֹלָמוֹת, וּבְאַרְבַּע זְקִיפוֹת בְּשֵׁשׁ בְּרָכוֹת, שֶׁהוּא תִּפְאֶרֶת, כָּלוּל בְּשָׁלֹשׁ בְּרָכוֹת רִאשׁוֹנוֹת וְשָׁלֹשׁ בְּרָכוֹת אַחֲרוֹנוֹת.</p>\n<p>וְלִכְרֹעַ בְּחַ\"י עוֹלָמוֹת, וְזֶהוּ ו' ו' ו'. כָּל הַכּוֹרֵעַ - כּוֹרֵע בְּבָרוּךְ, וְכָל הַזּוֹקֵף - זוֹקֵף בְּשֵׁם יְהֹוָה. הָעַמּוּד הָאֶמְצָעִי וְצַדִּיק ו\"ו. ו' עֶלְיוֹנָה בִּינָה, בֶּן יָ\"הּ, וְאֵלּוּ רְמוּזִים בְּוַ'יִּסַּע וַ'יָּבֹא וַ'יֵּט. ו' עֶלְיוֹנָה בֶּן יָ\"הּ אָחוּז בִּזְקִיפָה וּכְרִיעָה, וְכֻלָּם עוֹלִים ח\"י בְּרָכוֹת שֶׁל הַתְּפִלָּה.</p>\n<p>אַרְבַּע כְּרִיעוֹת בְּשֵׁם אֲדנָי, אַרְבַּע זְקִיפוֹת בְּשֵׁם יְהֹוָה, הָעַמּוּד הָאֶמְצָעִי וְהַשְּׁכִינָה - חַ\"י הָעוֹלָמִים, קוֹשֵׁר אוֹתָם, וְזֶה יְאֲהַדוָנָה\"י, אָמֵן. בְּכָל בְּרָכָה מֵח\"י בְּרָכוֹת, ח\"י פְּעָמִים יְהֹוָה שֶׁהֵם ע\"ב עֵינַיִם שֶׁמְּאִירִים בְּע\"ב כְּנָפַיִם, שֶׁהֵם ח\"י פְּעָמִים אֲדנָי.</p>\n<p>וְסוֹד הַדָּבָר - וְגַבֵּיהֶן, וְגֹבַהּ לָהֶם, וְגַבּתָם. וְגַבֵּיהֶן - כְּנָפַיִם. וְגֹבַהּ לָהֶם - פָּנִים. וְגַבּתָם - שֶׁהֵם עֲלֵיהֶם. מְלֵאֹת עֵינַיִם סָבִיב לְאַרְבַּעְתָּן - כֻּלָּם מְרֻבָּעוֹת. וְהַכֹּל אֱמֶת. שִׁבְעִים עֲנָפִים (פנים) לַתּוֹרָה. כְּנָפַיִם - אֲדנָי. פָּנִים - יְהֹוָה. עֵינַיִם - אֶהְיֶה. וְעוֹלִים יב\"ק בְּחֶשְׁבּוֹן, אֲדנָי, בְּמַעֲשֶׂה. יְהֹוָה בְּדִבּוּר. אֶהְיֶה בְּמַחֲשָׁבָה.</p>\n<p>בְּכָל עַיִן וְעַיִן שִׁעוּר גּוּדָל. וְזֶה אוֹת ו' בֵּינוֹנִית. וּשְׁנֵי פְרָקִים בַּגּוּדָל הֵם י' י'. כְּנֶגֶד הַחֹטֶם אוֹת ו'. כְּנֶגֶד שְׁנֵי נְקָבִים שֶׁל הַחֹטֶם שְׁתֵּי י' י', וְעוֹלוֹת יוֹד הֵא. וְזֶה וַיִּיצֶר. שִׁעוּר שֶׁל כָּל מִדָּה וּמִדָּה - יוֹד הֵא, בְּכָל מָקוֹם שְׁלִיטָתוֹ, בְּכָל אֵבֶר וְאֵבֶר. כָּל אֵבֶר, כְּגוֹן (דברים לב) יִפְרֹשׂ כְּנָפָיו יִקָּחֵהוּ יִשָּׂאֵהוּ עַל אֶבְרָתוֹ.</p>\n<p>אֵין אֵבֶר בְּכָל מֶרְכַּבְתּוֹ שֶׁאֵין הוּא כָּל אֵבֶר בְּצוּרָתוֹ. וּבְכָל מָקוֹם נִמְצָא. (יחזקאל א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה. כְּנֶגֶד הַפָּרָשִׁיּוֹת הַפְּתוּחוֹת שֶׁל הַתְּפִלִּין. כְּנֶגֶד הַתּוֹרָה. וְכַאֲשֶׁר הֵן לְמַטָּה הֵן סְתוּמוֹת הַפָּרָשִׁיּוֹת, כְּנֶגֶד יְאֲהַדוָנָהי עֲלֵיהֶם, בְּפָנָיו וּבִכְנָפָיו.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא רָשַׁם בְּיִשְׂרָאֵל כְּנֶגְדָּם בַּתְּפִלָּה לִהְיוֹת חֲבֵרִים עִמָּהֶם, לִכְרֹעַ בְּכָל גּוּפָם, בִּשְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת שֶׁל הַתְּפִלָּה, לְהַמְלִיךְ עֲלֵיהֶם אָמֵן, וְהוּא יְאֲהַדוָנָהי, בְּכָל אֵבֶר וְאֵבֶר שֶׁלָּהֶם. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִי שֶׁלֹּא יִהְיֶה רָשׁוּם לִפְנֵיכֶם לִהְיוֹת כּוֹרֵעַ בְּבָרוּךְ וְזוֹקֵף בַּיהֹוָה בְּקוֹמַת הַגּוּף, לֹא תִכָּנֵס תְּפִלָּתוֹ בַּהֵיכָל שֶׁלִּי, שֶׁהוּא אֲדנָי. לֹא תְקַבְּלוּ דִבּוּרִים שֶׁלּוֹ עַל כַּנְפֵיכֶם וּפְנֵיכֶם. שֶׁכָּל מִי שֶׁמִּתְפַּלֵּל בַּאדנָי, וּמְצָרֵף לַיהֹוָה פָּנִים (ענפים) שֶׁל הַמַּלְאָכִים, וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת לְמַעְלָה, (לטל) יְאֲהַדוָנָהי, בְּדִבְרֵי הַתְּפִלָּה שֶׁיּוֹצְאִים מִפִּיו שֶׁל הָאָדָם.</p>\n<p>וְגָדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מִן הַמְבָרֵךְ. שֶׁלְּגַבֵּי אֲדנָי יְהֹוָה בַּתְּפִלָּה נֶאֱמַר וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת. כְּנֶגֶד יְהֹוָה בַּפָּנִים, אֲדֹנָי בַּכְּנָפַיִם, (שמות כה) כְּרוּב אֶחָד מִקָּצָה מִזֶּה וּכְרוּב אֶחָד מִקָּצָה מִזֶּה. אֲבָל כַּאֲשֶׁר חוֹזֵר שְׁלִיחַ צִבּוּר הַתְּפִלָּה וְעוֹנֶה אָמֵן, הוּא בַּמַּחְבֶּרֶת הַשֵּׁנִית, מִתְחַבְּרִים שְׁנֵי שֵׁמוֹת בַּמַּחְבֶּרֶת הַשֵּׁנִית. בַּתְּחִלָּה - (שמות לו) מַקְבִּילֹת הַלֻּלָאֹת אַחַת אֶל אֶחָת וְגוֹ' בַּקְּרָסִים, שֶׁהֵם קִשְׁרֵי הָאֶצְבָּעוֹת. אֲבָל בְּאָמֵן - (שם כו) וְהָיָה הַמִּשְׁכָּן אֶחָד, שֶׁבּוֹ חוֹבְרוֹת אִשָּׁה אֶל אֲחֹתָהּ.</p>"],[9522012494,"<p>הַתִּקּוּן הַשְּׁלִישִׁי סֵדֶר הַדִּבּוּר (חדר של הדבור) שֶׁל הַתְּפִלָּה, שֶׁבּוֹ חַיּוֹת אֵשׁ מְמַלְּלוֹת. וְזֶהוּ (יחזקאל א) וָאֵרֶא כְּעֵין חַשְׁמַל כְּמַרְאֵה אֵשׁ בֵּית לָהּ סָבִיב. זֶהוּ סוֹד הַחַשְׁמַל, שֶׁהֵן חַיּוֹת אֵשׁ, עִתִּים שׁוֹתְקוֹת עִתִּים מְדַבְּרוֹת. וְהֵן שׁוֹתְקוֹת לַסֵּפֶר תּוֹרָה בִּזְמַן שֶׁדִּבּוּר יוֹצֵא מִפִּי הַקּוֹרֵא. הוּא נֶחְשָׁב לָהֶן כְּאִלּוּ מְקַבְּלִים הַתּוֹרָה בְּהַר סִינַי. וּבִזְמַן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אָנֹכִי - לֹא נִשְׁמַע קוֹל וְלֹא דִבּוּר אַחֵר שֶׁל הַחַיּוֹת אֶלָּא שֶׁלּוֹ.</p>\n<p>כְּגוֹן זֶה, כַּאֲשֶׁר דִּבּוּר זֶה יוֹצֵא מִפִּיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, חַיּוֹת אֵשׁ שׁוֹתְקוֹת. וּבִזְמַן שֶׁשּׁוֹתֵק - חַיּוֹת אֵשׁ מְדַבְּרוֹת. זֶהוּ שֶׁכָּתוּב (שמות כ) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת, קוֹלוֹת שֶׁל הַחַיּוֹת שֶׁהָיוּ שׁוֹאֲגוֹת. וְאֶת הַלַּפִּידִם - שֶׁהָיוּ יוֹצְאִים בַּדִּבּוּר שֶׁל הַחַיּוֹת בְּכַמָּה מִינֵי נִגּוּנִים לִפְנֵי הַמֶּלֶךְ. וְאֵלּוּ שֶׁהֵן שׁוֹתְקוֹת לַסֵּפֶר תּוֹרָה, הֵן בַּצּוּרָה שֶׁל הַחַיּוֹת. וּמְמַנֶּה לָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲלוֹת אוֹתָן בְּחֶדֶר שֶׁל מַרְאֵה אֵשׁ בֵּית לָהּ.</p>\n<p>וְעוֹד, שֶׁאֵלּוּ שֶׁשּׁוֹתְקוֹת (ועוד אלו שיוצא מהם דבורבתפלה שבו חיות אש מדברות והן שותקות) בַּתְּפִלָּה בְּח\"י בְּרָכוֹת, יִכָּנְסוּ בְּחֶדֶר שֶׁל מַרְאֶה זֶה. וְעוֹד, אֵלּוּ שֶׁשּׁוֹתְקִים לַהֲלָכָה, שֶׁנֶּאֱמַר בָּהּ שְׂכַר הַשְּׁמוּעָה הֲבָנָה, יִכָּנְסוּ בְּחֶדֶר שֶׁהוּא הֵיכָל שֶׁל מַרְאֶה זֶה, שֶׁהַתּוֹרָה, עָלֶיהָ נֶאֱמַר (ירמיה כג) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה' וּכְפַטִּישׁ יְפֹצֵץ סָלַע. וְזֶה הַסֶּלַע שֶׁנֶּאֱמַר בּוֹ (במדבר כ) וְדִבַּרְתֶּם אֶל הַסֶּלַע לְעֵינֵיהֶם וְנָתַן מֵימָיו. אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בָּהּ לִשְׁמָהּ, יוֹצֵא לָהֶם מַיִם שֶׁל הַתּוֹרָה מְתוּקִים, וְנֶאֱמַר בָּהֶם (שם) וַתֵּשְׁתְּ הָעֵדָה וּבְעִירָם. וְאֵלּוּ שֶׁלֹּא מִשְׁתַּדְּלִים בָּהּ לִשְׁמָהּ, יוֹצֵא לָהֶם מַיִם מָרִים, שֶׁנֶּאֱמַר בָּהֶם (שמות א) וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבדָה קָשָׁה - זֶה קֻשְׁיָה. בְּחֹמֶר - זֶה קַל וָחֹמֶר. וּבִלְבֵנִים - בְּלִבּוּן הֲלָכָה.</p>"],[9522012495,"<p>תִּקּוּן רְבִיעִי וַחֲמִישִׁי - (יחזקאל א) מִמַּרְאֵה מָתְנָיו וּלְמָעְלָה וּמִמַּרְאֵה מָתְנָיו וּלְמַטָּה. שֶׁבָּהֶם שׁוֹקֵי הַחַיּוֹת כְּנֶגֶד כֻּלָּם, וּבִסְפִירוֹת נֵצַח וְהוֹד. מְטַטְרוֹן הוּא אוֹת בַּצָּבָא שֶׁלּוֹ, וְהוּא צוּרַת הַצַּדִּיק. שֶׁהַצַּדִּיק הוּא אוֹת בַּצָּבָא שֶׁל מַעְלָה, וּמְטַטְרוֹן הוּא אוֹת בַּצָּבָא שֶׁל מַטָּה. מְטַטְרוֹן שַׁדַּי בּוֹ נֶאֱמַר, (שם) וְהַחַיּוֹת רָצוֹא וָשׁוֹב כְּמַרְאֵה הַבָּזָק.</p>\n<p>וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה - שֶׁרַגְלֵיהֶם שֶׁל הַמַּזִּיקִים כֻּלָּם עֲקַלָּתוֹן. וְרַגְלֵיהֶם - וְהָרַגְלַיִם שֶׁל חַיּוֹת הַקֹּדֶשׁ, נֶאֱמַר בָּהֶן וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה, מִצַּד חַיָּה שֶׁהִיא יִשְׂרָאֵל, יִשְׂרָאֵל כָּלוּל בְּשָׁלֹשׁ חַיּוֹת, שֶׁנֶּאֱמַר בָּהֶם, הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה.</p>\n<p>וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עֵגֶל (שם) - מִצַּד הַחַיָּה שֶׁהִיא שׁוֹר. וְנֹצְצִים כְּעֵין נְחֹשֶׁת קָלָל - מִצַּד הַנָּחָשׁ בָּרִיחַ שֶׁל הַיָּם, שֶׁהוּא עוֹלֶה אֵצֶל זֶה שֶׁבַּיַּבָּשָׁה. רָצוֹא - מִצִּדּוֹ שֶׁל נוּרִיאֵל שֶׁעוֹלֶה גִּימַטְרִיָּא רָצוֹ\"א. וָשׁוֹב - מִצַּד שֵׁם שַׁדַּ\"י, שֶׁכָּךְ עוֹלֶה בְּחֶשְׁבּוֹן. וְהוּא עוֹלֶה מְטַטְרוֹן.</p>\n<p>וְכַאֲשֶׁר הָיוּ יִשְׂרָאֵל שׁוֹמְעִים קוֹל מִמִּזְרָח, הָיוּ רָצִים שָׁם. וְלַמַּעֲרָב כָּךְ, וְכֵן לַדָּרוֹם וְלַצָּפוֹן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַלְאֲכֵי הַשָּׁרֵת: אֵלּוּ שֶׁרָצִים לִתְפִלָּה שֶׁל מִצְוָה, וְרָצִים לִדְרָשָׁה בְּשַׁבָּת, וְרָצִים לַעֲשׂוֹת רָצוֹן שֶׁלִּי וְשָׁבִים בִּתְשׁוּבָה - קַבְּלוּ אוֹתָם בַּהֵיכָל שֶׁל זֶה הַמַּרְאֶה, שֶׁבְּאֵלּוּ הַסִּימָנִים הֵם חֲבֵרִים אִתְּכֶם. אֵלּוּ שֶׁרָצִים וְשָׁבִים בַּתּוֹרָה, בְּדִבּוּר שֶׁל הֲלָכָה, הֵם רְשׁוּמִים אִתְּכֶם, וְתַכְנִיסוּ אוֹתָם בַּהֵיכָל הַזֶּה.</p>\n<p>כָּךָ כַּאֲשֶׁר מִתְפַּלְלִים יִשְׂרָאֵל, מִיכָאֵ\"ל עָף הָעוֹלָם בְּמָעוֹף אֶחָד. וְגַבְרִיאֵ\"ל עָף בִּשְׁתֵּי עֲפִיפוֹת. וְכַאֲשֶׁר יוֹצֵא דִבּוּר מִיִּשְׂרָאֵל בַּהֲלָכָה, בִּתְפִלָּה וּבְכָל מִצְוָה שֶׁהַשְּׁכִינָה שָׁם - הֵם רָצִים אֶצְלָהּ וְשָׁבִים בָּהּ בִּשְׁלִיחוּת קוֹנָם. וּבְכָל מָקוֹם שֶׁשּׁוֹמְעִים קוֹל הַתּוֹרָה, שֶׁשָּׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, הֵם רָצִים אֵצֶל הַקּוֹל הַהוּא, וְשָׁבִים בָּהּ בִּשְׁלִיחוּת קוֹנָם. שֶׁבְּכָל קוֹל שֶׁשֵּׁם יְהֹוָ\"ה אֵינוֹ שָׁם, וּבְדִבּוּר שֶׁאֵין שָׁם אֲדנָי, לֹא רָצִים וְשָׁבִים שָׁם. וּמִשּׁוּם זֶה, וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה, (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה'. בְּמָקוֹם שֶׁשֵּׁם יְהֹוָ\"ה שָׁם, הִיא דֶּרֶךְ יְשָׁרָה. וְאִם אֵין שָׁם יְהֹוָ\"ה, אֵין הִיא דֶּרֶךְ יְשָׁרָה.</p>\n<p>וְעוֹד רַגְלֵיהֶם רֶגֶל יְשָׁרָה - אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁמִּי שֶׁמִּתְפַּלֵּל צָרִיךְ לְתַקֵּן רַגְלָיו בִּתְפִלָּתוֹ כְּמַלְאֲכֵי הַשָּׁרֵת. כְּכַף רֶגֶל עֵגֶל, לִהְיוֹת רָשׁוּם עִמָּהֶם. וּמִשּׁוּם זֶה פֵּרְשׁוּהוּ חֲכָמִים, הַמִּתְפַּלֵּל צָרִיךְ לְכַוֵּן אֶת רַגְלָיו, שֶׁנֶּאֱמַר וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עֵגֶל. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֵלּוּ שֶׁהֵם רְשׁוּמִים בַּתְּפִלָּה כָּךְ, לְכַוֵּן רַגְלָיו כְּמוֹתְכֶם - פִּתְחוּ לוֹ שַׁעֲרֵי הַהֵיכָל לְהִכָּנֵס בְּמַרְאָה זוֹ.</p>"],[9522012496,"<p>תִּקּוּן שִׁשִּׁי - (יחזקאל א) רָאִיתִי כְּמַרְאֵה אֵשׁ. כָּאן רְאִיָּה מַמָּשׁ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִי שֶׁיִּכָּנֵס בְּמַרְאֶה זֶה, וְיִהְיֶה בִתְפִלָּתוֹ לִבּוֹ לְמַעְלָה לְשֵׁם יְהֹוָ\"ה, וְעֵינָיו לְמַטָּה בַּשֵּׁם שֶׁל אֲדנָ\"י, תַּכְנִיסוּהוּ בַּהֵיכָל הַזֶּה כְּמוֹ הַמַּלְאָכִים, וְגַבֵּיהֶן - לְמַעְלָה, וְיִרְאָה לָהֶם - לְמַטָּה, כְּנֶגֶד הַשְּׁכִינָה שֶׁהִיא יִרְאַת יְהֹוָ\"ה.</p>\n<p>וּבִרְאִיָּה וּשְׁמִיעָה וְרֵיחַ וְדִבּוּר שׁוֹרֶה שֵׁם יְהֹוָ\"ה. בַּעֲשִׂיָּה, בְּמִשּׁוּשׁ, שִׁמּוּשׁ, הִלּוּךְ, שׁוֹרֶה שֵׁם אֲדנָי. וְזוֹ רְאִיָּה שֶׁל אוֹר וְנֵר (של התורה), שֶׁנֶּאֱמַר בָּהּ (משלי ו) וְתוֹרָה אוֹר. רֵיחַ הַקָּרְבָּנוֹת, שֶׁהֵם תְּפִלּוֹת, דִּבּוּר - בַּתּוֹרָה, דִּבּוּר בִּתְפִלָּה. וַעֲשִׂיָּה שֶׁל מִצְוָה, וְשִׁמּוּשׁ שֶׁלָּהּ, וּמִשּׁוּשׁ שֶׁלָּהּ, וְהִלּוּךְ שֶׁלָּהּ. וּרְאִיָּה וּשְׁמִיעָה שֶׁאֵין שָׁם תּוֹרָה וּמִצְוָה, הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ אֵינָהּ שׁוֹרָה שָׁם. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹרֶה בִּרְאִיָּה, וְכֵן הַשְּׁכִינָה, שֶׁהַתּוֹרָה - וְתוֹרָה אוֹר, וְהַשְּׁכִינָה הִיא רְאִיָּה שֶׁלּוֹ, (במדבר יב) ה' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע (הקדוש ברוך הוא במראה אליו אתודע שכינתו).</p>\n<p>בַּמַּחֲשָׁבָה מִבִּפְנִים בִּינָה - בֶּן יָ\"הּ. יִשְׂרָאֵל עָלָה בְמַחֲשָׁבָה. הִרְהוּר חָכְמָה, לֶחָכָם בְּרֶמֶז. חָכְמָה עָלָה בְמַחֲשָׁבָה, שֶׁהוּא בִּינָה. מַחֲשָׁבָה וְהִרְהוּר הַכֹּל אֶחָד. הַחָכְמָה לֹא נוֹדַעַת אֶלָּא בְּבִינָה, וְהַבִּינָה בַּלֵּב. וּמִשּׁוּם זֶה הַמַּחֲשָׁבָה בַּלֵּב, הַהִרְהוּר בַּלֵּב.</p>\n<p>וְכֵן הַתּוֹרָה - סֵפֶר תּוֹרָה, מִצְוָה לִשְׁמֹעַ. וְכֵן בַּחֹטֶם, רֵיחַ נִיחֹחַ לַה'. הַשְּׁכִינָה הִיא קָרְבָּן שֶׁלּוֹ, עוֹלָה שֶׁלּוֹ, וְהַתְּפִלָּה הִיא כְּמוֹ קָרְבָּן, וְעוֹלָה כְּרֵיחַ נִיחֹחַ אֶצְלוֹ וּמִתְקָרֶבֶת אֶצְלוֹ בִּתְפִלָּה. וְכֵן בְּדִבּוּר - (ירמיה כג) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. אוֹת ה' - שְׁכִינָה, דִּבּוּר שֶׁלּוֹ.</p>\n<p>כְּמוֹ שֶׁהַשְּׁכִינָה הִיא מַרְאָה שֶׁלּוֹ, שְׁמִיעָה שֶׁלּוֹ, רֵיחַ נִיחֹחַ שֶׁלּוֹ, דִּבּוּר שֶׁלּוֹ, בָּרֹאשׁ - כָּךְ הוּא בַּיָּדַיִם עֲשִׂיַּת מִצְוָה שֶׁלּוֹ, בַּגּוּף כְּרִיעָה שֶׁלּוֹ. בַּתְּפִלָּה זְקִיפָה שֶׁלּוֹ, בַּתְּפִלָּה עֲמִידָה שֶׁלּוֹ (שהיא מזל שלו), שֶׁהִיא שֶׁעוֹמֶדֶת לְפָנָיו בְּכָל מָקוֹם וְכוֹרַעַת לְגַבָּיו וְנוֹפֶלֶת לְרַגְלָיו בִּנְפִילַת אַפַּיִם לִשְׁאֹל מִמֶּנּוּ רַחֲמִים עַל בָּנֶיהָ. הִיא עֲנָוָה לְגַבָּיו, וְיֵשׁ לָהּ בּשֶׁת פָּנִים מִמֶּנּוּ.</p>\n<p>וְלֹא כְּמוֹ שִׁפְחָה רָעָה, לִילִית, חֲצוּפָה בְּלִי עֲנָוָה, אֵין לָהּ בֹּשֶׁת פָּנִים, אִמָּם שֶׁל הָעֵרֶב רַב, וּמִשּׁוּם זֶה אָמַר שְׁלֹמֹה, (משלייב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ וּכְרָקָב בְּעַצְמוֹתָיו מְבִישָׁה. שֶׁהַשְּׁכִינָה הִיא מַלְכָּה. הַשִּׁפְחָה שֶׁלָּהּ לִילִית, אֵין לָהּ עֲנָוָה וְלֹא בֹּשֶׁת פָּנִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. וְכָךְ בָּנֶיהָ עֵרֶב רַב. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַעֲבִיר אוֹתָהּ וְאֶת בָּנֶיהָ מֵהָעוֹלָם, שֶׁמַּמְזֵרִים הֵם מִבְּנֵי ט' מִדּוֹת - אסנ\"ת משגח\"ת (ראשי תבות', אנוס\"ה, שנוא\"ה, נדוי, תמורה, מורדת, שכורה, גרושת הלב, חצופה, תערבת), מַמְזֵרִים מִדְּרַבָּנָן.</p>\n<p>וְכֵן שְׁכִינָה הִיא שִׁמּוּשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הַיִּחוּד שֶׁלּוֹ עַל יְדֵי הַצַּדִּיק חַי הָעוֹלָמִים. וְהִיא הַהֲלִיכָה שֶׁלּוֹ, (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ, לַעֲשׂוֹת רְצוֹנוֹ. (בראשית כד) וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יֹצֵאת, רָצָה לִקְרָאתוֹ לַעֲשׂוֹת רְצוֹנוֹ. בִּרְאִיָּה, בִּשְׁמִיעָה, בְּרֵיחַ, בְּדִבּוּר, בַּעֲשִׂיָּה, בְּגוּף, בְּשִׁמּוּשׁ, בְּהִלּוּךְ, בְּכָל אֵבֶר הִיא מְצֻוָּה לְשַׁמֵּשׁ אוֹתוֹ וְלַעֲשׂוֹת רְצוֹנוֹ.</p>\n<p>וּבָנֶיהָ, כָּךְ הֵם בְּצוּרָתָהּ; בְּנֵי עֲנָוָה, בְּנֵי בּשֶׁת פָּנִים. כֻּלָּם כְּמוֹ הַמִּדּוֹת שֶׁלָּהּ. וּמִשּׁוּם זֶה צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, (שמות יח) וְאַתָּה תֶחֱזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים אַנְשֵׁי אֱמֶת שֹׂנְאֵי בָצַע. אַנְשֵׁי חַיִל - מִצַּד יָמִין שֶׁל אַבְרָהָם, שֶׁשָּׁם רְאִיָּה שֶׁל הַתּוֹרָה, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. יִרְאֵי אֱלֹהִים - מִצַּד שֶׁל יִצְחָק, שֶׁשָּׁם שְׁמִיעָה, שֶׁאָמַר חֲבַקּוּק הַנָּבִיא, (חבקוק ג) ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי. אַנְשֵׁי אֱמֶת - מִצַּד שֶׁל יַעֲקֹב, שֶׁשָּׁם רֵיחַ נִיחֹחַ לַה', בַּחֹטֶם. שּׁנְאֵי בָצַע - מִצַּד שֶׁל הַדִּבּוּר, רֶגֶל רְבִיעִית שֶׁל אָדָם הָרִאשׁוֹן שֶׁהִתְחַבֵּר בָּאָבוֹת. שָׁלֹשׁ חַיּוֹת הֵן: אַרְיֵה שׁוֹר נֶשֶׁר, בִּרְאִיָּה שְׁמִיעָה רֵיחַ. אָדָם - בְּדִבּוּר.</p>\n<p>וְשַׂמְתָּ עֲלֵהֶם שָׂרֵי אֲלָפִים - מִצַּד הָאוֹת א'. וְשָׂרֵי מֵאוֹת - מִצַּד הָאוֹת ד', אַרְבַּע מֵאוֹת שָׁנָה שֶׁנִּשְׁתַּעְבְּדוּ יִשְׂרָאֵל בְּמִצְרַיִם (בעניות של תורה). שָׂרֵי חֲמִשִּׁים - אוֹת נ'. וְשָׂרֵי עֲשָׂרֹת - אוֹת י'.</p>\n<p>יִשְׂרָאֵל - בְּאֵלּוּ הַמִּדּוֹת נִכָּרִים, שֶׁהֵם בָּנִים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ לִהְיוֹת בָּהֶם אַנְשֵׁי חַיִל, כְּגוֹן אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ, בַּעֲלֵי חֶסֶד. יִרְאֵי אֱלֹהִים. אַנְשֵׁי אֱמֶת, וְלֹא אַנְשֵׁי שֶׁקֶר, שֶׁבְּנֵי (צפניה ג) יִשְׂרָאֵל לֹא יַעֲשׂוּ עַוְלָה וְלֹא יְדַבְּרוּ כָזָב וְלֹא יִמָּצֵא בְפִיהֶם לְשׁוֹן תַּרְמִית. וְשּנְאֵי בָצַע - כְּאָדָם הַשָּׂמֵחַ בְּחֶלְקוֹ. וְלֹא כְּעֵרֶב רַב בְּנֵי הַשִּׁפְחָה הָרָעָה, שֶׁהֵם כְּנָחָשׁ שֶׁכָּל הָאָרֶץ לְפָנָיו. זֶהוּ שֶׁכָּתוּב (ישעיה סה) וְנָחָשׁ עָפָר לַחְמוֹ, וּמְפַחֵד לִשְׂבֹּעַ מֵהֶעָפָר, שֶׁמְּפַחֵד שֶׁיֶּחְסַר לוֹ. וְכָךְ בַּעֲלֵי בֶצַע, שֶׁלֹּא שְׂבֵעִים מִכָּל מָמוֹן שֶׁבָּעוֹלָם.</p>\n<p>וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, לֹא הַמִּדְרָשׁ הוּא הָעִקָּר אֶלָּא הַמַּעֲשֶׂה. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא סָתוּם בְּסִתְרֵי הַתּוֹרָה, בַּמֶּה מִתְגַּלֶּה? בַּמִּצְווֹת, שֶׁהִיא שְׁכִינָה, שֶׁהִיא צוּרָתוֹ. כְּמוֹ שֶׁהוּא עָנָו - שְׁכִינָתוֹ עֲנָוָה. הוּא חָסִיד - וְהִיא חֲסִידָה. הוּא גִּבּוֹר - וְהִיא גְּבֶרֶת עַל כָּל אֻמּוֹת הָעוֹלָם. שֶׁהוּא אֱמֶת - וְהִיא אֱמוּנָה. הוּא נָבִיא - וְהִיא נְבִיאָה. הוּא צַדִּיק - וְהִיא צַדֶּקֶת. הוּא מֶלֶךְ - וְהִיא מַלְכוּת. הוּא חָכָם - וְהִיא חֲכָמָה. הוּא מֵבִין - וְהִיא הַתְּבוּנָה שֶׁלּוֹ. הוּא כֶּתֶר - וְהִיא עֲטָרָה שֶׁלּוֹ, עֲטֶרֶת תִּפְאֶרֶת. וּמִשּׁוּם זֶה פֵּרְשׁוּהוּ חֲכָמִים, כָּל מִי שֶׁאֵין תּוֹכוֹ כְּבָרוֹ אַל יִכָּנֵס לְבֵית הַמִּדְרָשׁ. כִּדְמוּת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא תּוֹכוֹ, וְהַשְּׁכִינָה הִיא בָּרוֹ. הוּא תּוֹכוֹ מִבִּפְנִים - וְהִיא בָּרוֹ מִבַּחוּץ. וְלֹא מִשְׁתַּנֵּית הִיא שֶׁבַּחוּץ מֵאוֹתוֹ שֶׁבִּפְנִים לִהְיוֹת יָדוּעַ שֶׁהִיא אֲצִילוּתוֹ, וְאֵין פֵּרוּד שָׁם כְּלָל, (שמות כה) שֶׁמִּבַּיִת וּמִחוּץ תְּצַפֶּנּוּ.</p>\n<p>וּמִשּׁוּם שֶׁהוּא יְהֹוָה, סָתוּם מִבִּפְנִים, וְלֹא נִקְרָא אֶלָּא בִּשְׁכִינָתוֹ, אֲדנָי. וּמִשּׁוּם זֶה אָמְרוּ חֲכָמִים, לֹא כְשֶׁאֲנִי נִכְתָּב אֲנִי נִקְרָא. בָּעוֹלָם הַזֶּה נִכְתָּב אֲנִי בַּיהֹוָ\"ה, וְנִקְרָא אֲנִי בַּאדֹנָ\"י. אֲבָל בָּעוֹלָם הַבָּא נִכְתָּב בַּיהֹוָ\"ה, וְנִקְרָא בַיהֹוָ\"ה, לִהְיוֹת רַחֲמִים מִכָּל צַד. וּמִשּׁוּם זֶה צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַלְאֲכֵי הַשָּׁרֵת: מִי שֶׁלֹּא יִהְיֶה תוֹכוֹ כְּבָרוֹ בְּכָל אֵיבָרִים פְּנִימִיִּים וְחִיצוֹנִיִּים - לֹא יִכָּנֵס בְּהֵיכָל זֶה. וּמִשּׁוּם זֶה אָמַר הַפָּסוּק, (דברים לב) הַצּוּר תָּמִים פָּעֳלוֹ. (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ.</p>"],[9522012497,"<p>הַתִּקּוּן הַשְּׁבִיעִי - (יחזקאל א) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם. אָמְרוּ חֲכָמִים, מִן וָאֵרֶא עַד כְּמַרְאֵה הַקֶּשֶׁת, הֵן הֵן מַעֲשֵׂה הַמֶּרְכָּבָה. וְאָמְרוּ חֲכָמִים, כְּשֶׁהָיָה רַבִּי עֲקִיבָא דּוֹרֵשׁ בְּמַעֲשֵׂה מֶרְכָּבָה, יָרְדָה אֵשׁ מִן הַשָּׁמַיִם וְסִבְּבָה הָאִילָנוֹת, וְהָיוּ מִתְקַבְּצִים מַלְאֲכֵי הַשָּׁרֵת כִּבְשִׂמְחַת חָתָן וְכַלָּה, בִּגְלַל שֶׁאֵין יִחוּד וְקִשּׁוּר וּמֶרְכָּבָה לְשֵׁם יְהֹוָ\"ה בַּאדנָ\"י אֶלָּא עַל יְדֵי הַצַּדִּיק. שֶׁהוּא קֶשֶׁת, שֶׁהִיא (שבו) מֶרְכָּבָה שְׁלֵמָה שֶׁלְּמַעְלָה - יְאֲהַדוָנָה\"י.</p>\n<p>שְׁכִינָה הִיא מַעֲשֵׂה בְרֵאשִׁית, וּבֵאֲרוּהוּ, אֵין דּוֹרְשִׁין בְּמַעֲשֵׂה בְרֵאשִׁית בִּשְׁנַיִם. מִשּׁוּם שֶׁעַנְפֵי הָאִילָן הֵם פְּרוּדִים מִלְמַעְלָה בְּכַנְפֵי הַחַיּוֹת - יְהֹוָ\"ה לְיָמִין, אֲדנָ\"י לִשְׂמֹאל. חָתָן לְיָמִין, כַּלָּה לִשְׂמֹאל. כַּאֲשֶׁר מְבִיאִים אוֹתָהּ לַחֻפָּה, בְּכַמָּה מִינֵי נִגּוּנִים צְרִיכִים יִשְׂרָאֵל לְעוֹרֵר אוֹתָם לְמַטָּה, בְּשִׁירוֹת וְתִשְׁבָּחוֹת, בְּכָל מִינֵי נִגּוּן, בִּתְפִלָּה הִנֵּה הֵם בָּאִים לַחֻפָּה.</p>\n<p>וּצְרִיכִים יִשְׂרָאֵל לָתֵת קִדּוּשִׁין לַכַּלָּה מֵהֶחָתָן בִּקְשִׁירַת תְּפִלָּה שֶׁל יָד, לִהְיוֹתָהּ קְשׁוּרָה לוֹ, וּלְעַטֵּר אוֹתָם בִּתְפִלִּין שֶׁל רֹאשׁ, שֶׁהִיא פְּאֵר. זֶהוּ שֶׁכָּתוּב (יחזקאל כד) פְּאֵרְךְ חֲבוֹשׁ עָלֶיךְ. וְשָׁלֹשׁ כְּרִיכוֹת שֶׁל רְצוּעָה כְּנֶגֶד שָׁלֹשׁ קְדֻשּׁוֹת, שֶׁהֵן קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, (רצועה) קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. וְצָרִיךְ לְבָרֵךְ אוֹתָן בְּשֶׁבַע בְּרָכוֹת, שֶׁהֵן שֶׁבַע בְּרָכוֹת שֶׁל קְרִיאַת שְׁמַע - בַּשַּׁחַר שְׁתַּיִם לְפָנֶיהָ וְאַחַת לְאַחֲרֶיהָ, וּבָעֶרֶב שְׁתַּיִם לְפָנֶיהָ וּשְׁתַּיִם לְאַחֲ רֶיהָ.</p>\n<p>וְכַלָּה בְּחֻפָּה, שֶׁהִיא בְּצוּרַת כַּנְפֵי מִצְוָה, בְּצִיצִיּוֹת מֻזְהָבוֹת, וּתְכֵלֶת וְלָבָן, כִּסֵּא דִין וְכִסֵּא רַחֲמִים, כָּלוּל זֶה בָּזֶה. וְכַמָּה קְשָׁרִים וְחֻלְיוֹת סְבִיבָהּ, בְּכַמָּה מַרְגָּלִיּוֹת וַאֲבָנִים יְקָרוֹת מְלֵאוֹת סְגֻלּוֹת, סוֹבְבִים אֶצְלוֹ כִּדְמוּת פַּעֲמוֹנִים וְרִמּוֹנִים שֶׁל לְבוּשֵׁי הַמֶּלֶךְ וְהַמַּלְכָּה, שֶׁהֵם אַרְבָּעָה בִּגְדֵי לָבָן וְאַרְבָּעָה בִּגְדֵי זָהָב, מִצַּד שֶׁל שְׁנֵי שֵׁמוֹת - יְהֹוָ\"ה אֲדנָ\"י. כִּשְׁמוֹ כֵּן כִּסְאוֹ, כֵּן חֻפָּתוֹ, כֵּן לְבוּשׁוֹ. רָשׁוּם שְׁמוֹ בַּכֹּל כַּאֲשֶׁר רוֹצֶה לַעֲלוֹת בַּהֵיכָל לִהְיוֹת שָׁם חָתָן בְּכַלָּתוֹ בְּח\"י בִּרְכוֹת הַתְּפִלָּה, שֶׁהִיא (בהיכל להתיחד שם בתפלה בח\"י ברכות של הצדיק שהוא) כְּמַרְאֵה הַקֶּשֶׁת.</p>"],[9522012498,"<p>אֵין דּוֹרְשִׁין בַּמֶּרְכָּבָה בְּיָחִיד, מִשּׁוּם שֶׁהַדּוֹרֵשׁ - יָחִיד עִמּוֹ, וַהֲרֵי הֵם שְׁנַיִם בַּדְּרָשָׁה. וְלֹא צָרִיךְ לְהַשְׁמִיעַ קוֹל בִּתְפִלָּתוֹ, אֶלָּא (שמואל א א) רַק שְׂפָתֶיהָ נָעוֹת וְקוֹלָהּ לֹא יִשָּׁמֵעַ. וּבְסוֹד זֶה (במדבר ג) וְהַזָּר הַקָּרֵב יוּמָת. וְכָךְ בַּאֲצִילוּת (בתפלה) כָּל אֶחָד מִתְפַּלֵּל בַּחֲשַׁאי, שֶׁלֹּא תִשָּׁמַע תְּפִלָּתוֹ לְגַבֵּי חֲבֵרוֹ. כְּמוֹ מִי שֶׁדּוֹרֵשׁ לַחֲבֵרוֹ, וְיַשְׁתִּיק הַדִּבּוּר לַחֲבֵרוֹ, לֹא צָרִיךְ לַעֲשׂוֹת כָּךְ אֶלָּא לְדַבֵּר בַּחֲשַׁאי, שֶׁלֹּא יִשְׁמַע חֲבֵרוֹ. וּמִשּׁוּם זֶה פֵּרְשׁוּהוּ חֲכָמִים, כָּל הַמַּשְׁמִיעַ קוֹלוֹ בִּתְפִלָּתוֹ הֲרֵי זֶה מִקְּטַנֵּי אֲמָנָה.</p>\n<p>וּמִשּׁוּם זֶה חַיּוֹת אֵשׁ לְמַעְלָה, מְדַבְּרוֹת כְּעַנְפֵי הָאִילָן, שֶׁהָיוּ מִתְקַבְּצוֹת שָׁם כְּמוֹ בְּשִׂמְחַת חָתָן וְכַלָּה. בְּאֵיזֶה מָקוֹם? בִּקְרִיאַת שְׁמַע, שֶׁשָּׁם וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם, שֶׁהֵם ס\"ד לְאַרְבַּע כְּנָפַיִם, אַרְבַּע פְּעָמִים ס\"ד עוֹלִים רנ\"ו. וְזֶהוּ (ירמיה לא) רָנּוּ לְיַעֲקֹב שִׂמְחָה. מָתַי? לְאַחַר שֶׁנּוֹטֵל נְקָמָה מִשּׂוֹנְאָיו וְיִשְׂרֹף הָאֱלִילִים שֶׁלָּהֶם. זֶהוּ שֶׁכָּתוּב (משלי יא) וּבַאֲבֹד רְשָׁעִים רִנָּה. שֶׁהוּא הַנֵּר (מ, שנים) לְהַשְׁלִים ע\"ב ע\"ב ע\"ב. וּתְלוּיִים ס\"ד.</p>\n<p>וּתְלוּיִים ס\"ד מִשְּׁמוֹנֶה א\"ז. וְכָךְ ס\"ד מִשְּׁמוֹנֶה א\"ז לְאַרְבָּעָה צְדָדִים - רנ\"ו. וְכַאֲשֶׁר מַגִּיעַ לְל\"ב, שֶׁהֵם א\"ז א\"ז א\"ז א\"ז, שֶׁהֵם ח' ח' ח' ח', מִתְחַבֶּרֶת אוֹת י' לְכָל צַד, לִהְיוֹת ח\"י יְהֹוָ\"ה, בְּח\"י בְּרָכוֹת שֶׁל הַתְּפִלָּה שֶׁיֵּשׁ בָּהֶן ח\"י פְּעָמִים יְהֹוָ\"ה, שֶׁעוֹלִים ע\"ב. בַּזְּמַן הַהוּא שֶׁמִּתְחַבֵּר יְהֹוָ\"ה בַּאדֹנָ\"י עַל יְדֵי חַ\"י הָעוֹלָמִים יְאֲהַדוָנָהי, מִיָּד חַיּוֹת שֶׁל אֵשׁ שׁוֹתְקוֹת. מַה כָּתוּב בָּהֶן? (יחזקאל א) בְּעָמְדָם תְּרַפֶּינָה כַנְפֵיהֶן. בַּעֲמִידָתָם שֶׁל יִשְׂרָאֵל בַּגָּלוּת (בתפלה), תְּרַפֶּינָה כַנְפֵיהֶן, כְּדֵי שֶׁלֹּא יִוָּדְעוּ עַד הַשָּׁעָה הַהִיא.</p>\n<p>וְזְהִ הוּא רַק שְׂפָתֶיהָ נָעוֹת. שֶׁהֵן כַּנְפֵי הַחַיּוֹת, וְקוֹלָהּ לֹא יִשָּׁמֵעַ. וּמַה שֶּׁהָיָה חַשְׁמַל, חַיּוֹת אֵשׁ מְדַבְּרוֹת, הֵן עַתָּה שׁוֹתְקוֹת. וּמִשּׁוּם זֶה תִּקְּנוּ תְפִלָּה בְּלַחַשׁ, וְכֵן מַעֲשֵׂה מֶרְכָּבָה בְּלַחַשׁ, לְדַבֵּר שָׁם בְּלַחַשׁ בֵּינוֹ לְבֵין עַצְמוֹ. שָׁלֹשׁ תְּפִלּוֹת תִּקְּנוּ, וּבְכֻלָּן ח\"י יְהֹוָ\"ה, שֶׁהֵן ע\"ב אוֹתִיּוֹת, בְּכָל תְּפִלָּה בִּשְׁמוֹנֶה עֶשְׂרֵה בְּרָכוֹת, שֶׁהֵן רי\"ו, וּכְלוּלוֹת בְּחֶסֶד, בְּע\"ב, וְעִם ל\"ב נְתִיבוֹת, וַהֲרֵי הֵן ר\"נ חָסֵר שְׁתַּיִם שֶׁכְּלוּלוֹת בָּעַמּוּד הָאֶמְצָעִי.</p>\n<p>וּמֵהַקָּרְבָּנוֹת נִשְׁמָע עַל הַתְּפִלָּה, וּמֵהַתְּפִלָּה - לַקָּרְבָּן, כְּמוֹ שֶׁנֶּאֱמַר בָּהֶם, (יחזקאל א) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם. כָּךְ בַּכְּרוּבִים, (במדבר ז) וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו. כְּמוֹ הַכֶּבֶשׁ שֶׁעוֹלִים וְיוֹרְדִים בּוֹ קָרְבָּנוֹת וְעוֹלוֹת - כָּךְ בַּתְּפִלָּה, מַלְאָכִים עוֹלִים שְׁנַיִם וְיוֹרְדִים שְׁנַיִם. וּכְמוֹ סִינַי, שֶׁבּוֹ מֹשֶׁה וְאַהֲרֹן עוֹלִים וְיוֹרְדִים, עוֹלִים שְׁנַיִם וְיוֹרְדִים שְׁנַיִם. וּבְמִצְוָה זוֹ נִרְמְזוּ כָּל מִצְווֹת הַתּוֹרָה.</p>\n<p>וְכָךָ כַּאֲשֶׁר הָיָה פּוֹתֵחַ רַבִּי עֲקִיבָא בְּמַעֲשֵׂה מֶרְכָּבָה, פִּיו הָיָה סִינַי, וְקוֹלוֹ הָיָה סֻלָּם, שֶׁבּוֹ מַלְאָכִים עוֹלִים וְיוֹרְדִים. בְּכָל דִּבּוּר וְדִבּוּר שֶׁלּוֹ הָיָה רוֹכֵב עָלָיו מַלְאָךְ מְטַטְרוֹ\"ן. הוּא רֶכֶב לַשְּׁכִינָה שֶׁכְּלוּלָה בּוֹ סְפִירוֹת, עַמּוּד הָאֶמְצָעִי, שֶׁהוּא שֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א מִבִּפְנִים. וְהַשְּׁכִינָה שֶׁכְּלוּלָה מֵעֶשֶׂר סְפִירוֹת, מִבַּחוּץ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ הֵם רֶכֶב וּמֶרְכָּבָה. (עלות העלות) הָעַמּוּד הָאֶמְצָעִי הוּא רֶכֶב לְעִלַּת הָעִלּוֹת. וְהַשְּׁכִינָה הִיא רֶכֶב לָעַמּוּד הָאֶמְצָעִי. וְעִלַּת הָעִלּוֹת הוּא הַמְיַחֵד לַכֹּל, וּמְסַדֵּר לַכֹּל, וּמֵאִיר בַּכֹּל. אוֹרוֹ עוֹבֵר בַּנְּשָׁמָה וּבַגּוּף וּבַלְּבוּשׁ, וְאֵין בּוֹ שִׁנּוּי וְשֻׁתָּפוּת וְחֶשְׁבּוֹן וּתְמוּנָה וְדִמְיוֹן מִכָּל הַמֶּרְכָּבוֹת וּמַרְאֶה וְדִמְיוֹן שֶׁנִּרְאֶה בְּעֵין הַשֵּׂכֶל. מַדְרֵגוֹת עֶלְיוֹנוֹת וְתַחְתּוֹנוֹת הֵן רֶכֶב וּמֶרְכָּבָה אֶצְלוֹ, וְעָלָיו אֵין מִי שֶׁרוֹכֵב.</p>\n<p>קֶשֶׁת - סִימַן תְּקִיעָה שְׁבָרִים תְּרוּעָה. וְהֵם סִימַן הַמֶּרְכָּבָה שֶׁל הָאָבוֹת. תְּקִיעָה - שֶׁל אַבְרָהָם. שְׁבָרִים - שֶׁל יִצְחָק. תְּרוּעָה - שֶׁל יַעֲקֹב, שֶׁנֶּאֱמַר בּוֹ (במדבר כג) וּתְרוּעַת מֶלֶךְ בּוֹ. וּשְׁלֹשָׁה צְבָעִים נִרְאִים בּוֹ, לָבָן אָדֹם וְיָרֹק. וּמִצַּד הַגְּבוּרָה נִקְרָא (שמואל א ב) קֶשֶׁת גִּבֹּרִים חַתִּים. וּמִצַּד הַיָּמִין - (יחזקאל א) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם. כַּאֲשֶׁר נִרְאֶה בְּיוֹם הַגֶּשֶׁם - מַרְאֵה רַחֲמִים. וְכַאֲשֶׁר נִרְאֶה בְּלִי מָטָר - מַרְאֵה דִין. וְכַאֲשֶׁר מְעֹרָב בֵּין גֶּשֶׁם וְשֶׁמֶשׁ - מַרְאֵה דִין וְרַחֲמִים כְּלוּלִים. וְזוֹהִי אוֹת ש' מִשַּׁדַּי, שְׁלֹשָׁה עַנְפֵי הָאָבוֹת, שֶׁהֵם יְהֹוָ\"ה אֱלֹהֵינ\"וּ יְהֹוָ\"ה. שְׁלֹשָׁה שֵׁמוֹת כְּנֶגֶד שְׁלֹשָׁה עַנְפֵי הָאָבוֹת, וּבָהֶם י\"ד אוֹתִיּוֹת, בְּחֶשְׁבּוֹן אוֹתִיּוֹת ד\"י מִשַּׁדַּי. וּמַלְבּוּשׁ שֵׁם שַׁדַּי הוּא מְטַטְרוֹן, שֶׁכָּךְ עוֹלֶה בְּחֶשְׁבּוֹן שַׁדַּי. (ע\"כ רעיא מהימנא).</p>"],[9522012499,"<p>אָמַר רַבִּי שִׁמְעוֹן, מִי שֶׁפּוֹתֵחַ פֶּתַח יֹאמַר. אָמַר רַבִּי אֶלְעָזָר, שָׁנִינוּ, כָּל מִי שֶׁאוֹמֵר תְּהִלָּה לְדָוִד בְּכָל יוֹם שָׁלֹשׁ פְּעָמִים, הוּא בֶּן הָעוֹלָם הַבָּא. וַהֲרֵי נִתְבָּאֵר הַטַּעַם. אִם בִּגְלַל פַּרְנָסָה וּמָזוֹן שֶׁל כָּל הָעוֹלָמוֹת - פַּעֲמַיִם הֵם בְּכָל יוֹם, בַּבֹּקֶר וּבָעֶרֶב, שֶׁכָּתוּב (שמות טז) בְּתֵת ה' לָכֶם בָּעֶרֶב בָּשָׂר וְגוֹ'. לָמָּה שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם? אֶלָּא שְׁנַיִם לִמְזוֹן בְּנֵי אָדָם וְשֶׁל כָּל הָעוֹלָם, וְאֶחָד לָתֵת חֹזֶק לְאוֹתוֹ מָקוֹם שֶׁיָּדָיו פְּתוּחוֹת.</p>\n<p>וּשְׁנֵי מְזוֹנוֹת אֵלּוּ מְשֻׁנִּים זֶה מִזֶּה, וְכֻלָּם שְׁלֹשָׁה מְזוֹנוֹת כְּתוּבִים כָּאן: (תהלים קמה) וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ - זֶה מְזוֹן הָעֲשִׁירִים, שֶׁנּוֹתֵן אֹכֶל רַב בְּעִתּוֹ. הֲרֵי אֶחָד. שְׁנַיִם - שֶׁכָּתוּב וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן, זֶה מְזוֹן הָעֲנִיִּים, שֶׁהֵם שְׂבֵעִים מֵרָצוֹן וְלֹא מִתּוֹךְ אֹכֶל רַב. שְׁלֹשָׁה - שֶׁכָּתוּב פּוֹתֵחַ אֶת יָדֶךְ, זֶהוּ חֹזֶק לְאוֹתוֹ מָקוֹם, וּבִפְתִיחַת יָדָיו יוֹצֵא רָצוֹן וְשָׂבָע לַכֹּל.</p>\n<p>עוֹד כָּךְ לָמַדְנוּ, שֶׁאֵינוֹ אֶלָּא פַּעֲמַיִם בִּשְׁבִיל מָזוֹן וּפַרְנָסָה בְּכָל יוֹם, שֶׁאֵלּוּ חִיּוּב עַל הָאָדָם. וְאִם אָמַר יוֹתֵר, לֹא בִּגְלַל חוֹבָה הוּא, אֶלָּא בִּשְׁבִיל שֶׁבַח תּוֹךְ תִּשְׁבָּחוֹת שֶׁל זְמִירוֹת דָּוִד הַמֶּלֶךְ. (שיוצא ידיו של הקדוש ברוך הוא ומברך ושבעים מרצון, ועל זה אין חיוב הוא אלא פעמים ביום, ושבח הוא לקדוש ברוך הוא לתת לו זמירות של דוד המלך) מָה הַטַּעַם? מִשּׁוּם שֶׁפַּרְנָסָה לֹא רָאוּי לִשְׁאֹל, רַק לְאַחַר הַתְּפִלָּה וּפַרְנָסַת רִבּוֹנוֹ. הַמֶּלֶךְ יֹאכַל בַּתְּחִלָּה, וְאַחַר כָּךְ יֹאכְלוּ עֲבָדָיו.</p>"],[9522012500,"<p>זֶהוּ שֶׁכָּתוּב, (שיר השירים ה) בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה (וגו') אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי, אַחַר כָּךְ אִכְלוּ רֵעִים. אָכַלְתִּי יַעְרִי - זוֹ תְּפִלַּת מִיֹּשֶׁב. עִם דִּבְשִׁי - זוֹ קְרִיאַת שְׁמַע. אָכַלְתִּי יַעְרִי - זוֹ תְּפִלַּת מִיֹּשֶׁב, אוֹתוֹ יַעַר לְבָנוֹן, יוֹצֵר אוֹר (משרתים) וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ (כלם קדושים), כָּל אֵלֶּה נִקְרָאִים יַעַר עֵצִים וְנִצָּבִים שֶׁבּוֹ. עִם דִּבְשִׁי - זוֹ קְרִיאַת שְׁמַע, שֶׁהִיא מְתִיקוּת הַכֹּל, בְּכַמָּה צוּפִים וּמְתוּקִים.</p>\n<p>שָׁתִיתִי יֵינִי - זוֹ תְּפִלַּת מֵעֹמֶד, מֵהַטּוּב (משיכה) שֶׁל יַיִן עֶלְיוֹן הַמְשֻׁמָּר, וְזֶה בְּשָׁלֹשׁ בְּרָכוֹת רִאשׁוֹנוֹת. עִם חֲלָבִי - אֵלֶּה אוֹתָן שָׁלֹשׁ בְּרָכוֹת אַחֲרוֹנוֹת, וּכְלוּלִים אֵלּוּ בְאֵלּוּ. עַד כָּאן מַאֲכַל הַמֶּלֶךְ. לְאַחַר שֶׁאָכַל הַמֶּלֶךְ - אִכְלוּ רֵעִים לְמַעְלָה, שְׁתוּ וְשִׁכְרוּ דוֹדִים לְמַטָּה.</p>\n<p>וְלָכֵן אֵין חִיּוּב שֶׁל מָזוֹן אֶלָּא לְאַחַר הַתְּפִלָּה. בִּתְפִלַּת מִנְחָה (בערב) לִפְנֵי הַתְּפִלָּה. מָה הַטַּעַם? מִשּׁוּם שֶׁעַד שֶׁלֹּא נִמְצָא דִין קָשֶׁה בָּעוֹלָם, בְּעוֹד שֶׁפְּנֵי הַמֶּלֶךְ מְאִירוֹת, יֹאמַר תְּהִלָּה לְדָוִד בְּסִדּוּר זֶה שֶׁל הַמָּזוֹן. שֶׁלְּאַחַר שֶׁהַדִּין שָׁרוּי וְתָלוּי עַל הָעוֹלָם, זוֹ אֵינָהּ הַשָּׁעָה. בָּא רַבִּי פִּנְחָס וּנְשָׁקוֹ.</p>"],[9522012501,"<p>אָמַר רַבִּי יְהוּדָה, יֹאמַר לָנוּ הָרַב, (מאלו) דְּבָרִים עֶלְיוֹנִים שֶׁל רֹאשׁ הַשָּׁנָה. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (מלכים ב ד) וַיְהִי הַיּוֹם. בְּכָל מָקוֹם שֶׁכָּתוּב וַיְהִי - הוּא צַעַר. וַיְהִי בִּימֵי - צַעַר וַדַּאי. וַיְהִי הַיּוֹם - יוֹם שֶׁיֵּשׁ בּוֹ צַעַר, וְזֶהוּ רֹאשׁ הַשָּׁנָה, יוֹם שֶׁיֵּשׁ בּוֹ דִּין קָשֶׁה עַל הָעוֹלָם. וַיְהִי הַיּוֹם וַיַּעֲבֹר אֱלִישָׁע אֶל שׁוּנֵם - יוֹם שֶׁל רֹאשׁ הַשָּׁנָה הָיָה. וּבְכָל מָקוֹם וַיְהִי הַיּוֹם - זֶה רֹאשׁ הַשָּׁנָה. (איוב א) וַיְהִי הַיּוֹם וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים - יוֹם רֹאשׁ הַשָּׁנָה הָיָה.</p>\n<p>בְּכָל פַּעַם שְׁנֵי יָמִים הֵם. מָה הַטַּעַם? כְּדֵי שֶׁיִּהְיֶה יִצְחָק כָּלוּל מִדִּין וְרַחֲמִים, שְׁנֵי יָמִים וְלֹא אֶחָד. שֶׁאִם יִמָּצֵא יְחִידִי, יַחֲרִיב הָעוֹלָם. וְעַל זֶה כָּתוּב שְׁתֵּי פְעָמִים וַיְהִי הַיּוֹם וַיְהִי הַיּוֹם.</p>\n<p>וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים - אֵלּוּ בֵּית דִּין הַגָּדוֹל. בְּנֵי הָאֱלֹהִים - וַדַּאי בָּנָיו שֶׁל הַמֶּלֶךְ קְרֵבִים אֵלָיו. וְהֵם שִׁבְעִים מְמֻנִּים שֶׁסּוֹבְבִים תָּמִיד אֶת הַמֶּלֶךְ, וְהֵם חוֹתְכִים דִּין עַל הָעוֹלָם. לְהִתְיַצֵּב עַל ה', וְכִי מֵעַל ה' עוֹמְדִים? אֶלָּא בְּשָׁעָה שֶׁאֵלּוּ עוֹמְדִים בְּדִין, דִּין הָרִאשׁוֹן שֶׁהַכֹּל בּוֹ מַהוּ? מִי שֶׁלֹּא מְכַבֵּד לְשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא וְשֶׁלֹּא מְכַבֵּד לַתּוֹרָה וְלַעֲבָדָיו. אַף כָּךְ - מִי הוּא שֶׁלֹּא חוֹשֵׁשׁ עַל כְּבוֹדוֹ שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁלֹּא יִתְחַלֵּל בָּאָרֶץ. מִי הוּא שֶׁלֹּא חוֹשֵׁשׁ לִכְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִי הוּא שֶׁלֹּא נוֹתֵן כָּבוֹד לְשֵׁם זֶה. וַיָּבוֹא גַם הַשָּׂטָן בְּתוֹכָם, גַּם - לְרַבּוֹת אוֹתָהּ הַנְּקֵבָה שֶׁלּוֹ. אַף כָּךְ לְהִתְיַצֵּב עַל ה', שֶׁהוּא חוֹשֵׁשׁ גַּם לִכְבוֹדוֹ שֶׁל שֵׁם זֶה.</p>"],[9522012502,"<p>כָּאן נֶחְלְקוּ עַמּוּדֵי עוֹלָם הָרִאשׁוֹנִים. אֶחָד אָמַר, אִיּוֹב מֵחֲסִידֵי אֻמּוֹת הָעוֹלָם הָיָה. וְאֶחָד אָמַר, מֵחֲסִידֵי יִשְׂרָאֵל הָיָה. וְלָקָה לְכַפֵּר עַל הָעוֹלָם. שֶׁהֲרֵי יוֹם אֶחָד מְצָאוֹ רַב הַמְנוּנָא לְאֵלִיָּהוּ. אָמַר לוֹ, וַדַּאי לָמַדְנוּ שֶׁיֵּשׁ צַדִּיק וְרַע לוֹ, רָשָׁע וְטוֹב לוֹ. אָמַר, צַדִּיק - כָּל שֶׁמְּמֻעָטִין לוֹ חוֹבוֹתָיו, נוֹתְנִים לוֹ בָּעוֹלָם הַזֶּה חוֹבוֹ, וְעַל כֵּן צַדִּיק וְרַע לוֹ. וְכָל שֶׁמְּרֻבִּים עֲווֹנוֹתָיו וּמְמֻעָטִים זְכֻיּוֹתָיו, נוֹתְנִים לוֹ שְׂכָרוֹ בָּעוֹלָם הַזֶּה - רָשָׁע וְטוֹב לוֹ. אָמַר לוֹ, דִּינָיו שֶׁל רִבּוֹן הָעוֹלָם עַתִּיקִים (עמקים), אֲבָל בְּשָׁעָה שֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְכַפֵּר חוֹבוֹת שֶׁל הָעוֹלָם, מַלְקֶה בַּזְּרוֹעַ שֶׁלָּהֶם וּמְרַפֵּא לְכֻלָּם. מָשָׁל לְרוֹפֵא שֶׁהִלְקָה לַזְּרוֹעַ לְהַצִּיל כָּל הָאֵיבָרִים, כְּמוֹ שֶׁכָּתוּב (ישעיה נג) וְהוּא מְחֹלָל מִפְּשָׁעֵנוּ וְגוֹ'.</p>"],[9522012503,"<p>כְּמוֹ שֶׁנֶּאֱמַר בְּאוֹתוֹ יוֹם שֶׁל רֹאשׁ הַשָּׁנָה, שֶׁעוֹמְדִים שִׁבְעִים כִּסְאוֹת לָדוּן דִּין הָעוֹלָם, כַּמָּה הֵם בַּעֲלֵי מָגִנִּים, קָטֵגוֹרִים, שֶׁעוֹמְדִים לְמַעְלָה. אֵלּוּ מַיְמִינִים לִזְכוּת, וְאֵלּוּ מַשְׂמִאלִים לְחוֹבָה לְהַזְכִּיר חוֹבוֹת הָעוֹלָם, חוֹבוֹת שֶׁל כָּל אֶחָד וְאֶחָד. וְעַל זֶה צָרִיךְ הָאָדָם לְפָרֵשׁ חוֹבוֹתָיו, כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁהוּא. מִשּׁוּם שֶׁמִּי שֶׁמְּפָרֵשׁ חֶטְאוֹ, לֹא נִמְסָר דִּינוֹ אֶלָּא בִּידֵי הַמֶּלֶךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ. וּמִי שֶׁדָּן אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא - הוּא לְטוֹב. וְעַל זֶה בִּקֵּשׁ דָּוִד הַמֶּלֶךְ (ואמר), (תהלים מג) שָׁפְטֵנִי אֱלֹהִים. אַתָּה, וְלֹא אַחֵר. וְכֵן שְׁלֹמֹה אָמַר, (מלכים א ח) לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ. הוּא, וְלֹא אַחֵר. וְכָל בֵּית דִּין מִתְרַחֲקִים מִמֶּנּוּ.</p>\n<p>וְעַל זֶה צָרִיךְ לָנוּ לְפָרֵט הָעֲבֵרוֹת שֶׁל כָּל אֵיבָר וְאֵיבָר, וְכָל מַה שֶּׁעוֹשֶׂה בִּפְרָט. זֶהוּ שֶׁכָּתוּב (תהלים לב) חַטָּאתִי אוֹדִיעֲךְ וְגוֹ'. וּלְבַסּוֹף - וְאַתָּה נָשָׂאתָ עֲוֹן חַטָּאתִי סֶלָה. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב (שמות לב) אָנָּא חָטָא הָעָם הַזֶּה וְגוֹ'. בְּיִשְׂרָאֵל כָּתוּב, (שמואל איב) חָטָאנוּ כִּי עָזַבְנוּ אֶת ה'. שֶׁאִם תֹּאמַר זֶה בְּיָחִיד, אֲבָל בְּצִבּוּר לֹא - הֲרֵי כָּתוּב פָּסוּק זֶה. וְאִם תֹּאמַר זֶה בְּצִבּוּר, אֲבָל שָׁלִיחַ שֶׁלָּהֶם לֹא - הֲרֵי כָּתוּב (שמות לב) וַיָּשָׁב מֹשֶׁה אֶל ה' וְגוֹ'. וְכָתוּב (שם) וַיַּעֲשׂוּ לָהֶם וְגוֹ'. מָה הַטַּעַם? מִי שֶׁמְּפָרֵשׁ חוֹבוֹתָיו, בֵּית דִּין מִתְרַחֲקִים מִמֶּנּוּ, מִשּׁוּם שֶׁבֶּן אָדָם קָרוֹב לְעַצְמוֹ וְלֹא נִדּוֹן עַל פִּיו.</p>\n<p>וְעוֹד, לֹא עוֹזֵב לַמְקַטְרֵג לְלַמֵּד עָלָיו חוֹב וּמוּם. שֶׁבֶּן אָדָם יַקְדִּים וְיֹאמַר, וְלֹא יִתֵּן מָקוֹם לְאַחֵר לוֹמַר, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹחֵל לוֹ. זֶהוּ שֶׁכָּתוּב (משלי כח) וּמוֹדֶה וְעוֹזֵב יְרוּחָם.</p>\n<p>בִּימֵי רֹאשׁ הַשָּׁנָה מְתַקְּנִים בֵּית דִּין כִּסֵּא לַמֶּלֶךְ לָדוּן אֶת כָּל הָעוֹלָם, וְיִשְׂרָאֵל נִכְנָסִים בָּרִאשׁוֹנָה בַּדִּין לְפָנָיו, שֶׁיִּרְבּוּ הָרַחֲמִים. (לפני שירבה הרגז). לָמַדְנוּ, וּמִשְׁפַּט עַמּוֹ יִשְׂרָאֵל דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ מַה הוּא? אֶלָּא אֵלּוּ שְׁנֵי יָמִים שֶׁל רֹאשׁ הַשָּׁנָה. מַדּוּעַ שְׁנֵי יָמִים? מִשּׁוּם שֶׁהֵם שְׁנֵי בָּתֵּי דִין שֶׁמִּתְחַבְּרִים כְּאֶחָד. דִּין עֶלְיוֹן, שֶׁהוּא קָשֶׁה, בְּדִין תַּחְתּוֹן, שֶׁהוּא רָפֶה, וּשְׁנֵיהֶם נִמְצָאִים.</p>\n<p>וְעַל זֶה לֹא יוֹדְעִים אֵלּוּ הַבַּבְלִים סוֹד שֶׁל הַיְבָבָה וְהַיְלָלָה, וְלֹא יוֹדְעִים שֶׁשְּׁנֵיהֶם צְרִיכִים, יְלָלָה שֶׁהוּא דִּין תַּקִּיף. שְׁלֹשָׁה שְׁבָרִים שֶׁהוּא דִּין רָפֶה, גְּנִיחוֹת שֶׁגּוֹנֵחַ בְּרִפְיוֹן. הֵם לֹא יוֹדְעִים, וְעוֹשִׂים שְׁנֵיהֶם. וְאָנוּ יוֹדְעִים וְעוֹשִׂים שְׁנֵיהֶם. (ועל זה סוד היבבהוהיללה, ושניהם צריכים. אלו הבבלים אינם יודעים, ועושים שניהם.) וְהַכֹּל יוֹצֵא לְדֶרֶךְ אֱמֶת.</p>\n<p>פָּתַח וְאָמַר, (תהלים פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר, מַהוּ בַחֹדֶשׁ? זֶה בֵּית דִּין רָפֶה, שֶׁנִּקְרָא חֹדֶשׁ. בַּכֶּסֶה - (כסא של העולם העליון, כסא של אות ה', זה פחד יצחק שהוא כסא למלך העליון. עוד בכסה) זֶה דִּין קָשֶׁה, פַּחַד יִצְחָק. דִּין שֶׁמִּתְכַּסֶּה תָּמִיד, שֶׁאֵין הוּא דִּין בְּגִלּוּי. כִּי חֹק - זֶה דִּין רָפֶה. וּמִשְׁפָּט - זֶה דִּין (קשה). וּשְׁנֵיהֶם הֵם כְּאֶחָד. בִּגְלַל זֶה שְׁנֵי יָמִים, וּשְׁנֵיהֶם בְּסוֹד אֶחָד.</p>\n<p>אַשְׁרֵי הָעָם יֹדְעֵי תְרוּעָה וְגוֹ' (תהלים פט). לֹא כָתוּב שׁוֹמְעֵי, אוֹ תוֹקְעֵי תְרוּעָה, אֶלָּא יֹדְעֵי תְרוּעָה. בִּגְלַל (כגון) הַחֲכָמִים שֶׁדָּרִים בָּאֲוִיר שֶׁל הָאָרֶץ הַקְּדוֹשָׁה, אֵלּוּ יֹדְעֵי תְרוּעָה. סוֹד שֶׁל הַתְּרוּעָה, כְּמוֹ שֶׁכָּתוּב (תהלים ב) תְּרֹעֵם בְּשֵׁבֶט בַּרְזֶל. מִי עַם כְּיִשְׂרָאֵל שֶׁיּוֹדְעִים סוֹדוֹת עֶלְיוֹנִים שֶׁל רִבּוֹנָם, לַעֲלוֹת לְפָנָיו וּלְהִתְקַשֵּׁר בּוֹ. וְכָל אֵלּוּ שֶׁיּוֹדְעִים סוֹד הַתְּרוּעָה, יִתְקָרְבוּ לָלֶכֶת בְּאוֹר פָּנָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְזֶה הָאוֹר הָרִאשׁוֹן שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים. וְעַל זֶה צָרִיךְ לָדַעַת אוֹתָהּ.</p>"],[9522012504,"<p>כָּתוּב (ויקרא ט) הַיֹּתֶרֶת מִן הַכָּבֵד. וְכָתוּב (שם ג) וְאֶת הַיֹּתֶרֶת עַל הַכָּבֵד. (אחר שעשתה נאוף, עולה עליו.) יֹתֶרֶת מִן הַכָּבֵד - זוֹ אֵשֶׁת זְנוּנִים שֶׁהוֹלֶכֶת וְיוֹצֵאת מִן הַכָּבֵד לְהַחֲטִיא בְּנֵי הָעוֹלָם וּלְקַטְרֵג עֲלֵיהֶם, וְעוֹזֶבֶת אֶת הַזָּכָר לַעֲשׂוֹת זְנוּנִים, וּמִשּׁוּם זֶה הַיֹּתֶרֶת, שֶׁנִּפְרֶדֶת מִן הַכָּבֵד. יֹתֶרֶת עַל הַכָּבֵד - אַחַר שֶׁעָשְׂתָה נִאוּף, עוֹלָה עָלָיו. מֵצַח אִשָּׁה זוֹנָה. מִתְגַּבֶּרֶת עַל בַּעְלָהּ, שֶׁהוּא כָּבֵד, בַּכַּעַס שֶׁל הַמָּרָה. אֵשֶׁת מְדָנִים וָכַעַס, שֶׁשּׁוֹלֶטֶת עַל הַזָּכָר שֶׁלָּהּ. מֵצַח אִשָּׁה זוֹנָה שׁוֹלֶטֶת עַל הַכָּבֵד, אֵשֶׁת מְדָנִים וָכַעַס.</p>\n<p>יֹתֶרֶת מִן הַכָּבֵד - מִן הַכָּבֵד יוֹצֵאת לְהַבְאִישׁ לְכָל הָעוֹלָם וְלַעֲשׂוֹת נִאוּפִים עִם הַכֹּל. לְבַסּוֹף הִיא עוֹלָה לְגַבֵּי הַזָּכָר, מֵצַח אִשָּׁה זוֹנָה, בְּעַזּוּת שֶׁל פָּנִים, וְאָז הִיא עַל הַכָּבֵד. וְעוֹד, יֹתֶרֶת מִן הַכָּבֵד נִקְרֵאת מֵהַצַּד הָאַחֵר. אַחַר שֶׁיּוֹצֵאת לְנָאֵף עִם כֻּלָּם, נוֹתֶנֶת שִׁיּוּרִים לְבַעְלָהּ, וְזוֹהִי יֹתֶרֶת מִן הַכָּבֵד.</p>\n<p>מִתּוֹךָ הַכָּבֵד וְהַיּוֹתֶרֶת שֶׁלָּהּ יוֹצֵאת מָרָה, וְהִיא חֶרֶב שֶׁל מַלְאַךְ הַמָּוֶת, שֶׁיּוֹצְאוֹת מִמֶּנָּה טִפּוֹת מָרוֹת לַהֲרֹג לִבְנֵי אָדָם. זֶהוּ שֶׁכָּתוּב (משלי ה) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה. וְהִיא תְּלוּיָה בַּכָּבֵד, וְכָל הֶחֳלָאִים וְהַמִּיתוֹת תְּלוּיוֹת בּוֹ. וְאוֹתוֹ יוֹם שֶׁל רֹאשׁ הַשָּׁנָה (המשטין) מְשׁוֹטֵט בָּעוֹלָם לֶאֱסֹף אֶת כָּל חוֹבוֹת הָעוֹלָם, וְאָז כָּל הָאֵיבָרִים, שֶׁהֵם יִשְׂרָאֵל, הֵם בְּצָרָה, שֶׁהֵם אֵיבָרִים שֶׁל הַמַּלְכָּה, שֶׁנֶּאֱמַר (משלי כ) נֵר ה' נִשְׁמַת אָדָם. הַשְּׁכִינָה הַקְּדוֹשָׁה. וְאָז כָּל יִשְׂרָאֵל בְּצָרָה, וְלוֹקְחִים שׁוֹפָר לְעוֹרֵר בּוֹ אוֹתָהּ תְּקִיעָה וּשְׁבָרִים וּתְרוּעָה.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, וַדַּאי אַחַר שֶׁהָאֵיבָרִים וְהָעוֹרְקִים שֶׁל הַלֵּב, שֶׁדּוֹמִים לְיִשְׂרָאֵל, הֵם בְּצָרָה. צְרִיכִים לְעוֹרְרָם בְּקָנֶה, שֶׁהוּא שׁוֹפָר. וְזֶה קָנֶה שֶׁל רֵאָה. אַחַר שֶׁכַּנְפֵי רֵאָה לֹא יְכוֹלוֹת לְהַשְׁקִיט רֹגֶז הַמָּרָה שֶׁמִּתְגַּבֶּרֶת עַל עוֹרְקֵי הַלֵּב, וְעַל כָּל הָעוֹרְקִים שֶׁל הָאֵיבָרִים שֶׁל הַגּוּף. אוֹתָהּ הָרוּחַ שֶׁנּוֹשֶׁבֶת בָּהֶם עוֹלָה בְּקָנֶה, שֶׁהוּא שׁוֹפָר, עוֹלָם הַבָּא. שֶׁכָּךְ פֵּרְשׁוּהוּ, וֵשֶׁט דּוֹמֶה לָעוֹלָם הַזֶּה, שֶׁבּוֹ אֲכִילָה וּשְׁתִיָּה. קָנֶה דּוֹמֶה לָעוֹלָם הַבָּא, שֶׁאֵין בּוֹ אֲכִילָה וּשְׁתִיָּה.</p>\n<p>וְאַחַר שֶׁשָּׁט אוֹת ו' מִן וֵשֶׁט, בְּרִבּוּי אֲכִילָה שֶׁל גָּזֵל, נִתְאָרֵךְ וְנַעֲשֶׂה שָׂטָן. וּמִי גָרַם אֶת זֶה? שֶׁנֶּאֱמַר (במדבר יא) שָׁטוּ הָעָם וְלָקְטוּ. הַשְּׁטוּת שֶׁלָּהֶם שֶׁנִּתְעָרְבוּ בְּעֵרֶב רַב הַשּׁוֹטִים, שֶׁהַתַּאֲוָה שֶׁלָּהֶם הִיא אֲכִילָה וּשְׁתִיָּה שֶׁל גָּזֵל וְחָמָס שֶׁל (תהלים יב) שֹׁד עֲנִיִּים וְאֶנְקַת אֶבְיוֹנִים. בְּאוֹת נוּ\"ן כְּפוּפָה, הַשּׁוֹטִים, שֶׁאוֹכְלִים וּבְלִי לִטְחֹן. מַה כָּתוּב בָּהֶם? (במדבר יא) הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם טֶרֶם יִכָּרֵת וְאַף ה' חָרָה בָעָם. נִתְפַּשְּׁטָה אוֹת ו' שֶׁל שָׁטוּ, אוֹתוֹ שֶׁרוּחוֹ כָּפוּף, וְהוּא אוֹת נ'. וְזֶה גָּרַם שֶׁהִתְפַּשֵּׁט הַשָּׂטָן בַּאֲכִילָה וּשְׁתִיָּה, וּמִתְגַּבֵּר עַל כָּל אֵיבָרִים וְעוֹרְקִים בִּשְׁלֹשׁ מֵאוֹת שִׁשִּׁים וְחָמֵשׁ מִצְווֹת לֹא תַעֲשֶׂה. כְּחֶשְׁבּוֹן הַשָּׂטָ\"ן חָסֵר אֶחָד, זֶה יוֹם הַכִּפּוּרִים, שֶׁאֵין בּוֹ אֲכִילָה וּשְׁתִיָּה.</p>\n<p>וְהוּא כְּדֻגְמַת הַקָּנֶה, וְהוּא אוֹת ו' בֶּן יָ\"הּ מִבִּינָה. וְלָכֵן בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, הָרוֹאֶה קָנֶה בַּחֲלוֹם זוֹכֶה לְחָכְמָה. זֶהוּ שֶׁכָּתוּב (משלי ד) קְנֵה חָכְמָה קְנֵה בִינָה. שֶׁאֵין קָנֶה שֶׁהוּא פָּחוֹת מִשְּׁנֵיהֶם, שֶׁהֵם י' חָכְמָה, ה' בִּינָה. וּמִשּׁוּם זֶה צָרִיךְ לְעוֹרֵר בַּשּׁוֹפָר, שֶׁהוּא קָנֶה, עוֹלָם הַבָּא, עוֹלָם אָרֹךְ, אֶרֶךְ אַפַּיִם, שֶׁנִּמְצָאִים מִמֶּנּוּ שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת שֶׁל רַחֲמִים, כְּחֶשְׁבּוֹן וָא\"ו. אוֹת א' - אֶרֶךְ, שְׁתֵּי וָוִי\"ם - אַפַּיִם.</p>\n<p>וְאִמָּא עֶלְיוֹנָה הִיא תְּקִיעָה, מִצִּדּוֹ שֶׁל אַבְרָהָם. שְׁבָרִים מִצִּדּוֹ שֶׁל יִצְחָק. תְּרוּעָה מִצִּדּוֹ שֶׁל יַעֲקֹב. שְׁכִינָה תַּחְתּוֹנָה קֶשֶׁר שֶׁל כֻּלָּם. כְּלוֹמַר, אוֹת ק' - תְּקִיעָה. אוֹת ש' - שְׁבָרִים. אוֹת ר' - תְּרוּעָה. וְכֻלָּם מְשֻׁלָּשִׁים לְגַבֵּי הַשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב קְדֻשָּׁה לְךְ יְשַׁלֵּשׁוּ. שֶׁאֵין קוֹל יָכוֹל לָצֵאת הַחוּצָה אֶלָּא מִן הַפֶּה. אַף כָּךְ אֵין לְהַפְרִיד הַשְּׁכִינָה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נֶאֱמַר בּוֹ, (תהלים כט) קוֹל ה' חֹצֵב לַהֲבוֹת אֵשׁ. וְהַשְּׁכִינָה - תְּפִלַּת כָּל פֶּה. וְאֵלּוּ סִימָנִים: קשר\"ק, קש\"ק, קר\"ק. וּבַחִבּוּר הַקַּדְמוֹן. (עד כאן).</p>\n<p>לוֹקְחִים שׁוֹפָר לְעוֹרֵר בּוֹ תְּרוּעָה וּתְקִיעָה, דִּין קָשֶׁה בְּרַחֲמִים, וּשְׁבָרִים - דִּין קָשֶׁה בְּלִי רַחֲמִים (דין רפה ברחמים), וְאָז כָּךְ יְעוֹרְרוּ לְמַעְלָה לְהִתְעָרֵב זֶה בָּזֶה.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, בָּזֶה מִתְמַתֵּק הַשָּׂטָן וּמִתְקַצֶּרֶת אוֹת נוּ\"ן מִן וֵשֶׁט. מַה שֶּׁהָיָה שָׂטָן מִקֹּדֶם, שָׁב לַאֲחוֹרָיו, וְחָזַר לִהְיוֹת וֵשֶׁט כְּבָרִאשׁוֹנָה. מִשּׁוּם שֶׁהַקֹּל קוֹל יַעֲקֹב. יִשְׂרָאֵל שֶׁאֵין כֹּחָם בַּאֲכִילָה וּשְׁתִיָּה כִּשְׁאָר הָאֻמּוֹת, שֶׁיּוֹרְשִׁים עוֹלָם הַזֶּה, שֶׁכֹּחָם בַּאֲכִילָה וּשְׁתִיָּה. אֶלָּא כֹּחָם בְּקוֹל זֶה, שֶׁהוּא עוֹלָם הַבָּא, עוֹלָם אָרֹךְ, שֶׁנִּבְרָא בָּאוֹת יוֹ\"ד. וּמִשּׁוּם שֶׁקּוֹל שׁוֹפָר מִמֶּנּוּ יוֹצֵא, אָמְרוּ חֲכָמִים, אֵין פּוֹחֲתִין מֵעֲשָׂרָה שׁוֹפָרוֹת. וּבְאוֹת י' וַדַּאי נַעֲשָׂה עוֹלָם אָרֹךְ, שֶׁהוּא אוֹת ו', עוֹלָם הַבָּא. וּבָאוֹת ה' בָּרָא עוֹלָם הַזֶּה, שֶׁהִיא אוֹת ה' קְטַנָּה, שֶׁבָּהּ אֲכִילָה וּשְׁתִיָּה שֶׁל הַתּוֹרָה.</p>\n<p>וְעוֹד סוֹד אַחֵר, אַחַר שֶׁנִּגְזְרָה גְזֵרָה בִּשְׁתֵּי אוֹתִיּוֹת, שֶׁהֵם שְׁתֵּי ה' ה', שְׁנֵי בָּתֵּי דִינִים - מִי יָכוֹל לְבַטֵּל גְּזֵרָה שֶׁל שְׁנֵיהֶם? י' ו', שֶׁאוֹת הֵ\"א הִיא אִמָּא עֶלְיוֹנָה. י' - אָב. וּמַה כָּתוּב? (במדבר ל) כָּל נֵדֶר וְכָל שְׁבֻעַת אִסָּר לְעַנֹּת נָפֶשׁ, שֶׁהִיא אוֹת ה', אִישָׁהּ יְקִימֶנּוּ וְאִישָׁהּ יְפֵרֶנּוּ. וּמִשּׁוּם זֶה צָרִיךְ לְעוֹרֵר הַקּוֹל, שֶׁהוּא אוֹת ו', בַּעֲשָׂרָה שׁוֹפָרוֹת, שֶׁהֵם אוֹת י'. וְהָעִקָּר שֶׁלָּהֶם בִּנְשִׁימָה אַחַת, כָּל סִימָן וְסִימָן, בַּפֶּה, שֶׁהִיא אוֹת י' - מֵעֲשָׂרָה.</p>\n<p>מִיָּד שֶׁשָּׁמְעוּ דְבָרִים אֵלּוּ רַבִּי שִׁמְעוֹן וְכָל הַחֲבֵרִים, אָמְרוּ, בָּרוּךְ ה' שֶׁזָּכִינוּ לִשְׁמֹעַ דְּבָרִים אֵלּוּ מֵאוֹתוֹ שֶׁנִּקְרָא רַבָּם שֶׁל נְבִיאִים, רַבָּם שֶׁל חֲכָמִים, רַבָּם שֶׁל מַלְאֲכֵי הַשָּׁרֵת, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מְדַבֵּר עַל פִּיו, וְכָתַב עַל יָדָיו סוֹדוֹת אֵלּוּ שֶׁלֹּא נִשְׁמְעוּ כְמוֹתָם מִמַּתַּן תּוֹרָה וְעַד כָּאן.</p>\n<p>אָמַר לוֹ, מְנוֹרָה קְדוֹשָׁה, הַשְׁלֵם דִּבְרֵי הַסּוֹדוֹת שֶׁל הַחִבּוּר הַקַּדְמוֹן לְפָרֵשׁ אוֹתָם, שֶׁהֲרֵי כָּל בַּעֲלֵי הַיְשִׁיבוֹת שֶׁל מַעְלָה, וּבַעֲלֵי הַיְשִׁיבוֹת שֶׁל מַטָּה, כֻּלָּם מְזֻמָּנִים לִשְׁמֹעַ דְּבָרִים אֵלּוּ מִפִּיךְ וּפֵרוּשִׁים שֶׁלְּךְ, שֶׁהֲרֵי שִׂמְחָה וּפִדְיוֹן יִתְעוֹרֵר בָּהֶם לְמַעְלָה וּמַטָּה. אַל תִּתְּנוּ דֳמִי לוֹ, אַתָּה וְכָל הַחֲבוּרָה שֶׁלְּךְ. עוֹד נֶאֱמַר בַּחִבּוּר הַקַּדְמוֹן. (ע\"כ רעיא מהימנא).</p>"],[9522012505,"<p>בִּתְרוּעָה וּתְקִיעָה וּשְׁבָרִים נִמְתָּק הַכֹּל זֶה בָּזֶה. וְכָל מַה שֶּׁאוֹתוֹ כָּבֵד לוֹקֵחַ - מַקְרִיב אֶל הַלֵּב, שֶׁהוּא מֶלֶךְ, לָזוּן (לדון). וְאוֹתוֹ הַלֵּב אֵין דַּרְכּוֹ וְאֵין חִשְׁקוֹ בַּמַּעֲשִׂים הָעֲכוּרִים שֶׁל עַמּוֹ, אֶלָּא לוֹקֵחַ כָּל הַמְבֹרָר וְכָל הַצַּח וְכָל הַזְּכֻיּוֹת וְכָל הַמַּעֲשִׂים טוֹבִים. וְכָל אוֹתָהּ הָעֲכִירוּת וְהַטִּנּוּף וְהַלִּכְלוּךְ, שֶׁהֵם מַעֲשִׂים רָעִים, (אין) (זורק אותם לשאר עמים עובדי כוכבים ומזלות אותו כבד) מַשְׁאִיר לַכָּבֵד, שֶׁנֶּאֱמַר בּוֹ (בראשית כז) עֵשָׂו (אחי) אִישׁ שָׂעִר. וְכָל הָעוֹרְקִים שֶׁלּוֹ, שֶׁהֵם שְׁאָר אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. זֶהוּ שֶׁכָּתוּב, (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנֹתָם. מַהוּ עֲוֹנֹתָם? עֲווֹנוֹת תָּם, שֶׁנֶּאֱמַר בּוֹ (בראשית כה) וְיַעֲקֹב אִישׁ תָּם. וְהַחוֹבוֹת שֶׁל הָעַמּוּד (שלעמו) שֶׁהֵם עוֹרְקִים וּדְפָקִים שֶׁל הַלֵּב.</p>\n<p>וּמִשּׁוּם זֶה, שְׁחִין וְצָרַעַת וְסַפַּחַת שֶׁבְּכָל אוֹתָם אֵיבָרִים, מוֹצָאָם מֵהַכָּבֵד, מֵאוֹתָם לִכְלוּכִים שֶׁנִּשְׁאֲרוּ בוֹ. וּמֵהַלֵּב בָּאָה כָּל הַבְּרִיאוּת לְכָל הָאֵיבָרִים. שֶׁכָּךְ הוּא, כֵּיוָן שֶׁהַלֵּב נוֹטֵל כָּל הַזַּךְ וְהַמְבֹרָר וְהַצַּח. הַכָּבֵד נוֹטֵל כָּל מַה שֶּׁנִּמְצָא וְנִשְׁאָר מֵהַלִּכְלוּךְ וְהַטִּנֹּפֶת, וְזוֹרֵק לְכָל שְׁאָר הָאֵיבָרִים, שֶׁהֵם שְׁאָר אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת אֲחֵרִים, בְּעַל כָּרְחָם. וּמִפְּסֹלֶת שֶׁל פְּסֹלֶת הַכָּבֵד נוֹטֵל הַטְּחוֹל, שֶׁנֶּאֱמַר בּוֹ (בראשיתא) יְהִי מְאֹרֹת. (משליג) מְאֵרַת ה' בְּבֵית רָשָׁע.</p>"],[9522012506,"<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, וַהֲרֵי בֵּאֲרוּ חֲכָמִים עַל זֶה, טְחוֹל שׂוֹחֵק. וְזֶהוּ (קהלת ז) שְׂחֹק הַכְּסִיל. וּמִשּׁוּם זֶה פֵּרְשׁוּהוּ חַכְמֵי הַמִּשְׁנָה, אוֹי לוֹ לְמִי שֶׁהַשָּׁעָה מְשַׂחֶקֶת לוֹ. וְקֹהֶלֶת אָמַר, (שם) טוֹב כַּעַס מִשְּׂחוֹק. טוֹב כַּעַס שֶׁל הַכָּבֵד, שֶׁהִיא מָרָה, רְצוּעָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, רְצוּעָה לְהַלְקוֹת בָּהּ הַצַּדִּיקִים בָּעוֹלָם הַזֶּה בָּחֳלָאִים רָעִים, בִּנְגָעִים, מִשְּׂחוֹק שֶׁשּׂוֹחֵק לָהֶם בַּטְּחוֹל, בַּלִּכְלוּךְ שֶׁל הָעוֹלָם הַזֶּה, שֶׁשּׂוֹחֶקֶת לָהֶם הַשָּׁעָה בְּעֹשֶׁר. וְעוֹד, אֶרֶס הַטְּחוֹל שֶׁהוּא הַזּוֹחֵל בֶּעָפָר, וְהוּא חָזָק יוֹתֵר מֵאֶרֶס הַמָּרָה.</p>\n<p>וּמִשּׁוּם שֶׁעֵרֶב רַב הֵם שְׂאוֹר שֶׁבָּעִסָּה, וְאֵלּוּ אֻמּוֹת הָעוֹלָם דּוֹמִים לְמֹץ, יוֹתֵר מְעַכְּבִים בַּגָּלוּת הָעֵרֶב רַב אֶת יִשְׂרָאֵל מֵאֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. כְּמוֹ שֶׁפֵּרְשׁוּהוּ חֲכָמִים, מִי מְעַכֵּב? שְׂאוֹר שֶׁבָּעִסָּה מְעַכֵּב. שֶׁהֵם דְּבֵקִים בְּיִשְׂרָאֵל כִּשְׂאוֹר בָּעִסָּה. אֲבָל אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת אֵינָם כֵּן, אֶלָּא (תהלים א) כַּמֹּץ אֲשֶׁר תִּדְּפֶנּוּ רוּחַ.</p>"],[9522012507,"<p>וְעוֹד, (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו, כַּאֲשֶׁר רְצוֹנוֹ לַעֲשׂוֹת קִטְרוּג לְהַקָּדוֹשׁ בָּרוּךְ הוּא עִם יִשְׂרָאֵל, וְהוּא נוֹשֵׂא כָּל הַחוֹבוֹת שֶׁיָּכוֹל לָשֵׂאת אוֹתָם עַד שֶׁנַּעֲשֶׂה כָּבֵד, שֶׁנֶּאֱמַר (תהלים לח) כְּמַשָּׂא כָבֵד יִכְבְּדוּ מִמֶּנּוּ, חוֹבוֹת עַל כְּנָפָיו. מָה עוֹשֶׂה? עוֹלֶה לְהַר עֶלְיוֹן, כַּחֲמוֹר כַּאֲשֶׁר הוּא רוֹצֶה לַעֲלוֹת לְהַר גָּבוֹהַּ, כְּמַשָּׂא כָבֵד יִכְבַּד עָלָיו. כַּאֲשֶׁר הוּא לְמַעְלָה וְרוֹצֶה לַעֲלוֹת עוֹד לְפִי הַמְּעַט שֶׁנִּשְׁאָר לוֹ, כָּבֵד עָלָיו מַשָּׂאוֹ, וְנוֹפֵל, וּמַפִּיל עַצְמוֹ לְמַטָּה. וּבְכֹבֶד הַמַּשָּׂא שֶׁהֻכְבַּד עָלָיו, נַעֲשׂוּ כָּל הָאֵיבָרִים שֶׁלּוֹ חֲתִיכוֹת, שֶׁלֹּא נִשְׁאָר אֵיבָר שָׁלֵם. גַּם כָּךְ נַעֲשֶׂה לְסָמָאֵל וְנָחָשׁ, הַכָּבֵד וְיוֹתֶרֶת הַכָּבֵד, יֵצֶר הָרָע וּבַת זוּגוֹ זוֹנָה. מִשָּׁם כָּל בַּת אֵל נֵכָר זוֹנָה. (ע\"כ רעיא מהימנא).</p>\n<p>אָמַר רַבִּי פִּנְחָס, דֶּרֶךְ זוֹ הָיְתָה מְתֻקֶּנֶת לִי לִשְׁמֹעַ דְּבָרִים אֵלּוּ מֵעַתִּיק הַיָּמִים, אַשְׁרֵי הָעוֹלָם שֶׁאַתָּה נִמְצָא בְתוֹכוֹ. אוֹי לָעוֹלָם שֶׁיִּשָּׁאֲרוּ יְתוֹמִים וְלֹא יוֹדְעִים דִּבְרֵי תוֹרָה כְּמוֹ שֶׁצָּרִיךְ. וַדַּאי כָּךְ הוּא, שֶׁהַכָּבֵד נוֹטֵל הַכֹּל - טוֹב וָרָע. וְאַף עַל גַּב שֶׁמְּשׁוֹטֵט וְאוֹסֵף כָּל חוֹבוֹתָם שֶׁל יִשְׂרָאֵל - כָּךְ גַּם זְכֻיּוֹתֵיהֶם אוֹסֵף כְּדֵי לְהַעֲמִיד קִטְרוּגוֹ. וְהַכֹּל, זֶה וָזֶה מַקְרִיב לְגַבֵּי הַלֵּב. וְדֶרֶךְ הַלֵּב שֶׁלֹּא נוֹטֵל אֶלָּא הַזַּךְ וְהַמְבֹאָר וְהַצַּח שֶׁל הַלֵּב, כְּמוֹ שֶׁאָמַרְתָּ. וּשְׁאָר הַטִּנֹּפֶת וְהַלִּכְלוּךְ מַחֲזִיר לַכָּבֵד, וְלוֹקֵחַ הַכֹּל בְּעַל כָּרְחוֹ, שֶׁנֶּאֱמַר וְנָשָׂא הַשָּׂעִיר עָלָיו וְגוֹ'. דָּבָר זֶה חָזַרְתִּי כְּדֵי שֶׁיִּתְמַתֵּק לְפִי כִּמְתִיקוּת הַדְּבַשׁ. אַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לָזֶה, לִרְאוֹת זֶה בְּעֵינַי.</p>\n<p>אַף הוּא פָּתַח וְאָמַר, (תהלים קלא) ה' לֹא גָבַהּ לִבִּי וְלֹא רָמוּ עֵינַי וְגוֹ'. פָּסוּק זֶה אָמַר דָּוִד בְּשָׁעָה שֶׁהָיָה הוֹלֵךְ עַל שְׂפַת הַנָּהָר, (והיה אומר) רִבּוֹנוֹ שֶׁל עוֹלָם, כְּלוּם הָיָה בֶּן אָדָם שֶׁהוֹדָה וְשִׁבַּח לַאֲדוֹנוֹ כָּמוֹנִי?! הִזְדַּמְּנָה לוֹ צְפַרְדֵּעַ, אָמְרָה לוֹ: דָּוִד, לֹא תִתְגָּאֶה, שֶׁאֲנִי עָשִׂיתִי יוֹתֵר מִמְּךְ, שֶׁמָּסַרְתִּי גוּפִי עַל דְּבַר קוֹנִי, שֶׁנֶּאֱמַר (שמות ז) וְשָׁרַץ הַיְאֹר צְפַרְדְּעִים, וַהֲרֵי פֵּרְשׁוּהוּ. וְעוֹד, שֶׁאֲנִי מְשַׁבַּחַת וּמְזַמֶּרֶת לַיְלָה וָיוֹם בְּלִי הַפְסָקָה. בְּאוֹתָהּ שָׁעָה אָמַר דָּוִד, ה' לֹא גָבַהּ לִבִּי וְלֹא רָמוּ עֵינַי. ה' לֹא גָבַהּ לִבִּי.</p>"],[9522012508,"<p>זֶהוּ קָרְבָּן שֶׁבְּכָל יוֹם וּבְכָל זְמַן וּזְמַן אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנִּכְלֶלֶת כְּנֶסֶת יִשְׂרָאֵל בּוֹ בֵּין כָּל שְׁאָר חֵילוֹתֶיהָ, וְכָל אוֹתָן הָעֲבוֹדוֹת מוֹצִיאִים אוֹתָהּ מִבֵּין הַקּוֹצִים וּמִבֵּין שְׁאָר הָאֻמּוֹת. כָּךְ יִשְׂרָאֵל, כָּל זְמַן שֶׁהֵם אֲטוּמֵי לֵב וְלֹא פוֹתְחִים בִּתְשׁוּבָה, לֹא מַעֲלִים רֵיחַ וְלֹא מוֹצִיא אוֹתָם מִבֵּין הַקּוֹצִים. אֲבָל כַּאֲשֶׁר פּוֹתְחִים בִּתְשׁוּבָה, מִיָּד מַעֲלִים רֵיחַ, וְיוֹצִיא אוֹתָם מִבֵּין הַקּוֹצִים, וְתֵהָנֶה בָהֶם כְּנֶסֶת יִשְׂרָאֵל, שֶׁנֶּאֱמַר (שיר השירים ה) פִּתְחִי לִי אֲחֹתִי רַעְיָתִי. שֶׁכָּל זְמַן שֶׁהַשּׁוֹשַׁנָּה אֲטוּמָה, אֵין לָהּ רֵיחַ וְלֹא עוֹלָה מִבֵּין הַקּוֹצִים, וְדִירָתָהּ בֵּינֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שָׁלַח אוֹתָנוּ לָלֶכֶת דֶּרֶךְ זוֹ אֶלָּא לִלְמֹד דְּבָרִים אֵלּוּ.</p>"],[9522012509,"<p>עַד שֶׁהָיוּ יוֹשְׁבִים, בָּא נֶשֶׁר וְיָרַד, וְנָטַל שׁוֹשַׁנָּה אַחַת מִבֵּינֵיהֶם וְהָלַךְ. אָמְרוּ, מִכָּאן וָהָלְאָה נֵלֵךְ לְדַרְכֵּנוּ. קָמוּ וְהָלְכוּ. עַד כָּאן דַּרְכּוֹ שֶׁל רַבִּי פִּנְחָס, וְרַבִּי שִׁמְעוֹן הָלַךְ לוֹ, הוּא וְרַבִּי אֶלְעָזָר וּשְׁאָר הַחֲבֵרִים, וְרַבִּי פִּנְחָס וּשְׁאָר הַחֲבֵרִים.</p>\n<p>פָּתַח וְאָמַר רַבִּי פִּנְחָס עַל זֶה, (תהלים ס) לַמְנַצֵּחַ עַל שׁוּשַׁן עֵדוּת מִכְתָּם לְדָוִד לְלַמֵּד. מַהוּ לְלַמֵּד? לְלַמֵּד לִבְנֵי הָעוֹלָם חָכְמָה. וַהֲרֵי פֵּרְשׁוּהוּ, שׁוּשַׁן עֵדוּת - אֵלּוּ סַנְהֶדְרִין גְּדוֹלָה, שֶׁכָּתוּב בָּהּ (שיר השירים ז) סוּגָה בַּשּׁוֹשַׁנִּים. מִכְתָּם לְדָוִד - סִימָן שֶׁהֶרְאוּ לוֹ, לְדָוִד, כַּאֲשֶׁר שָׁלַח לְיוֹאָב לַאֲרַם נַהֲרַיִם וְלַאֲרַם צוֹבָה לְהִלָּחֵם בָּהֶם. אָמַר רַבִּי פִּנְחָס, זֶהוּ שׁוּשַׁן עֵדוּת שֶׁקַּיָּם כָּאן. הֲרֵי הַכּוֹכָבִים בַּשָּׁמַיִם, שְׁכִינָה עָלֵינוּ, וּמַדְרֵגוֹת עֶלְיוֹנוֹת עִמָּהּ, וְעֶזְרָה קְדוֹשָׁה לְשֶׁבַח. זֶהוּ שׁוּשָׁן בִּשְׁלֵמוּת כְּמוֹ שֶׁצָּרִיךְ. קָמוּ וְהָלְכוּ אֵלּוּ לְכָאן וְאֵלּוּ לְכָאן. הָלַךְ לוֹ רַבִּי פִּנְחָס וְלָן בִּכְפָר עֲקִימִין, וְרַבִּי יִצְחָק וְרַבִּי חִיָּיא עִמּוֹ.</p>\n<p>עֵד שֶׁהִקְדִּימוּ לָלֶכֶת, יָשְׁבוּ וְחִכּוּ לְאוֹר הַבּקֶר. זָקַף עֵינָיו רַבִּי חִיָּיא וְרָאָה אֵלּוּ כּוֹכָבִים שֶׁל שַׁרְבִיט שֶׁרָצִים וְהוֹלְכִים. אָמַר, וַדַּאי בְּכַמָּה פְעָמִים שָׁאַלְתִּי עַל אֵלּוּ הַכּוֹכָבִים.</p>\n<p>אָמַר רַבִּי פִּנְחָס, אֵלּוּ הַכּוֹכָבִים שֶׁל שַׁרְבִיט יְדוּעִים בַּהֲבָנָה שֶׁל הַחֲבֵרִים, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת כָּל אוֹתָם כּוֹכְבֵי הָרָקִיעַ, גְּדוֹלִים וּקְטַנִּים, וְכֻלָּם מוֹדִים וּמְשַׁבְּחִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא (שכתוב (תהלים קמז) מונה מספר לכוכבים). וְכַאֲשֶׁר מַגִּיעַ זְמַנָּם לְשַׁבֵּחַ, קוֹרֵא לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשֵׁם, שֶׁנֶּאֱמַר (ישעיה מ) לְכֻלָּם בְּשֵׁם יִקְרָא. וְאָז רָצִים וּמוֹשִׁיטִים שַׁרְבִיט שֶׁל אוֹר לָלֶכֶת לְשַׁבֵּחַ לְקוֹנָם, בְּאוֹתוֹ מָקוֹם שֶׁנִּצְטַוּוּ. זֶהוּ שֶׁכָּתוּב (שם) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה וְגוֹ'. תּוֹךְ כְּדֵי כָּךְ עָלָה הָאוֹר. קָמוּ וְהָלְכוּ.</p>"],[9522012510,"<p>עֵד שֶׁהָיוּ הוֹלְכִים, בָּא הַנֶּשֶׁר הַגָּדוֹל, הִקִּיף עַל רָאשֵׁיהֶם וְעָמַד עֲלֵיהֶם. אָמַר רַבִּי פִּנְחָס, וַדַּאי זְמַן רָצוֹן הוּא עַתָּה. אוֹתָהּ שָׁעָה נִפְתְּחוּ שַׁעֲרֵי רַחֲמִים לְכָל אוֹתָם שֶׁבְּבֵית חָלְיָם, וְהוּא זְמַן לָרְפוּאָה שֶׁלָּהֶם. וְאַף עַל גַּב שֶׁהֵם אֲסוּרֵי הַמֶּלֶךְ, שֶׁהֲרֵי נֶשֶׁר זֶה סִימָן שֶׁל רַחֲמִים הוּא.</p>\n<p>פָּתַח וְאָמַר, (דברים לב) כְּנֶשֶׁר יָעִיר קִנּוֹ עַל גּוֹזָלָיו יְרַחֵף וְגוֹ'. אֵין בָּעוֹלָם מִי שֶׁהוּא בַּעַל רַחֲמִים עַל בָּנָיו כְּנֶשֶׁר, וַהֲרֵי פֵּרְשׁוּ הַפָּסוּק שֶׁנֶּאֱמַר (משלי ל) וְיֹאכְלוּהָ בְנֵי נֶשֶׁר, שֶׁהוּא מְרַחֵם עַל בָּנָיו. וּמִתּוֹךְ שֶׁעַתָּה זְמַן שֶׁל רַחֲמִים, בָּא נֶשֶׁר זֶה וְסוֹבֵב עָלֵינוּ. בְּשָׁעָה זוֹ הִיא רַחֲמִים לְכָל אוֹתָם שֶׁבְּבֵית חָלְיָם. וְזֶהוּ שֶׁכָּתוּב (תהלים ה) ה' בֹּקֶר תִּשְׁמַע קוֹלִי. וְזֶה בֹּקֶר שֶׁל אַבְרָהָם וְהִתְעוֹרְרוּת שֶׁלּוֹ.</p>\n<p>תּוֹךָ כְּדֵי כָּךְ סָבַב הַנֶּשֶׁר וְעָבַר לִפְנֵיהֶם. אָמַר רַבִּי פִּנְחָס, נֶשֶׁר נֶשֶׁר, מָה אַתָּה אֶצְלֵנוּ? אִם בִּשְׁלִיחוּת קוֹנְךְ בָּאתָ - הֲרֵי אָנוּ כָּאן. אִם בִּגְלַל דָּבָר (סימן) אַחֵר בָּאתָ - הֲרֵי אָנוּ כָּאן מְזֻמָּנִים לִשְׁמֹעַ. הִתְרוֹמֵם הַנֶּשֶׁר לְמַעְלָה וְנִתְכַּסָּה מֵהֶם, וְהֵם יָשְׁבוּ.</p>\n<p>אָמַר רַבִּי חִיָּיא, זֶה שֶׁל שְׁלֹמֹה הַמֶּלֶךְ קָטָן (תמוה) הוּא, שֶׁלָּמַדְנוּ, הַנֶּשֶׁר הַגָּדוֹל הָיָה בָּא אֵצֶל שְׁלֹמֹה הַמֶּלֶךְ בְּכָל יוֹם וָיוֹם, וְהָיָה שְׁלֹמֹה הַמֶּלֶךְ רוֹכֵב עַל כְּנָפָיו, וּמוֹבִיל אוֹתוֹ אַרְבַּע מֵאוֹת פַּרְסָאוֹת בְּשָׁעָה אַחַת. לְאָן הוֹבִיל אוֹתוֹ? לְתַרְמוֹד בַּמִּדְבָּר בֶּהָרִים. מָקוֹם אֶחָד יֵשׁ אֵצֶל הָרֵי הַחֹשֶׁךְ שֶׁנִּקְרָא תַּרְמוֹד בַּמִּדְבָּר, וְאֵין הוּא מָקוֹם שֶׁל אַנְשֵׁי תַּרְמוֹד, אֶלָּא תַּרְמוֹד שֶׁהוּא בַּמִּדְבָּר בֶּהָרִים, וְשָׁם מִתְאַסְּפִים כָּל הָרוּחוֹת וְהַצְּדָדִים הָאֲחֵרִים. וְאוֹתוֹ נֶשֶׁר הָיָה טָס לְשָׁם בְּשָׁעָה אַחַת.</p>\n<p>כֵּיוָן שֶׁהָיָה עוֹמֵד עַל הַמָּקוֹם הַהוּא, הִגְבִּיהַּ הַנֶּשֶׁר, וּשְׁלֹמֹה כָּתַב פֶּתֶק וְהִשְׁלִיכוֹ לְשָׁם, וְנִצּוֹל מֵאֵלּוּ הָרוּחוֹת. וְהַנֶּשֶׁר הָיָה מִסְתַּכֵּל תּוֹךְ הַחֹשֶׁךְ שֶׁל הֶהָרִים לַמָּקוֹם שֶׁשָּׁם נִמְצָאִים עֲזָא וַעֲזָאֵל, שֶׁהֵם שָׁם אֲסוּרִים בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל קְבוּעוֹת תּוֹךְ הַתְּהוֹם, וְאֵין יְכֹלֶת (רשות) לְאָדָם בָּעוֹלָם לְהִכָּנֵס לְשָׁם, וַאֲפִלּוּ עוֹפוֹת הַשָּׁמַיִם, חוּץ מִבִּלְעָם.</p>\n<p>וְכֵיוָן שֶׁהַנֶּשֶׁר מִסְתַּכֵּל תּוֹךְ הַחֹשֶׁךְ הַגָּדוֹל, יוֹרֵד לְמַטָּה וְלוֹקֵחַ אֶת שְׁלֹמֹה הַמֶּלֶךְ תַּחַת כָּנָף הַשְּׂמָאלִי, וּמְכַסֶּה אוֹתוֹ, וְעוֹמֵד עַל אֵלּוּ הַשַּׁלְשְׁלָאוֹת, וְהוֹלֵךְ וּמִתְקָרֵב אֲלֵיהֶם, וּשְׁלֹמֹה אָז מוֹצִיא טַבַּעַת (שורטיגא) שֶׁחָקוּק עָלֶיהָ שֵׁם קָדוֹשׁ, וְשָׂם בְּפִי הַנֶּשֶׁר, וּמִיָּד הֵם הָיוּ אוֹמְרִים כָּל מַה שֶּׁרוֹצֶה שְׁלֹמֹה הַמֶּלֶךְ, וּמִשָּׁם הָיָה יוֹדֵעַ שְׁלֹמֹה חָכְמָה עֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב (מלכים א ט) וַיִּבֶן וְגוֹ' אֶת תַּדְמֹר (תרמוד) בָּאָרֶץ. וְכִי בִּנְיָנִים הָיָה עוֹשֶׂה בָּאָרֶץ? אֶלָּא מַהוּ וַיִּבֶן? הִסְתַּכֵּל בְּשִׂכְלוֹ וְיָדַע לְאוֹתוֹ מָקוֹם לָדַעַת בּוֹ חָכְמָה (עליונה. כמו שנאמר (נחמיה ח) ויבינו במקרא).</p>"],[9522012511,"<p>עַד שֶׁהָיוּ יוֹשְׁבִים, אוֹתוֹ נֶשֶׁר חָזַר אֲלֵיהֶם וְשׁוֹשַׁנָּה אַחַת בְּפִיו, וְהִשְׁלִיךְ לִפְנֵיהֶם וְהָלַךְ לוֹ. רָאוּ וְשָׂמְחוּ. אָמַר רַבִּי פִּנְחָס, וְלֹא אָמַרְתִּי לָכֶם שֶׁנֶּשֶׁר זֶה בִּשְׁלִיחוּת שֶׁל קוֹנוֹ הוֹלֵךְ וּבָא? שׁוֹשַׁנָּה זוֹ הִיא שׁוּשַׁן עֵדוּת שֶׁאָמַרְתִּי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתָהּ אֶצְלֵנוּ.</p>\n<p>פָּתַח כְּמִקֹּדֶם וְאָמַר, (תהלים ס) לַמְנַצֵּחַ עַל שׁוּשַׁן עֵדוּת מִכְתָּם לְדָוִד לְלַמֵּד. וְכִי שׁוּשַׁן עֵדוּת אֵיזוֹ עֵדוּת מֵעִיד? אֶלָּא שׁוּשָׁן זֶה הִיא עֵדוּת לְמַעֲשֵׂה בְרֵאשִׁית, וְהִיא עֵדוּת לִכְנֶסֶת יִשְׂרָאֵל, עֵדוּת לַיִּחוּד הָעֶלְיוֹן, וְזֶהוּ בִּגְלַל שֶׁשּׁוֹשַׁנָּה זוֹ יֵשׁ בָּהּ שְׁלֹשָׁה עָשָׂר עָלִים, וְכֻלָּם עוֹמְדִים בְּשֹׁרֶשׁ אֶחָד, וְיֵשׁ בָּהּ חֲמִשָּׁה עָלִים מִבַּחוּץ חֲזָקִים שֶׁמְּחַפִּים לְשׁוֹשַׁנָּה זוֹ וּמְגִנִּים עָלֶיהָ.</p>\n<p>וְהַכֹּל בְּסוֹד הַחָכְמָה הוּא. שְׁלֹשָׁה עָשָׂר עָלִים אֵלּוּ הֵם שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים שֶׁיּוֹרֶשֶׁת כְּנֶסֶת יִשְׂרָאֵל מִלְמַעְלָה, וְכֻלָּם אֲחוּזִים בְּשֹׁרֶשׁ אֶחָד. (שהם י\"ג תקונים של הזקן התחתון של אריך אנפין, שהם י\"ג תקונים עליונים של זעיר אנפין) וְהוּא בְּרִית אַחַת וְדֻגְמַת בְּרִית הַיְסוֹד (היחוד) שֶׁל הַכֹּל. חֲמִשָּׁה חֲזָקִים שֶׁסּוֹבְבִים עָלֶיהָ אֵלּוּ חֲמִשִּׁים שְׁעָרִים, חֲמֵשׁ מֵאוֹת שָׁנָה (שלהיסוד, יסוד (בּביתהמקדָּש) ברית קדש) שֶׁעֵץ הַחַיִּים הוֹלֵךְ בָּהֶם.</p>\n<p>עֵדוּת לְמַעֲשֵׂה בְרֵאשִׁית. כָּל מַעֲשֵׂה בְרֵאשִׁית, כֻּלָּם (חמש מאות שנה של היסוד ברית קדש, כלם מעשה של בראשית יושבים וכו') תֵּבוֹת יְדוּעוֹת בַּהֲבָנָה, וְעוֹמְדִים בְּחֶשְׁבּוֹן, וְשֵׁם אֱלֹהִים שֶׁל מַעֲשֵׂה בְרֵאשִׁית, מַרְאֶה לְמַעְלָה וּמַרְאֶה לְמַטָּה. מַרְאֶה לְמַעְלָה בְּסוֹד שֶׁל הָעוֹלָם הַבָּא, וּמַרְאֶה לְמַטָּה בְּסוֹד שֶׁל כְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>שׁוֹשַׁנָּה - עֵדוּת לְמַעֲשֵׂה בְרֵאשִׁית, שֶׁעוֹמֶדֶת בְּכָל אֵלּוּ הַסִּימָנִים, שֶׁכָּתוּב (זה) בְּרֵאשִׁית בָּרָא אֱלֹהִים. זוֹ שׁוֹשַׁנָּה. שְׁלֹשָׁה עָשָׂר עָלִים (הם) שְׁלֹשׁ עֶשְׂרֵה תֵּבוֹת עַד שֵׁם אֱלֹהִים הַשֵּׁנִי. וְאֵלּוּ הֵם: א - אֵת, ב - הַשָּׁמַיִם, ג - וְאֵת, ד - הָאָרֶץ, ה - וְהָאָרֶץ, ו - הָיְתָה, ז - תֹהוּ, ח - וָבֹהוּ, ט - וְחֹשֶׁךְ, י - עַל, יא - פְּנֵי, יב - תְהוֹם, יג - וְרוּחַ. הֲרֵי שְׁלֹשָׁה עָשָׂר עָלִים שֶׁל הַשּׁוֹשַׁנָּה. חֲמִשָּׁה חֲזָקִים שֶׁסּוֹבְבִים לְאֵלּוּ הֵם: א - מְרַחֶפֶת, ב - עַל, ג - פְּנֵי, ד - הַמָּיִם, ה - וַיֹּאמֶר. הֲרֵי חֲמִשָּׁה אֲחֵרִים. אַחַר כָּךְ נֶאֱמַר יְהִי אוֹר, הֲרֵי עִקָּר וְשֹׁרֶשׁ שֶׁל הַשּׁוֹשַׁנָּה שֶׁהַכֹּל אָחוּז בָּהּ.</p>\n<p>עֵדוּת לַיִּחוּד. חֲמִשָּׁה עָלִים חֲזָקִים, הַשֹּׁרֶשׁ וְהַיִּחוּד שֶׁאֲחוּזִים בּוֹ שְׁלֹשָׁה עָשָׂר עָלִים אֵלּוּ. (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' - הֲרֵי חֲמִשָּׁה עָלִים שֶׁל הַשּׁוֹשַׁנָּה. אֶחָד - זֶהוּ הָעִקָּר וְהַשֹּׁרֶשׁ שֶׁהַכֹּל אָחוּז בּוֹ. סוֹד (עדות ליחוד. חמש תבות שמע ישראל ה' אלהינו ה' אחד, אלו חמשה עלים חזקים של השושנה. שרש ויסוד אחוזים בו. זהו אחד. והוא עקר ושרש שהכל אחוזים בו. שלשה עשר עלים אלו סוד) שֶׁל שְׁלֹשׁ עֶשְׂרֵה בְּחֶשְׁבּוֹן, חוֹתַם הַמֶּלֶךְ.</p>\n<p>בֹּא וּרְאֵה, כְּדֻגְמַת הַשּׁוֹשַׁנָּה בֵּין הַחוֹחִים, (שיר השירים ב) כָּךְ הֵם יִשְׂרָאֵל בֵּין הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְכָךְ כְּנֶסֶת יִשְׂרָאֵל בֵּין שְׁאָר הֲמוֹנֵי הַשָּׂרִים הַמְמֻנִּים. כָּל זְמַן שֶׁהַשּׁוֹשַׁנָּה עוֹמֶדֶת סְגוּרָה וְאֵינָהּ פְּתוּחָה, אֵין בָּהּ רֵיחַ, וְלֹא מַעֲלִים אוֹתָהּ וְלֹא מוֹצִיאִים אוֹתָהּ מִתּוֹךְ הַקּוֹצִים. אֲבָל בְּשָׁעָה שֶׁהַשּׁוֹשַׁנָּה פְּתוּחָה, מַעֲלָה רֵיחַ, וְאָז מוֹצִיאִים אוֹתָהּ מִתּוֹךְ הַקּוֹצִים, וְנֶהֱנֵית מֵהֶם כְּנֶסֶת יִשְׂרָאֵל, שֶׁנֶּאֱמַר (שיר השירים ה) פִּתְחִי לִי אֲחֹתִי רַעְיָתִי. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שָׁלַח אוֹתָהּ לָנוּ אֶלָּא לָלֶכֶת לְדַרְכֵּנוּ.</p>"],[9522012512,"<p>וּבְחִבּוּר קַדְמוֹן, אָמַר רַבִּי אֶלְעָזָר לְאָבִיו, הֲרֵי שָׁמַעְתִּי עַל אֵלּוּ הָאֵיבָרִים הָאֲטוּמִים בְּסוֹד הַקָּרְבָּנוֹת. אֵיבָרִים אֲחֵרִים, הַסּוֹד שֶׁלָּהֶם מַהוּ? אָמַר לוֹ רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר, אֶלְעָזָר בְּנִי, כָּל שְׁאָר אֵיבָרִים שֶׁמִּבִּפְנִים, סוֹד עֶלְיוֹן הוּא.</p>\n<p>בֹּא וּרְאֵה, הַלֵּב הֲרֵי נֶאֱמַר, אֲבָל לֵב זֶה הוּא אֵשׁ שֶׁשּׂוֹרֵף, וְאִם לֹא שֶׁהִזְמִין אֵלָיו הַמֶּלֶךְ הָעֶלְיוֹן אֶת כַּנְפֵי הָרֵאָה, שֶׁמְּבִיאִים לְפָנָיו הָרוּחַ מֵרוּחַ שֶׁנּוֹשֶׁבֶת מִתּוֹךְ בְּשָׂמִים עֶלְיוֹנִים, הָיָה שׂוֹרֵף אֶת הָעוֹלָם בְּרֶגַע אֶחָד.</p>\n<p>פָּתַח וְאָמַר, (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ. מַדּוּעַ שָׂרַף אוֹתָם? מִשּׁוּם שֶׁכַּנְפֵי רֵאָה לֹא נָשְׁבוּ בְּאוֹתָהּ שָׁעָה. וְהַסּוֹד שֶׁל כַּנְפֵי הָרֵאָה, זֶה שֶׁנֶּאֱמַר (תהלים סח) כַּנְפֵי יוֹנָה נֶחְפָּה בַכֶּסֶף. וְאֵלּוּ הֵם רְפָאֵל וְצַדְקִיאֵל. וַעֲלֵיהֶם נֶאֱמַר (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת, לְנַשֵּׁב תָּמִיד לִפְנֵי הַמֶּלֶךְ (הלב).</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, הַמְּנוֹרָה הַקְּדוֹשָׁה, כָּל מַה שֶּׁאָמַרְתָּ - נָכוֹן, אֲבָל הַמֹּחַ הוּא מַיִם, וְהַלֵּב הוּא אֵשׁ, וּשְׁנֵיהֶם הֵם רַחֲמִים וְדִין. זֶה כִּסֵּא רַחֲמִים, וְזֶה כִּסֵּא דִין. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ, עוֹמֵד מִכִּסֵּא דִין, שֶׁהוּא הַלֵּב, וְיוֹשֵׁב עַל כִּסֵּא רַחֲמִים, שֶׁהוּא הַמֹּחַ.</p>\n<p>וְכַאֲשֶׁר הַחוֹבוֹת מִתְרַבִּים עַל הָאֵיבָרִים וְעַל הָעוֹרְקִים שֶׁל הַלֵּב, שֶׁהוּא כִּסֵּא שֶׁל דִּין, נֶאֱמַר בַּלֵּב, (אסתר ז) וְהַמֶּלֶךְ קָם בַּחֲמָתוֹ מִמִּשְׁתֵּה הַיַּיִן, שֶׁהוּא יֵינָהּ שֶׁל תּוֹרָה. וּבִזְמַן שֶׁכַּנְפֵי רֵאָה נוֹשְׁבוֹת עַל הַלֵּב, נֶאֱמַר (אסתר ז) וַחֲמַת הַמֶּלֶךְ שָׁכָכָה. שֶׁעַל שְׁתֵּי כַּנְפֵי רֵאָה נֶאֱמַר, (שמות כה) וְהָיוּ הַכְּרֻבִים פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה סֹכֲכִים בְּכַנְפֵיהֶם עַל הַכַּפֹּרֶת, זוֹ הַכַּפֹּרֶת שֶׁל הַלֵּב.</p>\n<p>וּבַמָּה חֲמַת הַמֶּלֶךְ שָׁכָכָה? בִּגְלַל (שואשמע את קול כנפיהם) (במדבר ז) וַיִּשְׁמַע אֶת הַקּוֹל - זֶה קוֹל הַתּוֹרָה, קוֹל שֶׁל קְרִיאַת שְׁמַע. וַיְדַבֵּר אֵלָיו - בִּתְפִלּוֹת הַפֶּה, שֶׁעָלָיו נֶאֱמַר (תהלים נא) אֲדנָי שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךְ.</p>\n<p>וְאוֹתָהּ הָרוּחַ שֶׁנּוֹשֶׁבֶת בְּכַנְפֵי הָרֵאָה, הִיא מוֹצִיאָה קוֹל בְּקָנֶה, שֶׁהוּא קְנֵה חָכְמָה קְנֵה בִינָה. וְנֶאֱמַר בָּהּ, (יחזקאל לז) כֹּה אָמַר ה' מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ. שֶׁהֵן אַרְבַּע אוֹתִיּוֹת יְהֹוָ\"ה, וְזוֹהִי רוּחַ שֶׁדּוֹפֶקֶת בְּכָל עוֹרְקֵי הַלֵּב, שֶׁנֶּאֱמַר בָּהֶם (יחזקאל א) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, וַדַּאי רוֹעֶה נֶאֱמָן, מַדְרֵגָה שֶׁלְּךְ הִיא, שֶׁבָּהּ נֶאֱמַר וַחֲמַת הַמֶּלֶךְ שָׁכָכָה. (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָ\"ה, בְּגִימַטְרִיָּא מֹשֶׁה. אָמַר לוֹ, בָּרוּךְ אַתָּה הַמָּאוֹר הַקָּדוֹשׁ, נֵר שֶׁדּוֹלֵק לִפְנֵי הַמֶּלֶךְ וְהַמַּלְכָּה. נֵר ה' - הִיא נְשָׁמָה שֶׁלְּךְ.</p>\n<p>אָמַר לוֹ, הֲרֵי אָמַרְתָּ מֹחַ וְלֵב וְכַנְפֵי רֵאָה, שְׁתֵּי כְלָיוֹת מָהֵן? אָמַר הָרוֹעֶה הַנֶּאֱמָן, הֲרֵי בֵּאַרְנוּ בְּכַנְפֵי רֵאָה אֶת הַפָּסוּק עֹשֶׂה מַלְאָכָיו רוּחוֹת. וְהַכְּלָיוֹת - מְשָׁרְתָיו אֵשׁ לוֹהֵט. וְהֵן שְׁתֵּי כַנְפֵי רֵאָה וּשְׁתֵּי כְלָיוֹת, כְּנֶגֶד אַרְבַּע חַיּוֹת שֶׁל הַכִּסֵּא. הַכִּסֵּא הוּא הַלֵּב בָּאֶמְצַע.</p>\n<p>וְכֵן הַמֹּחַ יֵשׁ לוֹ אַרְבַּע חַיּוֹת, שֶׁהוּא כִּסֵּא שֶׁל רַחֲמִים. וּמָהֵן? רְאִיָּה שְׁמִיעָה רֵיחַ דִּבּוּר. רְאִיָּה - אַרְיֵה. שְׁמִיעָה - שׁוֹר. רֵיחַ - נֶשֶׁר. וְאַרְבַּע פָּנִים וְאַרְבַּע כְּנָפַיִם לְכָל אֶחָד. דִּבּוּר - הוּא אָדָם. אָחוּז לְמַעְלָה וּלְמַטָּה, זְרוֹעוֹת, שֶׁבָּהֶן נֶאֱמַר וְיָדֵינוּ פְרוּשׂוֹת כְּנִשְׁרֵי שָׁמַיִם. גּוּף - אַרְיֵה, וְשׁוֹקַיִם, עֲלֵיהֶן נֶאֱמַר (יחזקאל א) וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עֵגֶל. וְעַל הַגּוּף נֶאֱמַר (בראשית א) מֶרְכֶּבֶת הַמִּשְׁנֶה. מִשְׁנָה כָּתוּב, לְשׁוֹן הַמִּשְׁנָה. וּבְחִבּוּר קַדְמוֹן. (ע\"כ רעיא מהימנא).</p>\n<p>טְחוֹל, פָּתַח הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, (קהלת ד) וָאֶרְאֶה אֶת כָּל הָעֲשֻׁקִים (שנעשו) אֲשֶׁר נַעֲשִׂים תַּחַת הַשָּׁמֶשׁ וְהִנֵּה דִמְעַת הָעֲשֻׁקִים. מִי אֵלּוּ הָעֲשׁוּקִים? אֵלּוּ תִּינוֹקוֹת שֶׁהֵם בְּחֵיק אִמּוֹתָם, שֶׁמִּסְתַּלְּקִים מֵהָעוֹלָם עַל יְדֵי מַלְאַךְ הַמָּוֶת. וְכִי מַלְאַךְ הַמָּוֶת הוֹרֵג אוֹתָם שֶׁהוּא עוֹשֵׁק? אֶלָּא חָזַר וְאָמַר, וּמִיַּד עֹשְׁקֵיהֶם כֹּחַ וְאֵין לָהֶם מְנַחֵם. מִי הוּא אוֹתוֹ כֹּחַ? זֶהוּ שֶׁנֶּאֱמַר (בראשית א) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם. וְזֶהוּ מְאֹרֹת חָסֵר וָא\"ו, וְזוֹ לִילִית, שֶׁהִיא מְמֻנָּה עַל אוֹתוֹ הָעוֹשֵׁק.</p>\n<p>וְהִיא נִקְרֵאת טְחוֹל, וְהִיא הוֹלֶכֶת וּמְצַחֶקֶת בַּתִּינוֹקוֹת, וְאַחַר כָּךְ עוֹשָׂה בָּהֶם רֹגֶז וּדְמָעוֹת, לִבְכּוֹת עֲלֵיהֶם. הַטְּחוֹל הוֹלֵךְ אַחַר הַכָּבֵד, שֶׁהוּא מִינוֹ. זֶה נִבְרָא בַּשֵּׁנִי, וְזֶה בָּרְבִיעִי בְּמַעֲשֵׂה בְרֵאשִׁית. וּמִשּׁוּם זֶה אֵין סִימָן טוֹב בַּשֵּׁנִי וּבָרְבִיעִי. כָּבֵד - מִיתָה שֶׁל הַגְּדוֹלִים, טְחוֹל - מִיתָה שֶׁל הַקְּטַנִּים.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, וַדַּאי כָּךְ הוּא, שֶׁהַכָּבֵד הוּא מַדְרֵגָה שֶׁל עֵשָׂו. עֵשָׂו הוּא אֱדוֹם. הוּא כּוֹנֵס אֶת כָּל הַדָּמִים, בֵּין הַצְּלוּלִים בֵּין הָעֲכוּרִים. וְלֹא מַבְחִין בֵּין טוֹב לְרַע. לֹא עוֹשֶׂה הַבְדָּלָה בֵּינֵיהֶם. הַלֵּב הוּא יִשְׂרָאֵל, שֶׁמַּבְדִּיל בֵּין טוֹב לְרַע, בֵּין דָּם טָמֵא לְדָם טָהוֹר, וְלֹא לוֹקֵחַ אֶלָּא הַמְבֹרָר וְהַנָּקִי שֶׁל אוֹתוֹ דָּם, כְּבוֹרֵר אֹכֶל מִתּוֹךְ פְּסֹלֶת.</p>\n<p>וְאַחַר שֶׁנּוֹטֵל הַלֵּב, שֶׁהוּא יַעֲקֹב, הַמְבֹרָר שֶׁבַּדָּמִים, שֶׁהוּא לְמַעְלָה, וְנִשְׁאָר כָּבֵד, שֶׁהוּא עֵשָׂו, עִם הַפְּסֹלֶת - הוּא כּוֹעֵס עָלָיו בַּמָּרָה, שֶׁהִיא גֵּיהִנָּם, שֶׁנִּבְרְאָה בַּיּוֹם הַשֵּׁנִי, מִיתַת הַגְּדוֹלִים, וְהִיא נְקֵבָה הָרָעָה, אֵשׁ זָרָה, עֲבוֹדָה קָשָׁה, עֲבוֹדָה זָרָה קוֹרְאִים לָהּ.</p>\n<p>וּמִשּׁוּם שֶׁמִּמֶּנָּה מִתְעוֹרֵר כַּעַס לַכָּבֵד, פֵּרְשׁוּהָ חַכְמֵי הַמִּשְׁנָה, כָּל הַכּוֹעֵס כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה. וְלֹא עוֹד, אֶלָּא שֶׁאֵין שְׂרֵפָה וַחֲמִימוּת בְּכָל הַמַּחֲלוֹת שֶׁל אֶבְרֵי הַגּוּף אֶלָּא מִמָּרָה. שֶׁהִיא מַדְלִיקָה בְּשַׁלְהָבוֹת עַל הָעוֹרְקִים שֶׁל הַכָּבֵד וְרוֹצָה לִשְׂרֹף אֶת כָּל הַגּוּף. וְהִיא כְּדֻגְמַת הַיָּם כַּאֲשֶׁר הוּא כּוֹעֵס, שֶׁגַּלֵּי הַיָּם עוֹלִים עַד לָרָקִיעַ וְרוֹצִים לָצֵאת מִגְּבוּלָם לְשַׁבֵּר (להחריב) הָעוֹלָם. אִם לֹא הַשְּׁכִינָה, שֶׁהִיא לַחוֹלֶה כַּחוֹל הַמַּקִּיף אֶת הַיָּם שֶׁלֹּא יוֹצֵא מִשְּׂפָתוֹ - אַף כָּךְ הַשְּׁכִינָה סוֹבֶבֶת לַגּוּף וְסוֹמֶכֶת אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מא) ה' יִסְעָדֶנּוּ עַל עֶרֶשׂ דְּוָי.</p>\n<p>וּמִשּׁוּם זֶה בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, הַמְבַקֵּר אֶת הַחוֹלֶה לֹא יֵשֵׁב לִמְרַאֲשׁוֹתָיו, מִשּׁוּם שֶׁשְּׁכִינָה עַל רֹאשׁוֹ. וְלֹא לְמַרְגְּלוֹתָיו, כֵּיוָן שֶׁמַּלְאַךְ הַמָּוֶת לְמַרְגְּלוֹתָיו. וְזֶה לֹא לְכָל בֶּן אָדָם, אֶלָּא לְבֵינוֹנִי. אֲבָל לְצַדִּיק גָּמוּר - ה' יִסְעָדֶנּוּ עַל עֶרֶשׂ דְּוָי, עַל רֹאשׁוֹ. וְהַשְּׁכִינָה מַקִּיפָה אֶת גּוּפוֹ עַד רַגְלָיו. וּמִשּׁוּם זֶה נֶאֱמַר בְּיַעֲקֹב, (בראשית מט) וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, וְזוֹ הַשְּׁכִינָה שֶׁנֶּאֱמַר בָּהּ, (ישעיה סו) וְהָאָרֶץ הֲדם רַגְלָי. וּלְרָשָׁע גָּמוּר, מַלְאַךְ הַמָּוֶת מַקִּיף אוֹתוֹ בְּכָל צְדָדָיו. וְזֶה יֵצֶר הָרָע, שֶׁמַּלְאַךְ הַמָּוֶת מַקִּיף אוֹתוֹ בְּכָל צְדָדָיו, חֶרֶב שֶׁלּוֹ, שֶׁפָּנָיו מוֹרִיקוֹת בְּטִפָּה אַחַת מֵאוֹתָן שָׁלֹשׁ טִפּוֹת שֶׁזּוֹרֵק בּוֹ. זֶהוּ שֶׁכָּתוּב (משלי ה) וְאַחֲרִיתָה מָרָה כַלַּעֲנָה. הַכָּבֵד זֶה הַזָּכָר. יוֹתֶרֶת הַכָּבֵד - נְקֵבָה. (עד כאן).</p>\n<p>הַקֵּבָה הִיא דַּרְגָּה אַחַת מִשִּׁשִּׁים מִמִּיתָה, וְזֶה נִקְרָא תַּרְדֵּמָה. מַלְאָךְ עַסְטִירְאָה (עסירטא), דַּרְגָּה שִׁשִּׁית שֶׁל מַלְאַךְ הַמָּוֶת. וּמִתּוֹךְ שֶׁבָּא מֵרָחוֹק, הוּא מִצַּד הַמָּוֶת, וְלֹא מָוֶת מַמָּשׁ. וְנִרְמָז - אֶחָד מִשִּׁשִּׁים מִמִּיתָה.</p>\n<p>אָמַר הָרוֹעָה הַנֶּאֱמָן, מֵאַחַר שֶׁהַגּוּף הוּא מֵעֵץ שֶׁל טוֹב וָרָע, אֵין אֵיבָר בַּגּוּף שֶׁאֵין בּוֹ יֵצֶר הָרָע וְיֵצֶר הַטּוֹב לַבֵּינוֹנִים. וּלְצַדִּיקִים גְּמוּרִים שְׁתֵּי יְצִירוֹת, שֶׁל זָכָר וּנְקֵבָה, וּשְׁנֵיהֶם טוֹבִים, כְּדֻגְמַת חָתָן וְכַלָּה. וְלִרְשָׁעִים גְּמוּרִים שְׁתֵּי יְצִירוֹת רָעוֹת, זָכָר וּנְקֵבָה, בְּכָל אֵיבָר וְאֵיבָר, מִצַּד שֶׁל סָמָאֵ\"ל וְנָחָשׁ.</p>\n<p>וּמִשּׁוּם זֶה מִצַּד שֶׁל עֵץ טוֹב וָרָע, הִיא הַקֵּבָה שֶׁיֵּשׁ בָּהּ שְׁתֵּי דְרָגוֹת. שֶׁכָּךְ בֵּאֲרוּהוּ חֲכָמִים, קֵבָה - יָשֵׁן. וְיֵשׁ שֵׁנָה אַחַת מִשִּׁשִּׁים בְּמִיתָה. וְשֵׁנָה, אַחַת מִשִּׁשִּׁים בִּנְבוּאָה. וּמִשּׁוּם זֶה פֵּרְשׁוּהוּ חֲכָמִים בַּעֲלֵי הַיְשִׁיבָה, כָּתוּב (זכריה י) וַחֲלֹמוֹת הַשָּׁוְא יְדַבֵּרוּ, וַהֲרֵי כָּתוּב (במדבר יב) בַּחֲלוֹם אֲדַבֶּר בּוֹ? לֹא קָשֶׁה. כָּאן עַל יְדֵי שֵׁד - כָּאן עַל יְדֵי מַלְאָךְ. חֲלוֹם עַל יְדֵי מַלְאָךְ - אֶחָד מִשִּׁשִּׁים בִּנְבוּאָה. חֲלוֹם עַל יְדֵי שֵׁד הוּא שָׁוְא, מִצַּד שֶׁל הַמָּוֶת. וְהוּא תֶּבֶן. שֶׁכָּךְ בֵּאֲרוּהוּ, כְּשֵׁם שֶׁאִי אֶפְשָׁר לְבָר בְּלֹא תֶבֶן, כָּךְ אִי אֶפְשָׁר לַחֲלוֹם בְּלֹא דְבָרִים בְּטֵלִים.</p>\n<p>הָאִצְטוֹמְכָה זֶה קֻרְקְבָן נִקְלָף. וּבֵאֲרוּ חֲכָמִים, קֻרְקְבָן טוֹחֵן, שֶׁהוּא לוֹקֵחַ הַכֹּל וְשׁוֹחֵק, וְשׁוֹלֵחַ לְכָל הָאֵיבָרִים. אִם הָאֵיבָרִים בְּלִי עֲווֹנוֹת, כְּגוֹן מַה שֶּׁאָמְרוּ חֲכָמִים, שֶׁיֵּשׁ דְּבָרִים הַמְעַכְּבִים אֶת הַקָּרְבָּן, שֶׁלֹּא יוֹרֵד לְקַבֵּל אוֹתוֹ הַהוּא שֶׁשָּׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַבֵּל הַמַּתָּנָה שֶׁלּוֹ. שֶׁיֵּשׁ שֶׁמְּקַבֵּל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי אַרְיֵה, שֶׁנֶּאֱמַר בּוֹ (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּן. וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹכֵב עָלָיו, וְיוֹרֵד בּוֹ לְקַבֵּל אוֹתוֹ דּוֹרוֹן. וְיִשִׁ דּוֹרוֹן שֶׁמְּקַבֵּל אוֹתוֹ עַל יְדֵי שׁוֹר, שֶׁנֶּאֱמַר בּוֹ (שם) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול לְאַרְבַּעְתָּן.</p>\n<p>וְיֵשׁ דּוֹרוֹן שֶׁמְּקַבֵּל עַל יְדֵי נֶשֶׁר, שֶׁנֶּאֱמַר בּוֹ (שם) וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. שֶׁהֵם שְׁתֵּי תוֹרִים אוֹ שְׁנֵי בְנֵי יוֹנָה. וְיֵשׁ דּוֹרוֹן שֶׁמְּקַבֵּל אוֹתוֹ עַל יְדֵי אָדָם שֶׁכָּתוּב בּוֹ (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. בַּדְּמוּת שֶׁל זֶה שֶׁנֶּאֱמַר בּוֹ (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. שֵׁם יְהֹוָ\"ה יוֹרֵד עֲלֵיהֶם לְקַבֵּל הַקָּרְבָּן.</p>\n<p>וְיְשׁ חַיּוֹת טִבְעִיּוֹת מְמֻנּוֹת עַל הַגּוּפִים, שֶׁהֵם מֵאַרְבָּעָה יְסוֹדוֹת, וְהֵן טְהוֹרוֹת. וּלְעֻמָּתָן יֵשׁ אַרְבַּע חַיּוֹת דּוֹרְסוֹת, טְמֵאוֹת, (מלאכים ממנים) עַל אַרְבַּע מָרוֹת, שֶׁהֵן: מָרָה לְבָנָה, מָרָה אֲדֻמָּה, מָרָה יְרֻקָּה, מָרָה שְׁחֹרָה. וְיֵשׁ חַיּוֹת שִׂכְלִיּוֹת שֶׁסּוֹבְבוֹת הַכִּסֵּא. וְיֵשׁ לְמַעְלָה מֵהֶן וּגְבוֹהוֹת עֲלֵיהֶן, וְהֵן חַיּוֹת אֱלָהִיּוֹת, מִצַּד הַקְּדֻשָּׁה.</p>\n<p>וְיֵשׁ חַיּוֹת מֵהַצַּד הָאַחֵר, וְנִקְרָאוֹת אֱלֹהִים אֲחֵרִים. וְהַחַיּוֹת הָאֱלָהִיּוֹת מִצַּד הַקְּדֻשָּׁה נִקְרָאוֹת אֱלֹהִים חַיִּים. וְאֵלּוּ הָאֱלָהִיּוֹת שֶׁל הַקְּדֻשָּׁה נִקְרָאוֹת אֱלֹהֵי הָאֱלָהִיּוֹת, וְעִלַּת עַל הַכֹּל, אֵל אָדוֹן עַל כָּל הַמַּעֲשִׂים. וְכָל מִין הוֹלֵךְ לְמִינוֹ. וּמִשּׁוּם שֶׁיֵּשׁ אֱלֹהִים אֲחֵרִים, אָמַר עֲלֵיהֶם, (שמותכב) זֹּבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַה' לְבַדּוֹ. כְּדֵי שֶׁלֹּא יִתְעָרֵב אֱלֹהִים חַיִּים עִם אֱלֹהִים אֲחֵרִים. (ובחבור קדמון). (עד כאן).</p>\n<p>אִצְטוֹמְכָה זוֹ לוֹקַחַת וְשׁוֹחֶקֶת, וְשׁוֹלַחַת לְכָל הַצְּדָדִים שֶׁל מַטָּה, וּמִמֶּנָּה נִזּוֹנִים הַתַּחְתּוֹנִים. וּמֵאֵלּוּ שׁוֹתִים הַשְּׁמָרִים לְמַטָּה כָּל אוֹתָן רוּחוֹת וּצְדָדִים אֲחֵרִים שֶׁנִּזּוֹנִים בַּלַּיְלָה מֵאוֹתָם אֵיבָרִים וּפְדָרִים. וְהַשְּׁאָר נוֹטְלִים כָּל הָאֵיבָרִים, וְנוֹטֵל הַכֹּל הַכָּבֵד, וּמַקְרִיב לַלֵּב, כְּמוֹ שֶׁנֶּאֱמַר לְעֵיל. וְזֶהוּ שֶׁכָּתוּב (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין. וְעַל זֶה מִתְרָאֶה עַל הַמִּזְבֵּחַ דֻּגְמַת אַרְיֵה שֶׁאוֹכֵל קָרְבָּנוֹת. מִכָּאן וּלְהָלְאָה כָּל שְׁאָר הָאֵיבָרִים בְּסוֹד שֶׁל הַגּוּף כְּדֻגְמָא שֶׁל מַעְלָה.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, מָאוֹר הַקָּדוֹשׁ, וַדַּאי אִצְטוֹמְכָה בָּרִאשׁוֹנָה לוֹקַחַת הַכֹּל עַד שֵׁשׁ שָׁעוֹת, וְאוֹפָה. קֻרְקְבָן הוּא אוֹפֶה. וְהָרֵאָה הִיא מַשְׁקֶה. הַלֵּב הוּא הַמֶּלֶךְ. וְאֵלּוּ הַשְּׁנַיִם הֵם וַדַּאי אוֹפֶה וּמַשְׁקֶה לָתֵת לַמֶּלֶךְ מֵהַטּוֹב שֶׁל כָּל מַאֲכָלִים וּמַשְׁקִים, מֵהָרֹאשׁ שֶׁל כֻּלָּם, מֵהַמִּבְחָר שֶׁל כֻּלָּם, וְזֶהוּ שֶׁכָּתוּב (שיר השירים ה) אָרִיתִי מוֹרִי עִם בְּשָׂמִי אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי. אַחַר כָּךְ נֶאֱמַר אִכְלוּ רֵעִים, שֶׁהֵם שְׁאָר הָאֵיבָרִים, שֶׁהֵם חֲיָלוֹת וּמַחֲנוֹת הַמֶּלֶךְ, שֶׁמְּחַלֵּק לָהֶם מָזוֹן עַל יְדֵי שַׂר הָאוֹפִים. שְׁתוּ וְשִׁכְרוּ דּוֹדִים, עַל יְדֵי שַׂר הַמַּשְׁקִים.</p>\n<p>וְהַכָּבֵד הוּא לִימִין הַבֶּן אָדָם. וּמִשּׁוּם זֶה, וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם, לִימִין הַמֶּלֶךְ, שֶׁהוּא הַלֵּב. הַטְּחוֹל לִשְׂמֹאל. אֵלּוּ הֵם מֵהַצַּד הָאַחֵר, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול. מַשְׁקֵה יַיִן מָזוּג בְּמַיִם לַמֶּלֶךְ. וְאַרְיֵה אוֹכֵל, זֶה כָּבֵד, שֶׁאוֹסֵף מָזוֹן לִפְנֵי הַמֶּלֶךְ, שֶׁהוּא הַלֵּב.</p>\n<p>וְיִשִׁ לְהַקְשׁוֹת עַל זֶה: אִם כָּבֵד הוּא עֵשָׂו, אֵיךְ הוּא מְתַקֵּן מָזוֹן לַלֵּב? אֶלָּא וַדַּאי הַלֵּב הוּא כְּדֻגְמָתוֹ שֶׁל יִצְחָק. כָּבֵד - עֵשָׂו, שֶׁהוּא הַצָּד צַיִד. וְיֹאמַר לוֹ, (בראשית יז) יָקוּם אָבִי וְיֹאכַל מִצֵּיד בְּנוֹ. אֵלּוּ הֵן הַתְּפִלּוֹת שֶׁהוֹלְכוֹת וּמִתְרַחֲקוֹת מֵעֲנִיִּים, וְיִצְחָק בְּצַעַר וּבְיָגוֹן, שֶׁלֹּא יְכוֹלִים לְכַוֵּן לַתְּפִלָּה. וּמִשּׁוּם זֶה לֹא אָמַר וְיֹאכַל מִצֵּידִי, אֶלָּא וְיֹאכַל מִצֵּיד בְּנוֹ, (שמותד) בְּנִי בְכֹרִי יִשְׂרָאֵל. כְּמוֹ זֶה אֵין לָהֶם לְיִשְׂרָאֵל מָזוֹן בַּגָּלוּת אֶלָּא עַל יְדֵי אֻמּוֹת הָעוֹלָם.</p>\n<p>אֲבָל כַּאֲשֶׁר הֵם בְּאֶרֶץ יִשְׂרָאֵל, מְזוֹנוֹתָם עַל יְדֵי הַשְּׁכִינָה. וְיִהְיוּ שְׁתֵּי כַּנְפֵי הָרֵאָה מַשְׁקוֹת אֻמָּה, שַׂר הַמַּשְׁקִים. וּשְׁתֵּי הַכְּלָיוֹת - הָאוֹפִים, שֶׁמְּבַשְּׁלוֹת הַזֶּרַע הַיּוֹרֵד מִן הַמֹּחַ, וּמְבַשְּׁלוֹת מַיִם שֶׁמְּקַבְּלוֹת מִכַּנְפֵי הָרֵאָה. וּלְבַסּוֹף שֶׁיֹּאכַל הַמֶּלֶךְ, שֶׁהוּא הַלֵּב, נֶאֱמַר בִּשְׁתֵּי הַכְּלָיוֹת שֶׁלּוֹ אִכְלוּ רֵעִים. וְלִשְׁתֵּי כַּנְפֵי הָרֵאָה - שְׁתוּ וְשִׁכְרוּ דּוֹדִים.</p>\n<p>הַלֵּב הוּא כִּסֵּא דִין, אַרְבַּע חַיּוֹת שְׁלוּחִים שֶׁלּוֹ. שְׁתֵּי כַּנְפֵי רֵאָה וּשְׁתֵּי כְלָיוֹת. שֶׁעַל כַּנְפֵי רֵאָה נֶאֱמַר וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה, לְקַבֵּל עֲלֵיהֶם אֶת הַמֶּלֶךְ, שֶׁהוּא (ישעיה יא) רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת ה'. שֶׁיּוֹשֵׁב עַל כִּסֵּא, שֶׁהוּא הַלֵּב, שֶׁכָּל אוֹתָם דְּפָקִים מִתְנַהֲגִים אַחֲרָיו כְּחַיָּלִים אַחַר מַלְכָּם.</p>\n<p>וְהָרוּחַ שֶׁנּוֹשֶׁבֶת מִכַּנְפֵי הָרֵאָה, נוֹשֶׁבֶת עַל שְׁנֵי נִקְבֵי הַחֹטֶם, וְהִיא קְרִירָה וְצוֹנֶנֶת מֵהַשְּׂמֹאל, וְחַמָּה מִיָּמִין. וּמִצַּד הַמֹּחַ, שֶׁהוּא כִּסֵּא שֶׁל רַחֲמִים, הִיא רוּחַ קָרָה לִימִין הַחֶסֶד, וְחַמָּה מִשְּׂמֹאל הַגְּבוּרָה, שֶׁשָּׁם הַלֵּב וְהַמֹּחַ מָזוּג בּוֹ, בָּאֶמְצַע שֶׁל שְׁנֵיהֶם. אַף כָּךְ הַלֵּב מְמֻזָּג מִקֹּר וָחֹם. וְהַמֹּחַ גַּם כָּךְ, שֶׁמְּקַבְּלִים זֶה מִזֶּה.</p>\n<p>וְאֶת הַשְּׁמָרִים שֶׁל הַכֹּל נוֹטֵל הַטְּחוֹל וְהַמַּחֲנוֹת שֶׁלּוֹ, שֶׁהֵם עֲבָדִים וּשְׁפָחוֹת, שֶׁאָמַר עֲלֵיהֶם שְׁלֹמֹה, (קהלתב) קָנִיתִי לִי עֲבָדִים וּשְׁפָחוֹת. שְׁתֵּי כְלָיוֹת נִקְרָאוֹת אִשִּׁים, עַל שֵׁם אִשִּׁים שֶׁל מַעְלָה, שֶׁנֶּאֱמַר בָּהֶם (דברים יח) אִשֵּׁי ה' וְנַחֲלָתוֹ יֹאכֵלוּן.</p>\n<p>וּבַקָּנֶה יֵשׁ שֵׁשׁ טַבָּעוֹת, שֶׁעֲלֵיהֶן נֶאֱמַר (תהלים כט) הָבוּ לַה' בְּנֵי אֵלִים. שֶׁבָּהֶן עוֹלֶה הַקּוֹל שֶׁנֶּחֱלָק לְשִׁשָּׁה קוֹלוֹת שֶׁל הַשְּׁכִינָה. וְהַשְּׁבִיעִי עוֹלֶה לַפֶּה, שֶׁהוּא כִּסֵּא. וְשֵׁשׁ טַבָּעוֹת שֶׁל קָנֶה, שֶׁהֵם כְּדֻגְמַת שֵׁשׁ מַדְרֵגוֹת שֶׁל כִּסֵּא הַמֶּלֶךְ. וְקָנֶה הוּא סֻלָּם, שֶׁבּוֹ נֶאֱמַר (בראשית כח) מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ, שֶׁאוֹתָם הֲבָלִים עוֹלִים בּוֹ הַמֶּלֶךְ (מהלב), וְהָרוּחוֹת שֶׁבָּאֲוִיר (חורים יוצאים) יוֹרְדוֹת בּוֹ בַּלֵּב לְקָרֵר חֲמִימוּתוֹ, שֶׁלֹּא יִשְׂרֹף הַגּוּף.</p>\n<p>וְכַאֲשֶׁר הָרוּחַ יוֹרֶדֶת, יוֹרֶדֶת בְּכַמָּה רוּחוֹת, כְּמֶלֶךְ עִם חֵילוֹתָיו. וְכַנְפֵי הָרֵאָה מְקַבְּלוֹת לָרוּחַ, שֶׁהוּא מֶלֶךְ עֲלֵיהֶן, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת, (שמות כה) וְהָיוּ הַכְּרֻבִים פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה.</p>\n<p>אִם זַכָּאִים הָאֵיבָרִים שֶׁל הָאָדָם בְּמִצְווֹת עֲשֵׂה שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁהוּא רוּחַ הַקֹּדֶשׁ, יוֹרֵד בְּסֻלָּם, שֶׁהוּא הַגָּרוֹן, בְּכַמָּה רוּחוֹת קְדוֹשׁוֹת, שֶׁנֶּאֱמַר עֲלֵיהֶן (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת, וְעוֹלִים לְעֻמַּת אֵלּוּ הַהֲבָלִים שֶׁל הַלֵּב, שֶׁנֶּאֱמַר עֲלֵיהֶם מְשָׁרְתָיו אֵשׁ לֹהֵט. וַעֲלֵיהֶם נֶאֱמַר (תהלים כט) קוֹל יְהֹוָ\"ה חֹצֵב לַהֲבוֹת אֵשׁ. מִשּׁוּם שֶׁהַלֵּב - אֲדנָי, שֶׁמִּמֶּנּוּ עוֹלִים לַהֲבוֹת אֵשׁ בַּפֶּה, שֶׁהוּא יְהֹוָ\"ה, שֶׁיּוֹרְדוֹת עִמּוֹ כַּמָּה רוּחוֹת שֶׁל קְדֻשָּׁה מֵאַרְבַּע אוֹתִיּוֹת יְהֹוָה, שֶׁנֶּאֱמַר עֲלֵיהֶן (יחזקאל לז) כֹּה אָמַר יְהֹוָ\"ה מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ.</p>\n<p>קָנֶ\"ה - הוּא קְנֵה חָכְמָה קְנֵה בִינָה. שֶׁהֵם לִימִין הַחֶסֶד, וְלִשְׂמֹאל הַגְּבוּרָה. תִּפְאֶרֶת, סֻלָּם בָּאֶמְצַע, בַּגּוּף, כָּלוּל מִשְׁתֵי זְרוֹעוֹת וְגוּף וּבְרִית וּשְׁתֵּי (צדדים) שׁוֹקַיִם, כְּנֶגֶד שֵׁשׁ הַטַּבָּעוֹת שֶׁל הַקָּנֶה.</p>\n<p>וְכַאֲשֶׁר יוֹרֵד יְהֹוָ\"ה לַלֵּב לְגַבֵּי אֲדנָ\"י, מִתְחַבְּרִים הַדִּין בְּרַחֲמִים בַּלֵּב, שֶׁהוּא יְאֲהדוָנָהי. וְכַאֲשֶׁר עוֹלֶה שֵׁם אֲדנָי לַפֶּה, שֶׁנֶּאֱמַר אֲדנָי שְׂפָתַי תִּפְתָּח, לְקַבֵּל שֵׁם יְהֹוָה בַּפֶּה, וּלְהִתְחַבֵּר שָׁם שְׁנֵי שֵׁמוֹת בְּחִבּוּר אֶחָד - יְאֲהדוָנָהי, כְּמוֹ שֶׁמִּתְחַבְּרִים בַּלֵּב. וּמִשּׁוּם זֶה בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, מִי שֶׁאֵין תּוֹכוֹ כְּבָרוֹ אַל יִכָּנֵס לְבֵית הַמִּדְרָשׁ, אִם אֵין לָהֶם פֶּה וְלֵב שָׁוִים. (עד כאן).</p>\n<p>קָנֶה - שֵׁשׁ טַבָּעוֹת בַּקָּנֶה שֶׁמִּתְחַבְּרוֹת כְּאַחַת, וְהֵן נִקְרָאוֹת בְּנֵי אֵלִים. מוֹצִיאוֹת רוּחַ לְנַשֵּׁב עַל הָעוֹלָם, וּבָאוֹת מִצַּד הַגְּבוּרָה. וְכַאֲשֶׁר הֵן מִתְחַבְּרוֹת כְּאַחַת, הֵן כְּדֻגְמַת הַשּׁוֹפָר. וְאֵלּוּ נִקְרָאִים שׁוֹפָר, שׁוֹפָר שֶׁל אַיִל שֶׁל יִצְחָק. אֵלִים - בְּנֵי בָשָׁן, הָבוּ לַה' בְּנֵי אֵלִים. אֵלִים שֶׁל יִצְחָק. וּמוֹצִיאוֹת רוּחַ וְקוֹל. וְאוֹתוֹ קוֹל יוֹצֵא וּפוֹגֵעַ בְּעַנְנֵי גֶשֶׁם, וְנִשְׁמָע לַבְּרִיּוֹת שֶׁבַּחוּץ. וְעַל זֶה נֶאֱמַר, (איוב כו) וְרַעַם גְּבוּרוֹתָיו מִי יִתְבּוֹנָן. שֶׁוַּדַּאי מִצַּד הַגְּבוּרָה הֵם בָּאִים. וּמִשּׁוּם זֶה (ומה אומר הקול ההוא, ' קול ה' על המים אל הכבוד וגו') אֵל הַכָּבוֹד הִרְעִים ה' עַל מַיִם רַבִּים. אֵל הַכָּבוֹד רוֹעֵם לֹא כָתוּב, אֶלָּא אֵל הַכָּבוֹד הִרְעִים, עַל יְדֵיהֶם שֶׁל בְּנֵי אֵלִים. וְאֵין מִי שֶׁמַּכִּיר בַּשֶּׁבַח שֶׁל הַקּוֹל הַזֶּה. זֶהוּ שֶׁכָּתוּב מִי יִתְבּוֹנָן.</p>\n<p>פָּתַח הָרוֹעֶה הַנֶּאֱמָן וְאָמַר, אוֹי לָהֶם לִבְנֵי אָדָם, שֶׁהֵם אֲטוּמֵי לֵב, סְתוּמֵי עֵינַיִם, שֶׁלֹּא יוֹדְעִים אֶבְרֵי הַגּוּף שֶׁלָּהֶם עַל מָה הֵם מְתֻקָּנִים, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא (הקנ\"ה), שְׁלֹשָׁה חֲיָלוֹת כְּלוּלִים בּוֹ: אֶחָד - הָבָל, שֶׁהוּא לַהַב אֵשׁ, שֶׁיּוֹצֵא מִן הַלֵּב וְנֶחֱלָק לְשִׁבְעָה הֲבָלִים שֶׁאָמַר קֹהֶלֶת. שֵׁנִי - אֲוִיר שֶׁנִּכְנָס בְּתוֹכוֹ מִבַּחוּץ. שְׁלִישִׁי - מַיִם שֶׁל כַּנְפֵי רֵאָה, שֶׁהֵם דְּבוּקִים בַּקָּנֶה. וּמִשְּׁלֹשֶׁת אֵלּוּ נַעֲשֶׂה קוֹל - מַיִם וְרוּחַ וְאֵשׁ. וּמִתְחַלֵּק כָּל אֶחָד לְשִׁבְעָה, וְהֵם שֶׁבַע לֶהָבוֹת, שִׁבְעָה אֲוִירִים, שִׁבְעָה נְחָלִים.</p>\n<p>וְכַאֲשֶׁר פּוֹגְעוֹת לַהֲבוֹת הַלֵּב בְּעַנְנֵי גֶשֶׁם, שֶׁהֵם כַּנְפֵי רֵאָה, דֶּרֶךְ קְנֵה הָרֵאָה - זֶהוּ שֶׁנֶּאֱמַר וְרַעַם גְּבוּרוֹתָיו מִי יִתְבּוֹנָן. שֶׁבָּהּ הַלֵּב מֵבִין בַּבִּינָה, שֶׁהִיא בַּלֵּב לִשְׂמֹאלוֹ, גְּבוּרָה. וְחֶסֶד לְיָמִין, מַיִם שֶׁל כַּנְפֵי רֵאָה. וְשָׁם חָכְמָה, הַמֹּחַ, וּמִמֶּנּוּ (שיר השירים ד) מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים וְנֹזְלִים מִן לְבָנוֹן, שֶׁהוּא לֹבֶן הַמֹּחַ, נוֹזְלִים עַל הַקָּנֶה שֶׁל הָרֵאָה, אַחַר שֶׁעָלוּ עַנְנֵי הַבִּינָה לְגַבֵּי הַמֹּחַ.</p>\n<p>וְסוֹד הַדָּבָר - (שם ג) מִי זֹּאת עֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן. וְזֶה עֲשַׁן הַמַּעֲרָכָה שֶׁעוֹלֶה מִן הַלֵּב לַמֹּחַ, שֶׁכָּל הָרוּחוֹת שֶׁל הָעוֹלָם לֹא מְזִיזוֹת אוֹתוֹ מִמְּקוֹמוֹ. חָכְמָה - כֹּ\"חַ מָ\"ה. כֹּ\"חַ - בַּלֵּב. מָ\"ה - בַּמֹּחַ. קָנֶה - תִּפְאֶרֶת, כָּלוּל שֵׁשׁ סְפִירוֹת. שֵׁשׁ מַדְרֵגוֹת הֵן לַכִּסֵּא, שֶׁהִיא אִמָּא. שֶׁתֵּרֵד הַחָכְמָה אֶצְלָהּ מִן הַמֹּחַ לַלֵּב, שֶׁבָּהּ הַלֵּב מֵבִין. וּמִשּׁוּם זֶה, (משלי ד) קְנֵה חָכְמָה קְנֵה בִינָה. בּוֹ אַבָּא יוֹרֵד, בּוֹ אַבָּא עוֹלֶה. וְזֶהוּ סֻלָּם שֶׁבּוֹ (עלים וירדים בו) עֹלִים - שְׁנַיִם, וְיֹרְדִים - שְׁנַיִם. וּבַחִבּוּר הַקַּדְמוֹן. (ע\"כ)</p>\n<p>וֵשֶׁט - שֶׁבָּלַע מַאֲכָל, וּמִשָּׁם נִכְנָס לְכָל הָאֵיבָרִים, שֶׁהִיא (זה הוא סוד) בְּמַדְרֵגָה שֶׁל אִשִּׁים. אִשִּׁים הֵם קְרֵבִים מִיָּד, וּבוֹלְעִים וְנוֹטְלִים כָּלִיל (הכל) מִתּוֹךְ הָאֵשׁ הָעֶלְיוֹנָה, שֶׁכָּלִיל לָאִשִּׁים. וְסוֹד זֶה - (דברים יח) אִשֵּׁי ה' וְנַחֲלָתוֹ יֹאכֵלוּן. אֵלּוּ אוֹכְלִים וּבוֹלְעִים, וְהַשְּׁאָר לֹא אוֹכְלִים כָּךְ.</p>\n<p>וְכָל בְּנֵי הָעוֹלָם (שבחוץ) לְבַד, לֹא יוֹדְעִים אֵיךְ אוֹכְלִים וְלֹא הַסּוֹד שֶׁלָּהֶם, אֶלָּא מַדְרֵגוֹת שֶׁבִּפְנִים הֵם יוֹדְעִים, וְלוֹקְחִים מֵהֶם. וֵשֶׁט אֵין לוֹ בְּדִיקָה מִבַּחוּץ, שֶׁלֹּא יוֹדְעִים, אֶלָּא מִבִּפְנִים יוֹדְעִים וְנוֹטְלִים עַד שֶׁנִּכְנָסִים לְבֵית הַטְּחִינָה, וְנִשְׁחָק וּמִתְבַּשֵּׁל. וְלוֹקֵחַ הַכֹּל הַכָּבֵד, כְּמוֹ שֶׁנֶּאֱמַר. מֵאֵלּוּ הָאִשִּׁים יוֹצְאוֹת מַדְרֵגוֹת שֶׁמַּקְדִּימוֹת וְנוֹטְלוֹת מֵהַכָּבֵד בָּרִאשׁוֹנָה (ומהן, ' אלו) הַטּוֹחֲנוֹת, שֶׁאוֹכְלִים הַקָּרְבָּנוֹת וְטוֹחֲנִים אוֹתָם. וְעַל זֶה מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ כָּתוּב, (קהלתיב) וּבָטְלוּ הַ חֲנוֹת כִּי מִעֵטוּ. אֵלּוּ הַטּוֹחֲנוֹת בַּתְּחִלָּה.</p>\n<p>כֵּיוָן שֶׁנִּטְחָן, הֵם שׁוֹלְטִים עֲלֵיהֶם, בּוֹלְעִים וְנוֹטְלִים, וְנִקְרָאִים וֵשֶׁ\"ט. מַדּוּעַ? אֶלָּא וֵשֶׁט, צוּרָה שֶׁל אוֹת וָא\"ו, הוּא וֵשֶׁט כָּפוּף. וּלְאַחַר מִכֵּן מְשׁוֹטֵט לֶאֱכֹל וְלִשְׁתּוֹת יַיִן וּמַיִם, שֶׁנֶּאֱמַר (במדבריא) שָׁטוּ הָעָם וְלָקְטוּ. אֹכֶל לֶאֱכֹל, וּשְׁתִיָּה שֶׁל יַיִן וּמַיִם, נִסּוּךְ הַיַּיִן וְנִסּוּךְ הַמַּיִם.</p>\n<p>בָּזְהִ הַוֵּשֶׁט נִכְנָס, וְנִשְׁאָב בָּרֵאָה עַל יְדֵי אֵלּוּ הַשְּׂרָפִים (האיברים), בַּשַּׁלְהֶבֶת שֶׁלָּהֶם לוֹקְחִים הַמַּשְׁקֶה, וְנִקְרָאִים רֵאָה בְּחִבּוּר אֶחָד, וְנִשְׁאָב הַכֹּל בָּהֶם. וְכָל אֵלּוּ לוֹקְחִים כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁרָאוּי לָהֶם. וּמִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ נֶאֱמַר, (קהלת יב) וּבָטְלוּ הַטֹּחֲנוֹת כִּי מִעֵטוּ, כֻּלָּם. שֶׁהִמְעִיטוּ דְמוּתָם וּמְזוֹנָם, וְאֵין יוֹם שֶׁאֵין בּוֹ קְלָלָה. הֵרִים קוֹלוֹ רַבִּי שִׁמְעוֹן וְאָמַר, אוֹי יְרוּשָׁלַיִם עִיר קְדוֹשָׁה! אוֹי לָעָם שֶׁכָּל טוֹבוֹת אֵלּוּ אָבְדוּ! שָׂרִים גִּבּוֹרִים מְמֻנִּים הִקְטִינוּ דְמוּתָם. עַל זֶה בּוֹכִים הַחֲבֵרִים. אָמְרוּ, אוֹי רַבִּי! כַּאֲשֶׁר תִּסְתַּלֵּק מִן הָעוֹלָם, מִי יְגַלֶּה סוֹדוֹת סְתוּמִים עֲמֻקִּים כָּאֵלּוּ, שֶׁלֹּא נִשְׁמְעוּ מִיָּמָיו שֶׁל שְׁלֹמֹה הַמֶּלֶךְ וְעַד עַתָּה? אַשְׁרֵי הַדּוֹר שֶׁשּׁוֹמְעִים מִלִּים אֵלּוּ, וְאַשְׁרֵי הַדּוֹר שֶׁאַתָּה בְּתוֹכוֹ! אוֹי לַדּוֹר שֶׁיִּשָּׁאֲרוּ יְתוֹמִים מִמְּךְ!</p>"],[9522012513,"<p>פָּתַח הָרוֹעֶה הַנֶּאֱמָן וְאָמַר, וַהֲרֵי כָּתוּב וְשִׂפְתוֹתֵינוּ שֶׁבַח כְּמֶרְחֲבֵי רָקִיעַ. וְשִׁבְעָה רְקִיעִים הֵם: וִילוֹן, רָקִיעַ. שְׁחָקִים, זְבוּל. מָעוֹן. מָכוֹן. עֲרָבוֹת. שְׁחָקִים. שֶׁבָּהֶם רֵחַיִם שֶׁטּוֹחֲנִים מָן לַצַּדִּיקִים לֶעָתִיד לָבֹא. וְאֵלּוּ נִקְרָאִים שְׁחָקִים, עַל שֵׁם (שמות ל) וְשָׁחַקְתָּ מִמֶּנָּה הָדֵק. וְאֵלּוּ נֵצַח וְהוֹד, עֲלֵיהֶם נֶאֱמַר (ישעיה מה) וּשְׁחָקִים יִזְּלוּ צֶדֶק, שֶׁהִיא שְׁכִינָה תַּחְתּוֹנָה.</p>\n<p>וִילוֹן, שֶׁבּוֹ מַכְנִיס עַרְבִית וּמוֹצִיא שַׁחֲרִית. רָקִיעַ הוּא יְסוֹד, שֶׁבּוֹ מְאִירִים הַשֶּׁמֶשׁ וְהַיָּרֵחַ, שֶׁהוּא הָעַמּוּד הָאֶמְצָעִי וּשְׁכִינָה תַּחְתּוֹנָה. זֶהוּ שֶׁכָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ. וְצַדִּיק הוּא אוֹת בֵּין נֵצַח וְהוֹד, וְעֵדוּת בֵּין תִּפְאֶרֶת וּמַלְכוּת.</p>"],[9522012514,"<p>נֵצַח וְהוֹד - שְׁנֵי חֲצָאֵי גוּף הֵם, כְּדֻגְמַת שְׁנֵי תְאוֹמִים. וּמִשּׁוּם זֶה נִקְרָאִים שְׁחָקִים. שְׁנֵיהֶם כְּאֶחָד אוֹת וָ\"ו הֵם, מִן וֵשֶׁט, מִצַּד הַשְּׂמֹאל. וְהֵם שְׁתֵּי הַטּוֹחֲנוֹת, מִצַּד הַיָּמִין.</p>\n<p>וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ. עַצְמוֹת צַדִּיק יְסוֹד עוֹלָם, מַדְרֵגָה שֶׁל יוֹסֵף הַצַּדִּיק. וַעֲלֵיהֶם נֶאֱמַר, אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. וְאֵין לֶחֶם אֶלָּא תּוֹרָה, שֶׁנֶּאֱמַר (משלי ט) לְכוּ לַחֲמִי בְלַחְמִי. וְהֵם אֶשְׁכּוֹלוֹת שֶׁל הַצַּדִּיק. וְצַדִּיק עֵץ פְּרִי. וּבִגְלָלוֹ נֶאֱמַר (במדבר יג) וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם. וּמַדּוּעַ בַּמּוֹט? בִּגְלַל שֶׁלֹּא הָיָה שָׁם צַדִּיק.</p>\n<p>וּבִגְלָלָם נֶאֱמַר בּוֹ, (תהלים נה) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק, שֶׁהוּא עֵץ, שֶׁנֶּאֱמַר בּוֹ (במדבר יג) הֲיֵשׁ בָּהּ עֵץ אִם אָיִן. עָקְרוּ עֵץ שֶׁהוּא צַדִּיק, אֵלּוּ שֶׁהוֹצִיאוּ שֵׁם רַע עַל הָאָרֶץ, וְגָרְמוּ לְמַה שֶּׁנֶּאֱמַר וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם, ו' ו'.</p>\n<p>וְעַל הַמְּרַגְּלִים נֶאֱמַר, סָחֲטָה עֲנָבִים. צַדִּיק שֶׁהוּא יְסוֹד, בּוֹ סוֹד, שֶׁהוּא יַיִן הַמְשֻׁמָּר בַּעֲנָבָיו מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית. שֶׁהֵם שֵׁשׁ מַדְרֵגוֹת שֶׁל הָאוֹת ו'. וְהֵם שְׂרָפִים, אוֹתִיּוֹת ו' ו', שֶׁנֶּאֱמַר (ישעיה ו) שֵׁשׁ כְּנָפַיִם לְאֶחָד. מֵהַשְּׂמֹאל. וְאֵלּוּ הַמּוֹצִיאִים מַיִם - מֵהַיָּמִין. וּצְמֵאִים בַּשַּׁלְהֶבֶת שֶׁלָּהֶם מִצַּד הַגְּבוּרָה וְשׁוֹאֲבִים מִצַּד הַחֶסֶד.</p>\n<p>וַעָלֵיהֶם נֶאֱמַר, (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת, מִצַּד הָעַמּוּד הָאֶמְצָעִי, שֶׁנּוֹשְׁבִים עַל הַלֵּב, שֶׁהוּא מַדְרֵגָה עֲשִׂירִית בְּרוּחַ הַקֹּדֶשׁ, שֶׁהוּא בֵּינֵיהֶם. וְהוּא אוֹת ו', אוֹת בַּצָּבָא שֶׁלּוֹ, כָּלוּל ו' פְּרָקִים שֶׁל שְׁתֵּי שׁוֹקַיִם, שֶׁכָּתוּב בָּהֶן (שיר השירים ה) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ, וְזֶה צַדִּיק אוֹת בְּרִית.</p>\n<p>ו' עֶלְיוֹנָה - תִּפְאֶרֶת. בֵּין שִׁשָּׁה פְרָקִים שֶׁל שְׁתֵּי זְרוֹעוֹת. וּמִשּׁוּם זֶה ו' ו', גּוּף וּבְרִית שֶׁנֶּחְשָׁבִים כְּאֶחָד. וְהֵם (שמות כה) פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה, כְּנֶגֶד ו' עֶלְיוֹנָה שֶׁעֲלֵיהֶם. וּמִצִּדָּהּ נִקְרָאִים נְבִיאֵי אֱמֶת. סֹכֲכִים בְּכַנְפֵיהֶם עַל הַבְּרִית, שֶׁהִיא אוֹת ו' שְׁנִיָּה, (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וּמִשּׁוּם זֶה נֵצַח וְהוֹד טוֹחֲנִים מָן לַצַּדִּיקִים, שֶׁהֵם מִצַּד שֶׁל צַדִּיק יְסוֹד עוֹלָם, שֶׁהוּא בֵּינֵיהֶם. וּמִשּׁוּם זֶה נִקְרָאִים טוֹחֲנוֹת.</p>\n<p>וּמִצַד שֶׁל הַוֵּשֶׁט נֶאֱמַר, (במדבריא) שָׁטוּ הָעָם וְלָקְטוּ, אוֹתָם הַמְלַקְּטִים פְּסָקִים שֶׁל הַמִּשְׁנָה. וְטָחֲנוּ בָרֵחַיִם - מִכָּאן, מִי שֶׁמּוֹצִיא דִבּוּרִים שֶׁל תּוֹרָה, צָרִיךְ לְטָחֳנָם בַּשִּׁנַּיִם וּלְהוֹצִיא דִבּוּרִים שְׁלֵמִים, וְאֵלּוּ הַדִּבּוּרִים נִקְרָאִים שְׁלָמִים. וַאֲחֵרִים, אוֹתָם שֶׁהֵם שׁוֹטִים, שֶׁאוֹכְלִים דִּבּוּרִים בְּהַלְעָטָה וְלֹא טוֹחֲנִים אוֹתָם בַּטּוֹחֲנוֹת שֶׁלָּהֶם וּבַשִּׁנַּיִם, מַה כָּתוּב בָּהֶם? (שם) הַבָּשָׂר עוֹדֶנּוּ בֵּין שִׁנֵּיהֶם (וגו') וְאַף ה' חָרָה בָעָם. שֶׁהֵם מִשֹּׁרֶשׁ שֶׁל מִי שֶׁנֶּאֱמַר עָלָיו (בראשית כה) הַלְעִיטֵנִי נָא. וְנֵצַח וְהוֹד נִקְרָאִים כְּרוּבִים.</p>"],[9522012515,"<p>וּשְׁמוֹנָה הֵם: חָכְמָה, בִּינָה, גְּדֻלָּה, גְּבוּרָה, תִּפְאֶרֶת, מַלְכוּת, נֵצַח, הוֹד. צַדִּיק עֲטָרָה עַל רֹאשׁוֹ, שֶׁהוּא אֵין לוֹ זוּג. וּמָה הָעֲטָרָה שֶׁלּוֹ? כֶּתֶר עֶלְיוֹן. וּבִגְלָלוֹ פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, הָעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה, אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם. וְזֶהוּ שֶׁבֵּאֲרוּ, אָמְרָה שַׁבָּת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לְכָל הַיָּמִים נָתַתָּ בֶּן זוּג וְלִי לֹא נָתַתָּ בֶּן זוּג. (ע\"כ רעיא מהימנא).</p>"],[9522012516,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. אוֹת ע' גְּדוֹלָה, וְאוֹת ד' גַּם כֵּן. וְסִימָן זֶה - עֵד. וְזֶהוּ שֶׁכָּתוּב (שמואל א יב) עֵד ה' בָּכֶם. נִשְׁאֲרוּ אוֹתִיּוֹת ש\"מ. מ' פְּתוּחָה. מָה הַטַּעַם לֹא סְתוּמָה? מִשּׁוּם שֶׁם' סְתוּמָה הִיא מֶלֶךְ (עולם) עֶלְיוֹן. מ' פְּתוּחָה הִיא מֶלֶךְ (עולם) תַּחְתּוֹן. אוֹתִיּוֹת אֲחֵרוֹת נִשְׁאֲרוּ א' ח', עֲלֵיהֶן כָּתוּב (משלי כה) כְּבֹד אֱלֹהִים הַסְתֵּר דָּבָר.</p>\n<p>מָצָאנוּ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, כָּל מִי שֶׁמְּיַחֵד יִחוּד זֶה בְּכָל יוֹם, שִׂמְחָה מְזֻמֶּנֶת לוֹ מִלְמַעְלָה מִסּוֹד אוֹתִיּוֹת אֵלּוּ - ש\"מ מִצַּד זֶה, א\"ח מִצַּד זֶה. וּמְצָרֵף הָאוֹתִיּוֹת - לְמַפְרֵעַ (שדי) מַתְחִיל, וּבְיָשָׁר (חיים) מְסַיֵּם. וְסִימָנָם: אֶשְׂמַ\"ח, שֶׁנֶּאֱמַר (תהלים קד) אָנֹכִי אֶשְׂמַח בַּה'. מַמָּשׁ. זֶה יִחוּד הַקָּדוֹשׁ. וְיָפֶה הוּא. וְכָךְ הוּא בְּסִפְרוֹ שֶׁל חֲנוֹךְ, שֶׁאָמַר כְּמוֹ זֶה, שֶׁמִּי שֶׁמְּיַחֵד יִחוּד זֶה בְּכָל יוֹם, שִׂמְחָה מְזֻמֶּנֶת לוֹ מִלְמַעְלָה.</p>\n<p>עוֹד יֵשׁ בּוֹ אוֹתִיּוֹת ש\"מ, שֶׁנִּכְלָל מִן ע' גְּדוֹלָה. אֵלּוּ שִׁבְעִים שֵׁמוֹת בְּסוֹד הָאָבוֹת הַקְּדוֹשִׁים, וְזֶהוּ שְׁמַע - שֵׁם ע'. יִשְׂרָאֵל, ה', אֱלֹהֵינוּ, ה' - אֵלּוּ אַרְבָּעָה בָּתֵּי הַתְּפִלִּין שֶׁמְּאַחֵד אוֹתָם א\"ח. אוֹתוֹ שֶׁאָמַר (שיר השירים ה) פִּתְחִי לִי אֲחֹתִי רַעְיָתִי. אוֹת ד' - זֶה קֶשֶׁר שֶׁל תְּפִלִּין, שֶׁהִיא אֲחוּזָה בָּהֶם. סוֹד לַחֲכָמִים נֶאֱמַר, שֶׁלֹּא לְגַלּוֹת. שָׁתַק רַבִּי שִׁמְעוֹן. בָּכָה וְחִיֵּךְ. אָמַר, אֹמַר, שֶׁהֲרֵי וַדַּאי עֵת רָצוֹן נִמְצָא, וְאֵין כְּדוֹר זֶה עַד שֶׁיָּבוֹא מֶלֶךְ הַמָּשִׁיחַ, שֶׁיִּהְיֶה לָהֶם רְשׁוּת לְגַלּוֹת.</p>"],[9522012517,"<p>שְׁתֵּי רְצוּעוֹת יוֹצְאוֹת מִצַּד זֶה וּמִצַּד זֶה, סוֹד שֶׁל שְׁתֵּי יְרֵכַיִם שֶׁלְּמַטָּה שֶׁל זֶה הָא\"ח, שֶׁנְּבִיאֵי הָאֱמֶת אֲחוּזִים בּוֹ. שֶׁהֲרֵי מִלְמַעְלָה יוֹצְאִים שְׁתֵּי רְצוּעוֹת, סוֹד שֶׁל שְׁתֵּי זְרוֹעוֹת, מִיָּמִין וּמִשְּׂמֹאל. וְאוֹת דָּלֶ\"ת אֲחוּזָה בָּהֶן. לְבַסּוֹף יוֹרֶדֶת, וְנִתְפַּשְּׁטוּ שְׁתֵּי הַיְרֵכַיִם לְמַטָּה. כֵּיוָן שֶׁהִיא אֲחוּזָה לְמַעְלָה כְּמוֹ שֶׁצָּרִיךְ, יוֹרֶדֶת לְמַטָּה לְהִתְאַחֵד עִם עַמָּהּ. וְכַאֲשֶׁר הִיא מִתְאַחֶדֶת, נֶאֱחֶזֶת בְּסוֹף הַיְרֵכַיִם, וְסִימָן שֶׁל אוֹת יוֹ\"ד בְּרִית קֹדֶשׁ עָלֶיהָ מִלְמַעְלָה. אָז הִיא אֲחוּזָה בְּיִחוּד אֶחָד.</p>\n<p>יוֹ\"ד זֶהוּ סוֹד הַבְּרִית, (ועל זה) כָּל מִי שֶׁשּׁוֹמֵר בְּרִית זוֹ, הוּא נִשְׁמָר לְמַעְלָה, וְנִשְׁמָר לְמַטָּה. (מנין לנו, ') מִפִּנְחָס, מִשּׁוּם שֶׁהוּא קִנֵּא עַל בְּרִית זוֹ, נִצּוֹל מִן הַדִּין הָעֶלְיוֹן וּמִן הַדִּין שֶׁלְּמַטָּה, וּמִשּׁוּם זֶה נִרְשְׁמָה אוֹת יוֹ\"ד זוֹ בְּתוֹכוֹ. זֶהוּ שֶׁכָּתוּב פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וְגוֹ'.</p>\n<p>יוֹ\"ד זוֹ צָרִיךְ שֶׁלֹּא תֻפְרַד כְּלָל מִתּוֹךְ תְּפִלָּה שֶׁל יָד, שֶׁלֹּא תַעֲשֶׂה פֵּרוּד. וְכָל שִׂמְחָה שֶׁלָּהּ הִיא בְּזוֹ הָאוֹת יוֹ\"ד. יוֹ\"ד זוֹ הִיא בְּזָכָר, וְלֹא בִּנְקֵבָה. הוּא צַדִּיק, וְהִיא צֶדֶק. וּמִשּׁוּם זֶה מִתְקָרֶבֶת אֶצְלָהּ, וּמִי שֶׁמַּרְחִיק אוֹתוֹ מִמָּקוֹם זֶה, רָחוֹק הוּא מֵהָעֹנֶג שֶׁל הָעוֹלָם הַבָּא.</p>\n<p>בְּזָכָר הוּא צַדִּיק, וְהִיא צֶדֶק בְּלִי אוֹת יוֹ\"ד. הוּא אִישׁ, וְהִיא אִשָּׁה, בְּלִי יוֹ\"ד. וּמִשּׁוּם זֶה שִׂמְחָה (תשובה) שֶׁלָּהּ לְהִתְקָרֵב אֵלֶיהָ וּלְהִתְעַנֵּג עִמָּהּ. מִי שֶׁמְּרַחֵק עֹנֶג זֶה, יַרְחִיקוּ אוֹתוֹ מֵעֹנֶג שֶׁל מַעְלָה. וְעַל זֶה כָּתוּב, (שמואל א ב) כִּי מְכַבְּדַי אֲכַבֵּד וְגוֹ'.</p>"],[9522012518,"<p>בֹּא וּרְאֵה, פִּנְחָס עָמַד בִּפְנֵי דִין תַּקִּיף שֶׁל יִצְחָק, וְסָתַם פִּרְצָה, בִּגְלַל זֶה הִשְׁלִים לְגַבֵּי פִּנְחָס סוֹד שֶׁל יִצְחָק. עָמַד בִּפְנֵי פִרְצָה, שֶׁכָּתוּב (תהלים קו) וַיַּעֲמֹד פִּינְחָס וַיְפַלֵּל. עָמַד בְּפִרְצָה לִפְנֵי דִין שֶׁל יִצְחָק כְּדֵי לְהָגֵן עַל יִשְׂרָאֵל. (פנחס עמד בפני דין התקיף של יצחק להגן עליהם על ישראל, שכתוב (תהלים קו) ויעמד פינחס ויפלל. מהו ויעמד, ' שעמד בפרץ בפני דין של יצחק, בגלל זה השלים לפנחס סוד של יצחק). וְעַל זֶה כָּלוּל זֶה בָּזֶה בְּחֶשְׁבּוֹן.</p>\n<p>וְאִם תֹּאמַר, חֶשְׁבּוֹן זֶה לֹא תָלוּי אֶלָּא בָּעֵינַיִם שֶׁלָּהּ, וְכָאן הַחֶשְׁבּוֹן לְמַעְלָה בְּיִצְחָק - אֶלָּא וַדַּאי כָּךְ הוּא, מִשּׁוּם שֶׁיִּצְחָק תָּלוּי וּמִשְׁתַּמֵּשׁ (ונמשך) בְּאוֹתוֹ מָקוֹם שֶׁהֵם עֵינַיִם, שֶׁשָּׁם דָּנִים דִּינִים שֶׁל כָּל הָעוֹלָם, שֶׁהֲרֵי הָעֵינַיִם שֶׁלָּהּ הֵם שִׁבְעִים כִּסְאוֹת, מְקוֹם דִּינֵי הָעוֹלָם, וְנִקְרָאִים סַנְהֶדְרִין. וְעַל כֵּן הַכֹּל אֶחָד, מִשּׁוּם שֶׁיִּצְחָק וְאֵלּוּ הוֹלְכִים כְּאֶחָד, וְהַכֹּל יָפֶה.</p>\n<p>פִּנְחָס זֶה יִצְחָק, וְעָמַד פִּנְחָס וְדָן דִּין, וּמִתְלַבֵּשׁ בִּגְבוּרָה חֲזָקָה, שֶׁהוּא שְׂמֹאל. וּמִשּׁוּם זֶה זָכָה לְיָמִין. כָּאן נִכְלָל שְׂמֹאל בְּיָמִין. הֵשִׁיב אֶת חֲמָתִי, מַהוּ הֵשִׁיב אֶת חֲמָתִי? אֶלָּא אֵלּוּ הֵם שְׁלֹשָׁה מְמֻנִּים שֶׁל הַגֵּיהִנָּם: מַשְׁחִית, אַף, וְחֵמָה. (אחד על שפיכות דמים, אחד על גלוי עריות, ואחד על עבודה זרה). מִשּׁוּם שֶׁרָאָה אוֹתוֹ חֵמָה שֶׁהָיָה מִתְפַּשֵּׁט וְנִמְשָׁךְ מִצִּדּוֹ שֶׁל יִצְחָק, מֶה עָשָׂה? הִתְלַבֵּשׁ הוּא בְּיִצְחָק, וְאָחַז בְּאוֹתָהּ חֵמָה כְּמִי שֶׁאוֹחֵז בַּחֲבֵרוֹ וְהֵשִׁיב אוֹתוֹ לַאֲחוֹרָיו.</p>\n<p>וְאָז דָּן דִּין, וְעָשָׂה דִּין. דָּן דִּין - שֶׁכָּל בּוֹעֵל אֲרַמִּית קַנָּאִים פּוֹגְעִים בּוֹ. וְעָשָׂה דִּין - שֶׁכָּתוּב וַיִּדְקֹר אֶת שְׁנֵיהֶם. וְעַל זֶה כָּתוּב כָּאן, הֵשִׁיב אֶת חֲמָתִי. וְכָתוּב שָׁם (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב. מַה שָּׁם לַאֲחוֹרָיו, כָּךְ גַּם כָּאן לַאֲחוֹרָיו. וְעַל זֶה אוֹת יוֹ\"ד שֶׁל פִּינְחָס כָּאן, יוֹ\"ד שֶׁל יִצְחָק. וְהַכֹּל הוּא מֵעַל בְּנֵי יִשְׂרָאֵל. שֶׁכַּאֲשֶׁר רָאָה אוֹתוֹ חֵמָה, רָאָה אוֹתוֹ שֶׁהָיָה יוֹרֵד עַל רָאשֵׁיהֶם שֶׁל יִשְׂרָאֵל.</p>"],[9522012519,"<p>מָה רָאָה? רָאָה אוֹת מ', אוֹת זוֹ שֶׁהָיְתָה טָסָה בָּרָקִיעַ, וְזֶהוּ סִימָן שֶׁל מַלְאַךְ הַמָּוֶת שֶׁרוֹצֶה לְהִבָּנוֹת בָּאוֹת וָא\"ו וְאוֹת ת'. מֶה עָשָׂה פִּנְחָס? שֶׁהָיָה מִתְלַבֵּשׁ בְּיִצְחָק, אָז נָטַל מ' הַהִיא, וְחָטַף אוֹתוֹ, וְחִבֵּר אוֹתָהּ עִמּוֹ. כֵּיוָן שֶׁרָאָה מַלְאַךְ הַמָּוֶת שֶׁפִּנְחָס חָטַף לוֹ אוֹת מ' הַהִיא עִמּוֹ, מִיָּד שָׁב לַאֲחוֹרָיו.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁכַּאֲשֶׁר קִנֵּא פִּנְחָס בְּלִבּוֹ, הִתְלַבֵּשׁ בְּיִצְחָק, וְהִתְעַלָּה לִהְיוֹת בְּחֶשְׁבּוֹן מָאתַיִם וּשְׁמוֹנֶה, וְכָךְ עוֹלֶה שְׁמוֹ בְּמָאתַיִם וּשְׁמוֹנֶה, וְכָךְ עוֹלֶה יִצְחָק. כֵּיוָן שֶׁרָאָה לָאוֹת מ' עָפָה בָּרָקִיעַ, חָטַף אוֹתָהּ וְחִבֵּר אוֹתָהּ עִמּוֹ, וְנַעֲשָׂה מִיָּד מָאתַיִם וְאַרְבָּעִים וּשְׁמוֹנֶה. זֶהוּ שֶׁכָּתוּב וַיִּקַּח רֹמַח בְּיָדוֹ.</p>\n<p>מִשּׁוּם שֶׁאוֹת מ' הָיְתָה סִימָן רִאשׁוֹן לְאָדָם הָרִאשׁוֹן לִבְנוֹת מָוֶת עַל הָעוֹלָם, מִשּׁוּם שֶׁאוֹת זוֹ הָיְתָה טָסָה עַל רֹאשׁוֹ שֶׁל אָדָם, בְּשָׁעָה שֶׁכָּתוּב (בראשית ג) וַתִּקַּח מִפִּרְיוֹ, מ' פִּרְיוֹ. וְהָיוּ מְחַכּוֹת אוֹתִיּוֹת ו\"ת בִּזְמַן שֶׁכָּתוּב וַתֹּאכַל, וַתִּתֵּן, וַתִּפָּקַחְנָה. אָז נִבְנָה מָוֶת עַל הָעוֹלָם.</p>\n<p>פִּנְחָס הָיָה נִרְאֶה לוֹ עַכְשָׁו אוֹתָהּ אוֹת מ', עָף עַל רָאשֵׁיהֶם שֶׁל יִשְׂרָאֵל. וְאֵיךְ רָאָה אוֹתוֹ? רָאָה צוּרַת אוֹת מ' פְּתוּחָה, מְלֵאָה דָּם. כֵּיוָן שֶׁרָאָה אוֹתוֹ, אָמַר: זֶה וַדַּאי סִימָן שֶׁל מַלְאַךְ הַמָּוֶת. מִיָּד חָטַף אוֹתָהּ, הִזְכִּיר עָלֶיהָ שֵׁם הַמְפֹרָשׁ, וְהוֹרִיד לְאוֹתָהּ הָאוֹת אֶצְלוֹ. וּמַה שֶּׁהָיָה בְּגִימַטְרִיָּא מָאתַיִם וּשְׁמוֹנֶה, הִצְטָרֵף לִהְיוֹת מָאתַיִם וְאַרְבָּעִים וּשְׁמוֹנֶה. וְאָז נֶאֱמַר וַיִּקַּח רֹמַח בְּיָדוֹ. וְעַל זֶה כָּתוּב, מֵעַל בְּנֵי יִשְׂרָאֵל בְּקַנְאוֹ אֶת קִנְאָתִי. שֶׁקִּנֵּא לַשֵּׁם הַקָּדוֹשׁ, שֶׁהָיוּ מְחַבְּרִים לוֹ בְּרָשׁוּת אַחֶרֶת. בְּתוֹכָם, מַהוּ בְּתוֹכָם? מִשּׁוּם שֶׁהָיָה הוֹלֵךְ וּבָא בְּתוֹךְ כַּמָּה הֲמוֹנִים וְכַמָּה חֲשׁוּבִים, וּמָסַר עַצְמוֹ לְמִיתָה בֵּינֵיהֶם. אֲבָל בְּתוֹכָם, בְּתוֹךְ מ', בְּתוֹךְ מ' הָיָה אוֹתָהּ קִנְאָה שֶׁקִּנֵּא.</p>\n<p>מַה טַּעַם אוֹת מ'? מִשּׁוּם שֶׁהִיא סִימָן שֶׁל מָוֶת, הִיא סִימָן שֶׁל מ' מַלְקֻיּוֹת. הִיא סִימָן שֶׁל ד' מִיתוֹת בֵּית דִּין. וּמִשָּׁם עָלָה וְיָרַד, וְיָרַד וְעָלָה. עָלָה לְמ', וְיָרַד לְד'. יָרַד מִד', שֶׁהֵם ד' רוּחוֹת שֶׁנִּפְרָדוֹת מִתּוֹךְ זָכָר וּנְקֵבָה מֵהַטֻּמְאָה, וּבִגְלָלָן ד' מִיתוֹת בֵּית דִּין. וּמִשָּׁם עוֹלִים לְמ'. כְּלוֹמַר, מ' סִימָנִים וְכֵלִים שֶׁל מַלְאַךְ הַמָּוֶת. וְזֶה לָקַח פִּנְחָס וְעָמַד בְּתוֹךְ מ', וְעַל זֶה נֶאֱמַר וְלֹא כִלִּיתִי אֶת בְּנֵי יִשְׂרָאֵל בְּקִנְאָתִי.</p>\n<p>וְכִי אֵיךְ הֵשִׁיב פִּנְחָס אֶת חֲמָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי כָּתוּב וַיִּהְיוּ הַמֵּתִים בַּמַּגֵּפָה וְגוֹ'? אִם לֹא מֵת אֶחָד מֵהֶם, הָיִיתִי אוֹמֵר הֵשִׁיב חֲמָתִי, אֲבָל כֵּיוָן שֶׁכָּל אֵלּוּ מֵתוּ, מָה הַטַּעַם הֵשִׁיב אֶת חֲמָתִי וְלֹא כִלִּיתִי אֶת בְּנֵי יִשְׂרָאֵל? אֶלָּא וַדַּאי בֵּרוּר הַדָּבָר: אוֹי לוֹ לְבֶן אָדָם שֶׁפּוֹגֵם זַרְעוֹ! אוֹי לוֹ לְמִי שֶׁלֹּא שׁוֹמֵר זַרְעוֹ כְּמוֹ שֶׁצָּרִיךְ! חַס וְשָׁלוֹם שֶׁאֲפִלּוּ אֶחָד מִיִּשְׂרָאֵל מֵת, אֶלָּא שֵׁבֶט שִׁמְעוֹן, כַּאֲשֶׁר בָּאוּ אוֹתָם עֵרֶב רַב, הִתְעָרְבוּ בַּנָּשִׁים שֶׁל שֵׁבֶט שִׁמְעוֹן לְאַחַר שֶׁהִתְגַּיְּרוּ, וְהוֹלִידוּ בָנִים - מֵהֶם מֵתוּ בָּעֵגֶל, וּמֵהֶם מֵתוּ בַּמַּגֵּפָה, וַאֲחֵרִים מֵתוּ כָּאן, אֵלּוּ שֶׁנִּשְׁאֲרוּ. זֶהוּ שֶׁכָּתוּב וַיִּהְיוּ הַמֵּתִים בַּמַּגֵּפָה. אֲשֶׁר מֵתוּ לֹא כָתוּב, אֶלָּא הַמֵּתִים, מֵתִים שֶׁכְּבָר הָיוּ.</p>\n<p>וּמִשּׁוּם שֶׁנִּשְׁמְרוּ יִשְׂרָאֵל וְכָל אוֹתָם זֶרַע קָדוֹשׁ, נִמְנוּ כֻלָּם, מִשּׁוּם שֶׁלֹּא חָסַר אֲפִלּוּ אֶחָד מֵהֶם. וְעַל זֶה כָּתוּב וְלֹא כִלִּיתִי אֶת בְּנֵי יִשְׂרָאֵל. מִכְּלָל שֶׁאֲחֵרִים כָּלוּ. וְכֵן מַה שֶּׁנֶּאֱמַר הֵשִׁיב אֶת חֲמָתִי מֵעַל בְּנֵי יִשְׂרָאֵל - מֵעַל בְּנֵי יִשְׂרָאֵל הֵשִׁיב, אֲבָל מֵעַל אֲחֵרִים שֶׁהָיוּ עֵרֶב רַב לֹא הֵשִׁיב. וְעַל זֶה כָּתַב הַפָּסוּק וְאָמַר מֵעַל בְּנֵי יִשְׂרָאֵל. וּמִשּׁוּם זֶה נִמְנוּ בְּנֵי יִשְׂרָאֵל כְּמִקֹּדֶם, וְחִבֵּר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא עִמּוֹ. כְּדֻגְמַת זֶה בְּמַעֲשֵׂה הָעֵגֶל, שֶׁכָּתוּב (שמות לב) וַיִּפֹּל מִן הָעָם וְגוֹ'. כָּל אֵלּוּ מֵעֵרֶב רַב הָיוּ. וּלְהַרְאוֹת שֶׁלֹּא הָיוּ מִבְּנֵי יִשְׂרָאֵל, מַה כָּתוּב אַחַר כָּךְ? (שמות לה) וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל.</p>"],[9522012520,"<p>קְחוּ מֵאִתְּכֶם תְּרוּמָה (שמות לה). בֹּא וּרְאֵה, בָּרִאשׁוֹנָה כָּתוּב (שמות כה) מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. הַכֹּל בִּכְלָל. כֵּיוָן שֶׁאֵלּוּ הָעֵרֶב רַב עָשׂוּ זֹּאת וּמֵתוּ מֵהֶם אוֹתָם שֶׁמֵּתוּ, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְפַּיֵּס עִמָּהֶם עִם יִשְׂרָאֵל. אָמַר לָהֶם: הִתְחַבְּרוּ כֻלְּכֶם לְצַד אֶחָד. זֶהוּ שֶׁכָּתוּב (שמות לה) וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל - לְבַדָּם. אָמַר לָהֶם: בָּנַי, בָּכֶם אֲנִי רוֹצֶה לִשְׁכֹּן, עִמָּכֶם תִּהְיֶה הַדִּירָה שֶׁלִּי. וְעַל זֶה, (שם כה) קְחוּ מֵאִתְּכֶם תְּרוּמָה. מֵאִתְּכֶם, וְלֹא מֵאֲחֵרִים. לֹא רוֹצֶה שֶׁתִּהְיֶה שֻׁתָּפוּת לַאֲחֵרִים עִמִּי, וְלֹא עִמָּכֶם, וּמִשּׁוּם זֶה כֻּלָּם נִכְרְתוּ. אַף כָּאן הֲרֵי הֵם מֵאֵלּוּ שֹׁרֶשׁ הָרָע הָיוּ, וַיִּהְיוּ הַמֵּתִים. הַמֵּתִים - וַדַּאי מֵתִים, וְלֹא מִיִּשְׂרָאֵל. וּמִשּׁוּם זֶה מָנָה אוֹתָם, שֶׁנֶּאֱמַר שְׂאוּ אֶת רֹאשׁ בְּנֵי יִשְׂרָאֵל, הָרִימוּ רָאשֵׁיהֶם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַבָּא, כַּמָּה נָכוֹן הוּא, אִם לֹא מָצָאתִי חוֹלְקִים עַל זֶה. אָמַר לוֹ, בְּנִי אֱמֹר. אָמַר לוֹ, וַהֲרֵי כָּתוּב (במדבר כה) וַיִּצָּמֶד יִשְׂרָאֵל לְבַעַל פְּעוֹר, וְלָמַדְנוּ שֶׁהִתְחַבְּרוּ יִשְׂרָאֵל עִמּוֹ. כְּצָמִיד זֶה שֶׁמִּתְחַבֵּר בָּאָדָם בְּקִשּׁוּטָיו, כָּךְ הִתְחַבְּרוּ יִשְׂרָאֵל בְּבַעַל פְּעוֹר. אָמַר לוֹ, אֶלְעָזָר, כָּךְ הוּא - וַיִּצָּמֶד יִשְׂרָאֵל לְבַעַל פְּעוֹר. אֶלָּא אֲנִי לֹא אָמַרְתִּי שֶׁנִּטְהֲרוּ יִשְׂרָאֵל מֵאוֹתוֹ חוֹב, אֶלָּא שֶׁנִּטְהָרוּ מִמָּוֶת, שֶׁלֹּא שָׁרָה עֲלֵיהֶם מָוֶת.</p>\n<p>אָמַר לוֹ, וַהֲרֵי כָּתוּב (במדבר כה) קַח אֶת כָּל רָאשֵׁי הָעָם וְהוֹקַע אוֹתָם. אָמַר לוֹ, רָאשֵׁי הָעָם וַדַּאי, וְלֹא רָאשֵׁי בְּנֵי יִשְׂרָאֵל. וּמִן הָעָם יֵשׁ לָנוּ לִלְמֹד. כָּתוּב כָּאן הָעָם, וְכָתוּב שָׁם (שמות לב) וַיַּרְא הָעָם. (שם) וַיִּקָּהֵל הָעָם. (שם) וַיִּפֹּל מִן הָעָם. אֲבָל בֹּא וּרְאֵה, וַיִּצָּמֶד יִשְׂרָאֵל לְבַעַל פְּעוֹר, וְלֹא עָבְדוּ לוֹ. אֲבָל מִסּוֹף הַפָּסוּק מוּכָח, שֶׁכָּתוּב וַיֹּאכַל הָעָם וַיִּשְׁתַּחֲווּ, וְלֹא כָתוּב וַיֹּאכַל וַיִּשְׁתַּחוּ יִשְׂרָאֵל. אֶלָּא הָעָם, כֵּיוָן שֶׁכָּתוּב וַיִּצָּמֶד יִשְׂרָאֵל, מַהוּ וַיּאכַל הָעָם? אֶלָּא אוֹתוֹ זֶרַע רַע הָיוּ חוֹבָה לְיִשְׂרָאֵל.</p>\n<p>מַהוּ שֶׁכָּתוּב (במדבר כה) וַיִּצָּמֶד יִשְׂרָאֵל לְבַעַל פְּעוֹר? בֹּא וּרְאֵה, וַיִּצָּמֶד יִשְׂרָאֵל בְּבַעַל פְּעוֹר לֹא כָתוּב, אֶלָּא לְבַעַל פְּעוֹר. קִשּׁוּטִים וְתֹקֶף נָתְנוּ לְבַעַל פְּעוֹר בְּלִי דַעַת, מִשּׁוּם שֶׁעֲבוֹדַת פְּעוֹר הוּא לִפְרֹעַ עַצְמוֹ וּלְהוֹצִיא לְפָנָיו צוֹאָה רוֹתַחַת. וְאוֹתָהּ עֲבוֹדָה מוֹעִילָה לוֹ וּמִתְחַזֵּק מִמֶּנָּה. וְיִשְׂרָאֵל, כֵּיוָן שֶׁרָאוּ זֹּאת, חָשְׁבוּ שֶׁזֶּה זִלְזוּל שֶׁלָּהּ הוּא וְקִלְקוּל שֶׁלָּהּ, שֶׁהֲרֵי בַּעֲבוֹדָה זָרָה כָּתוּב, (ישעיה ל) צֵא תֹּאמַר לוֹ. וְהֵם בִּגְלַל הַזִּלְזוּל שֶׁל הָעֲבוֹדָה זָרָה פָּרְעוּ עַצְמָם בְּלִי יְדִיעָה, וְעַל זֶה כִּפֵּר פִּנְחָס וּבִטֵּל הַמַּגֵּפָה, שֶׁנֶּאֱמַר וַיְכַפֵּר עַל בְּנֵי יִשְׂרָאֵל.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, הֵשִׁיב אֶת חֲמָתִי. מַהוּ הֵשִׁיב אֶת חֲמָתִי? אֶלָּא שְׁלֹשָׁה מְמֻנִּים שֶׁל הַגֵּיהִנָּם: אֶחָד עַל שְׁפִיכוּת דָּמִים, וְאֶחָד עַל גִּלּוּי עֲרָיוֹת, וְאֶחָד עַל עֲבוֹדָה זָרָה. וְהֵם: מַשְׁחִית, אַף, וְחֵמָה. הוּא (ראה שיהו\"ה) (חמה שהיה) עָף בָּעוֹלָם. אָמַר הֵשִׁיב אֶת חֲמָתִי מֵעַל בְּנֵי יִשְׂרָאֵל, וְלֹא אָמַר מֵעַל הָעָם, שֶׁהֵם עֵרֶב רַב, שֶׁנֶּאֱמַר וַיִּפֹּל מִן הָעָם בַּיּוֹם הַהוּא כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ, שֶׁכָּךְ בֵּאַרְנוּ וְשָׁאֲלוּ לַמְּנוֹרָה הַקְּדוֹשָׁה (עד כאן).</p>\n<p>וּמַה כָּתוּב? קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה', וְלֹא מֵעֵרֶב רַב. שֶׁלֹּא נִקְרָאִים קְהִלָּה וְחִבּוּר עַד שֶׁעָבַר מֵהֶם עֵרֶב רַב. כִּבְיָכוֹל בִּזְמַן שֶׁמִּתְעָרְבִים בֵּינֵיהֶם, כְּאִלּוּ לֹא הָיוּ גוֹי אֶחָד. וּמִשּׁוּם זֶה קְחוּ מֵאִתְּכֶם תְּרוּמָה, וְלֹא מִשֻּׁתָּפוּת אַחֶרֶת, שֶׁאֵינִי רוֹצֶה לְשַׁתֵּף אֲחֵרִים בֵּינִי וּבֵינֵיכֶם.</p>\n<p>וְלֹא עוֹד, אֶלָּא כַּאֲשֶׁר עֵרֶב רַב הֵם מְעֹרָבִים בְּיִשְׂרָאֵל, מַה כָּתוּב? (איכה א) הָיוּ צָרֶיהָ לְרֹאשׁ. וְיִשְׂרָאֵל, אַחַר שֶׁעוֹבְרִים מֵהֶם אֵלּוּ, מַה כָּתוּב? שְׂאוּ אֶת רֹאשׁ כָּל עֲדַת בְּנֵי יִשְׂרָאֵל. וְלֹא עוֹד, אֶלָּא שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲנִי רוֹצֶה לָדוּר עִמָּכֶם. זֶהוּ שֶׁכָּתוּב (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם.</p>\n<p>וְלֹא עוֹד, אֶלָּא כַּאֲשֶׁר בְּנֵי יִשְׂרָאֵל בַּגָּלוּת, עֲלֵיהֶם נֶאֱמַר, מִי מְעַכֵּב? שְׂאוֹר שֶׁבָּעִסָּה. וַהֲרֵי בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, בִּזְמַן שֶׁעֵרֶב רַב הֵם רָאשִׁים עַל יִשְׂרָאֵל, כִּבְיָכוֹל כְּאִלּוּ (מעבירים שלטון של הקדוש ברוך הוא) עוֹשִׂים שִׁלְטוֹן בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִכְנָסִים בְּמִשְׁפְּטֵי כוֹכָבִים וּמַזָּלוֹת. וּמִשּׁוּם זֶה צוֹעֲקִים וְאוֹמְרִים, (ישעיה כו) ה' אֱלֹהֵינוּ בְּעָלוּנוּ אֲדנִים זוּלָתֶךְ.</p>\n<p>דָּבָר אַחֵר, פִּינְחָס וְכוּ'. קוּם הַמְּנוֹרָה הַקְּדוֹשָׁה וּפְתַח בִּדְבָרִים לִפְנֵי הַשְּׁכִינָה. קָם הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, בַּחִבּוּר הַקַּדְמוֹן נֶאֱמַר כָּךְ. בֹּא וּרְאֵה, פִּינְחָס עָמַד לִפְנֵי הַדִּין הַתַּקִּיף שֶׁל יִצְחָק, וְעָמַד לִפְנֵי פִרְצָה, שֶׁכָּתוּב (תהלים קו) וַיַּעֲמֹד פִּינְחָס וַיְפַלֵּל וַתֵּעָצַר הַמַּגֵּפָה, כְּדֵי לְהָגֵן עֲלֵיהֶם שֶׁל יִשְׂרָאֵל, וּמִשּׁוּם זֶה כְּלוּלִים זֶה וָזֶה בְּחֶשְׁבּוֹן, פִּינְחָס כְּחֶשְׁבּוֹן יִצְחָק, וְכָאן צָרִיךְ לְחַדֵּשׁ דְּבָרִים.</p>"],[9522012521,"<p>פָּתַח וְאָמַר, אֵלִיָּהוּ אֲהוּבוֹ שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן רָאָה מ' מִן מָוֶת, עָף בָּאֲוִיר, חָטַף אוֹתָהּ וְשִׁתֵּף אוֹתָהּ עִם ר\"ח, שֶׁהוּא יִצְחָק, וְהוּא בְּחֶשְׁבּוֹן פִּינְחָס, וְנִשְׁלַם עַל יָדָהּ לְרמ\"ח. אַחַר כָּךְ רָאָה אוֹת ו' מִן מָוֶ\"ת, עָף בָּרָקִיעַ וְחָטַף אוֹתָהּ, וְשָׂם אוֹתָהּ בְּרַמַ\"ח, וְנִשְׁלַם לְרֹמַ\"ח. זֶהוּ שֶׁכָּתוּב וַיִּקַּח רֹמַח בְּיָדוֹ.</p>\n<p>וְהוּא, בַּמֶּה יָכוֹל לַחֲטֹף שְׁתֵּי אוֹתִיּוֹת אֵלּוּ? בִּשְׁתֵּי רוּחוֹת שֶׁנִּשְׁמְרוּ (שהסתתרו) לְמַעְלָה, שֶׁהִשְׁתַּתְּפוּ בְּפִינְחָס. פְּנֵ\"י חָ\"ס. בִּשְׁנֵי פָנִים אֵלּוּ חָס עַל יִשְׂרָאֵל שֶׁלֹּא נֶאֶבְדוּ, בַּכֹּחַ שֶׁל שְׁנֵיהֶם, וַיִּדְקֹר אֶת שְׁנֵיהֶם, בִּשְׁתֵּי אוֹתִיּוֹת - מ\"ו. וְזֶהוּ שֶׁנֶּאֱמַר בְּקַנְאוֹ אֶת קִנְאָתִי בְּתוֹכָם.</p>\n<p>וּמַדּוּעַ הִשְׁתַּתֵּף בְּיִצְחָק? מִשּׁוּם שֶׁיִּצְחָק מָסַר עַצְמוֹ לְמִיתָה, וּמִשּׁוּם זֶה שִׁתֵּף אֶת יִצְחָק לִהְיוֹת לוֹ לְעֵזֶר. שֶׁמִּצַּד שֶׁל שְׁנֵי עָפְרֵי הָאַיָּלִים הִשְׁתַּתְּפוּ בוֹ אַבְרָהָם וְיַעֲקֹב, שֶׁאַבְרָהָם שֶׁדַּרְגָתוֹ חֶסֶד הִשְׁתַּתֵּף בְּח\"ס שֶׁל פִּנְחָ\"ס. וְיַעֲקֹב שֶׁהוּא פְּנֵ\"י אֵ\"ל (יעקב הוא פנ\"י של פינחס). שֶׁפִּנְחָס, מִשּׁוּם שֶׁנֶּאֱמַר בּוֹ (בראשית לב) כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל (שם המקום פנ\"י), פְּנֵ\"י אֵ\"ל. וּמִשּׁוּם שֶׁכַּאֲשֶׁר הָעוֹלָם הוּא בְּצַעַר וְיֵשׁ צַדִּיק בָּעוֹלָם הַמְקַנֵּא עַל הַבְּרִית, הָאָבוֹת מִשְׁתַּתְּפִים עִמּוֹ, וּבִגְלָלָם אָמַר מֹשֶׁה בְּצַעֲרָם שֶׁל יִשְׂרָאֵל, (שמותלב) זְכֹר לְאַבְרָהָם לְיִצְחָק וּלְיִשְׂרָאֵל עֲבָדֶיךְ. וּבִשְׁלֹשׁ אוֹתִיּוֹת יה\"ו מֵאֵלִיָּהוּ זָכָה לָאוֹת ה' מִן הַנָּבִיא, וְזֶהוּ אֵלִיָּהוּ, ה' נָבִיא (וזה סוד אל יהוה נביא), וְנִשְׁלָם בּוֹ יְהֹוָ\"ה.</p>"],[9522012522,"<p>אוֹת י' שֶׁזָּכָה בָּהּ פִּנְחָס מִשּׁוּם שֶׁקִּנֵּא עַל הַבְּרִית - זָכָה לִבְרִית. וּשְׁתֵּי יוֹדִי\"ן הֵן, י' עֶלְיוֹנָה מִן יְהֹוָ\"ה, שֶׁכָּרַת בָּהּ לְאַבְרָהָם בֵּין עֶשֶׂר אֶצְבְּעוֹת יָדָיו. יוֹ\"ד קְטַנָּה הִיא מִן אֲדנָי, שֶׁכָּרַת בָּהּ בֵּין עֶשֶׂר אֶצְבְּעוֹת רַגְלָיו, וְהִיא אוֹת קְדוֹשָׁה שֶׁמִּתְעַטֶּרֶת בָּרֹשֶׁם הָעֶלְיוֹן.</p>\n<p>וְזְהִ רָשׁוּם תָּמִיד לְעוֹלָמִים, וְהִיא אוֹת הַשַּׁבָּת, אוֹת הַתְּפִלִּין, אוֹת שֶׁל יָמִים טוֹבִים, אוֹת שֵׁם שַׁדַּי שֶׁרָשׁוּם (דברים יא) עַל מְזוּזוֹת בֵּיתֶךְ וּבִשְׁעָרֶיךְ, לִהְיוֹת בָּהּ רְשׁוּמִים יִשְׂרָאֵל בָּרְצוּעוֹת, בַּבְּרִית שֶׁלָּהֶם, שֶׁהֵם בְּנֵי הַמַּלְכָּה, בְּנֵי הַהֵיכָל שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ. וּבַתּוֹרָה הֵם רְשׁוּמִים בְּאוֹת י' עֶלְיוֹנָה שֶׁהֵם בְּנֵי הַמֶּלֶךְ הָעֶלְיוֹן, כְּמוֹ שֶׁבֵּאֲרוּהוּ. וְכֵן נֶאֱמַר (דברים יא) בָּנִים אַתֶּם לַייָ אֱלֹהֵיכֶם.</p>\n<p>וְאוֹת י' שֶׁל שַׁדַּי הִיא חֻלְיָה שֶׁל שַׁלְשֶׁלֶת עַל צַוָּארוֹ שֶׁל שֵׁד יֵצֶר הָרָע שֶׁלֹּא יַזִּיק לוֹ לְבֶן אָדָם. שֶׁעָלָיו אָמַר דָּוִד, (תהלים כב) הַצִּילָה מֵחֶרֶב נַפְשִׁי מִיַּד כֶּלֶב יְחִידָתִי. הוּא נָחָשׁ, הוּא כֶּלֶב, הוּא אַרְיֵה. שֶׁעָלָיו אָמַר דָּוִד, (שם י) יֶאֱרֹב בַּמִּסְתָּר כְּאַרְיֵה בְסֻכֹּה. וְהַנָּבִיא</p>\n<p>קָרָא לוֹ דּב. זֶהוּ שֶׁכָּתוּב (איכה ג) דּב אֹרֵב הוּא לִי אֲרִי בְּמִסְתָּרִים. (תהלים מט) נִמְשַׁל כַּבְּהֵמוֹת. נִמְשָׁל לְכָל חַיּוֹת טְמֵאוֹת, שֶׁהֵן דּוֹרְסוֹת. נִמְשָׁל לְכָל אָדָם כְּפִי חוֹבוֹתָיו, וַהֲרֵי נִתְבָּאֵר. וְזְהִוּ כֶּלֶב וְנָחָשׁ וַחֲמוֹר נוֹעֵר, שֶׁמַּרְכִּיבִים עָלָיו נֶפֶשׁ. וּמִיָּד שֶׁנּוֹדָע זֶה שֶׁרוֹכֵב עָלָיו שֶׁהוּא הַחוֹטֵא, עָלָיו כָּתוּב (בראשית מט) וַיִּפֹּל רֹכְבוֹ אָחוֹר. וְסוֹד הַדָּבָר - (דברים כב) כִּי יִפֹּל הַנֹּפֵל מִמֶּנּוּ. וּמִשּׁוּם זֶה אָמַר אִיּוֹב, (אביו יב) לֹא נֹפֵל אָנֹכִי מִכֶּם. וְצַדִּיק שֶׁרוֹכֵב עָלָיו, קוֹשֵׁר אוֹתוֹ בִּקְשִׁירָה שֶׁל רְצוּעוֹת הַתְּפִלִּין. אוֹת תְּפִלִּין שֶׁהִיא אוֹת יוֹ\"ד שֶׁל שַׁדַּי, טַבַּעַת עַל צַוָּארוֹ. ש' שֶׁל הַתְּפִלִּין הִיא שַׁלְשֶׁלֶת עַל צַוָּארוֹ.</p>\n<p>וּבוֹ רָכַב אֵלִיָּהוּ וְעָלָה הַשָּׁמַיְמָה. זֶהוּ שֶׁכָּתוּב (מלכים בב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם. וּבוֹ (איוב לח) וַיַּעַן יְהֹוָ\"ה אֶת אִיּוֹב מִן הַסְּעָרָה. וּמִשּׁוּם זֶה בֵּאֲרוּהוּ חַכְמֵי הַמִּשְׁנָה עָלָיו, אֵיזֶהוּ גִבּוֹר? הַכּוֹבֵשׁ אֶת יִצְרוֹ. וְיֵשׁ מִי שֶׁנֶּהְפָּךְ לוֹ לַחֲמוֹר, שֶׁאֵינוֹ מִצְטַעֵר רוֹכְבוֹ. וְאֵלּוּ הֵם הַמִּשְׁתַּדְּלִים בְּקַל וָחֹמֶר. וּמִשּׁוּם זֶה נֶאֱמַר בְּאַבְרָהָם, (בראשית כב) וַיַּחֲבֹשׁ אֶת חֲמֹרוֹ. וּבִגְלָלוֹ נֶאֱמַר עַל הַמָּשִׁיחַ, (זכריה ט) עָנִי וְרֹכֵב עַל חֲמוֹר.</p>\n<p>וּמִשּׁוּם זֶה י' מִן שַׁדַּ\"י, שֶׁהִיא חֻלְיָה שֶׁל הַשַּׁלְשֶׁלֶת, מִמֶּנָּה (מפחדים) מְפֻזָּרִים כָּל שֵׁדִים וּמַזִּיקִים, וּמִיָּד שֶׁרוֹאִים אוֹתוֹ בַּמְּזוּזוֹת שֶׁל הַפְּתָחִים, בּוֹרְחִים, שֶׁבָּהּ נֶאֱמַר (תהלים קמט) לֶאְסֹר מַלְכֵיהֶם בְּזִקִּים וְנִכְבְּדֵיהֶם בְּכַבְלֵי בַרְזֶל. כָּל שֶׁכֵּן כַּאֲשֶׁר רוֹאִים אוֹתוֹ בְּאוֹת שֶׁל תְּפִלִּין שֶׁעַל הַזְּרוֹעַ, וּרְשׁוּמִים בָּהּ בְּאוֹת בְּרִית בִּבְשָׂרָם, (במדבר א) וְהַזָּר הַקָּרֵב יוּמָת. אֵין זָר אֶלָּא יֵצֶר הָרָע, שֶׁדּוֹמֶה לְכָל חַיּוֹת וְעוֹפוֹת דּוֹרְסִים.</p>\n<p>וּמִשּׁוּם זֶה נֶאֱמַר, (איוב ד) זְכָר נָא מִי הוּא נָקִי אָבָד - זֶה פִּנְחָס שֶׁקִּנֵּא עַל הַבְּרִית, וְנִרְשַׁם בּוֹ שֶׁהוּא בְּנָם שֶׁל הַמֶּלֶךְ וְהַמַּלְכָּה. קִנֵּא בְמַחֲשָׁבָה, וְזָכָה לָאוֹת י' מִן יְהֹוָ\"ה. וְקִנֵּא בְמַעֲשָׂיו, וְזָכָה לָאוֹת י' מִן אֲדנָי. וְזוֹהִי חָכְמָה בָּרֹאשׁ, וְחָכְמָה בַּסּוֹף. וּמִשּׁוּם שֶׁאָדָם הָרִאשׁוֹן הָיָה רָשׁוּם בִּשְׁנֵיהֶם, בֵּאֲרוּהוּ חֲכָמִים שֶׁהוּא רִאשׁוֹן לַמַּחֲשָׁבָה וְאַחֲרוֹן לְמַעֲשֶׂה. תּוֹךְ כְּדֵי שֶׁאָמַר דְּבָרִים אֵלּוּ, נִכְסָה מֵהֶם. אָמַר רַבִּי אֶלְעָזָר (לחבריו), אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לִשְׁמֹעַ דְּבָרִים מִבְּנֵי הָעוֹלָם הָעֶלְיוֹן.</p>\n<p>וּבַחִבּוּר הַקַּדְמוֹן. לָכֵן אֱמֹר. בִּשְׁבוּעָה עָלֶיךְ, אִם הוּא בִּרְצוֹנְךְ וְאִם לֹא - אֱמֹר רַבִּי פִּנְחָס בֶּן יָאִיר. אוֹתוֹ הַצֵּל הִכָּה בְּעֵינָיו שֶׁל רַבִּי אַבָּא. וְכִי לֹא הָיָה יוֹדֵעַ הַקָּדוֹשׁ בָּרוּךְ הוּא אִם הָיָה בִּרְצוֹנוֹ אִם לָאו? אָמַר לוֹ, אִם לוֹ גָּלוּי - הַאִם גָּלוּי לַאֲחֵרִים? וּמִשּׁוּם זֶה נֶאֱמַר לָכֵן אֱמֹר.</p>"],[9522012523,"<p>וְעוֹד נֶאֱמַר בַּחִבּוּר הַקַּדְמוֹן, (תהלים ס) מִכְתָּם לְדָוִד - סִימָן שֶׁהֶרְאוּ לוֹ לְדָוִד כַּאֲשֶׁר שָׁלַח לְיוֹאָב לַאֲרַם נַהֲרַיִם וְלַאֲרַם צוֹבָה לַעֲשׂוֹת בָּהֶם קְרָב. אָמַר הָרוֹעֶה הַנֶּאֱמָן, שׁוּשַׁן עֵדוּת - זוֹ עֵדוּת שֶׁל הַשְּׁכִינָה, שֶׁהִיא שׁוּשַׁן עֵדוּת. שֶׁהִיא עֵדוּת שֶׁעוֹמֶדֶת עָלֵינוּ וּמְעִידָה עָלֵינוּ לִפְנֵי הַמֶּלֶךְ, וּמַדְרֵגוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת עִמָּהּ, וְסִיּוּעַ קָדוֹשׁ לְשֶׁבַח. אָמַר הָרוֹעֶה הַנֶּאֱמָן, שׁוּשַׁן עֵדוּת - שֶׁהֵם מְעִידִים עַל יִשְׂרָאֵל, שֶׁהֵם אֵיבָרִים, וְהִיא נְשָׁמָה עֲלֵיהֶם, וְהִיא סִיּוּעַ מִשָּׁמַיִם, שֶׁנֶּאֱמַר בָּהּ (מלכים א ח) וְאַתָּה תִשְׁמַע הַשָּׁמַיִם. הִיא סִיּוּעַ קָדוֹשׁ (וממנה תלוי), שֶׁנֶּאֱמַר עָלֶיהָ, תַּנְיָא הַמְסַיַּעַת לָךְ.</p>\n<p>אֵיתָן מוֹשָׁבֶךְ וְשִׂים בַּסֶּלַע קִנֶּךְ (במדבר כד). אֵיתָ\"ן - תַּנְיָ\"א. שָׁם הַקֵּן שֶׁל הַנֶּשֶׁר הָעֶלְיוֹן, וְהִיא הַשְּׁכִינָה, וְעָלֶיהָ נֶאֱמַר (דברים לב) כְּנֶשֶׁר יָעִיר קִנּוֹ עַל גּוֹזָלָיו יְרַחֶף, שֶׁהֵם שׁוֹנֵי הֲלָכוֹת וּמִשְׁנָיוֹת. וְכָל דִּבּוּר וְדִבּוּר שֶׁיּוֹצֵא מִפִּיו שֶׁל זֶה הַתַּנְיָ\"א, שֶׁמּוֹצִיא אוֹתוֹ לְשֵׁם הַשֵּׁם - בֵּין בְּתוֹרָה, בֵּין בִּתְפִלָּה, בֵּין בִּבְרָכָה, בֵּין בְּכָל מִצְוָה וּמִצְוָה - מַה כָּתוּב בּוֹ? יִפְרֹשׂ כְּנָפָיו, אוֹתוֹ הַנֶּשֶׁר, שֶׁהוּא דִּבּוּר שֶׁבּוֹ יְהֹוָ\"ה.</p>\n<p>יִקָּחֵהוּ יִשָּׂאֵהוּ עַל אֶבְרָתוֹ. מַהוּ עַל אֶבְרָתוֹ? עַל אוֹתוֹ אֵיבָר שֶׁל בֶּן הָאָדָם (של אותו נשר) שֶׁבּוֹ מִצְוָה יְהֹוָ\"ה, וְנִקְרָא אֵיבָר שֶׁל הַשְּׁכִינָה. וּמִשּׁוּם זֶה נֶאֱמַר יִשָּׂאֵהוּ עַל אֶבְרָתוֹ. יִשָּׂאֵהוּ, כְּמוֹ (במדבר ו) יִשָּׂא יְהֹוָ\"ה פָּנָיו אֵלֶיךְ.</p>\n<p>וּמַהוּ שֶׁכָּתוּב וְשִׂים בַּסֶּלַע קִנֶּךְ? אֶלָּא אָמַר דָּוִד עָלָיו, (שמואל ב כב) ה' סַלְעִי וּמְצֻדָתִי. כָּךְ גַּם הַשּׁוֹנֶה הֲלָכָה שֶׁבּוֹ הֲלָכָה תַּקִּיפָה כַּסֶּלַע, שֶׁאֵין פַּטִּישׁ יָכוֹל לְפוֹצֵץ אוֹתָהּ בְּכָל קֻשְׁיוֹת שֶׁבָּעוֹלָם. בָּזֶה הוּא מְקַנֵּן הַנֶּשֶׁר, וְכָל הַתַּנָּאִים נִקְרָאִים קִנִּים שֶׁלָּהּ. וּמִשּׁוּם זֶה נֶאֱמַר, (דברים כב) כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךְ, בְּדֶרֶךְ מִקְרֶה, פַּעַם אַחַת, כְּאוֹרֵחַ וְאַכְסְנַאי שֶׁמִּזְדַּמֵּן לְפִי שָׁעָה לְבֵית מְלוֹנוֹ.</p>\n<p>וְיִשִׁ שֶׁהֵם בַּלִּמּוּד שֶׁלָּהֶם נַעֲשִׂים דִּירָה לַשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת וְגוֹ', לְדרֹתָם. לְדרֹתָם חָסֵר, לְשׁוֹן דִּירָה. וְיֵשׁ בַּעֲלֵי מִשְׁנָה שֶׁתּוֹרָתָם אֻמָּנוּתָם, שֶׁלֹּא זָזָה הַשְּׁכִינָה מֵהֶם כָּל יְמֵיהֶם. אֲבָל עַל אֵלּוּ נֶאֱמַר, כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךְ. בָּהֶם הַשְּׁכִינָה נִמְצֵאת בְּדֶרֶךְ מִקְרֶה. פְּעָמִים שֶׁשּׁוֹרָה עֲלֵיהֶם וְנִמְצֵאת עִמָּהֶם, וּפְעָמִים לֹא נִמְצֵאת עִמָּהֶם.</p>\n<p>וסוֹד הַדָּבָר - פְּעָמִים שֶׁנִּמְצֵאת עִמָּהֶם, נֶאֱמַר עֲלֵיהֶם לֹא תִקַּח הָאֵם. וּפְּעָמִים שֶׁלֹּא נִמְצֵאת עִמָּהֶם - שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם. אֶפְרֹחִים - אֵלּוּ בַּעֲלֵי מִשְׁנָה. אוֹ בֵיצִים - אֵלּוּ בַּעֲלֵי מִקְרָא. וּבְאֵלּוּ שֶׁלֹּא קוֹבְעִים אֶת לִמּוּדָם - שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם. אַבָל בְּאֵלּוּ שֶׁקּוֹבְעִים לִמּוּדָם - לֹא תִקַּח הָאֵם עַל הַבָּנִים. וְיֵשׁ בַּעֲלֵי הַלָכוֹת שֶׁדּוֹמִים לַכּוֹכָבִים. זֶהוּ שֶׁכָּתוּב (דניאל יב) וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד. לֹא כַכּוֹכָבִים שֶׁנֶּאֱמַר בָּהֶם (ישעיה לד) וְכָל צְבָאָם בּוֹל, אֶלָּא כְּאוֹתָם כּוֹכָבִים שֶׁל הָעוֹלָם הַבָּא, שֶׁהֵם לְעוֹלָם וָעֶד קַיָּמִים תָּדִיר.</p>"],[9522012524,"<p>ויֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם (בראשית א). אַחַר שֶׁהִשְׁלִימוּ אֶת עֲבוֹדָתָם כָּל אֵמָּן וְאֻמָּן, אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: מַעֲשֵׂה אֻמָּנוּת אֶחָד יֵשׁ לִי לַעֲשׂוֹת שֶׁיִּהְיֶה שֻׁתָּף לְכֻלָּנוּ. הִתְחַבְּרוּ כֻלְּכֶם כְּאֶחָד לַעֲשׂוֹת בּוֹ כָּל אֶחָד וְאֶחָד מֵחֶלְקוֹ, וַאֲנִי אְשְׁתַּתֵּף עִמָּהֶם לָתֵת לוֹ מֵחֶלְקִי. וזֶהוּ שֶׁנֶּאֱמַר נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. וּבֵאֲרוּהוּ חֲכָמִים, שֶׁאֵין אָדָם אֶלָּא יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (יחזקאל לד) ואתן צאני צאן מרעיתי אדם אתם. אתם אדם, ולא עובדי כוכבים מזלות. ומשום זה (תהלים קמט) ישמח ישראל בעשיו.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, וַדַּאי אוֹתוֹ תַּנָּא שֶׁנֶּעְלַם בַּסֶּלַע שֶׁל הַנָּחָשׁ אָמַר זֹּאת, שֶׁכָּתוּב בּוֹ אֵיתָן מוֹשָׁבֶךְ וְשִׂים בַּסֶּלַע קִנֶּךְ. שֶׁשְּׁלֹשָׁה אָבוֹת נִקְרְאוּ אִיתָנִים, וְהָרְבִיעִי - אֵיתָן מוֹשָׁבֶךְ. שֶׁבּוֹ מִתְיַשֶּׁבֶת הַהֲלָכָה, שֶׁנֶּאֱמַר בָּהּ הַלָכָה לְמֹשֶׁה מִסִּינַי. שֶׁהוּא מִתְפַּשֵּׁט עַל שִׁשִּׁים רִבּוֹא שֶׁל יִשְׂרָאֵל וּמֵאִיר לָהֶם בַּתּוֹרָה כַּשֶּׁמֶשׁ (לירח) שֶׁמִּתְכַּסֶּה בַּלַּיְלָה וּמֵאִיר לְכָל כּוֹכָבִים וּמַזָּלוֹת. וִאֵין לַיְלָה אֶלָּא גָּלוּת, וְהִיא (ישעיה כא) שמר מה מלילה שמר מה מליל. ומתגלה ביום, שנאמר (בראשית מד) הבקר אור. הבקר של אַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ (שמות טז) וּבקֶר וּרְאִיתֶם אֶת כְּבוֹד ה'. (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר.</p>\n<p>בְּתוֹךָ כָּךְ אוֹתוֹ הָרוֹעֶה הַנֶּאֱמָן יָצָא מֵאוֹתוֹ סֶלַע וְאָמַר, הַמְּנוֹרָה הַקְּדוֹשָׁה, מַה מּוֹעִיל לִי לְהִסְתַּתֵּר מִפָּנֶיךְ, שֶׁהֲרֵי לֹא הִשְׁאַרְתִּי מָקוֹם שֶׁלֹּא נִכְנַסְתִּי לְהִסְתַּתֵּר מִמְּךְ וְלֹא מָצָאתִי. אִם כֵּן, אֵין לִי לְהִתְכַּסּוֹת מִמֶּךָּ.</p>\n<p>אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, לְאַחַר שֶׁאָמַר נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, מַהוּ שֶׁאָמַר לְבַסּוֹף, וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ? אָמַר לוֹ, מַה שֶּׁבֵּאֲרוּ עַל זֶה בַּעֲלֵי הַמִּשְׁנָה, שֶׁמֵּהֶם אָמְרוּ יִבָּרֵא, וּמֵהֶם אָמְרוּ לֹא יִבָּרֵא - הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹתוֹ, שֶׁכָּתוּב וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. אָמַר לוֹ, אִם כֵּן הוּא, לֹא נָתַן חֵלֶק בּוֹ אַף אֶחָד מֵהֶם, וְלֹא נַעֲשָׂה בַּצּוּרָה שֶׁלָּהֶם, אֶלָּא בְּצוּרַת הַמֶּלֶךְ, בְּצַלְמוֹ כִּדְמוּתוֹ, שֶׁהוּא צֶלֶם דְּמוּת תַּבְנִיתוֹ. אָמַר, כָּךְ מַשְׁמָע מֵהַכָּתוּב.</p>\n<p>אָמַר, חַס וְשָׁלוֹם! אֶלָּא אֲנִי אָמַרְתִּי לְךְ, שֶׁנִּבְרָא בַּכֹּל וְהִשְׁלִיטוֹ עַל הַכֹּל. וְאִם הָיָה נוֹתֵן כָּל אֶחָד בּוֹ חֶלְקוֹ בִּזְמַן שֶׁהָיָה כּוֹעֵס עָלָיו, כָּל אֶחָד הָיָה נוֹטֵל חֶלְקוֹ מִמֶּנּוּ, (ישעיה ב) כִּי בַמֶּה נֶחְשָׁב הוּא.</p>\n<p>אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹתוֹ (כל אחד ואחד) בְּצוּרָתוֹ, זוֹ הַמַּלְכוּת הַקְּדוֹשָׁה שֶׁהִיא תְּמוּנַת כֹּל, שֶׁבָּהּ הִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא וּבָרָא אֶת הָעוֹלָם וְכָל הַבְּרִיּוֹת שֶׁבָּרָא בָּעוֹלָם, וְכָלַל בָּהּ עֶלְיוֹנִים וְתַחְתּוֹנִים בְּלִי פֵרוּד כְּלָל, וְכָלַל בָּהּ עֶשֶׂר סְפִירוֹת וְכָל שֵׁמוֹת וְכִנּוּיִים וַהֲוָיוֹת. וְהָעֶלְיוֹן עַל הַכֹּל, שֶׁהוּא אָדוֹן עַל הַכֹּל, וְאֵין אֱלוֹהַּ חוּץ מִמֶּנּוּ, וְאֵין נִמְצָא בְּעֶלְיוֹנִים וְתַחְתּוֹנִים פָּחוֹת מִמֶּנּוּ. מִשּׁוּם שֶׁהוּא קֶשֶׁר שֶׁל כֻּלָּם, שְׁלֵמוּת שֶׁל כֻּלָּם, לְקַיֵּם בּוֹ (תהלים קג) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. וּמִשּׁוּם שֶׁלֹּא נִמְצָא עֶלְיוֹן עַל הַכֹּל בָּעֶלְיוֹנִים וְתַחְתּוֹנִים פָּחוֹת מִמֶּנּוּ, אֲפִלּוּ בְּאֶחָד מֵהֶם, נִקְרֵאת אֱמוּנַת יִשְׂרָאֵל. וּמִצִּדּוֹ שֶׁל הָעֶלְיוֹן עַל הַכֹּל נֶאֱמַר בָּהּ (דברים ד) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. אֲבָל מִצַּד שֶׁל שְׁאָר הַבְּרִיּוֹת נֶאֱמַר בָּהּ (במדבר יב) וּתְמוּנַת ה' יַבִּיט.</p>\n<p>בָּא הַמְּנוֹרָה הַקְּדוֹשָׁה וּשְׁאָר הַחֲבֵרִים, וְהִשְׁתַּטְּחוּ לְפָנָיו וְאָמְרוּ, וַדַּאי עַתָּה אֵין מִי שֶׁיָּכוֹל לָקַחַת מִמֶּנּוּ חֶלְקוֹ, שֶׁלֹּא נָתַן בּוֹ חֶלְקוֹ אֶחָד בָּעוֹלָם אֶלָּא בּוֹרֵא הָעוֹלָם, עֶלְיוֹן עַל הַכֹּל, וּבוֹ תָּלוּי עָנְשׁוֹ אוֹ שְׂכָרוֹ, וְלֹא בְמַלְאָךְ וְשָׂרָף וְלֹא בְשׁוּם בְּרִיָּה בָּעוֹלָם. וּמִשּׁוּם זֶה בֵּאֲרוּ חַכְמֵי הַמִּשְׁנָה, הַמְשַׁתֵּף שֵׁם שָׁמַיִם וְדָבָר אַחֵר, נֶעֱקָר מִן הָעוֹלָם. מִיָּד שֶׁשָּׁמַע דְּבָרִים אֵלּוּ שֶׁאָמַר רַבִּי שִׁמְעוֹן הַמְּנוֹרָה הַקְּדוֹשָׁה, שָׂמַח הָרוֹעֶה הַנֶּאֱמָן. (שאמרהרועההנאמן, שמחהמנורה הקדושה) וְכָל הַחֲבֵרִים בֵּרְכוּ אוֹתוֹ וְאָמְרוּ, רוֹעֶה נֶאֱמָן, אִם לֹא הָיָה בָּא אָדָם בָּעוֹלָם אֶלָּא לִשְׁמֹעַ זֶה - דַּי.</p>"],[9522012525,"<p>אַשְׁרָיו מִי שֶׁמִּשְׁתַּדֵּל בַּגָּלוּת הָאַחֲרוֹנָה לָדַעַת הַשְּׁכִינָה, לְכַבֵּד אוֹתָהּ בְּכָל הַמִּצְווֹת וְלִסְבֹּל בִּגְלָלָהּ כַּמָּה צָרוֹת, כְּמוֹ שֶׁנֶּאֱמַר, הַשָּׂכָר עֲבוּר שִׂמְחַת חָתָן וְכַלָּה הוּא הַדּחַק. וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא (בראשית כח) - אִם יֵשׁ כ\"ב אוֹתִיּוֹת שֶׁל הַתּוֹרָה, הַשְּׁכִינָה שׁוֹכֶבֶת עִמּוֹ.</p>\n<p>מַהוּ יֵ\"שׁ? חָכְמָה מֵאַיִן. שֶׁבְּמָקוֹם שֶׁהַשְּׁכִינָה הָעֶלְיוֹנָה שָׁם, חָכְמָה שָׁם. וּבִגְלָלָהּ נֶאֱמַר, (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ. וְזֶהוּ (שמות כ) וְעֹשֶׂה חֶסֶד לַאֲלָפִים לְאֹהֲבַי - מִצַּד שֶׁל אַהֲבַת חֶסֶד. וְיֵשׁ - שֶׁהִיא חָכְמָה - לְיָמִין. שֶׁכָּךְ בֵּאֲרוּהוּ, הָרוֹצֶה לְהַחְכִּים - יַדְרִים. וּמִשּׁוּם זֶה נֶאֱמַר לְהַנְחִיל אֹהֲבַי יֵשׁ.</p>\n<p>בֹּא וּרְאֵה, בַּסּוֹדוֹת הַסְּתוּמִים, בַּמִּדּוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אוֹתָהּ מִדָּה שֶׁמִּשְׁתַּדְּלִים בָּהּ וְזוֹכְרִים אוֹתָהּ, עָלֶיהָ נֶאֱמַר, בְּמִדָּה שֶׁאָדָם מוֹדֵד, בָּהּ מוֹדְדִים לוֹ. וְשִׁבְעִים פָּנִים לַתּוֹרָה, וְזֶהוּ שֶׁנֶּאֱמַר (שם) בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי. תַּזְכִּיר אֶת שְׁמִי צָרִיךְ לִהְיוֹת! אֶלָּא בְּאוֹתָהּ מִדָּה שֶׁאַזְכִּיר אֶת שְׁמִי, בְּאוֹתָהּ מִדָּה אָבוֹא אֵלֶיךְ וּבֵרַכְתִּיךְ. (ע\"כ רעיא מהימנא).</p>\n<p>זֹהַר עַל פִּי הַגּוֹרָל תֵּחָלֵק נַחֲלָתוֹ בֵּין רַב לִמְעָט (במדבר כו). רַבִּי יְהוּדָה פָּתַח וְאָמַר (קהלת ג) יָדַעְתִּי כִּי כָּל אֲשֶׁר יַעֲשֶׂה הָאֱלֹהִים הוּא יִהְיֶה לְעוֹלָם עָלָיו אֵין לְהוֹסִיף וּמִמֶּנּוּ אֵין לִגְרֹעַ וְגוֹ'. שְׁלֹמֹה הַמֶּלֶךְ, שֶׁחָכְמָתוֹ יְתֵרָה עַל כָּל בְּנֵי הָעוֹלָם, לֹא יָדַעְנוּ כִּי כָּל אֲשֶׁר יַעֲשֶׂה הָאֱלֹהִים הוּא יִהְיֶה לְעוֹלָם, וְהוּא אָמַר יָדַעְתִּי, מַה שֶּׁלֹּא יָדַע בֶּן אָדָם אַחֵר?!</p>\n<p>אֶלָּא וַדַּאי שְׁלֹמֹה הַמֶּלֶךְ חָכְמָתוֹ עוֹלָה עַל כָּל בְּנֵי הָעוֹלָם, וּמַה שֶּׁהוּא יָדַע, לֹא יוֹדְעִים כָּל שְׁאָר בְּנֵי הָעוֹלָם. בֹּא וּרְאֵה, שְׁאָר בַּעֲלֵי אֻמָּנוּת שֶׁבָּעוֹלָם, כַּאֲשֶׁר הוּא עוֹשֶׂה מַעֲשֶׂה, מַשְׁגִּיחַ בּוֹ וּמִסְתַּכֵּל פַּעַם וּשְׁתֵּי פְעָמִים וְעוֹשֶׂה אוֹתוֹ, וּלְבַסּוֹף מוֹסִיף עָלָיו אוֹ גּוֹרֵעַ מִמֶּנּוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כָּךְ - מוֹצִיא מַעֲשֶׂה לַאֲמִתּוֹ מִתֹּהוּ, שֶׁאֵין בּוֹ מַמָּשׁוּת כְּלָל, וְהוּא מַמָּשׁ נִתְקָן כְּמוֹ שֶׁצָּרִיךְ, וְלֹא צָרִיךְ לְהוֹסִיף וְלִגְרֹעַ מִמֶּנּוּ. בִּגְלַל זֶה כָּתוּב, (בראשית א) וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד.</p>"],[9522012526,"<p>וְעוֹד, כָּל אֲשֶׁר יַעֲשֶׂה הָאֱלֹהִים, לְתִקּוּן הָעוֹלָם, וַדַּאי הוּא יִהְיֶה לְעוֹלָם. רַבִּי יִצְחָק אָמַר, אִם כֵּן, מַהוּ שֶׁנֶּאֱמַר וְהָאֱלֹהִים עָשָׂה שֶׁיִּירְאוּ מִלְּפָנָיו? אֶלָּא זֶה הַפָּסוּק כָּךְ לָמַדְנוּ, וְהוּא סוֹד עֶלְיוֹן בֵּין חֲבֵרֵינוּ. פָּסוּק זֶה כָּךְ צָרִיךְ לִהְיוֹת: כִּי כָּל אֲשֶׁר עָשָׂה הָאֱלֹהִים הוּא יִהְיֶה לְעוֹלָם. מַהוּ כָּל אֲשֶׁר יַעֲשֶׂה? וַהֲרֵי כָּתוּב, מַה שֶּׁהָיָה כְּבָר הוּא וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה, וְאַתָּה אָמַרְתָּ כָּל אֲשֶׁר יַעֲשֶׂה?!</p>\n<p>אֶלָּא מִפָּסוּק אַחֵר נִשְׁמָע. כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. יַעֲשֶׂה?! עָשִׂיתָ צָרִיךְ לִהְיוֹת! לִמְחַכֵּה לוֹ?! לְךְ צָרִיךְ לִהְיוֹת! אֶלָּא מָקוֹם עֶלְיוֹן הוּא, שֶׁנִּמְשָׁךְ וְיוֹצֵא וּמַדְלִיק נֵרוֹת כֻּלָּם לְכָל כִּוּוּן, וְנִקְרָא עוֹלָם הַבָּא. וּמִמֶּנּוּ יוֹצֵא אִילָן אֶחָד לְהַשְׁקוֹתוֹ וּלְתַקְּנוֹ. וְזֶה הָאִילָן עֶלְיוֹן וּמְכֻבָּד הוּא עַל כָּל שְׁאָר הָאִילָנוֹת, וּכְבָר בֵּאֲרוּהוּ. וְאוֹתוֹ עוֹלָם הַבָּא שֶׁנִּמְשָׁךְ וְיוֹצֵא, מְתַקֵּן לוֹ לְזֶה הָאִילָן תָּמִיד, מַשְׁקֶה אוֹתוֹ וּמְתַקֵּן אוֹתוֹ בְּמַעֲשָׂיו, מְעַטֵּר אוֹתוֹ בַּעֲטָרוֹת, וְלֹא מַפְסִיק מְקוֹרוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>בְּאוֹתוֹ אִילָן תְּלוּיָה הָאֱמוּנָה, בּוֹ שׁוֹרֶה מִכָּל שְׁאָר הָאִילָנוֹת, קִיּוּם הַכֹּל בּוֹ. וְעַל זֶה כָּתוּב, כָּל אֲשֶׁר יַעֲשֶׂה הָאֱלֹהִים הוּא יִהְיֶה לְעוֹלָם. וַדַּאי הוּא הָיָה, הוּא הֹוֶה, וְהוּא יִהְיֶה. עָלָיו אֵין לְהוֹסִיף וּמִמֶּנּוּ אֵין לִגְרֹעַ. וְעַל זֶה בַּתּוֹרָה כָּתוּב, (דברים יג) לֹא תֹסֵף עָלָיו וְלֹא תִגְרַע מִמֶּנּוּ. שֶׁאִילָן זֶה תּוֹרָה הוּא. וּמָקוֹם זֶה מְתַקֵּן הָאֱלֹהִים תָּמִיד. הָאֱלֹהִים סְתָם, זוֹ גְּבוּרָה מֵאֵין סוֹף וּמֵאֵין חֵקֶר, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מ) אֵין חֵקֶר לִתְבוּנָתוֹ. הָאֱלֹהִים, וְלֹא אֱלֹהִים. וְעַל זֶה עָשָׂה, יַעֲשֶׂה תָּמִיד, כִּנְבִיעָה שֶׁלֹּא פוֹסְקִים מֵימֶיהָ לְדוֹרֵי דוֹרוֹת.</p>\n<p>בִּגְלַל זֶה כָּתוּב, וְהָאֱלֹהִים עָשָׂה שֶׁיִּירְאוּ מִלְּפָנָיו. תִּקֵּן לוֹ לְזֶה הָאִילָן בְּתִקּוּן שָׁלֵם שֶׁאָחוּז לְכָל צַד, עֶלְיוֹן וְתַחְתּוֹן, כְּדֵי שֶׁיִּירְאוּ מִלְּפָנָיו, וְלֹא יַחֲלִיפוּ אוֹתוֹ בְּחִלּוּף אַחֵר לְדוֹרֵי דוֹרוֹת.</p>\n<p>אָמַר רַבִּי אַבָּא, וַדַּאי יָפֶה אַתָּה אוֹמֵר, אֲבָל שׁוּב יֵשׁ לְהִסְתַּכֵּל: בַּתְּחִלָּה יַעֲשֶׂה, וּלְבַסּוֹף - וְהָאֱלֹהִים עָשָׂה. מַה בֵּין זֶה לָזֶה? אֶלָּא (תמיד) וַדַּאי יַעֲשֶׂה וִיתַקֵּן לְזֶה הָאִילָן שֶׁלֹּא יִפָּסְקוּ מֵימָיו לְדוֹרֵי דוֹרוֹת. וּלְבַסּוֹף עָשָׂה. מַהוּ עָשָׂה? אֶלָּא עָשָׂה הָאֱלֹהִים אִילָן אַחֵר לְמַטָּה מִמֶּנּוּ. וְלֹא יַעֲשֶׂה כְּמוֹ זֶה. שֶׁזֶּה הָאִילָן הַתַּחְתּוֹן עָשָׂה אוֹתוֹ וְהִתְקִין אוֹתוֹ, מִשּׁוּם שֶׁמִּי שֶׁיִּכָּנֵס לָאִילָן הָעֶלְיוֹן, יִכָּנֵס בִּרְשׁוּת, וְיִמְצָא לָאִילָן הַתַּחְתּוֹן, וְיִירָא לְהִכָּנֵס, אֶלָּא כְּמוֹ שֶׁרָאוּי.</p>\n<p>בֹּא וּרְאֵה שֶׁזֶּה, שׁוֹמֵר הַפֶּתַח הוּא, וְעַל זֶה נִקְרָא (תהלים קכא) שׁוֹמֵר יִשְׂרָאֵל. וְזֶה הָאִילָן הַתַּחְתּוֹן עָשָׂה, וּמֻשְׁקֶה וְנִזּוֹן מֵהָאִילָן הָעֶלְיוֹן. וְעַל זֶה לֹא כָתוּב יַעֲשֶׂה, אֶלָּא עָשָׂה. מָה הַטַּעַם? שֶׁיִּירְאוּ מִלְּפָנָיו בְּנֵי הָעוֹלָם וְלֹא יִתְקָרְבוּ אֵלָיו אֶלָּא אֵלּוּ שֶׁיִּהְיוּ רְאוּיִים לְהִתְקָרֵב, וְלֹא אֲחֵרִים, וְיִשְׁמְרוּ בְּנֵי הָאָדָם דַּרְכֵי הַתּוֹרָה וְלֹא יִסְטוּ לְיָמִין וְלִשְׂמֹאל.</p>"],[9522012527,"<p>בֹּא וּרְאֵה, עַל זֶה הָאִילָן שֶׁכָּל חֲיָלָיו בּוֹ נִמְצָאִים, אָמַר דָּוִד, (תהלים טז) אַתָּה תּוֹמִיךְ גּוֹרָלִי. מַהוּ גּוֹרָלִי? זֶה הַגּוֹרָל שֶׁאוֹחֵז בּוֹ דָּוִד הַמֶּלֶךְ. וְעַל זֶה כָּתוּב עַל פִּי הַגּוֹרָל. וְכֵן הוּא עַל פִּי ה'. וַיָּמָת שָׁם עַל פִּי ה'. כָּתוּב הַגּוֹרָל (כן בו על פי). אַשְׁרֵי חֶלְקָם שֶׁל אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יוֹמָם וָלַיְלָה וְיוֹדְעִים דְּרָכָיו, וְהֵם אוֹכְלִים בְּכָל יוֹם מָזוֹן עֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ז) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. שֶׁהֲרֵי הַתּוֹרָה שֶׁל מַעְלָה מִמָּקוֹם זֶה נִזּוֹנֵית, וַהֲרֵי נִתְבָּאֵר עֲלֵיהֶם, (ישעיה סה) הִנֵּה עֲבָדַי יֹאכֵלוּ.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (יחזקאל א) וַיְהִי קוֹל מֵעַל הָרָקִיעַ. זֶה הַקּוֹל שֶׁאָחוּז לְזֶה הָרָקִיעַ וּמִשְׁתַּתֵּף עִמּוֹ. וְזֶהוּ שֶׁכָּתוּב (תהלים קיא) זֵכֶר עָשָׂה לְנִפְלְאוֹתָיו. וְאוֹתוֹ רָקִיעַ עוֹמֵד עֲלֵיהֶם, עַל אוֹתָן חַיּוֹת. וְזֶה הוּא שֶׁנִּבְרָא בַּשֵּׁנִי, לְהַבְדִּיל (בראשית א) בֵּין מַיִם לָמָיִם.</p>\n<p>וַהֲרֵי בֵּאֲרוּהָ, שֶׁשִּׁבְעָה רְקִיעִים לְמַעְלָה לְמַעְלָה. וַדַּאי וִילוֹן אֵינוֹ מְשַׁמֵּשׁ, שֶׁהֲרֵי אֵין לוֹ מִשֶּׁלּוֹ, אֶלָּא מַה שֶּׁנּוֹתְנִים לוֹ. וְהָעֲנִיִּים בּוֹ אֲחוּזִים. זֶהוּ סוֹד הַכָּתוּב, (דברי הימים אכב) (ו) בעָניּיּ הַכיּנותיּ לביּת אִלהַיּ, וזִה מַכניּס שַׁחֲרִית וּמוֹצִיא עַרְבִית. שֶׁהֲרֵי בַּלַּיְלָה מוֹצִיא חֵילוֹתָיו לְכָל הַצְּדָדִים, וְשׁוֹלֵט עַל אוֹתָם חֲיָלוֹת וַהֲמוֹנִים. וּבַשַּׁחֲרִית מְכַנֵּס לְכֻלָּם, וּמַכְנִיסָם לְנִקְבָּם וְלֹא שׁוֹלְטִים. שֶׁהֲרֵי הַבֹּקֶר כּוֹלֵל אֶת כֻּלָּם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צב) לְהַגִּיד בַּבֹּקֶר חַסְדֶּךְ וֶאֱמוּנָתְךְ בַּלֵּילוֹת. וַהֲרֵי בֵּאֲרוּהוּ.</p>\n<p>וְיִשִׁ קוֹל עַל זֶה הָרָקִיעַ, מִמֶּנּוּ נִזּוֹן זֶה הָרָקִיעַ. בְּשָׁעָה שֶׁקּוֹל זֶה מִתְעוֹרֵר, כָּל הַהֲמוֹנִים לֹא נוֹסְעִים, וְאֵין לָהֶם רְשׁוּת אֶלָּא לַעֲמֹד בִּמְקוֹמָם, וּמְקָרְבִים אֶת חֵילוֹתֵיהֶם וּמְחַכִּים לְאוֹתוֹ טוֹב שֶׁנִּמְשָׁךְ לְאוֹתוֹ רָקִיעַ וְיִתְבָּרְכוּ בִגְלָלוֹ, וְעַל זֶה הוּא מֵעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם.</p>\n<p>בֹּא וּרְאֵה, רָקִיעַ רָקִיעַ אֲשֶׁר עַל אֶבֶן סַפִּיר דְּמוּת כִּסֵּא, מַה שֶּׁכָּתַב כְּמַרְאֵה אֶבֶן סַפִּיר - זוֹ אֶבֶן יִשְׂרָאֵל. וְזֶהוּ סוֹד הַכָּתוּב, (בראשית כט) וְגָלֲלוּ אֶת הָאֶבֶן וְגוֹ'. אֶבֶן אַחַת יָרְדָה מִלְמַעְלָה כַּאֲשֶׁר רָצוּ יִשְׂרָאֵל לָרֶשֶׁת אֶת הָאָרֶץ, וְכָתוּב בָּהּ גּוֹרָל. וְהִיא אָמְרָה: זֶה לִפְלוֹנִי, וְזֶה לִפְלוֹנִי. וְזוֹ הָאֶבֶן הִיא מִתַּחַת כִּסֵּא הַמֶּלֶךְ יוֹרֶדֶת. וַדַּאי (שם מט) מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל כָּתוּב. וּמִשּׁוּם זֶה עַל פִּי הַגּוֹרָל וַדַּאי תֵּחָלֵק נַחֲלָתוֹ.</p>\n<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים מֵאוּשָׁא לְלוֹד. פָּגַע בָּהֶם רַבִּי אֶלְעָזָר. רָצוּ אַחֲרָיו. אָמְרוּ, וַדַּאי נָרוּץ אַחֲרֵי הַשְּׁכִינָה. עַד שֶׁהִגִּיעוּ אֶצְלוֹ, אָמְרוּ, וַדַּאי נִשְׁתַּתֵּף אִתְּךְ וְנִשְׁמַע דְּבַר חִדּוּשׁ.</p>\n<p>פָּתַח וְאָמַר, (ישעיה נא) שִׁמְעוּ אֵלַי רֹדְפֵי צֶדֶק מְבַקְשֵׁי וְגוֹ'. שִׁמְעוּ אֵלַי רֹדְפֵי צֶדֶק - אֵלּוּ שֶׁהוֹלְכִים אַחַר הָאֱמוּנָה, רֹדְפֵי צֶדֶק, וַדַּאי אֵלּוּ מְבַקְשֵׁי ה'. אִם רְצִיתֶם לָדַעַת הָאֱמוּנָה וְלֶאֱחֹז בְּזֶה הַצֶּדֶק, לֹא תִסְתַּכְּלוּ בָהּ לְבַדָּהּ כִּשְׁאָר בְּנֵי הָעוֹלָם שֶׁגָּרְמוּ מִיתָה לְעַצְמָם עַל זֶה. אֲבָל (שם) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם וְאֶל מַקֶּבֶת בּוֹר נֻקַּרְתֶּם.</p>\n<p>צַו אֶת בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵיהֶם אֶת קָרְבָּנִי לַחְמִי וְגוֹ'. כָּתוּב (שמואל א טו) הַחֵפֶץ לַה' בְּעֹלוֹת וּזְבָחִים כִּשְׁמֹעַ בְּקוֹל ה' וְגוֹ'. אֵין רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְחַיֵּב בֶּן אָדָם וְעַל חוֹבוֹ יַקְרִיב קָרְבָּן. אֶלָּא קָרְבָּן שֶׁהוּא בְּלִי חוֹבָה, זֶהוּ קָרְבָּן שָׁלֵם, וְנִקְרָא שְׁלָמִים. וְקָרְבַּן תָּמִיד גַּם כָּךְ, וְאַף עַל גַּב שֶׁמְּכַפֵּר עַל חוֹבוֹת.</p>\n<p>רַבִּי אַבָּא פָּתַח, (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ, שֶׁרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵין רְצוֹנוֹ בְּקָרְבָּן שֶׁל אָדָם עַל חֲטָאָיו, אֶלָּא רוּחַ נִשְׁבָּרָה. וּבְנֵי אָדָם לֹא יוֹדְעִים מָה אוֹמְרִים. וְכָךְ שָׁמַעְנוּ מֵהַמְּנוֹרָה הַקְּדוֹשָׁה, שֶׁכַּאֲשֶׁר בָּא אָדָם לְהִטַּמֵּא בַּחֲטָאָיו, מַמְשִׁיךְ עָלָיו רוּחַ מִצַּד הַטֻּמְאָה, וּמִתְגָּאֶה עַל הָאָדָם וְשׁוֹלֵט עָלָיו לְכָל רְצוֹנוֹ. וְאוֹתוֹ צַד הַטֻּמְאָה מִתְגַּבֵּר בְּכֹחוֹ וּמִתְחַזֵּק, וְשׁוֹלֵט עָלָיו שֶׁיַּעֲשֶׂה רְצוֹנוֹ. בָּא אָדָם וְשׁוֹלֵט עָלָיו לְהִטַּהֵר - מְטַהֲרִים אוֹתוֹ.</p>\n<p>בִּזְמַן שֶׁהָיָה בֵּית הַמִּקְדָּשׁ קַיָּם, הִקְרִיב קָרְבָּנוֹ - כָּל כַּפָּרָה שֶׁלּוֹ תְּלוּיָה עָלָיו, עַד שֶׁהִתְחָרֵט וְשָׁבַר לְאוֹתָהּ הָרוּחַ מִתּוֹךְ גַּאֲוָתוֹ וְהִשְׁפִּיל אוֹתָהּ. וְזוֹהִי הַשְּׁבִירָה שֶׁל אוֹתָהּ דַּרְגָּה שֶׁל טֻמְאָה. וְכַאֲשֶׁר נִשְׁבֶּרֶת אוֹתָהּ רוּחַ הַטֻּמְאָה וּמַקְרִיב קָרְבָּנוֹ, זֶהוּ שֶׁמִּתְקַבֵּל בְּרָצוֹן כְּמוֹ שֶׁצָּרִיךְ.</p>\n<p>וְאִם לֹא נִשְׁבֶּרֶת אוֹתָהּ רוּחַ, אֵין קָרְבָּנוֹ כְּלוּם, וְנִמְסָר לַכְּלָבִים, שֶׁהֲרֵי קָרְבָּן זֶה אֵינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶלָּא מֵהַכְּלָבִים. וּמִשּׁוּם זֶה זִבְחֵי אֱלֹהִים כְּמוֹ שֶׁצָּרִיךְ הוּא רוּחַ נִשְׁבָּרָה, שֶׁיְּשַׁבֵּר אוֹתָהּ רוּחַ טֻמְאָה וְלֹא תִשְׁלֹט. וְעַל זֶה מִי שֶׁיִּשְׁבֹּר אוֹתָהּ כְּמוֹ שֶׁצָּרִיךְ, עָלָיו כָּתוּב, (תהלים עח) רוּחַ הוֹלֵךְ וְלֹא יָשׁוּב. שֶׁיִּהְיֶה אוֹתוֹ אָדָם בְּהַבְטָחָה שֶׁלֹּא יָשׁוּב אֶצְלוֹ לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב וְלֹא יָשׁוּב. לֵב נִשְׁבָּר וְנִדְכֶּה - אוֹתוֹ אָדָם שֶׁלֹּא הִתְגָּאָה וְלֹא הִתְעַנֵּג בְּתַעֲנוּגֵי הָעוֹלָם - אֱלֹהִים לֹא תִבְזֶה, בְּכָבוֹד הוּא אֶצְלוֹ.</p>\n<p>צַו אֶת בְּנֵי יִשְׂרָאֵל (במדבר כח). מַהוּ צַו? זֶה עֲבוֹדָה זָרָה, כְּדֵי שֶׁלֹּא יַכְנִיס עַצְמוֹ לְהִטַּמֵּא בְּרוּחַ טֻמְאָה, שֶׁהִיא עֲבוֹדָה זָרָה מַמָּשׁ.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח, (שיר השירים ה) בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ, אֲבָל יֵשׁ דְּבָרִים נִסְתָּרִים בַּקָּרְבָּן (ששה סדרים בקרבן) כָּאן, וְהַכֹּל נִתְבָּאֵר. אָמַר לוֹ רַבִּי שִׁמְעוֹן, יָפֶה הוּא שֶׁהִתְחַלְתָּ הַדָּבָר, וְסָתַמְתָּ, תֹּאמַר. (סתמתמדוע, ') אָמַר, מִשּׁוּם שֶׁרָאִיתִי בְּסִפְרוֹ שֶׁל חֲנוֹךְ דָּבָר וְלָמַדְתִּי. אָמַר, תֹּאמַר אוֹתוֹ הַדָּבָר שֶׁרָאִיתָ וְשָׁמַעְתָּ.</p>\n<p>אָמַר, הַכֹּל דָּבָר אֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר אֶת זֶה, בָּאתִי לְגַנִּי, בִּגְלַל שֶׁכָּל קָרְבְּנוֹת הָעוֹלָם כַּאֲשֶׁר עוֹלִים, כֻּלָּם עוֹלִים לְתוֹךְ גַּן עֵדֶן בַּתְּחִלָּה, סוֹד כְּנֶסֶת יִשְׂרָאֵל. וְכֵיצַד? בָּרִאשׁוֹנָה וּבְהַתְחָלַת הַקָּרְבָּן, בְּשָׁעָה שֶׁאָדָם מוֹדֶה עַל חֲטָאָיו, וּשְׁחִיטָתוֹ וּזְרִיקַת דָּמוֹ עַל הַמִּזְבֵּחַ.</p>\n<p>עַתָּה יֵשׁ לְהִסְתַּכֵּל, אֵיךְ אוֹתָן רוּחוֹת קְדוֹשׁוֹת נֶהֱנוֹת מִזֶּה, וּמַה טַּעַם שֶׁל קָרְבַּן בְּהֵמָה, וַהֲרֵי יוֹתֵר הָיָה רָאוּי לָאָדָם לִשְׁבֹּר אוֹתָהּ הָרוּחַ וְלָשׁוּב בִּתְשׁוּבָה, וּמָה הַטַּעַם שֶׁל שְׁחִיטַת הַבְּהֵמָה וּלְשָׂרְפָהּ בְּאֵשׁ הַמִּזְבֵּחַ?</p>\n<p>אֶלָּא סוֹד הוּא, מִשּׁוּם שֶׁיֵּשׁ בְּהֵמָה שֶׁרוֹבֶצֶת עַל אֶלֶף הָרִים, וְאֶלֶף הָרִים אוֹכֶלֶת בְּכָל יוֹם, וְכֻלָּם נִקְרָאִים (תהלים נ) בְּהֵמוֹת בְּהַרְרֵי אָלֶף. וְעַל זֶה לָמַדְנוּ שֶׁיֵּשׁ בְּהֵמָה שֶׁאוֹכֶלֶת בְּהֵמָה. וּמִמָּה נַעֲשׂוּ? מֵאֵשׁ. וְאֶת כֻּלָּם לוֹחֶכֶת אוֹתָם אוֹתָהּ בְּהֵמָה בִּלְחִיכָה אַחַת. זֶהוּ שֶׁכָּתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא אֵל קַנָּא. וְכָל מֵי הַיַּרְדֵּן שֶׁנִּתְמַלֵּא בְּשֵׁשׁ שָׁנִים, הִיא שׁוֹתָה אוֹתָם בִּגְמִיעָה אַחַת. זֶהוּ שֶׁכָּתוּב (איוב מ) יִבְטַח כִּי יָגִיחַ יַרְדֵּן אֶל פִּיהוּ.</p>\n<p>סוֹד הַדָּבָר, הַחֲמוּרָה שֶׁל כָּל אֵלּוּ, עִקָּר וִיסוֹד לְאֵלּוּ הַבְּהֵמוֹת שֶׁלְּמַטָּה, מִשּׁוּם שֶׁהָרוּחַ מִתְפַּשֶּׁטֶת מֵהֶן (שרוחות הבהמות מתפשטות מהן) לְמַטָּה, וּמִצְטַיֶּרֶת אוֹתָהּ הָרוּחַ לְמַטָּה בַּבְּהֵמוֹת. וְכַאֲשֶׁר חָטָא הָאָדָם, מֵבִיא בְּהֵמָה לְקָרְבָּן, וְאוֹתָהּ הָרוּחַ שֶׁל בְּהֵמָה זוֹ עוֹלָה וְחוֹזֶרֶת לִמְקוֹמָהּ, וּמִתְפַּשֶּׁטֶת אוֹתָהּ הָרוּחַ בְּכֻלָּם. וְכָל אֵלּוּ מִסּוּג זֶה מִתְקָרְבִים וּבָאִים וְנֶהֱנִים מֵאוֹתוֹ חֵלֶב וְדָם שֶׁהָיָה לְבוּשׁ שֶׁל רוּחַ זוֹ, שֶׁהֲרֵי מִצַּד שֶׁלָּהֶם הָיְתָה (בגלל) אוֹתָהּ הָרוּחַ (שלהם). וְכֻלָּם נֶהֱנוּ וְנִזּוֹנוּ וְנַעֲשׂוּ סָנֵגוֹרִים עַל אוֹתוֹ הָאָדָם. וְנִכְנָס דֶּרֶךְ הַוֵּשֶׁט, כְּמוֹ שֶׁנִּתְבָּאֵר. וּמִשּׁוּם זֶה הַקָּרְבָּן מִן הַבְּהֵמָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בָּרוּךְ בְּנִי לְהַקָּדוֹשׁ בָּרוּךְ הוּא, עָלֶיךְ נֶאֱמַר (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ. יִשְׂמַח אָבִיךְ - שֶׁלְּמַעְלָה. וְאִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְתָגֵל יוֹלַדְתֶּךְ - זוֹ בִּתּוֹ שֶׁל רַבִּי פִּנְחָס שֶׁל יָאִיר הֶחָסִיד. אֶלְעָזָר בְּנִי, אֱמֹר, זֶה קָרְבַּן בְּהֵמָה, קָרְבַּן הָעוֹף מַהוּ שֶׁכָּתוּב (ויקראא) וְאִם מִן הָעוֹף עֹלָה קָרְבָּנוֹ? אָמַר לוֹ, לֹא רָאִיתִי, אֲבָל הִסְתַּכַּלְתִּי מִדָּבָר זֶה שֶׁל הַבְּהֵמָה, דָּבָר שֶׁל עוֹפוֹת. וְלֹא אַחֵר, וְלֹא אֹמַר, מִשּׁוּם שֶׁלֹּא רָאִיתִי, וְעַד כָּאן לֹא שָׁמַעְתִּי.</p>\n<p>אָמַר לוֹ, אֶלְעָזָר, יָפֶה אָמַרְתָּ. אֲבָל סוֹד הַקָּרְבָּנוֹת סְתָרִים רַבִּים שָׁם, וְלֹא נִמְסְרוּ לְגַלּוֹת חוּץ מִצַּדִּיקֵי אֱמֶת, שֶׁסּוֹד שֶׁל אֲדוֹנָם לֹא נִכְסָה מֵהֶם. סִתְרֵי הַקָּרְבָּנוֹת זֶהוּ סוֹד לְאוֹתָם כֵּלִים (חיות) הַקְּדוֹשִׁים. אַרְבַּע דְּמֻיּוֹת חֲקוּקוֹת בַּכִּסֵּא, וְזֶהוּ כִּסֵּא וּפַרְנָס שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ: פְּנֵי שׁוֹר, פְּנֵי נֶשֶׁר, פְּנֵי אַרְיֵה, פְּנֵי אָדָם. פְּנֵי אָדָם שֶׁכּוֹלֵל לְכֻלָּם. וְכָל הַפָּנִים מִסְתַּכְּלִים אֵלּוּ בְּאֵלּוּ, וְנִכְלָלִים אֵלּוּ בְּאֵלּוּ, וּמֵהֶם מִתְפַּשְּׁטִים לְכַמָּה צְדָדִים וּרְבָבוֹת לְמַעְלָה וּלְמַטָּה, שֶׁאֵין לָהֶם שִׁעוּר וּמִנְיָן וְחֶשְׁבּוֹן.</p>\n<p>מִפְּנֵי הַשּׁוֹר מִתְפַּשֶּׁטֶת לַבְּהֵמוֹת רוּחַ מִמֶּנּוּ לְאַרְבָּעָה מִינִים, וְנִכְלָלִים בְּאֶחָד. וְאֵלּוּ הֵם: פָּרִים, וּכְבָשִׂים, וְעַתּוּדִים, וְעִזִּים. וְהֵם עוֹמְדִים לְקָרְבָּן. וּמִשּׁוּם שֶׁמֵּהֶם הָיוּ, אֵלּוּ חֲיָלוֹת קְדוֹשִׁים שֶׁמִּתְפַּשְּׁטִים מֵאוֹתוֹ פְּנֵי שׁוֹר, מִתְקָרְבִים לַיְסוֹד שֶׁלָּהֶם, וְנֶהֱנִים מֵאוֹתוֹ יְסוֹד וּמַלְבּוּשׁ שֶׁלָּהֶם. וְאִם לֹא שֶׁהָיוּ לָהֶם יְסוֹדוֹת שֶׁל עוֹלָם הַזֶּה, לֹא הָיוּ נִקְרָבִים שָׁם.</p>\n<p>כְּדֻגְמַת שֶׁיֵּשׁ נַחַת לַשְּׁכִינָה הַקְּדוֹשָׁה מֵרוּחוֹת הַצַּדִּיקִים, וּמִתְקָרֶבֶת לְקַבֵּל רוּחַ שֶׁל אוֹתוֹ צַדִּיק וְנֶהֱנֵית מִמֶּנּוּ, מִשּׁוּם שֶׁמִּמֶּנָּה הָיְתָה אוֹתָהּ רוּחַ - כָּךְ אֵלּוּ נֶהֱנִים מִצַּד הַיְסוֹד שֶׁלָּהֶם, וְנֶהֱנִים מֵאוֹתוֹ הַלְּבוּשׁ שֶׁמִּתְקָרְבִים אֵלָיו, (שהרי) רוּחַ הַמַּלְבּוּשׁ (כך אלו נהנים מאותו הלבוש שמקריבים שמצד היסוד שלהם, שהרי חלב ודם מלבוש) שֶׁל רוּחַ שֶׁלָּהֶם הָיְתָה, וּמִשּׁוּם זֶה נֶהֱנִים מֵהֶם.</p>\n<p>פְּנֵי נֶשֶׁר מִתְפַּשֵּׁט לָעוֹפוֹת רוּחַ מִמֶּנּוּ. וְנֶשֶׁר בִּשְׁנֵי צְדָדִים הוּא. וְסוֹד זֶה (בראשית א) וְעוֹף יְעוֹפֵף, שְׁתֵּי רוּחוֹת. וּמִשּׁוּם זֶה מִתְפַּשֵּׁט וְיוֹרֵד (ונשר בשני צדדים הוא, ימין ושמאל. וסוד זה (שם) ועוף יעופף, וּמשוּם זה שתּי רוּחות מתפּשטות ממנּוּ ויורדות) מימין ומשמאל קרבן העוף.</p>\n<p>מִכָּל הַצַּד הַטָּהוֹר לֹא מַקְרִיבִים אֶלָּא יוֹנָה וְתוֹרִים, שֶׁהֵם נֶאֱמָנִים לִבְנֵי זוּגָם מִכָּל שְׁאָר הָעוֹפוֹת. וְהֵם נִרְדָּפִים וְלֹא רוֹדְפִים, וְנֶאֱמָנִים זֶה לָזֶה, הַנְּקֵבָה לְבֶן זוּגָהּ, וְעַל זֶה הַקָּרְבָּן מֵהֶם. וְיוֹרְדוֹת וּמִתְקָרְבוֹת אֵלּוּ הָרוּחוֹת הַקְּדוֹשׁוֹת, וְנֶהֱנוֹת מִיסוֹד וְעִקָּר שֶׁלָּהֶם.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ מִתְפַּשֵּׁט מִמְּעַט שֶׁל יוֹנָה זוֹ אוֹ מִתּוֹר זֶה לְכַמָּה צְדָדִים וַחֲיָלוֹת שֶׁאֵין לָהֶם שִׁעוּר? אוֹ מִן בְּהֵמָה אַחַת אַף כָּךְ? בֹּא רְאֵה, נֵר אֶחָד דַּק דּוֹלֵק, וּמִתְמַלֵּא מִמֶּנּוּ כָּל הָעוֹלָם. עוֹד, עֵץ קָטָן מַדְלִיק לַגָּדוֹל.</p>\n<p>עַד כָּאן קָרְבָּן מִשְּׁנֵי צְדָדִים שֶׁחֲקוּקִים בַּכִּסֵּא. וְעַתָּה יֵשׁ לִשְׁאֹל, אַרְבַּע דְּמֻיּוֹת הֵן שֶׁחֲקוּקוֹת בַּכִּסֵּא. מַה טַּעַם אֵין קָרְבָּנוֹת מִשְּׁנֵי צְדָדִים אֲחֵרִים? אֶלָּא וַדַּאי מִכֻּלָּם יֵשׁ קָרְבָּן. אַרְיֵה חָקוּק בַּכִּסֵּא, וּבְשָׁעָה שֶׁקָּרְבָּן שָׁלֵם, אַרְיֵה יוֹרֵד וְעוֹלֶה בָּאֵשׁ, וְאוֹכֵל וְנֶהֱנֶה מִשָּׁם. אָדָם חָקוּק בַּכִּסֵּא, אָדָם עִקַּר הַכֹּל, וּמַקְרִיב שָׁם רוּחוֹ וְנִשְׁמָתוֹ. וְהָאָדָם הָעֶלְיוֹן נֶהֱנֶה מֵהָאָדָם הַתַּחְתּוֹן, וְכָל מִין מִתְקָרֵב לְמִינוֹ וְנֶהֱנֶה מִמֶּנּוּ מִשֶּׁלּוֹ מַמָּשׁ וּמֵהַיְסוֹד שֶׁלּוֹ.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי אַרְיֵה שֶׁאֵין לוֹ יְסוֹד לְמַטָּה בְּאוֹתוֹ קָרְבָּן - אַרְיֵה כָּלוּל בְּכֻלָּם, שֶׁהֲרֵי לְיָמִין הוּא, וּמִשּׁוּם זֶה אוֹכֵל בְּכֻלָּם, וְכָל הַשְּׁאָר לֹא אוֹכְלִים (ממנו) מִמִּינוֹ, מִשּׁוּם שֶׁיָּמִין הוּא. הֲרֵי כָּל אַרְבַּע הַדְּמֻיּוֹת הַחֲקוּקוֹת בַּכִּסֵּא נִקְרָבוֹת לְקָרְבָּן, וּמִשּׁוּם זֶה הוּא קָרְבָּן שָׁלֵם. וְכַאֲשֶׁר נֶהֱנִים מֵעִקָּר וִיסוֹד שֶׁלָּהֶם, אָז נַחַת רוּחַ לְהַדְלִיק נֵרוֹת הָעֶלְיוֹנִים.</p>\n<p>כֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים נוֹתְנִים (הם) יְסוֹד וְשֹׁרֶשׁ לְאֵלּוּ הַמַּדְרֵגוֹת הָעֶלְיוֹנוֹת שֶׁלָּהֶם. וְכָל מַדְרֵגָה נוֹתֶנֶת לִיסוֹדָהּ אַרְבַּע דְּמֻיּוֹת שֶׁל הַכִּסֵּא בָּרִאשׁוֹנָה, כְּמוֹ שֶׁאָמַרְנוּ מִין כְּנֶגֶד מִינוֹ, וּמִתְקָרְבִים אֵלּוּ בָּרִאשׁוֹנָה מִין לְמִינוֹ. פְּנֵי הַשּׁוֹר, כֻּלָּם פָּנִים שֶׁמִּתְפַּשְּׁטִים לְאוֹתָם מִינִים כְּמוֹ שֶׁאָמַרְנוּ, כֻּלָּם מִתְקָרְבִים לַשֹּׁרֶשׁ וְלַיְסוֹד שֶׁלָּהֶם. פְּנֵי נֶשֶׁר, כְּמוֹ שֶׁאָמַרְנוּ. פְּנֵי אַרְיֵה, כְּמוֹ שֶׁאָמַרְנוּ. פְּנֵי אָדָם, שֶׁמַּקְרִיב רוּחוֹ וְנִשְׁמָתוֹ מִתְקָרֵב אֵצֶל הָאָדָם הָעֶלְיוֹן.</p>\n<p>כֹּהֵן שֶׁמְּיַחֵד שֵׁם הַקָּדוֹשׁ, נִקְרָב לְגַבֵּי הַכֹּהֵן הָעֶלְיוֹן. אוֹתוֹ שֶׁנִּכְנָס לְבֵית קֹדֶשׁ הַקְּדָשִׁים. וְנִקְרָב זֶה, וּמַדְלִיק בְּתִקּוּנוֹ בְּהֶאָרַת הַפָּנִים (של האותיות) לִקְרַאת הַכֹּהֵן שֶׁלְּמַטָּה. לְוִיִּם שֶׁמְּנַגְּנִים בְּשִׂמְחָה, אוֹתוֹ צַד שֶׁלָּהֶם שָׂמֵחַ וּמֵאִיר פָּנִים. יִשְׂרָאֵל שֶׁמַּקְרִיב, (שעומדים) עַל הַקָּרְבָּנוֹת בִּתְפִלָּה, שֶׁהֲרֵי תְּפִלָּה עַל הַכֹּל הָיְתָה. הִתְעוֹרֵר לְעֻמָּתָם יִשְׂרָאֵל סָבָא (העליון), סָתוּם (חטם) הַקָּדוֹשׁ, וּמֵאִיר פָּנִים.</p>\n<p>כָּל מִין לְמִינוֹ, וְכָל דִּבּוּר אַחַר יְסוֹד שֶׁלּוֹ הוֹלֵךְ, וּמְעוֹרְרוֹת מַדְרֵגוֹת תַּחְתּוֹנוֹת לְמַדְרֵגוֹת עֶלְיוֹנוֹת, וְאַף עַל גַּב שֶׁכֻּלָּם מִתְעוֹרְרוֹת, וּמִתְעוֹרְרוֹת מַדְרֵגוֹת שֶׁחֲקוּקוֹת בַּכִּסֵּא לְגַבֵּי מַדְרֵגוֹת שֶׁל הָאָרֶץ, יְסוֹד שֶׁלָּהֶן. וְהֵן מַדְרֵגוֹת עֶלְיוֹנוֹת שֶׁנִּסְתָּרוֹת, כֻּלָּן מִתְעוֹרְרוֹת וּמִתְקָרְבוֹת לִסְעוּדָה, וּמִתְעַדְּנוֹת. אֲבָל אֵין רְשׁוּת לְאַחַת מֵהֶן לֶאֱכֹל, לֹא לְמַדְרֵגוֹת עֶלְיוֹנוֹת וְלֹא לְמַדְרֵגוֹת תַּחְתּוֹנוֹת, וְלֶהֱנוֹת שׁוּם הֲנָאָה, וְלֹא לְהוֹשִׁיט יָדָהּ לְקָרְבָּן, עַד שֶׁהַמֶּלֶךְ הָעֶלְיוֹן אוֹכֵל וְנוֹתֵן לָהֶן רְשׁוּת.</p>\n<p>וְאַחַר שֶׁנּוֹתֵן לָהֶן רְשׁוּת, כָּל אַחַת וְאַחַת נֶהֱנֵית וְאוֹכֶלֶת (כמו שצריך). וְזֶהוּ שֶׁכָּתוּב (שיר השירים ה) אָרִיתִי מוֹרִי עִם בְּשָׂמִי - אֵלּוּ הֵן מַדְרֵגוֹת עֶלְיוֹנוֹת. מוֹרִי עִם בְּשָׂמִי, אוֹכְלִים וְנֶהֱנִים כְּמוֹ שֶׁצָּרִיךְ. (זו זרוע ימין בירך שמאל). אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי - זֶה יַעֲקֹב בְּרָחֵל, זוֹ אֲכִילָה כְּמוֹ שֶׁצָּרִיךְ. שָׁתִיתִי יֵינִי עִם חֲלָבִי - זוֹ זְרוֹעַ שְׂמֹאל בְּיֶרֶךְ יָמִין. הֲרֵי כֻּלָּן מַדְרֵגוֹת (קרבנות) עֶלְיוֹנוֹת שֶׁנֶּהֱנֶה מֵהֶן הַמֶּלֶךְ הַקָּדוֹשׁ בָּרִאשׁוֹנָה, וְזוֹ הָאֲכִילָה שֶׁלּוֹ וְהַהֲנָאָה שֶׁלּוֹ. עַד כָּאן אֲכִילַת הַמֶּלֶךְ הָעֶלְיוֹן בָּרִאשׁוֹנָה.</p>\n<p>מִכָּאן וּלְהָלְאָה נָתַן רְשׁוּת לְאַרְבַּע דְּמֻיּוֹת שֶׁחֲקוּקוֹת בַּכִּסֵּא, וּלְכָל אוֹתָם שֶׁמִּתְפַּשְּׁטִים מִמֶּנּוּ, לֵהָנוֹת וְלֶאֱכֹל. זֶהוּ שֶׁכָּתוּב אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דּוֹדִים. אִכְלוּ רֵעִים - אֵלּוּ הֵן אַרְבַּע דְּמֻיּוֹת כְּמוֹ שֶׁאָמַרְנוּ. שְׁתוּ וְשִׁכְרוּ דּוֹדִים - כָּל אוֹתָם שֶׁמִּתְפַּשְּׁטִים מֵהֶן, וְכֻלָּם אוֹכְלִים וּמִתְפַּשְּׁטִים וְנֶהֱנִים כְּמוֹ שֶׁרָאוּי, וּמְאִירִים הַפָּנִים, וְהָעוֹלָמוֹת כֻּלָּם בְּשִׂמְחָה. וְכָל אֶחָד וְאֶחָד, בֵּין מַדְרֵגוֹת עֶלְיוֹנוֹת וּבֵין מַדְרֵגוֹת תַּחְתּוֹנוֹת, בַּשֹּׁרֶשׁ שֶׁלָּהֶם מִתְקָרְבִים וְנֶהֱנִים. זֶהוּ סוֹד וְסֵתֶר הַקָּרְבָּן כְּמוֹ שֶׁרָאוּי.</p>\n<p>בָּאוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וּשְׁאָר הַחֲבֵרִים וְהִשְׁתַּטְּחוּ לְפָנָיו. אָמַר רַבִּי אַבָּא, אִם לֹא נִמְסְרָה הַתּוֹרָה בְּהַר סִינַי, אֶלָּא שֶׁהָיָה אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲרֵי בֶּן יוֹחַאי הוּא הַתּוֹרָה וְהַסְּתָרִים שֶׁלִּי - דַּי לָעוֹלָם. אוֹי כַּאֲשֶׁר תִּסְתַּלֵּק מִן הָעוֹלָם. מִי יָאִיר אוֹרוֹת הַתּוֹרָה. הַכֹּל יֶחֱשַׁךְ מֵאוֹתוֹ יוֹם. שֶׁהֲרֵי עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ לֹא יִהְיֶה דוֹר כְּדוֹר זֶה שֶׁרַבִּי שִׁמְעוֹן נִמְצָא בְּתוֹכוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, עַל סוֹד זֶה אָסוּר לוֹ לְבֶן אָדָם לִטְעֹם כְּלוּם עַד שֶׁיֹּאכַל הַמֶּלֶךְ הָעֶלְיוֹן. וּמַה הוּא? תְּפִלָּה. תְּפִלָּה שֶׁל בֶּן אָדָם, כְּדֻגְמַת זֶה בַּתְּחִלָּה מְזַמְּנִים לַדְּמֻיּוֹת שֶׁחֲקוּקוֹת בַּכִּסֵּא עַל אוֹתָן הַבְּרִיּוֹת שֶׁמִּתְפַּשְּׁטוֹת רוּחוֹת שֶׁלָּהֶן עַל עוֹפוֹת וּבְהֵמוֹת לְקָרְבָּן, בְּרִיּוֹת שֶׁהָרוּחַ שֶׁלָּהֶן יְסוֹד בָּעוֹלָם הַזֶּה מֵהֶן, וְזֶהוּ (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה', שֶׁהֲרֵי בְּרִיּוֹת שֶׁרְאוּיוֹת לְהַקְרִיב, רוּחַ שֶׁלָּהֶן מִתְפַּשֶּׁטֶת עֲלֵיהֶן, אַרְבַּע דְּמֻיּוֹת מְזֻמָּנוֹת עַל קָרְבָּנוֹת אֵלּוּ. וְזֶהוּ שֶׁאָנוּ אוֹמְרִים, וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ, וְכָל אוֹתָם חֲיָלוֹת אֲחֵרִים שֶׁמִּתְפַּשְּׁטִים מֵהֶם.</p>\n<p>וּלְבַסּוֹף הַכֹּהֵן הַגָּדוֹל שֶׁהוּא מְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, וְזֶהוּ שֶׁאוֹמְרִים אַהֲבַת עוֹלָם אֲהַבְתָּנוּ וְכוּ'. וְהַיִּחוּד שֶׁמְּיַחֵד, זֶהוּ (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וּלְבַסּוֹף הַלְוִיִּם שֶׁמִּתְעוֹרְרִים לְנִגּוּן, זֶהוּ (שם יא) וְהָיָה אִם שָׁמֹעַ וְגוֹ', הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה וְגוֹ'. זֶה נִגּוּן הַלְוִיִּם, כְּדֵי לְהַסְתִּיר סֵתֶר (לעורר צד) זֶה בְּקָרְבָּן זֶה. וְאַחַר כָּךְ יִשְׂרָאֵל, זֶה אֱמֶת וְיַצִּיב וְנָכוֹן, יִשְׂרָאֵל סָבָא שֶׁעוֹמֵד עַל הַקָּרְבָּן, (קרבן עליון אלו המדרגות) שֶׁהִיא עֶשֶׂר מַדְרֵגוֹת עֶלְיוֹנוֹת פְּנִימִיּוֹת שֶׁל הַכֹּל, עוֹמְדוֹת עַל הַשֻּׁלְחָן.</p>\n<p>אֲבָל אֵין רְשׁוּת לְאֶחָד מֵהֶם לֶאֱכֹל וּלְהוֹשִׁיט יָדוֹ לַקָּרְבָּן עַד שֶׁהַמֶּלֶךְ הָעֶלְיוֹן אוֹכֵל. וְזֶהוּ ג' רִאשׁוֹנוֹת וְג' אַחֲרוֹנוֹת. כֵּיוָן שֶׁהוּא אָכַל, נָתַן רְשׁוּת לְאַרְבַּע דְּמֻיּוֹת, וּלְכָל אוֹתָם הַצְּדָדִים שֶׁנִּפְרָדִים מֵהֶן, לֶאֱכֹל.</p>\n<p>וְאָז אָדָם, שֶׁהוּא דְּמוּת שֶׁכּוֹלֶלֶת אֶת כָּל שְׁאָר הַדְּמֻיּוֹת, יוֹרֵד וְנוֹפֵל עַל פָּנָיו, וּמוֹסֵר עַצְמוֹ וְרוּחוֹ לְגַבֵּי הָאָדָם הָעֶלְיוֹן שֶׁעוֹמֵד עַל אוֹתָן הַדְּמֻיּוֹת, שֶׁכּוֹלֵל כָּל הַדְּמֻיּוֹת, לְעוֹרֵר אוֹתוֹ עָלָיו כְּמוֹ שֶׁרָאוּי, וְזֶהוּ שֶׁנֶּאֱמַר (תהלים כה) אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא, לְעוֹרֵר (שלש) דְּמֻיּוֹת אֲחֵרוֹת וְכָל אֵלּוּ שֶׁמִּתְפַּשְּׁטִים מֵהֶן. (תהלה לדוד) וְזֶהוּ שֶׁכָּתוּב (שם קמה) יַבִּיעוּ. יְרַנֵּנוּ. יֹאמֵרוּ. יְדַבֵּרוּ. וְכֻלָּם אוֹכְלִים וְנֶהֱנִים, כָּל אֶחָד וִאֶחָד כְּמוֹ שֶׁרָאוּי לוֹ.</p>\n<p>מִכָּאןֹ וּלְהָלְאָה יֹאמַר אָדָם צָרוֹת שֶׁלּוֹ בּוֹ (של לבו), זֶהוּ שֶׁכָּתוּב (שם כ) יַעַנְךְ ה' בְּיוֹם צָרָה. (צרה) כְּעֻבָּרָה שֶׁיּוֹשֶׁבֶת בְּצָרָה, כְּדֵי לְהַפֵּךְ אֶת כֻּלָּם לִהְיוֹת סָנֵגוֹרִים עַל הָאָדָם. וְעַל זֶה כָּתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ וְגוֹ'.</p>\n<p>רַבִּי שִׁמְעוֹן הָיָה הוֹלֵךְ לִטְבֶרְיָה. פָּגַע בּוֹ אֵלִיָּהוּ, אָמַר לוֹ, שָׁלוֹם עָלֶיךְ מוֹרִי. אָמַר לוֹ רַבִּי שִׁמְעוֹן, בַּמָּה עוֹסֵק הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָקִיעַ? אָמַר לוֹ, בְּקָרְבָּנוֹת עוֹסֵק, וְאוֹמֵר דְּבָרִים חֲדָשִׁים מִשִּׁמְךְ. אַשְׁרֶיךְ! וּבָאתִי לְהַקְדִּים לְךְ שָׁלוֹם, וְדָבָר אֶחָד רוֹצֶה אֲנִי לִשְׁאֹל מִמְּךְ לְהַסְכִּים., בַּיְשִׁיבָה שֶׁל הָרָקִיעַ שָׁאֲלוּ שְׁאֵלוֹת: הָעוֹלָם הַבָּא אֵין בּוֹ אֲכִילָה וּשְׁתִיָּה, וַהֲרֵי כָּתוּב (שיר השירים ה) בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה וְגוֹ', אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי וְגוֹ'. מִי שֶׁאֵין בּוֹ אֲכִילָה וּשְׁתִיָּה, הוּא אוֹמֵר אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי?!</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַה הֵשִׁיב לָהֶם? אָמַר לוֹ, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲרֵי בַּר יוֹחַאי יֹאמַר, וּבָאתִי לִשְׁאֹל מִמְּךְ. אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה חֲבִיבוּת חִבֵּב הַקָּדוֹשׁ בָּרוּךְ הוּא לִכְנֶסֶת יִשְׂרָאֵל, וּמֵרִבּוּי הָאַהֲבָה שֶׁאוֹהֵב אוֹתָהּ, שִׁנָּה מַעֲשָׂיו מִמַּה שֶּׁהוּא עוֹשֶׂה. שֶׁאַף עַל גַּב שֶׁאֵין דְּרָכָיו בַּאֲכִילָה וּשְׁתִיָּה - בִּגְלַל הָאַהֲבָה אָכַל וְשָׁתָה. הוֹאִיל וּבָא אֶצְלָהּ, עָשָׂה רְצוֹנָהּ. כַּלָּה נִכְנֶסֶת לַחֻפָּה וְרוֹצָה לֶאֱכֹל, אֵין זֶה דִּין שֶׁיֹּאכַל חֲתָנָהּ עִמָּהּ אַף עַל גַּב שֶׁאֵין דַּרְכּוֹ לַעֲשׂוֹת כָּךְ?! זֶהוּ שֶׁכָּתוּב בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה. הוֹאִיל וּבָאתִי אֶצְלָהּ וְלַעֲלוֹת עִמָּהּ לַחֻפָּה, אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי וְגוֹ'.</p>\n<p>וְלָמַדְנוּ מִדָּוִד, שֶׁהִזְמִין לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְשִׁנָּה מַעֲשָׂיו מִמַּה שֶּׁדְּרָכָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קִבֵּל וְעָשָׂה רְצוֹנוֹ. זִמֵּן לַמֶּלֶךְ וְהַמַּלְכָּה עִמּוֹ - זֶהוּ שֶׁכָּתוּב (תהלים קלב) קוּמָה ה' לִמְנוּחָתֶךְ אַתָּה וַאֲרוֹן עֻזֶּךְ. מֶלֶךְ וּמַלְכָּה כְּאֶחָד, כְּדֵי שֶׁלֹּא לְהַפְרִיד אוֹתָם, שִׁנָּה כֵּלִים וְשִׁנָּה מַעֲשִׂים שֶׁל הַמֶּלֶךְ.</p>\n<p>זֶהוּ שֶׁכָּתוּב (שם) כֹּהֲנֶיךְ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךְ יְרַנֵּנוּ בַּעֲבוּר דָּוִד וְגוֹ'. כֹּהֲנֶיךְ יִלְבְּשׁוּ צֶדֶק?! לְוִיֶּיךְ צָרִיךְ לִכְתֹּב! שֶׁהֲרֵי צֶדֶק מִצַּד הַלְוִיִּם הוּא. וַחֲסִידֶיךְ יְרַנֵּנוּ?! לְוִיֶּיךְ יְרַנֵּנוּ צָרִיךְ לִכְתֹּב! שֶׁהֲרֵי רִנָּה וְזִמְרָה הִיא בַּלְוִיּם. וְהוּא שִׁנָּה וְאָמַר כֹּהֲנֶיךְ וַחֲסִידֶיךְ, שֶׁהֵם מִצַּד הַיָּמִין.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, דָּוִד, אֵין דַּרְכִּי כָּךְ. אָמַר דָּוִד, בַּעֲבוּר דָּוִד עַבְדֶּךְ אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךְ. תִּקּוּן שֶׁאֲנִי תִּקַּנְתִּי, אַל תְּשַׁנֶּה אוֹתוֹ. אָמַר לוֹ, דָּוִד, הוֹאִיל וְזִמַּנְתָּ אוֹתִי, יֵשׁ לִי לַעֲשׂוֹת רְצוֹנְךְ, וְלֹא רְצוֹנִי. וּלְמֵדִים מִכָּאן דֶּרֶךְ הָעוֹלָם, שֶׁמִּי שֶׁמְּזַמֵּן לְאַחֵר, אוֹתוֹ שֶׁבָּא אֶצְלוֹ יֵשׁ לוֹ לַעֲשׂוֹת רְצוֹנוֹ אַף עַל גַּב שֶׁאֵין דַּרְכּוֹ בְּכָךְ.</p>\n<p>כָּךָ (בראשית כח) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וְגוֹ'. הוֹאִיל וּבָא חָתָן אֵצֶל הַכַּלָּה, אַף עַל גַּב שֶׁאֵין דַּרְכּוֹ לִשְׁכַּב אֶלָּא בְּכָרִים וּכְסָתוֹת, וְהִיא נָתְנָה לוֹ אֲבָנִים לִשְׁכַּב - הַכֹּל יְקַבֵּל בִּרְצוֹן הַלֵּב. זֶהוּ שֶׁכָּתוּב וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, עַל אוֹתָם אֲבָנִים, אַף עַל גַּב שֶׁאֵין דַּרְכּוֹ בְּכָךְ.</p>\n<p>אַף גַּם כָּאן, אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי - אַף עַל גַּב שֶׁאֵין דַּרְכּוֹ בְּכָךְ, בִּגְלַל אַהֲבָה שֶׁל הַכַּלָּה. וְעִם כָּל זֶה בְּבֵיתָהּ שֶׁל הַכַּלָּה, וְלֹא בְמָקוֹם אַחֵר. בִּמְקוֹמוֹ לֹא אוֹכֵל וְלֹא שׁוֹתֶה - בַּמָּקוֹם שֶׁלָּהּ אוֹכֵל וְשׁוֹתֶה. זֶהוּ שֶׁכָּתוּב בָּאתִי לְגַנִּי. מַלְאָכִים שֶׁשָּׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם לֹא אָכְלוּ וְלֹא שָׁתוּ בִּמְקוֹמָם - בִּשְׁבִיל אַבְרָהָם אָכְלוּ וְשָׁתוּ. אָמַר לוֹ, רַבִּי, חַיֶּיךְ דָּבָר זֶה רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לוֹמַר, וּמִשּׁוּם שֶׁלֹּא לְהַחֲזִיק טוֹבָה לְעַצְמוֹ לִפְנֵי כְּנֶסֶת יִשְׂרָאֵל, הֵבִיא הַדָּבָר לְפָנֶיךְ. אַשְׁרֶיךְ בָּעוֹלָם, שֶׁאֲדוֹנְךְ מִשְׁתַּבֵּחַ בְּךְ לְמַעְלָה, וְעָלֶיךְ כָּתוּב (שמואל ב כג) צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים.</p>\n<p>אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי וְגוֹ' (במדבר כח). רַבִּי יוּדָאִי אָמַר, בַּקָּרְבָּן יֵשׁ עָשָׁן, וְיֵשׁ רֵיחַ, וְיֵשׁ נִיחוֹחַ. עָשָׁן - אֵלּוּ בַּעֲלֵי הָרֹגֶז, שֶׁנֶּאֱמַר (דברים כט) כִּי אָז יֶעְשַׁן אַף ה'. אֵלּוּ נֶהֱנִים מֵהֶעָשָׁן, וַעֲשַׁן רֹגֶז בַּחֹטֶם הוּא. רֵיחַ - אֵלּוּ שֶׁנִּקְרָאִים תַּפּוּחִים. אָמַר רַבִּי אַבָּא, כַּתַּפּוּחִים - זֶהוּ שֶׁכָּתוּב (שיר השירים ז) וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים.</p>\n<p>אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַבֹּקֶר (במדבר כח). מַהוּ בַבֹּקֶר? זֶה בֹּקֶר שֶׁל אַבְרָהָם, שֶׁנֶּאֱמַר (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבּקֶר. מִנַּיִן לָנוּ שֶׁזֶּה הַבֹּקֶר שֶׁל אַבְרָהָם? אָמַר רַבִּי אֶלְעָזָר, מִכָּאן, שֶׁנֶּאֱמַר (שם מד) הַבֹּקֶר אוֹר. בֹּקֶר אוֹר לֹא כָתוּב, אֶלָּא הַבֹּקֶר אוֹר, וְזֶה אוֹר רִאשׁוֹן שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית, וְעַל זֶה נֶאֱמַר תַּעֲשֶׂה בַבֹּקֶר, בַּבֹּקֶר הַיָּדוּעַ. וּכְנֶגֶד בֹּקֶר שֶׁל אַבְרָהָם מַקְרִיבִים קָרְבָּן זֶה. קָרְבָּן שֶׁל בֵּין הָעַרְבַּיִם זֶה יִצְחָק, וּכְנֶגֶד עֶרֶב שֶׁל יִצְחָק נִקְרָב. מִנַּיִן לָנוּ? שֶׁנֶּאֱמַר (בראשית כד) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב. וְעֶרֶב הוּא שֶׁל יִצְחָק, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>מִצְוָה זוֹ לְהַקְרִיב מִנְחָה בְּכָל יוֹם וּלְהַקְרִיב קָרְבַּן מוּסַף שַׁבָּת. וְאַחֲרָיו לְסַדֵּר לֶחֶם הַפָּנִים וּלְבוֹנָה, וְקָרְבַּן מוּסָף בְּרֹאשׁ חֹדֶשׁ. הַמְּנוֹרָה הַקְּדוֹשָׁה, בְּכָל יוֹם צָרִיךְ לִשְׁלֹחַ דּוֹרוֹן לַמֶּלֶךְ בִּידֵי הַמַּלְכָּה. אִם הִיא בִּרְשׁוּת בַּעְלָהּ, צָרִיךְ תּוֹסֶפֶת, כְּמוֹ מוּסָף בְּשַׁבָּת וּבְרֹאשׁ חֹדֶשׁ, וּמוּסָף שֶׁל כָּל יָמִים טוֹבִים.</p>\n<p>שֶׁהִיא רְשׁוּת הַיָּחִיד שֶׁלּוֹ, וְהָעַמּוּד הָאֶמְצָעִי הוּא בַּעְלָהּ שֶׁל רְשׁוּת זוֹ. וְיַעֲקֹב שֶׁתִּקֵּן תְּפִלַּת עַרְבִית, הוּא מַדְרֵגָה שֶׁלּוֹ שֶׁל הָעַמּוּד הָאֶמְצָעִי. בִּגְלַל זֶה בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, תְּפִלַּת עַרְבִית רְשׁוּת. שֶׁאַף עַל גַּב שֶׁבַּגָּלוּת, הַדּוֹמָה לְלַיְלָה, שֶׁשּׁוֹלְטִים שָׁם סָמָאֵל וְנָחָשׁ וְכָל הַמְמֻנִּים שֶׁל הַהֲמוֹנִים שֶׁלּוֹ, וּשְׁכִינָה יוֹרֶדֶת בַּגָּלוּת עִם יִשְׂרָאֵל - הִיא נִמְצֵאת בִּרְשׁוּת בַּעְלָהּ. זֶהוּ שֶׁכָּתוּב (ישעיה מב) אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן.</p>\n<p>וּמִשּׁוּם זֶה נֶאֱמַר (בראשית כח) וַיִּפְגַּע בַּמָּקוֹם. אֵין פְּגִיעָה אֶלָּא פִּיּוּס, כְּמוֹ (רות א) אַל תִּפְגְּעִי בִי. כְּנֶסֶת יִשְׂרָאֵל מְפַיֶּסֶת לוֹ שֶׁלֹּא יָזוּז מִמֶּנָּה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא מְקוֹמוֹ שֶׁל עוֹלָם. אֵיזֶה עוֹלָם? זוֹ הַשְּׁכִינָה. תַּרְגּוּם עוֹלָם הוּא עָלְמָא, לְשׁוֹן נַעֲרָה, כְּמוֹ שֶׁנֶּאֱמַר (שמות ב) הָעַלְמָה. וּמַה כָּתוּב בּוֹ? (בראשית כח) וַיָּלֶן שָׁם. הִתְפַּיֵּס עִמָּהּ לָלוּן שָׁם בַּגָּלוּת עִם הַשְּׁכִינָה. וְאִם תֹּאמַר שֶׁיַּעֲקֹב פִּיֵּס אוֹתָהּ - נָכוֹן. וּמִשּׁוּם שֶׁהִיא בְּכָל לַיְלָה, שֶׁהוּא הַגָּלוּת, בִּרְשׁוּת בַּעְלָהּ, פֵּרְשׁוּ תְּפִלַּת עַרְבִית רְשׁוּת. וּפֵרוּשׁ אַחֵר, הוּא תֶּבֶן לֶאֱכֹל לַבְּהֵמוֹת חָמְרִיּוּת בְּקַל וָחֹמֶר. יָרְדוּ בַּעֲלֵי הַמִּשְׁנָה וְהִשְׁתַּטְּחוּ לְפָנָיו, וְשָׂמַח בְּדָבָר זֶה, וְקָשְׁרוּ אוֹתָהּ בְּכַמָּה קְשָׁרִים שֶׁל סוֹדוֹת סְתוּמִים וְעִטְּרוּ אוֹתָהּ, וְהֶעֱלוּ אוֹתָהּ אֵצֶל הַחֲבֵרִים שֶׁנִּשְׁאֲרוּ שָׁם.</p>\n<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, הַמְּנוֹרָה הַקְּדוֹשָׁה, בִּגְלַל זֶה בִּשְׁאָר הַתְּפִלּוֹת הוּא חוֹבָה, כִּשְׁטַר חוֹב שֶׁעָלָיו, לִסְמֹךְ אוֹתָהּ בְּצַדִּיק חַי הָעוֹלָמִים, שֶׁבּוֹ כָּל הַסּוֹמֵךְ גְּאֻלָּה לִתְפִלָּה אֵינוֹ נִזּוֹק בְּכָל אוֹתוֹ יוֹם. וּבַמֶּה נִסְמֶכֶת עַל יְסוֹד? בִּזְרוֹעַ יָמִין. זֶהוּ שֶׁכָּתוּב (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר.</p>\n<p>כַּאֲשֶׁר מַגִּיעַ זְמַן תְּפִלַּת מִנְחָה, (אסתר ב) בָּעֶרֶב הִיא בָאָה. זֶהוּ שֶׁכָּתוּב (בראשית ח) וַתָּבֹא אֵלָיו הַיּוֹנָה לְעֵת עֶרֶב. מִשּׁוּם שֶׁמִּנְחָה שְׁלוּחָה הִיא לַאדוֹנִי, (אדני צריך להיות) בַּגָּלוּת שֶׁל עֵשָׂו, (שם לב) וְהִנֵּה גַם הוּא אַחֲרֵינוּ. וְעוֹד לַאדוֹנִי (אדוני לאדוני), זֶהוּ אֲדוֹן כָּל הָאָרֶץ, וְזֶה צַדִּיק, מִשָּׁם יוֹסֵף הַצַּדִּיק, (דברים לג) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ, שָׁעָתִיד לָצֵאת מִמֶּנּוּ מָשִׁיחַ בֶּן אֶפְרַיִם. וּבִגְלָלוֹ נֶאֱמַר (בראשית לז) וְהִנֵּה קָמָה אֲלֻמָּתִי וְגַם נִצָּבָה וְהִנֵּה תְסֻבֶּינָה אֲלֻמֹּתֵיכֶם וַתִּשְׁתַּחֲוֶיןָ לַאֲלֻמָּתִי. וּבְצַדִּיק נֶאֱמַר, כָּל הַכּוֹרֵעַ - כּוֹרֵעַ בְּבָרוּךְ.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה נֶאֱמָן, בְּךְ נֶאֱמַר (שמות יג) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף. מִשּׁוּם שֶׁגּוּף וּבְרִית נֶחְשָׁבִים כְּאֶחָד. וּמִשּׁוּם זֶה עָלֶיךְ נֶאֱמַר, וְהִנֵּה קָמָה אֲלֻמָּתִי וְגַם נִצָּבָה. שֶׁכָּךְ תְּפִלָּה בַּעֲמִידָה. וְכֵן כָּל הַזּוֹקֵף - זוֹקֵף בַּשֵּׁם. וּבְצַדִּיק, כָּל הַכּוֹרֵעַ - כּוֹרֵעַ בְּבָרוּךְ, וְזֶהוּ וַתִּשְׁתַּחֲוֶיןָ לַאֲלֻמָּתִי. שֶׁאַתָּה אָחוּז בְּיָמִין וּבִשְׂמֹאל, בְּגוּף וּבְרִית. וְאַחַר כָּךְ תַּעֲלֶה עֲלֵיהֶם לְבִינָה, לִפְתֹּחַ בָּהּ חֲמִשִּׁים שְׁעָרִים שֶׁל חֵרוּת לְיִשְׂרָאֵל, לְקַיֵּם (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. וּמִשּׁוּם זֶה תְּפִלַּת שַׁחֲרִית חוֹבָה, וּתְפִלַּת עַרְבִית רְשׁוּת.</p>\n<p>בְּעַרְבִית הוּא בִּרְכַּת הַשְׁכִּיבֵנוּ, שֶׁשּׁוֹכֶבֶת בֵּין זְרוֹעֵי הַמֶּלֶךְ בַּגָּלוּת. כַּאֲשֶׁר יָבֹא הַבֹּקֶר, פֶּסַח אָחוּז בּוֹ בְּיָמִין. אֲבָל בִּזְרוֹעַ שְׂמֹאל שֶׁל יִצְחָק - חֹדֶשׁ תִּשְׁרֵי. (בראשית כד) וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יֹצֵאת, מִן הַגָּלוּת. וּמִשּׁוּם שֶׁלֹּא יוֹצֵאת מִצַּד הַדִּין, יַעֲקֹב שִׂכֵּל אֶת יָדָיו, וְשָׁם שׁוֹר בְּיָמִין, אַרְיֵה בִּשְׂמֹאל. וּמִשּׁוּם זֶה (תהלים קי) נְאֻם ה' לַאדוֹנִי שֵׁב לִימִינִי - זֶה צַדִּיק, כְּנֶגְדּוֹ מָשִׁיחַ בֶּן יוֹסֵף. וְאָמַר לוֹ שֵׁב לִימִינִי, זְרוֹעַ שֶׁל אַבְרָהָם, בַּגָּלוּת שֶׁל יִשְׁמָעֵאל, עַד אָשִׁית אֹיְבֶיךְ הֲדוֹם לְרַגְלֶיךְ.</p>"],[9522012528,"<p>בְּאוֹתוֹ זְמַן תִּתְעוֹרֵר רוּחַ יְתֵרָה תּוֹסֶפֶת עַל יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (יואל ג) אֶשְׁפּוֹךְ אֶת רוּחִי עַל כָּל בָּשָׂר. וְיִהְיֶה מְנוּחָה לְיִשְׂרָאֵל מֵאֻמּוֹת הָעוֹלָם, (אסתר ט) וְנוֹחַ מֵאֹיְבֵיהֶם. כְּדֻגְמַת הַשַּׁבָּת, שֶׁנּוֹסֶפֶת בָּאָדָם נֶפֶשׁ יְתֵרָה בְּשַׁבָּת וְיֵשׁ לָהֶם בָּהּ נַחַת - אִם בְּנֶפֶשׁ יְתֵרָה יֵשׁ לָהֶם נַחַת, שֶׁהִיא נְקֵבָה, כָּל שֶׁכֵּן בְּרוּחַ, שֶׁהוּא זָכָר.</p>\n<p>וְתַנָּאִים וְאָמוֹרָאִים, נֶפֶשׁ יְתֵרָה לְכָל יִשְׂרָאֵל כְּאֶחָד - אַחַת הִיא, אֲבָל לְכָל אָדָם הוּא כְּפִי מַעֲשָׂיו. וְלָמַדְנוּ מִקַּל וָחֹמֶר שֶׁל הַתְּשׁוּבָה, שֶׁכָּל יִשְׂרָאֵל כְּאֶחָד, בְּכָל זְמַן שֶׁחוֹזְרִים כֻּלָּם - מִתְקַבְּלִים. זֶהוּ שֶׁכָּתוּב (דברים ד) כַּה' אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. שֶׁשֵּׁם ה' מֻכְתָּר עֲלֵיהֶם בְּכִתְרוֹ, שֶׁהוּא כֶּתֶר עֶלְיוֹן. וְזוֹהִי נְשָׁמָה יְתֵרָה שֶׁל יִשְׂרָאֵל בְּשַׁבָּת וְיָמִים טוֹבִים. וּמִשּׁוּם זֶה תִּקְּנוּ בְּכָל יוֹם לַחְתֹּם בְּשֵׁם יְהֹוָה, שֶׁהוּא חוֹתָם שֶׁל כָּל הַבְּרָכוֹת שֶׁל הַתְּפִלּוֹת, וְלֹא אוֹמְרִים מוּסָף בְּלִי כֶּתֶר. וּבְשַׁבָּת תִּקְּנוּ לוֹמַר בְּמוּסָף, כֶּתֶר יִתְּנוּ לְךְ ה' אֱלֹהֵינוּ.</p>\n<p>אֲבָל לְכָל אֶחָד מִיִּשְׂרָאֵל, כָּךְ יוֹרֶדֶת לוֹ נֶפֶשׁ יְתֵרָה כְּפִי מַדְרֵגָתוֹ. אִם הוּא חָסִיד - נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה מִמִּדַּת חֶסֶד כְּפִי מַדְרֵגָתוֹ; אִם הוּא גִּבּוֹר, יְרֵא חֵטְא - נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה מִמִּדַּת הַגְּבוּרָה., וְאִם הוּא אִישׁ תָּם - נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה מִמִּדַּת אֱמֶת. וְנֶפֶשׁ יְתֵרָה זוֹ מַלְכוּת, שֶׁהִיא כְּלוּלָה מֵעֶשֶׂר סְפִירוֹת, וּכְפִי מִדָּה שֶׁל בֶּן אָדָם. אִם נְשִׂיא יִשְׂרָאֵל, אוֹ חָכָם, אוֹ מֵבִין בְּחָכְמָה, אוֹ בַּתּוֹרָה, שֶׁנֶּאֱמַר בּוֹ (משלי א) לְהָבִין מָשָׁל וּמְלִיצָה, אוֹ בַּנְּבִיאִים, אוֹ בַּכְּתוּבִים - כָּךְ נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה שֶׁנִּקְרֵאת כֶּתֶר מַלְכוּת.</p>\n<p>וְאִם חָכָם, כְּמוֹ שֶׁבֵּאַרְנוּ, הַמַּחְכִּים לְכָל אָדָם, שֶׁנֶּאֱמַר (תהלים קד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ - נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה מִשָּׁם. וְאִם הוּא מֵבִין דָּבָר מִתּוֹךְ דָּבָר בַּתּוֹרָה - נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה מִבִּינָה. וְאִם הוּא חָכָם בַּנְּבִיאִים וּבַכְּתוּבִים - נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה מִנֵּצַח וְהוֹד. וְאִם הוּא צַדִּיק גָּמוּר שֶׁשּׁוֹמֵר אוֹת בְּרִית, אוֹת שַׁבָּת, אוֹת יָמִים טוֹבִים, אוֹת תְּפִלִּין - נוֹתְנִים לוֹ נֶפֶשׁ יְתֵרָה מִצַּדִּיק. וּבְכָל מָקוֹם, נֶפֶשׁ יְתֵרָה מִמַּלְכוּת.</p>\n<p>וְאִם הוּא אָדָם מִכָּל מִדּוֹת אֵלּוּ - נוֹתְנִים לוֹ כֶּתֶר בְּשֵׁם יְהֹוָה, כַּיהֹוָה אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. אֵין קָדוֹשׁ כַּיהֹוָה. מֵעוֹלַם הַזָּכָר, שֶׁהוּא תִּפְאֶרֶת, מֶלֶךְ מֻכְתָּר בְּכֶתֶר עֶלְיוֹן, שֶׁבָּהּ יִמְלֹךְ בַּשְּׁכִינָה, שֶׁהִיא נֶפֶשׁ יְתֵרָה. וְכֶתֶר נְשָׁמָה יְתֵרָה, יְהֹוָ\"ה, רוּחַ, שֶׁנֶּאֱמַר (יואל ג) אֶשְׁפּוֹךְ אֶת רוּחִי עַל כָּל בָּשָׂר, וְהוּא כָּלוּל עֶשֶׂר סְפִירוֹת מִמַּעְלָה לְמַטָּה, כְּדֻגְמַת זֶה: י' חָכְמָה. ה' בִּינָה. ו' כּוֹלֵל שֵׁשׁ סְפִירוֹת מֵחֶסֶד עַד יְסוֹד. ה' מַלְכוּת. כ' מִן כַּיהֹוָה אֱלֹהֵינוּ, כֶּתֶר עַל רֹאשׁוֹ. וְזוֹהִי נְשָׁמָה שֶׁנּוֹסֶפֶת בְּיוֹם הַשַּׁבָּת.</p>\n<p>וּמִשּׁוּם שֶׁעִלַּת הָעִלּוֹת מֻפְלָא וּמְכֻסֶּה בְּכֶתֶר זֶה, וּמִתְפַּשֵּׁט בְּשֵׁם יְהֹוָה בְּשַׁבָּתוֹת וְיָמִים טוֹבִים, אֵין שִׁלְטוֹן לְסָמָאֵל וּלְנָחָשׁ וּלְכָל הַמְמֻנִּים שֶׁלּוֹ, וְאֵין לוֹ שִׁלְטוֹן לַגֵּיהִנָּם, נְקֵבָה רָעָה שֶׁל סָמָאֵל, וְלֹא לַמַּחֲנוֹת שֶׁלּוֹ. כֻּלָּם נִסְתָּרִים מִלִּפְנֵי מַחֲנֵה הַמֶּלֶךְ, כְּמוֹ שֶׁיִּסְתַּתְּרוּ אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם כַּאֲשֶׁר יִתְגַּלֶּה הַמָּשִׁיחַ. זֶהוּ שֶׁכָּתוּב (ישעיהב) וּבָאוּ בִּמְעָרוֹת צֻרִים (שם ז) וּבִנְקִיקֵי הַסְּלָעִים.</p>\n<p>קָמוּ תַנָּאִים וְאָמוֹרָאִים וְאָמְרוּ, רוֹעֶה נֶאֱמָן, אַתָּה הוּא שֶׁשָּׁקוּל לְכָל יִשְׂרָאֵל, מְמֻלָּא מִכָּל מִדּוֹת טוֹבוֹת, וַדַּאי בְּךְ שׁוֹרֶה זֶה שֶׁנֶּאֱמַר בּוֹ (שמואל א ב) אֵין קָדוֹשׁ כַּיהֹוָה אֱלֹהֵינוּ. אַתָּה כֶּתֶר עַל כָּל אֶחָד וְאֶחָד מִיִּשְׂרָאֵל, כִּי אֵין בִּלְתְּךְ בֶּן אָדָם שֶׁיִּהְיֶה כֶּתֶר עָלֶיךְ, לֹא נָשִׂיא, וְלֹא חָכָם, וְלֹא מֵבִין, וְלֹא חָסִיד, וְלֹא גִבּוֹר, וְלֹא תָם, וְלֹא נָבִיא, וְלֹא צַדִּיק, וְלֹא מֶלֶךְ. אַתָּה הוּא בִּדְמוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בֵּן בִּדְמוּת אָבִיו, כְּמוֹ יִשְׂרָאֵל שֶׁנֶּאֱמַר בָּהֶם (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. הַשְׁלֵם מִצְווֹת שֶׁל אֲדוֹנְךְ, שֶׁאֵין מִצְווֹת מֵאֵלּוּ שֶׁלְּךְ שֶׁלֹּא יִתְעַטֵּר בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מַעְלָה וּמַטָּה בְּכֶתֶר עֶלְיוֹן בְּכָל מִדָּה וּמִדָּה.</p>\n<p>פָּתַח וְאָמַר, תַּנָּאִים וְאָמוֹרָאִים, שֶׁכַּאֲשֶׁר הָיָה קוֹרֵא לְכֻלָּם, לְרַבִּי שִׁמְעוֹן בִּכְלַל עִמָּהֶם בְּכָל זְמַן, אֱמֹר לָהֶם, אֲנִי מְשַׁבֵּחַ לָכֶם כְּפִי נְדִיבוּת שֶׁלָּכֶם, שֶׁאַתֶּם בְּנֵי נְדִיבִים אַבְרָהָם יִצְחָק וְיַעֲקֹב. אֵין מִי שֶׁיָּכוֹל לְשַׁבֵּחַ לָכֶם אֶלָּא אֲדוֹן הָעוֹלָם, שֶׁאֲפִלּוּ הַתּוֹרָה כֻּלָּהּ עַד אֵין סוֹף בָּכֶם הִיא תְּלוּיָה, כְּמוֹ מַה שֶּׁנֶּאֱמַר בַּתּוֹרָה, (איוב יא) אֲרֻכָּה מֵאֶרֶץ מִדָּהּ וּרְחָבָה מִנִּי יָם. כָּךְ הַשֶּׁבַח שֶׁלָּכֶם. אֲבָל יִתְקַיֵּם בָּכֶם מַה שֶּׁהִתְקַיֵּם בִּי, שֶׁשָּׂמַחְתִּי בִּכְבוֹדוֹ שֶׁל אַהֲרֹן אָחִי, כְּמוֹ שֶׁבֵּאֲרוּהוּ, הַלֵּב שֶׁשָּׂמַח בִּגְדֻלַּת אָחִיו, יִלְבַּשׁ אוּרִים וְתֻמִּים.</p>\n<p>וְתַנָּאִים וְאָמוֹרָאִים, כָּל מוּסָפִים שֶׁל שַׁבָּתוֹת וְיָמִים טוֹבִים, כָּל מוּסָף שֶׁאוֹמְרִים בּוֹ כֶּתֶר - מִכָּאן נוֹדָעִים. וְכָל תְּפִלּוֹת שֶׁל יִשְׂרָאֵל, רֵיחָן כְּרֵיחַ שֶׁל (שיר השירים ג) מוֹר וּלְבוֹנָה וְכֹל אַבְקַת רוֹכֵל, בִּשְׁאָר יָמִים. אֲבָל בְּשַׁבָּתוֹת וְיָמִים טוֹבִים חָשׁוּב עָלָיו מִינֵי בְשָׂמִים.</p>\n<p>מִשּׁוּם שֶׁבְּיָמִים טוֹבִים עוֹלִים מִכֹּל אַבְקַת רוֹכֵל, שֶׁנֶּאֱמַר בּוֹ (בראשית לב) וַיֵּאָבֵק אִישׁ עִמּוֹ. שֶׁתְּפִלָּה שֶׁהִיא פְּגוּמָה, נֶאֱבָק עִמָּהּ סָמָאֵל, לְהִלָּחֵם עִמָּהּ בְּאוֹתוֹ פְּגָם שֶׁל עֲבֵרָה שֶׁבְּאוֹתוֹ אָבָק, שֶׁזֶּה וָזֶה עוֹלֶה עַד הַשָּׁמַיִם.</p>"],[9522012529,"<p>אָבָק שֶׁל יַעֲקֹב, לְלַמֵּד זְכוּת עַל הַתְּפִלָּה בְּכַמָּה מַחֲנוֹת שֶׁל חוֹבוֹת (זכיות) שֶׁהֵם (חילות) קְבוּצוֹת וּמַחֲנוֹת, שֶׁמִּתְאַסְּפִים עִמּוֹ לְלַמֵּד זְכוּת עָלֶיהָ. וְהָאָבָק בְּמַדְרֵגָה שֶׁל סָמָאֵל עוֹלֶה בְּכַמָּה מַחֲנוֹת שֶׁל חוֹבוֹת לְלַמֵּד חוֹבוֹת עָלֶיהָ, וְזוֹ תְּפִלַּת עַרְבִית שֶׁנִּקְרֵאת סֻלַּם יַעֲקֹב, שֶׁבָּהּ (בראשית כח) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. אֵלּוּ שֶׁמַּעֲלִים חוֹבוֹת וּמוֹרִידִים זְכֻיּוֹת תַּחְתֵּיהֶם, וְאֵלּוּ מַעֲלִים זְכֻיּוֹת, וְיוֹרְדִים חוֹבוֹת תַּחְתֵּיהֶן, וּמַשְׁפִּילִים לָהֶם בְּכַמָּה קְרָבוֹת.</p>\n<p>שֶׁהֵם בַּעֲלֵי מָגִנִּים בְּמִלְחַמְתָּהּ שֶׁל תּוֹרָה, עַד שֶׁנִּשְׁמַעַת הַמִּלְחָמָה לֶהָרִים הַגְּבוֹהִים, שֶׁהֵם אַבְרָהָם יִצְחָק וְיַעֲקֹב. זֶהוּ שֶׁכָּתוּב (מיכה ו) שִׁמְעוּ הָרִים אֶת רִיב ה'. רִיב הַתְּפִלָּה, וְרִיב הַתּוֹרָה. וְזֶה הַקְּרָב שֶׁל תְּפִלַּת עַרְבִית שֶׁנִּמְשָׁךְ עַד עֲלוֹת הַשַּׁחַר. שֶׁרַבָּן גַּמְלִיאֵל הֶעֱמִיד אוֹתָהּ עַד עֲלוֹת הַשַּׁחַר, שֶׁתְּפִלַּת עַרְבִית זְמַנָּהּ כָּל הַלַּיְלָה, אֶלָּא שֶׁחֲכָמִים עָשׂוּ גָדֵר עַד חֲצוֹת.</p>\n<p>וּמִשּׁוּם זֶה נֶאֱמַר וַיֵּאָבֵק אִישׁ עִמּוֹ עַד עֲלוֹת הַשָּׁחַר. מַהוּ הַשַּׁחַר? תְּפִלַּת עַרְבִית, שֶׁשִּׁעוּרָהּ עַד בֹּקֶר שֶׁל אַבְרָהָם, שֶׁהוּא אַרְבַּע שָׁעוֹת. (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. בִּתְחִלַּת שָׁעָה רִאשׁוֹנָה בְּסוֹף הַשַּׁחַר, (שהוא) נֵצַח יַעֲקֹב, שֶׁשָּׁם (תהלים כב) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר, לָקַחַת נְקָמָה מִסָּמָאֵל, שֶׁנָּגַע בְּיֶרֶךְ שְׂמֹאל שֶׁל יַעֲקֹב, שֶׁהוּא הוֹד, שֶׁבּוֹ נֶאֱמַר (איכה א) נְתָנַנִי שּמֵמָה כָּל הַיּוֹם דָּוָה, הוֹד, מִצַּד הַהוֹד, אֶלֶף חֲמִשִּׁי, נִשְׁאָר בֵּית הַמִּקְדָּשׁ חָרֵב וְיָבֵשׁ.</p>"],[9522012530,"<p>אָמַר רַבִּי שִׁמְעוֹן, זֶה הוֹד שֶׁלְּךְ, רוֹעֶה נֶאֱמָן, שֶׁבּוֹ אַתָּה חָרֵב מִנְּבוּאָתְךְ מִשְּׂמֹאל, וּמִשּׁוּם שֶׁאַתָּה (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה, שֶׁהוּא נֵצַח, רֹאשׁ שֶׁל הַשַּׁחַר, וְנֶאֱמַר (משלי ה) אַיֶּלֶת אֲהָבִים, לָכֵן פָּתַח דָּוִד וְאָמַר לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר, שֶׁבּוֹ יָבֹא בַּעַל נוֹצֵחַ הַקְּרָב. וּמִשּׁוּם שֶׁנֵּצַח וְהוֹד הֵם שְׁנֵי מִינֵי שַׁחַר, בֵּאֲרוּ בַּמִּשְׁנָה מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִין, וְלֹא אָמַר בַּשַּׁחַר, אֶלָּא בְּשַׁחֲרִין - לְשׁוֹן רַבִּים, שְׁנַיִם.</p>\n<p>וּשְׁנֵי מְשִׁיחִים יִתְעוֹרְרוּ לְגַבֵּיהֶם - מָשִׁיחַ בֶּן דָּוִד כְּנֶגֶד הַנֵּצַח, וְנִקְשָׁר בַּבֹּקֶר שֶׁל אַבְרָהָם, זֶהוּ שֶׁכָּתוּב (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח. הוֹד קָשׁוּר בִּגְבוּרָה, שֶׁבּוֹ מָשִׁיחַ בֶּן אֶפְרַיִם אָחוּז. אַתָּה בָּאֶמְצַע, שֶׁמַּדְרֵגָה שֶׁלְּךְ תִּפְאֶרֶת, שֶׁנִּקְשָׁר בְּךְ הָעַמּוּד הָאֶמְצָעִי. וִיסוֹד חַי הָעוֹלָמִים בַּמַּדְרֵגָה שֶׁלְּךְ. וְחָכְמָה בְּיָמִין, כַּנֶּאֱמַר הָרוֹצֶה לְהַחְכִּים - יַדְרִים. וּבִינָה לִשְׂמֹאל, הָרוֹצֶה לְהַעֲשִׁיר - יַצְפִּין.</p>\n<p>הִיא הַקֶּשֶׁת אֶצְלָהּ, וְזֶהוּ לְבוּשׁ הַשְּׁכִינָה, לְבוּשׁ הַצַּדִּיק, שֶׁנִּקְרָא בְּרִית הַקֶּשֶׁת. וְהִיא אוֹת שַׁבָּת, וְאוֹת יוֹם טוֹב, וְאוֹת תְּפִלִּין, וְאוֹת בְּרִית מִילָה. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִי שֶׁאֵינוֹ רָשׁוּם בְּאוֹת זוֹ, לֹא יִכָּנֵס בְּמַרְאָה זוֹ בְּחֶדֶר זֶה. וְזֶהוּ מַטֶּה, שֶׁהָעַמּוּד הָאֶמְצָעִי מַטֶּה בּוֹ כְּלַפֵּי חֶסֶד לְצַדִּיקִים גְּמוּרִים לָתֵת לָהֶם זְכֻיּוֹת בִּשְׁמוֹנֶה עֶשְׂרֵה בִּרְכוֹת הַתְּפִלָּה. וּמַטֶּה כְּלַפֵּי חוֹבָה לָרְשָׁעִים, לָדוּן אוֹתָם בִּגְבוּרָה לְדִין כְּפִי מַעֲשֵׂיהֶם. וּבָעַמּוּד הָאֶמְצָעִי מַאֲרִיךְ עַל הַבֵּינוֹנִיִּים. וְזוֹהִי אוֹת ש'.</p>\n<p>שְׁלֹשָה גּוֹנֵי הַקֶּשֶׁת - אוֹת בְּרִית הַקֶּשֶׁת, בַּת יְחִידָה, שַׁבַּת הַמַּלְכָּה. וְיֵשׁ לָהּ שֵׁשׁ מַדְרֵגוֹת תַּחַת שִׁלְטוֹנָהּ, שֶׁהֵם שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה שֶׁכְּלוּלִים בִּמְטַטְרוֹן, וַעֲלֵיהֶם נֶאֱמַר, (שמות כג) שֵׁשֶׁת יָמִים תַּעֲשֶׂה מַעֲשֶׂיךְ. אֲבָל בַּת יְחִידָה הִיא שַׁבָּת לַה', הָעוֹשֶׂה בָּהּ מְלָאכָה יוּמָת.</p>\n<p>יְהֹוָה נִקְרָא בְּצֵרוּף אוֹת ה' אַחֲרוֹנָה, וּמִצַּד זֶה יה\"ו לְיָמִין, שֶׁהִיא ה' שְׁלֵמוּת שֶׁלּוֹ. וְכָךְ לְכָל צַד מִשִּׁשָּׁה צְדָדִים: יהו, הוי, ויה, יוה, היו, והי. שֶׁהֵם שְׁמוֹנֶה עֶשְׂרֵה אוֹתִיּוֹת שֶׁכְּלוּלוֹת בְּצַדִּיק חַי הָעוֹלָמִים. וְהִיא רְבִיעִית הַהִין בְּכָל צַד.</p>\n<p>וְהִיא אוֹת הֵ\"א, מִצַּד שֶׁל שֵׁם הַמְפֹרָשׁ, יוֹ\"ד הֵ\"א וָא\"ו. יוֹ\"ד בְּחֶסֶד, הֵ\"א בִּגְבוּרָה, וָא\"ו בְּתִפְאֶרֶת. כְּשֶׁשּׁוֹלֵט הַט\"ל הַזֶּה, אָסְרוּ חֲכָמִים אַרְבָּעִים מְלָאכוֹת חָסֵר אַחַת. וְנִקְרָאוֹת אֲבוֹת מְלָאכוֹת, עַל שֵׁם שֶׁהֵם כְּנֶגֶד אָבוֹת שֶׁשּׁוֹלֵט עֲלֵיהֶם ט\"ל, שֶׁהוּא אַרְבָּעִים חָסֵר אַחַת.</p>\n<p>וּבְאֵלּוּ אַרְבָּעִים מְלָאכוֹת חָסֵר אַחַת, הִכָּה עֶשֶׂר מַלְקִיּוֹת לָאָדָם, וְעֶשֶׂר לְחַוָּה, וְעֶשֶׂר לַנָּחָשׁ, וְתֵשַׁע לָאָרֶץ. וּמִשּׁוּם שֶׁט\"ל שׁוֹלֵט בְּשַׁבָּת, שֶׁהִיא אוֹת ה', לָכֵן אֵין לוֹקִין בְּשַׁבָּת. וְזֶה הַט\"ל אֵינוֹ כְּמוֹ הַט\"ל שֶׁל יוֹם חֹל, מִצַּד שֶׁל עֶבֶד מְטַטְרוֹן, שֶׁהֵן אַרְבָּעִים מְלָאכוֹת חָסֵר אַחַת: הַזּוֹרֵעַ וְהַחוֹרֵשׁ וְכוּ'.</p>\n<p>זָקֵן זָקֵן, הַשְּׁכִינָה נִקְרֵאת אֶרֶץ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהָאָרֶץ הֲדם רַגְלָי. מִצַּד הַחֶסֶד נִקְרֵאת מַיִם, וּמִצַּד הַגְּבוּרָה נִקְרֵאת אֵשׁ, וּמִצַּד הָעַמּוּד הָאֶמְצָעִי - אֲוִיר. וְהִיא אֶרֶץ, קַרְקַע לְכֻלָּם.</p>\n<p>וּמִשּׁוּם שֶׁנְּשָׁמָה יְתֵרָה מִתְפַּשֶּׁטֶת בַּשְּׁכִינָה, שֶׁהִיא שַׁבַּת הַמַּלְכָּה, שֶׁנֶּאֱמַר בָּהּ (תהלים קג) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה - מִשָּׁם הִיא נַעֲשֵׂית מַלְכוּת, שֶׁשְּׁלִיטָתָהּ עַל הָאָרֶץ וְעַל אִילָנוֹת וּזְרָעִים (והרים ואבנים). וּמִשּׁוּם שֶׁאִילַן הַחַיִּים, שֶׁהִיא נְשָׁמָה יְתֵרָה בְּשַׁבָּת, בָּהּ תּוֹלָדוֹת שֶׁלָּהּ - יֵשׁ בָּהּ מְנוּחָה לָאָרֶץ, שֶׁהִיא הַשְּׁכִינָה.</p>\n<p>וּמִשּׁוּם שֶׁהַשְּׁכִינָה הָעֶלְיוֹנָה הִתְפַּשְּׁטָה בָּאָרֶץ, שֶׁנֶּאֱמַר עָלֶיהָ (במדבר יט) פָּרָה אֲדֻמָּה תְּמִימָה אֲשֶׁר אֵין בָּהּ מוּם אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל, לָכֵן אָסוּר לַחֲרשׁ בְּשַׁבָּת. וַחֲרִישָׁה בְּשׁוֹר, שֶׁנֶּאֱמַר (תהלים קכט) עַל גַּבִּי חָרְשׁוּ חֹרְשִׁים. וְהַשְּׁכִינָה הַתַּחְתּוֹנָה הִיא פָּרָה אֲדֻמָּה מִצַּד הַגְּבוּרָה. תְּמִימָה - מִצַּד הַחֶסֶד, שֶׁהִיא מַדְרֵגָה שֶׁל אַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. אֲשֶׁר אֵין בָּהּ מוּם - מִצַּד הָעַמּוּד הָאֶמְצָעִי. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל - מִצַּד הַשְּׁכִינָה הָעֶלְיוֹנָה שֶׁהִיא חֵרוּת הַכֹּל, בַּמָּקוֹם שֶׁהִיא שׁוֹלֶטֶת, (במדבר א) וְהַזָּר הַקָּרֵב יוּמָת, אֵין רְשׁוּת לַצַּד הָאַחֵר לִשְׁלֹט, לֹא שָׂטָן, וְלֹא מַשְׁחִית, וְלֹא מַלְאַךְ הַמָּוֶת, שֶׁהֵם מִצַּד הַגֵּיהִנָּם.</p>\n<p>וּמִשּׁוּם זֶה בִּימֵי הַחֹל אוֹמְרִים יִשְׂרָאֵל, (תהלים עח) וְהוּא רַחוּם יְכַפֵּר עָוֹן וְלֹא יַשְׁחִית וְהִרְבָּה לְהָשִׁיב אַפּוֹ וְגוֹ'. מִשּׁוּם שֶׁבִּימֵי הַחֹל הַשְּׁכִינָה הַתַּחְתּוֹנָה מִתְלַבֶּשֶׁת בְּאֵלּוּ הַקְּלִפּוֹת שֶׁל מִיתָה וְדִין. וּבְשַׁבָּת מִתְפַּשֶּׁטֶת מֵהֶם, בִּגְלַל שֶׁעֵץ הַחַיִּים שֶׁהוּא בֶּן י\"ה, יה\"ו, מִתְחַבֵּר בָּאוֹת הֵ\"א. בַּזְּמַן הַהוּא מְנוּחָה נִמְצֵאת לָאוֹת הֵ\"א, וְכָל מַה שֶּׁהוּא מִתַּחְתֶּיהָ, וְלֹא צָרִיךְ לוֹמַר בָּהּ וְהוּא רַחוּם. וּמִי אֵלּוּ (שתחתיה) ? תַּחַת י' יִשְׂרָאֵל. וְכָל מָקוֹם שֶׁיִּשְׂרָאֵל נִמְצָאִים, שְׁמִירָה נִמְצֵאת וּמְנוּחָה.</p>\n<p>וּמִשּׁוּם זֶה אָסוּר לַחֲרֹשׁ בָּאָרֶץ וְלַעֲשׂוֹת בָּהּ גֻּמּוֹת, שֶׁנַּעֲשָׂה כְּאִלּוּ עָשָׂה פְּגָם בָּאָרֶץ הַקְּדוֹשָׁה, שֶׁהִיא שְׁכִינָה. וְאָסוּר לְהִשְׁתַּמֵּשׁ בַּכֵּלִים שֶׁל הָאָרֶץ בְּשַׁבָּת, וַאֲפִלּוּ לְטַלְטֵל אֶבֶן וְלֹא דָבָר, אֶלָּא כְּלִי סְתָם, שֶׁיִּהְיֶה מְנוּחָה לָהֶם בִּזְכוּת הַשְּׁכִינָה שֶׁנִּקְרֵאת אֶבֶן, שֶׁכָּתוּב בָּהּ (בראשית כח) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה - בִּתְפִלָּה, עֲמִידָה הִיא לְיִשְׂרָאֵל, שֶׁבִּגְלָלָהּ יֵשׁ לָהֶם קִיּוּם בָּעוֹלָם, וְעָלֶיהָ נֶאֱמַר (שם מט) מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל. (זכריה ג) עַל אֶבֶן אַחַת שִׁבְעָה עֵינָיִם. (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים.</p>\n<p>וּמִשּׁוּם זֶה נֶאֱמַר, (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדרֹתָם בְּרִית עוֹלָם. צָרִיךְ לִשְׁמֹר אוֹתָהּ בְּדִירָתָם, שֶׁלֹּא יֵצְאוּ מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים. וְזֶהוּ שֶׁבֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, יְצִיאוֹת הַשַּׁבָּת שְׁתַּיִם שֶׁהֵן אַרְבַּע, הוֹצָאָה מֵרְשׁוּת לִרְשׁוּת, וְהַכְנָסָה גַּם כֵּן יְצִיאָה קוֹרֵא לָהּ. וְאֵלּוּ הֵם סָמָאֵל וְנָחָשׁ, צְרִיכִים יִשְׂרָאֵל לִשְׁמֹר עֲלֵיהֶם שֶׁלֹּא יִכָּנְסוּ לַדִּירָה שֶׁל הַשְּׁכִינָה, שֶׁהִיא רְשׁוּת הַיָּחִיד. מִי רְשׁוּת הָרַבִּים? חֲלָלָה שִׁפְחָה זוֹנָה נִדָּה גּוֹיָה, רְשׁוּת שֶׁל סָמָאֵל וְנָחָשׁ, וְשִׁבְעִים מְמֻנִּים שֶׁל הָעַמִּים.</p>"],[9522012531,"<p>וּבַחִבּוּר הַקַּדְמוֹן, אָרִיתִי מוֹרִי עִם בְּשָׂמִי - זְרוֹעַ יָמִין בְּיֶרֶךְ שְׂמֹאל. אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי - יַעֲקֹב בְּרָחֵל. שָׁתִיתִי יֵינִי עִם חֲלָבִי - זְרוֹעַ שְׂמֹאל בְּיֶרֶךְ יָמִין. זְרוֹעַ יָמִין בְּיֶרֶךְ שְׂמֹאל, הֵם חֶסֶד עִם הוֹד. יַעֲקֹב בְּרָחֵל - הָעַמּוּד הָאֶמְצָעִי בְּמַלְכוּת. זְרוֹעַ שְׂמֹאל בְּיֶרֶךְ יָמִין - גְּבוּרָה בְּנֵצַח.</p>\n<p>וּמַדּוּעַ שְׁתֵּי מִדּוֹת שֶׁלּוֹ כָּךְ? אֶלָּא הַסּוֹד שֶׁנֶּאֱמַר כָּאן, דָּוִד אָמַר כָּאן, (תהלים קלב) כֹּהֲנֶיךְ יִלְבְּשׁוּ צֶדֶק וַחֲסִידֶיךְ יְרַנֵּנוּ. וְנֶאֱמַר שָׁם, וּלְוִיֶּיךְ צָרִיךְ הָיָה לוֹ לוֹמַר! אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵין דֶּרֶךְ לְשַׁנּוֹת מִדּוֹתַי, אֶלָּא אַחַר שֶׁהִזְמַנְתִּי אוֹתִי, יֵשׁ לִי לַעֲשׂוֹת רְצוֹנְךְ. וּמִכָּאן לָמַדְנוּ, שֶׁבַּעַל הַבַּיִת שֶׁמַּזְמִין אֲפִלּוּ לְמֶלֶךְ, יֵשׁ לוֹ לַעֲשׂוֹת רְצוֹנוֹ. וּמִשּׁוּם זֶה בֵּאֲרוּהוּ, כָּל מַה שֶּׁאוֹמֵר לְךְ בַּעַל הַבַּיִת עֲשֵׂה, חוּץ מִצֵּא. וְעִם כָּל זֶה שֶׁסּוֹד זֶה יָפֶה הוּא, הֲרֵי כָּתוּב (מלאכי ג) אֲנִי ה' לֹא שָׁנִיתִי, וּבְכָל הַקָּרְבָּנוֹת לֹא כָתוּב בָּהֶם אֶלָּא לַיהֹוָה, וְאֵיךְ יָכוֹל לִהְיוֹת שֶׁיְּשַׁנֶּה מַדְרֵגוֹת שֶׁל שְׁמוֹ בַּקָּרְבָּנוֹת?</p>\n<p>אֶלָּא, אָרִיתִי מוֹרִי - יוֹצֵר אוֹר. עִם בְּשָׂמִי - אַהֲבַת עוֹלָם. אָכַלְתִּי יַעְרִי - שְׁמַע יִשְׂרָאֵל. עִם דִּבְשִׁי - בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. שָׁתִיתִי יֵינִי - וְהָיָה אִם שָׁמֹעַ, עַד וַיֹּאמֶר. עִם חֲלָבִי - מִן וַיּאמֶר עַד אֱמֶת. אִכְלוּ רֵעִים - ג' רִאשׁוֹנוֹת, וְג' אַחֲרוֹנוֹת. שְׁתוּ וְשִׁכְרוּ דוֹדִים - שְׁאָר בִּרְכוֹת הַתְּפִלָּה.</p>\n<p>וּבַחִבּוּר הַקַּדְמוֹן, סֵתֶר הַקָּרְבָּנוֹת - פָּרִים וּכְבָשִׂים וְעַתּוּדִים וְעִזִּים, הֵם אַרְבָּעָה, פְּנֵי שׁוֹר, פְּנֵי נֶשֶׁר וְגוֹ', שְׁתֵּי תוֹרִים אוֹ שְׁנֵי בְנֵי יוֹנָה. וְצָרִיךְ לְפָרֵשׁ. אַרְיֵה יוֹרֵד לְגַבֵּי שׁוֹר, שֶׁהוּא שְׂמֹאל, לִקְשֹׁר חֶסֶד בִּגְבוּרָה. אָדָם יוֹרֵד לְגַבֵּי נֶשֶׁר, דַּרְגָּה שֶׁל יַעֲקֹב. וּמִשּׁוּם זֶה בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, תֹּאַר פָּנָיו שֶׁל יַעֲקֹב הָיָה תֹּאַר פָּנָיו שֶׁל אָדָם הָרִאשׁוֹן. וּמִי גָרַם שֶׁיַּעֲלֶה וְיִקָּרֵא יִשְׂרָאֵל, שֶׁכָּתוּב (בראשית לב) לֹא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךְ כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ? שֶׁיִּהְיֶה יִשְׂרָאֵל עִקָּר לְהַבְדִּיל בֵּינֵיהֶם. (ע\"כ רעיא מהימנא).</p>"],[9522012532,"<p>וַעָשִׂירִית הָאֵיפָה (במדבר כח), מַדּוּעַ? אֶלָּא עֲשִׂירִית הָאֵיפָה, כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא הָעֲשִׂירִית שֶׁבַּמַּדְרֵגוֹת, וּצְרִיכָה לְהִנָּתֵן בֵּין שְׁתֵּי זְרוֹעוֹת, וְהִיא סֹלֶת הַלֶּחֶם, וְהִיא לֶחֶם. וּמִשּׁוּם שֶׁהִיא לֶחֶם, לֹא הֻפְקַד עַל לֶחֶם שֶׁל חֲמֵשֶׁת הַמִּינִים, שֶׁהֵם חִטָּה, וּשְׂעוֹרָה, וְשִׁיפוֹן וְכוּ', מְמֻנֶּה שֶׁל הָעוֹלָם. וְלֹא שָׂם מְמֻנֶּה עֲלֵיהֶם, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ.</p>\n<p>וּמִשּׁוּם זֶה מִי שֶׁמְּזַלְזֵל בְּלֶחֶם וְזוֹרֵק אוֹתוֹ בָּאָרֶץ, עֲנִיּוּת רוֹדֶפֶת אַחֲרָיו. וּמְמֻנֶּה אֶחָד הֻפְקַד עַל זֶה, וְהוּא רוֹדֵף אַחֲרָיו לָתֵת לוֹ עֲנִיּוּת, וְלֹא יוֹצֵא מִן הָעוֹלָם עַד שֶׁיִּצְטָרֵךְ לַבְּרִיּוֹת. וְעָלָיו כָּתוּב, (איוב טו) נֹדֵד הוּא לַלֶּחֶם אַיֵּה. נֹדֵד הוּא, וְיֵלֵךְ מִטַּלְטֵל, וְגוֹלֶה מִמָּקוֹם לְמָקוֹם, לַלֶּחֶם אַיֵּה הוּא. וְאֵין מִי שֶׁיַּשְׁגִּיחַ עָלָיו. זֶהוּ שֶׁכָּתוּב אַיֵּה מִי שֶׁיְּרַחֵם עָלָיו, מִשּׁוּם שֶׁלֹּא יִמָּצֵא.</p>\n<p>וּבַחִבּוּר הַקַּדְמוֹן, אָמַר הָרוֹעֶה הַנֶּאֱמָן, וּמַה מִּי שֶׁמְּזַלְזֵל בַּפֵּרוּרִים שֶׁל הַלֶּחֶם וְזוֹרֵק אוֹתָם בְּמָקוֹם שֶׁלֹּא צָרִיךְ כָּךְ - כָּל שֶׁכֵּן מִי שֶׁמְּזַלְזֵל בַּפֵּרוּרִים שֶׁל הַמֹּחַ, שֶׁהֵם טִפּוֹת הַזֶּרַע, שֶׁזּוֹרֵק אוֹתָם בָּאָרֶץ, שֶׁנֶּאֱמַר בָּהֶם (בראשית ו) כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ. אוֹ שֶׁזּוֹרֵק אוֹתָם בְּנִדָּה, אוֹ בְּבַת אֵל נֵכָר, אוֹ בְּשִׁפְחָה אוֹ בְּזוֹנָה. וְכָל שֶׁכֵּן וְכָל שֶׁכֵּן מִי שֶׁמְּזַלְזֵל בְּפֵרוּרִים שֶׁל הַלֶּחֶם שֶׁל הַתּוֹרָה, שֶׁהֵם קוֹצֵי הָאוֹתִיּוֹת וְתָגֵי הָאוֹתִיּוֹת, שֶׁנֶּאֱמַר עֲלֵיהֶם, כָּל הַמִּשְׁתַּמֵּשׁ בְּכֶתֶר - יַחֲלֹף.</p>\n<p>וְכָל שֶׁכֵּן מִי שֶׁמּוֹסֵר סוֹדוֹת הַתּוֹרָה, וְסִתְרֵי קַבָּלָה, וְסוֹדוֹת מַעֲשֵׂה בְרֵאשִׁית, אוֹ סִתְרֵי הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַמְפֹרָשׁ לַאֲנָשִׁים שֶׁאֵינָם הֲגוּנִים, שֶׁשּׁוֹלֵט עֲלֵיהֶם יֵצֶר הָרָע, אִשָּׁה זוֹנָה, שֶׁנֶּאֱמַר עָלֶיהָ (משלי ו) כִּי בְעַד אִשָּׁה זוֹנָה עַד כִּכַּר לָחֶם. וְאֵין לֶחֶם אֶלָּא כ\"ב אוֹתִיּוֹת הַתּוֹרָה. וְאֵין כִּכָּר אֶלָּא אֲפִלּוּ הֲלָכָה אַחַת. (ועוד רעיא מהימנא).</p>\n<p>וּבַחִבּוּר הַקַּדְמוֹן לֹא גִלָּה סוֹד בְּאוֹתָם פֵּרוּרִים אֶלָּא בְּדֶרֶךְ פְּשָׁט, וְלֹא נָתַן בָּהֶם שִׁעוּר. אֲבָל בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁשִּׁעוּר שֶׁל פֵּרוּרִים כַּזַּיִת לְפָחוֹת, כָּל שֶׁכֵּן אִם הֵם כַּבֵּיצָה. שֶׁבַּעֲלֵי הַמִּשְׁנָה דִּקְדְּקוּ עֲלֵיהֶם, עַד כַּזַּיִת עַד כַּבֵּיצָה לְבָרֵךְ עֲלֵיהֶם.</p>"]]});
